locals {
  tags = {
    Project   = "transit-gateway-hub"
    ManagedBy = "terraform"
  }

  # Pick the first two Availability Zones so every VPC gets multi-AZ subnets.
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  # One or more VPCs to connect to the central Transit Gateway.
  vpcs = {
    "vpc-a" = {
      cidr_block = "10.10.0.0/16"
    }
    "vpc-b" = {
      cidr_block = "10.20.0.0/16"
    }
  }

  # Flatten the VPC map into individual subnet definitions (two per VPC).
  subnet_definitions = {
    for pair in flatten([
      for vpc_key, vpc in local.vpcs : [
        for idx in range(2) : {
          key     = "${vpc_key}-${idx}"
          vpc_key = vpc_key
          cidr    = cidrsubnet(vpc.cidr_block, 8, idx)
          az      = local.azs[idx]
        }
      ]
    ]) : pair.key => pair
  }
}

resource "aws_vpc" "this" {
  for_each = local.vpcs

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = each.key
  })
}

resource "aws_subnet" "this" {
  for_each = local.subnet_definitions

  vpc_id            = aws_vpc.this[each.value.vpc_key].id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = merge(local.tags, {
    Name = each.key
  })
}

# Lock down the auto-created default security group in every VPC.
resource "aws_default_security_group" "this" {
  for_each = aws_vpc.this

  vpc_id = each.value.id

  tags = merge(local.tags, {
    Name = "${each.key}-default-sg"
  })
}

resource "aws_ec2_transit_gateway" "this" {
  description                     = "Centralized Transit Gateway for inter-VPC routing"
  amazon_side_asn                 = 64512
  auto_accept_shared_attachments  = "disable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"
  multicast_support               = "disable"

  tags = merge(local.tags, {
    Name = "central-tgw"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Map of VPC key => list of subnet IDs used to attach each VPC to the TGW.
locals {
  vpc_subnet_ids = {
    for vpc_key in keys(local.vpcs) : vpc_key => [
      for k, s in local.subnet_definitions : aws_subnet.this[k].id
      if s.vpc_key == vpc_key
    ]
  }
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = local.vpc_subnet_ids

  transit_gateway_id = aws_ec2_transit_gateway.this.id
  vpc_id             = aws_vpc.this[each.key].id
  subnet_ids         = each.value

  dns_support                                     = "enable"
  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true

  tags = merge(local.tags, {
    Name = "tgw-attach-${each.key}"
  })
}

resource "aws_route_table" "this" {
  for_each = local.vpcs

  vpc_id = aws_vpc.this[each.key].id

  tags = merge(local.tags, {
    Name = "${each.key}-rt"
  })
}

resource "aws_route_table_association" "this" {
  for_each = local.subnet_definitions

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.this[each.value.vpc_key].id
}

# Route every VPC to each peer VPC through the central Transit Gateway.
resource "aws_route" "to_tgw" {
  for_each = {
    for pair in flatten([
      for src_key, _ in local.vpcs : [
        for dst_key, dst in local.vpcs : {
          key  = "${src_key}-to-${dst_key}"
          src  = src_key
          cidr = dst.cidr_block
        }
        if src_key != dst_key
      ]
    ]) : pair.key => pair
  }

  route_table_id         = aws_route_table.this[each.value.src].id
  destination_cidr_block = each.value.cidr
  transit_gateway_id     = aws_ec2_transit_gateway.this.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

output "transit_gateway_id" {
  description = "ID of the central Transit Gateway."
  value       = aws_ec2_transit_gateway.this.id
}

output "transit_gateway_attachment_ids" {
  description = "Map of VPC key to Transit Gateway VPC attachment ID."
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.this : k => v.id }
}

output "vpc_ids" {
  description = "Map of VPC key to VPC ID."
  value       = { for k, v in aws_vpc.this : k => v.id }
}

