  tags = {
    Name = "${local.project_name}-eip"
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr        = "10.0.0.0/16"
  azs             = slice(data.aws_availability_zones.available.names, 0, 2)
  public_subnets  = [cidrsubnet(local.vpc_cidr, 8, 0), cidrsubnet(local.vpc_cidr, 8, 1)]
  private_subnets = [cidrsubnet(local.vpc_cidr, 8, 10), cidrsubnet(local.vpc_cidr, 8, 11)]
  namespace_name  = "service.local"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "public-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${local.azs[count.index]}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "main-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "main-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH only from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Limit outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "app-sg"
  }
}

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.namespace_name
  description = "Private Service Discovery namespace for containerized applications"
  vpc         = aws_vpc.main.id

  tags = {
    Name = local.namespace_name
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name_prefix = "benchmark-backup"

  common_tags = {
    Name        = local.name_prefix
    ManagedBy   = "terraform"
    Environment = "production"
  }

  # Retention windows enforced by the vault lock (days).
  vault_min_retention_days = 7
  vault_max_retention_days = 90

  # Backup plan schedule (daily at 05:00 UTC).
  backup_schedule = "cron(0 5 * * ? *)"
}

# ---------------------------------------------------------------------------
# KMS key used to encrypt the backup vault and recovery points
# ---------------------------------------------------------------------------
resource "aws_kms_key" "backup" {
  description             = "KMS CMK used to encrypt AWS Backup vault and recovery points"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupService"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "backup.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.name_prefix}-vault"
  target_key_id = aws_kms_key.backup.key_id
}

# ---------------------------------------------------------------------------
# Backup vault (encrypted, with a vault lock / retention window)
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "this" {
  name        = "${local.name_prefix}-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "this" {
  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = local.vault_min_retention_days
  max_retention_days  = local.vault_max_retention_days
  changeable_for_days = 3
}

# ---------------------------------------------------------------------------
# IAM role assumed by AWS Backup to create/manage recovery points
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AssumeRoleForBackup"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup_service" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ---------------------------------------------------------------------------
# Backup plan with a scheduled rule targeting the vault
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "this" {
  name = "${local.name_prefix}-plan"

  rule {
    rule_name         = "${local.name_prefix}-daily"
    target_vault_name = aws_backup_vault.this.name
    schedule          = local.backup_schedule

    start_window      = 60
    completion_window = 360

    lifecycle {
      cold_storage_after = 0
      delete_after       = 30
    }

    recovery_point_tags = local.common_tags
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Backup selection: all resources tagged benchmark-backup = true
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "tagged" {
  name         = "${local.name_prefix}-selection"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "benchmark-backup"
    value = "true"
  }
}

###############################################################################
# Cognito User Pool + App Client + Identity Pool + Authenticated IAM Role
#
# Creates:
#   - aws_cognito_user_pool            : the user directory
#   - aws_cognito_user_pool_client     : the app client bound to the pool
#   - aws_cognito_identity_pool        : federates the user pool
#   - aws_iam_role (authenticated)     : role assumed by authenticated identities
#   - aws_iam_role_policy              : Cognito Sync + Mobile Analytics access
#   - aws_cognito_identity_pool_roles_attachment : wires the role to the pool
###############################################################################

locals {
  user_pool_name          = "app-cognito-user-pool"
  user_pool_client_name   = "app-cognito-client"
  identity_pool_name      = "app_cognito_identity_pool"
  authenticated_role_name = "app_cognito_authenticated_role"

  common_tags = {
    ManagedBy   = "terraform"
    Environment = "production"
    Service     = "cognito"
  }
}

# Static provider metadata only (no pre-existing infrastructure lookup).
data "aws_region" "current" {}

###############################################################################
# Cognito User Pool
###############################################################################
resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  # Strong password policy
  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  # Enforce MFA (optional but available via TOTP software token)
  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  # Account recovery via verified email
  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  # Advanced security / threat protection
  user_pool_add_ons {
    advanced_security_mode = "ENFORCED"
  }

  # Prevent accidental deletion of the user directory
  deletion_protection = "ACTIVE"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cognito User Pool App Client
###############################################################################
resource "aws_cognito_user_pool_client" "app" {
  name         = local.user_pool_client_name
  user_pool_id = aws_cognito_user_pool.main.id

  # Public mobile/SPA client - no client secret
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  # Do not leak whether a user exists
  prevent_user_existence_errors = "ENABLED"

  # Reasonable token validity
  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  enable_token_revocation = true
}

###############################################################################
# Cognito Identity Pool (linked to the User Pool)
###############################################################################
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role assumed by AUTHENTICATED identities
###############################################################################
data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentitiesToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    # Only identities from THIS identity pool may assume the role
    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    # Only authenticated (not unauthenticated) identities
    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = local.authenticated_role_name
  description        = "Role assumed by authenticated identities in the Cognito Identity Pool"
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json

  tags = local.common_tags
}

###############################################################################
# Least-privilege policy: Cognito Sync + Mobile Analytics
###############################################################################
data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    sid    = "CognitoSyncAccess"
    effect = "Allow"

    actions = [
      "cognito-sync:GetRecords",
      "cognito-sync:ListRecords",
      "cognito-sync:UpdateRecords",
      "cognito-sync:DescribeDataset",
      "cognito-sync:ListDatasets",
      "cognito-sync:SubscribeToDataset",
      "cognito-sync:UnsubscribeFromDataset",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "MobileAnalyticsAccess"
    effect = "Allow"

    actions = [
      "mobileanalytics:PutEvents",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "app-cognito-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated_permissions.json
}

###############################################################################
# Attach the authenticated role to the Identity Pool
###############################################################################
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.1.0/24"

  common_tags = {
    Name        = "custom-test-vpc"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "custom-test-vpc"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "custom-test-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "custom-test-igw"
  })
}

resource "aws_eip" "main" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "custom-test-eip"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = "ec2.internal"
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]

  tags = merge(local.common_tags, {
    Name = "custom-test-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "Allow HTTP from within the VPC CIDR"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Restrict egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "custom-test-default-sg"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  api_name       = "event-publisher-api"
  sns_topic_name = "event-topic"
  stage_name     = "prod"

  # Uniqueness suffix so account-scoped, user-named resources (IAM roles, log
  # group) do not collide with leftovers from earlier apply attempts.
  name_suffix = substr(uuid(), 0, 8)

  log_group_name = "/aws/apigateway/event-publisher-api-${local.name_suffix}"
}

###############################################################################
# Customer managed KMS key (rotation enabled) dedicated to the SNS topic
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "event_topic" {
  description             = "Customer managed key used to encrypt the ${local.sns_topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SNS topic "event-topic" encrypted with the dedicated CMK
###############################################################################

resource "aws_sns_topic" "event_topic" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.event_topic.arn

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role that lets API Gateway publish to the SNS topic
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_sns" {
  name               = "apigw-sns-publish-role-${local.name_suffix}"
  description        = "Role assumed by API Gateway to publish messages to the ${local.sns_topic_name} SNS topic"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw_sns_publish" {
  statement {
    sid    = "PublishToEventTopic"
    effect = "Allow"

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "UseEventTopicKmsKey"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.event_topic.arn]
  }
}

resource "aws_iam_role_policy" "apigw_sns_publish" {
  name   = "apigw-sns-publish-policy"
  role   = aws_iam_role.apigw_sns.id
  policy = data.aws_iam_policy_document.apigw_sns_publish.json
}

###############################################################################
# REST API Gateway that forwards POST requests to the SNS topic
###############################################################################

resource "aws_api_gateway_rest_api" "this" {
  name        = local.api_name
  description = "Publishes incoming POST requests to the ${local.sns_topic_name} SNS topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "post" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "AWS_IAM"
}

resource "aws_api_gateway_integration" "sns" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method

  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sns:path//"
  credentials             = aws_iam_role.apigw_sns.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = aws_api_gateway_method_response.post_200.status_code

  depends_on = [aws_api_gateway_integration.sns]
}

###############################################################################
# Access logging for the API stage
###############################################################################

resource "aws_cloudwatch_log_group" "api_logs" {
  name              = local.log_group_name
  retention_in_days = 90
}

data "aws_iam_policy_document" "apigw_logs_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_logs" {
  name               = "apigw-cloudwatch-logs-role-${local.name_suffix}"
  assume_role_policy = data.aws_iam_policy_document.apigw_logs_assume.json
}

data "aws_iam_policy_document" "apigw_logs" {
  statement {
    sid    = "WriteApiGatewayLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.api_logs.arn,
      "${aws_cloudwatch_log_group.api_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "apigw_logs" {
  name   = "apigw-cloudwatch-logs-policy"
  role   = aws_iam_role.apigw_logs.id
  policy = data.aws_iam_policy_document.apigw_logs.json
}

resource "aws_iam_role_policy_attachment" "apigw_logs_managed" {
  role       = aws_iam_role.apigw_logs.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_logs.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_logs_managed]
}

###############################################################################
# Deployment, stage and stage-level settings
###############################################################################

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.post.id,
      aws_api_gateway_integration.sns.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.sns,
    aws_api_gateway_integration_response.post_200,
  ]
}

resource "aws_api_gateway_stage" "this" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  deployment_id = aws_api_gateway_deployment.this.id
  stage_name    = local.stage_name

  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
    })
  }
}

resource "aws_api_gateway_method_settings" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  stage_name  = aws_api_gateway_stage.this.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled      = true
    logging_level        = "INFO"
    data_trace_enabled   = false
    caching_enabled      = true
    cache_ttl_in_seconds = 300
    cache_data_encrypted = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "invoke_url" {
  description = "Base invoke URL for the API stage"
  value       = "https://${aws_api_gateway_rest_api.this.id}.execute-api.${data.aws_region.current.region}.amazonaws.com/${aws_api_gateway_stage.this.stage_name}/events"
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic that receives API Gateway events"
  value       = aws_sns_topic.event_topic.arn
}

output "api_gateway_publish_role_arn" {
  description = "ARN of the IAM role API Gateway uses to publish to SNS"
  value       = aws_iam_role.apigw_sns.arn
}

variable "aws_region" {
  description = "AWS region in which to provision the networking stack"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the custom VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 2)
  vpc_name           = "terraform-aws-vpc"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

############################################
# Multi-tier VPC ("ntier primary")
# Tiers: web, app, database, management
#       + duplicate web, app, database set
############################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = "ntier primary"
  vpc_cidr = "10.10.0.0/16"

  # Primary tier subnet CIDRs
  web_cidr        = "10.10.1.0/24"
  app_cidr        = "10.10.2.0/24"
  database_cidr   = "10.10.3.0/24"
  management_cidr = "10.10.4.0/24"

  # Duplicate web/app/database set CIDRs
  web2_cidr      = "10.10.5.0/24"
  app2_cidr      = "10.10.6.0/24"
  database2_cidr = "10.10.7.0/24"

  azs = data.aws_availability_zones.available.names
}

############################################
# VPC
############################################
resource "aws_vpc" "ntier" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

############################################
# Internet Gateway
############################################
resource "aws_internet_gateway" "ntier" {
  vpc_id = aws_vpc.ntier.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

############################################
# Primary tier subnets
############################################
resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.web_cidr
  availability_zone = local.azs[0]

  tags = {
    Name = "${local.vpc_name}-web"
    Tier = "web"
  }
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.app_cidr
  availability_zone = local.azs[1]

  tags = {
    Name = "${local.vpc_name}-app"
    Tier = "app"
  }
}

resource "aws_subnet" "database" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.database_cidr
  availability_zone = local.azs[2]

  tags = {
    Name = "${local.vpc_name}-database"
    Tier = "database"
  }
}

resource "aws_subnet" "management" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.management_cidr
  availability_zone = local.azs[0]

  tags = {
    Name = "${local.vpc_name}-management"
    Tier = "management"
  }
}

############################################
# Duplicate web/app/database subnet set
############################################
resource "aws_subnet" "web2" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.web2_cidr
  availability_zone = local.azs[1]

  tags = {
    Name = "${local.vpc_name}-web2"
    Tier = "web"
  }
}

resource "aws_subnet" "app2" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.app2_cidr
  availability_zone = local.azs[2]

  tags = {
    Name = "${local.vpc_name}-app2"
    Tier = "app"
  }
}

resource "aws_subnet" "database2" {
  vpc_id            = aws_vpc.ntier.id
  cidr_block        = local.database2_cidr
  availability_zone = local.azs[0]

  tags = {
    Name = "${local.vpc_name}-database2"
    Tier = "database"
  }
}

############################################
# Route tables (both route to the IGW)
############################################
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier.id
  }

  tags = {
    Name = "${local.vpc_name}-public"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier.id
  }

  tags = {
    Name = "${local.vpc_name}-private"
  }
}

############################################
# Public route table associations
# web, management, web2
############################################
resource "aws_route_table_association" "web_public" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "management_public" {
  subnet_id      = aws_subnet.management.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web2_public" {
  subnet_id      = aws_subnet.web2.id
  route_table_id = aws_route_table.public.id
}

############################################
# Private route table associations
# app, database, app2, database2
############################################
resource "aws_route_table_association" "app_private" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database_private" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app2_private" {
  subnet_id      = aws_subnet.app2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database2_private" {
  subnet_id      = aws_subnet.database2.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Terraform / provider requirements
###############################################################################

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Data sources (static provider / account metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

# --- Mutually exclusive creation flags -------------------------------------

variable "create" {
  description = "Create a standard customer-managed KMS key with AWS-provided key material."
  type        = bool
  default     = true
}

variable "create_external" {
  description = "Create a KMS key backed by imported (base64) external key material."
  type        = bool
  default     = false
}

variable "create_replica" {
  description = "Create a standard multi-region replica KMS key referencing a primary key ARN."
  type        = bool
  default     = false
}

variable "create_replica_external" {
  description = "Create a multi-region replica KMS key with custom external key material."
  type        = bool
  default     = false
}

# --- Key attributes ---------------------------------------------------------

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "KMS key managed by Terraform"
}

variable "key_usage" {
  description = "Intended use of the KMS key (ENCRYPT_DECRYPT, SIGN_VERIFY or GENERATE_VERIFY_MAC)."
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Key spec: SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, ECC_NIST_P256, ECC_NIST_P384, ECC_NIST_P521, ECC_SECG_P256K1 or HMAC_*."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "multi_region" {
  description = "Enable multi-region for the standard customer-managed key."
  type        = bool
  default     = false
}

variable "enable_key_rotation" {
  description = "Enable automatic annual key rotation (symmetric / HMAC keys only)."
  type        = bool
  default     = true
}

variable "rotation_period_in_days" {
  description = "Custom rotation period in days (90-2560). Set to null to use the AWS default."
  type        = number
  default     = null
}

variable "is_enabled" {
  description = "Whether the standard KMS key is enabled."
  type        = bool
  default     = true
}

variable "deletion_window_in_days" {
  description = "Duration in days before the key is deleted after destruction (7-30)."
  type        = number
  default     = 30
}

variable "bypass_policy_lockout_safety_check" {
  description = "Skip the default key policy safety check."
  type        = bool
  default     = false
}

# --- External / replica key material ---------------------------------------

variable "base64_key_material" {
  description = "Base64-encoded 256-bit key material for imported external keys. Never commit a real value."
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-region key the replica key is created from."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary external multi-region key the replica external key is created from."
  type        = string
  default     = null
}

# --- Key policy inputs ------------------------------------------------------

variable "key_owners" {
  description = "Principals granted full key management. Use \"*\" to denote the account root."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "Principals that administer the key but do not use it for cryptographic operations."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "Principals granted standard cryptographic usage of the key."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "AWS service role principals granted cryptographic usage of the key."
  type        = list(string)
  default     = []
}

variable "key_ec2_autoscaling_role_arns" {
  description = "EC2 Auto Scaling role ARNs granted cryptographic usage of the key."
  type        = list(string)
  default     = []
}

variable "key_symmetric_encryption_users" {
  description = "Principals granted symmetric encrypt/decrypt usage."
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "Principals granted HMAC generate/verify usage."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "Principals granted asymmetric public-key encryption usage."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "Principals granted asymmetric sign/verify usage."
  type        = list(string)
  default     = []
}

variable "key_route53_dnssec_signing_enabled" {
  description = "Grant the Route 53 DNSSEC signing service the permissions it requires."
  type        = bool
  default     = false
}

variable "key_source_policy_documents" {
  description = "List of JSON policy documents merged with the generated key policy."
  type        = list(string)
  default     = []
}

variable "key_override_policy_documents" {
  description = "List of JSON policy documents that override conflicting statements in the generated key policy."
  type        = list(string)
  default     = []
}

variable "key_policy" {
  description = "Complete JSON key policy that, when set, replaces the generated key policy."
  type        = string
  default     = null
}

# --- Aliases ----------------------------------------------------------------

variable "aliases" {
  description = "List of exact KMS alias names (an \"alias/\" prefix is added when absent)."
  type        = list(string)
  default     = []
}

variable "alias_name_prefix" {
  description = "Prefix used to generate KMS alias names (an \"alias/\" prefix is added when absent)."
  type        = string
  default     = ""
}

variable "alias_name_prefix_count" {
  description = "Number of aliases to create when alias_name_prefix is set."
  type        = number
  default     = 1
}

# --- Grants -----------------------------------------------------------------

variable "grants" {
  description = "Map of KMS grants to create on the key."
  type = map(object({
    name               = optional(string)
    grantee_principal  = string
    operations         = list(string)
    retiring_principal = optional(string)
    constraints = optional(list(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    })), [])
  }))
  default = {}
}

# --- Tags -------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  # Mutually exclusive effective key-type flags. A standard key is only created
  # when no other key flavour is requested.
  create_standard_key         = var.create && !var.create_external && !var.create_replica && !var.create_replica_external
  create_external_key         = var.create_external
  create_replica_key          = var.create_replica
  create_replica_external_key = var.create_replica_external

  create_any_key = local.create_standard_key || local.create_external_key || local.create_replica_key || local.create_replica_external_key

  # Automatic rotation is only supported for symmetric and HMAC keys.
  supports_rotation = var.customer_master_key_spec == "SYMMETRIC_DEFAULT" || startswith(var.customer_master_key_spec, "HMAC")

  default_tags = merge(var.tags, { ManagedBy = "Terraform" })

  # Map the special "*" token to the account root ARN.
  normalize_principals = {
    for k, v in {
      owners      = var.key_owners
      admins      = var.key_administrators
      users       = var.key_users
      services    = var.key_service_users
      ec2         = var.key_ec2_autoscaling_role_arns
      symmetric   = var.key_symmetric_encryption_users
      hmac        = var.key_hmac_users
      asy_encrypt = var.key_asymmetric_public_encryption_users
      asy_sign    = var.key_asymmetric_sign_verify_users
    } : k => [for p in v : p == "*" ? local.account_root_arn : p]
  }

  policy_principal_count = (
    length(var.key_owners) +
    length(var.key_administrators) +
    length(var.key_users) +
    length(var.key_service_users) +
    length(var.key_ec2_autoscaling_role_arns) +
    length(var.key_symmetric_encryption_users) +
    length(var.key_hmac_users) +
    length(var.key_asymmetric_public_encryption_users) +
    length(var.key_asymmetric_sign_verify_users)
  )

  # Include the default root statement only when no other principals are supplied.
  use_default_root_policy = local.policy_principal_count == 0

  key_management_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:Delete*",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion",
  ]

  key_usage_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  # Key identifier / ARN of whichever single key flavour is being created.
  target_key_id = try(
    aws_kms_key.this[0].id,
    aws_kms_external_key.this[0].id,
    aws_kms_replica_key.this[0].id,
    aws_kms_replica_external_key.this[0].id
  )

  target_key_arn = try(
    aws_kms_key.this[0].arn,
    aws_kms_external_key.this[0].arn,
    aws_kms_replica_key.this[0].arn,
    aws_kms_replica_external_key.this[0].arn
  )
}

###############################################################################
# Dynamically generated key policy
###############################################################################

data "aws_iam_policy_document" "key" {
  count = local.create_any_key && var.key_policy == null ? 1 : 0

  source_policy_documents   = var.key_source_policy_documents
  override_policy_documents = var.key_override_policy_documents

  # Default root policy (prevents the key from becoming unmanageable).
  dynamic "statement" {
    for_each = local.use_default_root_policy ? [1] : []

    content {
      sid    = "DefaultRootPolicy"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [local.account_root_arn]
      }

      actions   = ["kms:*"]
      resources = ["*"]
    }
  }

  # Key owners - full management access.
  dynamic "statement" {
    for_each = length(var.key_owners) > 0 ? [1] : []

    content {
      sid    = "KeyOwners"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.owners
      }

      actions   = local.key_management_actions
      resources = ["*"]
    }
  }

  # Key administrators - management access without cryptographic usage.
  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []

    content {
      sid    = "KeyAdministrators"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.admins
      }

      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion",
      ]
      resources = ["*"]
    }
  }

  # Standard key users.
  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []

    content {
      sid    = "KeyUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.users
      }

      actions   = local.key_usage_actions
      resources = ["*"]
    }
  }

  # Service users.
  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []

    content {
      sid    = "KeyServiceUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.services
      }

      actions   = local.key_usage_actions
      resources = ["*"]
    }
  }

  # EC2 Auto Scaling roles.
  dynamic "statement" {
    for_each = length(var.key_ec2_autoscaling_role_arns) > 0 ? [1] : []

    content {
      sid    = "KeyEC2AutoScalingRoles"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.ec2
      }

      actions   = local.key_usage_actions
      resources = ["*"]
    }
  }

  # Symmetric encryption users.
  dynamic "statement" {
    for_each = length(var.key_symmetric_encryption_users) > 0 ? [1] : []

    content {
      sid    = "KeySymmetricEncryptionUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.symmetric
      }

      actions   = local.key_usage_actions
      resources = ["*"]
    }
  }

  # HMAC users.
  dynamic "statement" {
    for_each = length(var.key_hmac_users) > 0 ? [1] : []

    content {
      sid    = "KeyHmacUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.hmac
      }

      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac",
        "kms:DescribeKey",
      ]
      resources = ["*"]
    }
  }

  # Asymmetric public-key encryption users.
  dynamic "statement" {
    for_each = length(var.key_asymmetric_public_encryption_users) > 0 ? [1] : []

    content {
      sid    = "KeyAsymmetricPublicEncryptionUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.asy_encrypt
      }

      actions = [
        "kms:Encrypt",
        "kms:DescribeKey",
        "kms:GetPublicKey",
      ]
      resources = ["*"]
    }
  }

  # Asymmetric sign / verify users.
  dynamic "statement" {
    for_each = length(var.key_asymmetric_sign_verify_users) > 0 ? [1] : []

    content {
      sid    = "KeyAsymmetricSignVerifyUsers"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = local.normalize_principals.asy_sign
      }

      actions = [
        "kms:Sign",
        "kms:Verify",
        "kms:DescribeKey",
        "kms:GetPublicKey",
      ]
      resources = ["*"]
    }
  }

  # Route 53 DNSSEC signing service.
  dynamic "statement" {
    for_each = var.key_route53_dnssec_signing_enabled ? [1] : []

    content {
      sid    = "KeyRoute53DnssecSigning"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign",
      ]
      resources = ["*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

locals {
  generated_key_policy = try(data.aws_iam_policy_document.key[0].json, null)
  resolved_key_policy  = var.key_policy != null ? var.key_policy : local.generated_key_policy
}

###############################################################################
# KMS keys (mutually exclusive)
###############################################################################

resource "aws_kms_key" "this" {
  count = local.create_standard_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  key_usage                          = var.key_usage
  customer_master_key_spec           = var.customer_master_key_spec
  multi_region                       = var.multi_region
  enable_key_rotation                = local.supports_rotation ? var.enable_key_rotation : null
  rotation_period_in_days            = local.supports_rotation && var.enable_key_rotation ? var.rotation_period_in_days : null
  is_enabled                         = var.is_enabled
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  policy                             = local.resolved_key_policy

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_external_key" "this" {
  count = local.create_external_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  key_material_base64                = var.base64_key_material
  multi_region                       = var.multi_region
  enabled                            = var.is_enabled
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  policy                             = local.resolved_key_policy

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "this" {
  count = local.create_replica_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  primary_key_arn                    = var.primary_key_arn
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  policy                             = local.resolved_key_policy

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_external_key" "this" {
  count = local.create_replica_external_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  primary_key_arn                    = var.primary_external_key_arn
  key_material_base64                = var.base64_key_material
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  policy                             = local.resolved_key_policy

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# KMS aliases (exact names and name prefix)
###############################################################################

resource "aws_kms_alias" "this" {
  for_each = local.create_any_key ? toset(var.aliases) : toset([])

  name          = startswith(each.value, "alias/") ? each.value : "alias/${each.value}"
  target_key_id = local.target_key_id
}

resource "aws_kms_alias" "name_prefix" {
  count = local.create_any_key && var.alias_name_prefix != "" ? var.alias_name_prefix_count : 0

  name_prefix   = startswith(var.alias_name_prefix, "alias/") ? var.alias_name_prefix : "alias/${var.alias_name_prefix}"
  target_key_id = local.target_key_id
}

###############################################################################
# KMS grants
###############################################################################

resource "aws_kms_grant" "this" {
  for_each = local.create_any_key ? var.grants : {}

  name               = coalesce(each.value.name, each.key)
  key_id             = local.target_key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = each.value.constraints

    content {
      encryption_context_equals = constraints.value.encryption_context_equals
      encryption_context_subset = constraints.value.encryption_context_subset
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "key_id" {
  description = "ID of the KMS key created by this configuration."
  value       = local.create_any_key ? local.target_key_id : null
}

output "key_arn" {
  description = "ARN of the KMS key created by this configuration."
  value       = local.create_any_key ? local.target_key_arn : null
}

output "alias_names" {
  description = "Exact alias names created by this configuration."
  value       = [for a in aws_kms_alias.this : a.name]
}

output "alias_name_prefix_names" {
  description = "Names of the aliases created from the configured prefix."
  value       = [for a in aws_kms_alias.name_prefix : a.name]
}

output "grant_ids" {
  description = "IDs of the KMS grants created by this configuration."
  value       = { for k, g in aws_kms_grant.this : k => g.grant_id }
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Name of the SNS topic. Also used as the base for the KMS alias."
  type        = string
  default     = "sns-topic"
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for SNS server-side encryption."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ARN of an existing KMS master key used for SNS encryption when no dedicated key is created."
  type        = string
  default     = ""
}

variable "create_topic_policy" {
  description = "Whether to create an SNS topic policy from the supplied JSON document."
  type        = bool
  default     = false
}

variable "topic_policy" {
  description = "Custom JSON policy document to apply to the SNS topic."
  type        = string
  default     = ""
}

variable "fifo_topic" {
  description = "Whether the SNS topic is a FIFO topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication. Only valid for FIFO topics."
  type        = bool
  default     = false
}

variable "application_success_feedback_role_arn" {
  description = "IAM role ARN for SNS application endpoint success delivery status logging."
  type        = string
  default     = null
}

variable "application_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for application endpoint success delivery status logging."
  type        = number
  default     = null
}

variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN for SNS application endpoint failure delivery status logging."
  type        = string
  default     = null
}

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN for SNS HTTP/S endpoint success delivery status logging."
  type        = string
  default     = null
}

variable "http_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for HTTP/S endpoint success delivery status logging."
  type        = number
  default     = null
}

variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN for SNS HTTP/S endpoint failure delivery status logging."
  type        = string
  default     = null
}

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN for SNS Lambda endpoint success delivery status logging."
  type        = string
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Lambda endpoint success delivery status logging."
  type        = number
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN for SNS Lambda endpoint failure delivery status logging."
  type        = string
  default     = null
}

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN for SNS SQS endpoint success delivery status logging."
  type        = string
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for SQS endpoint success delivery status logging."
  type        = number
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN for SNS SQS endpoint failure delivery status logging."
  type        = string
  default     = null
}

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN for SNS Firehose endpoint success delivery status logging."
  type        = string
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Firehose endpoint success delivery status logging."
  type        = number
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN for SNS Firehose endpoint failure delivery status logging."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to the created resources."
  type        = map(string)
  default     = {}
}

variable "subscriptions" {
  description = "Map of SNS subscriptions to create, keyed by a unique name."
  type = map(object({
    protocol               = string
    endpoint               = string
    endpoint_auto_confirms = optional(bool, false)
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string)
    redrive_policy         = optional(string)
  }))
  default = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # FIFO topics require a name ending in ".fifo".
  topic_name = var.fifo_topic && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name

  # Dynamically select the KMS key: dedicated key ARN > explicit master key ARN > AWS managed alias.
  kms_key_arn = try(aws_kms_key.sns[0].arn, null)

  kms_master_key_id = coalesce(
    var.create_kms_key ? local.kms_key_arn : null,
    var.kms_master_key_id != "" ? var.kms_master_key_id : null,
    "alias/aws/sns",
  )
}

###############################################################################
# KMS key (optional)
###############################################################################

resource "aws_kms_key" "sns" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key for SNS topic ${local.topic_name} server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = var.tags
}

resource "aws_kms_alias" "sns" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/sns/${var.name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

data "aws_iam_policy_document" "kms" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid     = "EnableRootAccountAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsServiceEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }
}

###############################################################################
# SNS topic
###############################################################################

resource "aws_sns_topic" "this" {
  name = local.topic_name

  kms_master_key_id = local.kms_master_key_id

  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : false

  tags = var.tags
}

###############################################################################
# SNS topic policy (optional)
###############################################################################

resource "aws_sns_topic_policy" "this" {
  count = var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this.arn
  policy = var.topic_policy
}

###############################################################################
# SNS subscriptions (dynamic)
###############################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn              = aws_sns_topic.this.arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy
  redrive_policy         = each.value.redrive_policy
}

###############################################################################
# Outputs
###############################################################################

output "sns_topic_arn" {
  description = "ARN of the created SNS topic."
  value       = aws_sns_topic.this.arn
}

output "sns_topic_name" {
  description = "Name of the created SNS topic."
  value       = aws_sns_topic.this.name
}

output "kms_master_key_id" {
  description = "KMS master key identifier used for SNS encryption."
  value       = local.kms_master_key_id
}

output "kms_key_arn" {
  description = "ARN of the dedicated KMS key, if created."
  value       = try(aws_kms_key.sns[0].arn, null)
}

output "kms_key_alias_name" {
  description = "Alias name of the dedicated KMS key, if created."
  value       = try(aws_kms_alias.sns[0].name, null)
}

###############################################################################
# Variables - independent boolean creation toggles and default settings
###############################################################################

variable "create_iam_group" {
  description = "Toggle creation of the IAM developer group."
  type        = bool
  default     = true
}

variable "create_iam_policy" {
  description = "Toggle creation of the IAM read-only and S3 read/write access policy."
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Toggle attachment of the access policy to the developer group."
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle creation of the default IAM users."
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_policy" {
  description = "Toggle creation of the EC2 console screenshot policy."
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Toggle attachment of the EC2 console screenshot policy to each user."
  type        = bool
  default     = true
}

variable "create_group_memberships" {
  description = "Toggle association of the IAM users with the developer group."
  type        = bool
  default     = true
}

variable "create_instance_role" {
  description = "Toggle creation of the EC2 instance role."
  type        = bool
  default     = true
}

variable "iam_group_name" {
  description = "Name of the IAM developer group."
  type        = string
  default     = "developers"
}

variable "iam_policy_name" {
  description = "Name of the IAM read-only and S3 read/write access policy."
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "ec2_screenshot_policy_name" {
  description = "Name of the EC2 console screenshot policy."
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "instance_role_name" {
  description = "Name of the EC2 instance assume role."
  type        = string
  default     = "instance_role"
}

variable "iam_users" {
  description = "List of default IAM users to create."
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "user_tag_created_by" {
  description = "Value applied to the user_created_by tag on IAM users."
  type        = string
  default     = "terraform"
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_partition" "current" {}

locals {
  # AWS-managed policy ARN, built from static partition metadata.
  iam_read_only_access_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

###############################################################################
# IAM group
###############################################################################

resource "aws_iam_group" "developers" {
  count = var.create_iam_group ? 1 : 0

  name = var.iam_group_name
}

###############################################################################
# IAM read-only + S3 read/write access policy
###############################################################################

data "aws_iam_policy_document" "iam_read_only_and_s3_full_access" {
  statement {
    sid    = "IAMReadActions"
    effect = "Allow"

    actions = [
      "iam:Get*",
      "iam:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count = var.create_iam_policy ? 1 : 0

  name        = var.iam_policy_name
  description = "IAM read actions plus S3 object read/write access for the developers group."
  policy      = data.aws_iam_policy_document.iam_read_only_and_s3_full_access.json
}

###############################################################################
# Attach the access policy to the developer group
###############################################################################

resource "aws_iam_group_policy_attachment" "iam_read_only_and_s3_full_access" {
  count = var.create_iam_group && var.create_iam_policy && var.create_group_policy_attachment ? 1 : 0

  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

###############################################################################
# IAM users
###############################################################################

resource "aws_iam_user" "developers" {
  count = var.create_iam_users ? length(var.iam_users) : 0

  name = var.iam_users[count.index]

  tags = {
    user_created_by = var.user_tag_created_by
  }
}

###############################################################################
# EC2 console screenshot policy
###############################################################################

data "aws_iam_policy_document" "ec2_get_console_screenshot" {
  statement {
    sid    = "EC2GetConsoleScreenshot"
    effect = "Allow"

    actions = [
      "ec2:GetConsoleScreenshot",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count = var.create_ec2_screenshot_policy ? 1 : 0

  name        = var.ec2_screenshot_policy_name
  description = "Grants permission to retrieve the EC2 console screenshot."
  policy      = data.aws_iam_policy_document.ec2_get_console_screenshot.json
}

###############################################################################
# Attach the EC2 console screenshot policy directly to each user
###############################################################################

resource "aws_iam_user_policy_attachment" "ec2_get_console_screenshot" {
  count = var.create_iam_users && var.create_ec2_screenshot_policy && var.create_user_policy_attachments ? length(var.iam_users) : 0

  user       = aws_iam_user.developers[count.index].name
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

###############################################################################
# Group membership associations
###############################################################################

resource "aws_iam_user_group_membership" "developers" {
  count = var.create_iam_group && var.create_iam_users && var.create_group_memberships ? length(var.iam_users) : 0

  user   = aws_iam_user.developers[count.index].name
  groups = [aws_iam_group.developers[0].name]
}

###############################################################################
# EC2 instance assume role
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid    = "EC2AssumeRole"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance_role" {
  count = var.create_instance_role ? 1 : 0

  name               = var.instance_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "instance_role_iam_read_only_access" {
  count = var.create_instance_role ? 1 : 0

  role       = aws_iam_role.instance_role[0].name
  policy_arn = local.iam_read_only_access_policy_arn
}

###############################################################################
# Outputs
###############################################################################

output "iam_group_name" {
  description = "Name of the developer IAM group."
  value       = var.create_iam_group ? aws_iam_group.developers[0].name : null
}

output "iam_policy_arn" {
  description = "ARN of the IAM read-only and S3 read/write access policy."
  value       = var.create_iam_policy ? aws_iam_policy.iam_read_only_and_s3_full_access[0].arn : null
}

output "ec2_screenshot_policy_arn" {
  description = "ARN of the EC2 console screenshot policy."
  value       = var.create_ec2_screenshot_policy ? aws_iam_policy.ec2_get_console_screenshot[0].arn : null
}

output "iam_user_names" {
  description = "Names of the created IAM users."
  value       = var.create_iam_users ? aws_iam_user.developers[*].name : []
}

output "instance_role_arn" {
  description = "ARN of the EC2 instance role."
  value       = var.create_instance_role ? aws_iam_role.instance_role[0].arn : null
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for this user pool"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified"
  type        = list(string)
  default     = []
}

variable "mfa_configuration" {
  description = "Multi-factor authentication configuration"
  type        = string
  default     = "OPTIONAL"
}

variable "email_verification_message" {
  description = "Email verification message"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject"
  type        = string
  default     = "Some subject"
}

variable "sms_authentication_message" {
  description = "SMS authentication message"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message"
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template configuration (including by-link options)"
  type        = any
  default     = {}
}

variable "sms_configuration" {
  description = "SMS configuration for the user pool"
  type        = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "account_recovery_setting" {
  description = "Account recovery settings"
  type        = any
  default = {
    recovery_mechanism = [
      {
        name     = "verified_email"
        priority = 2
      },
      {
        name     = "verified_phone_number"
        priority = 1
      },
    ]
  }
}

variable "invite_message_template" {
  description = "Invite message template for admin-created users"
  type        = any
  default     = {}
}

variable "admin_create_user_only" {
  description = "Whether to allow admin create user only"
  type        = bool
  default     = false
}

variable "software_token_mfa_configuration" {
  description = "Software token MFA configuration"
  type        = any
  default = {
    enabled = true
  }
}

variable "username_case_sensitivity" {
  description = "Whether username case sensitivity is enabled"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device configuration parameters"
  type        = any
  default     = null
}

variable "lambda_config" {
  description = "Optional Lambda trigger configuration"
  type        = any
  default     = {}
}

variable "schema" {
  description = "Custom schema definitions for the user pool"
  type        = any
  default = [
    {
      attribute_data_type      = "String"
      developer_only_attribute = false
      mutable                  = true
      name                     = "email"
      required                 = true
    },
  ]
}

variable "clients" {
  description = "List of Cognito User Pool Client names to create"
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Whether to generate a client secret for the user pool clients"
  type        = bool
  default     = false
}

variable "client_access_token_validity" {
  description = "Access token validity in the units configured in client_token_validity_units"
  type        = number
  default     = 120
}

variable "client_id_token_validity" {
  description = "ID token validity in the units configured in client_token_validity_units"
  type        = number
  default     = 120
}

variable "client_refresh_token_validity" {
  description = "Refresh token validity in the units configured in client_token_validity_units"
  type        = number
  default     = 7
}

variable "client_token_validity_units" {
  description = "Units used for the token validities"
  type        = map(string)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth_flows_user_pool_client" {
  description = "Whether the client is allowed to follow the OAuth protocol when interacting with Cognito user pools"
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Whether token revocation is enabled for the client"
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "List of explicit authentication flows enabled for the client"
  type        = list(string)
  default = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]
}

variable "client_prevent_user_existence_errors" {
  description = "Prevent user existence errors setting for the client"
  type        = string
  default     = "LEGACY"
}

variable "client_read_attributes" {
  description = "List of user attributes that the client has read access to"
  type        = list(string)
  default     = null
}

variable "client_write_attributes" {
  description = "List of user attributes that the client has write access to"
  type        = list(string)
  default     = null
}

variable "client_callback_urls" {
  description = "List of allowed callback URLs for the client"
  type        = list(string)
  default     = null
}

variable "client_logout_urls" {
  description = "List of allowed logout URLs for the client"
  type        = list(string)
  default     = null
}

variable "client_allowed_oauth_flows" {
  description = "List of allowed OAuth flows for the client"
  type        = list(string)
  default     = null
}

variable "client_allowed_oauth_scopes" {
  description = "List of allowed OAuth scopes for the client"
  type        = list(string)
  default     = null
}

variable "client_supported_identity_providers" {
  description = "List of provider names for the identity providers supported by the client"
  type        = list(string)
  default     = null
}

variable "group_name" {
  description = "Name of the Cognito user group to create"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the Cognito user group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "Optional IAM role ARN to associate with the Cognito user group"
  type        = string
  default     = ""
}

variable "domain" {
  description = "Cognito User Pool domain prefix/full domain to create"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "Optional ACM certificate ARN for the custom Cognito User Pool domain"
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create an alias Route 53 A-record for the Cognito User Pool domain"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID used for the alias record"
  type        = string
  default     = ""
}

locals {
  cloudfront_zone_id = "Z2FDTNDATAQYW2"
}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "this" {
  name                     = var.name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject

  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "verification_message_template" {
    for_each = length(var.verification_message_template) > 0 ? [var.verification_message_template] : []
    content {
      default_email_option  = lookup(verification_message_template.value, "default_email_option", null)
      email_message         = lookup(verification_message_template.value, "email_message", null)
      email_message_by_link = lookup(verification_message_template.value, "email_message_by_link", null)
      email_subject         = lookup(verification_message_template.value, "email_subject", null)
      email_subject_by_link = lookup(verification_message_template.value, "email_subject_by_link", null)
      sms_message           = lookup(verification_message_template.value, "sms_message", null)
    }
  }

  dynamic "sms_configuration" {
    for_each = (
      lookup(var.sms_configuration, "external_id", "") != "" &&
      lookup(var.sms_configuration, "sns_caller_arn", "") != ""
    ) ? [var.sms_configuration] : []
    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
    }
  }

  dynamic "account_recovery_setting" {
    for_each = length(lookup(var.account_recovery_setting, "recovery_mechanism", [])) > 0 ? [var.account_recovery_setting] : []
    content {
      dynamic "recovery_mechanism" {
        for_each = lookup(account_recovery_setting.value, "recovery_mechanism", [])
        content {
          name     = recovery_mechanism.value.name
          priority = recovery_mechanism.value.priority
        }
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    dynamic "invite_message_template" {
      for_each = length(var.invite_message_template) > 0 ? [var.invite_message_template] : []
      content {
        email_message = lookup(invite_message_template.value, "email_message", null)
        email_subject = lookup(invite_message_template.value, "email_subject", null)
        sms_message   = lookup(invite_message_template.value, "sms_message", null)
      }
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = lookup(device_configuration.value, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(device_configuration.value, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_configuration != null ? [var.software_token_mfa_configuration] : []
    content {
      enabled = software_token_mfa_configuration.value.enabled
    }
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitivity != null ? [var.username_case_sensitivity] : []
    content {
      case_sensitive = username_configuration.value
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [var.lambda_config] : []
    content {
      create_auth_challenge          = lookup(lambda_config.value, "create_auth_challenge", null)
      custom_message                 = lookup(lambda_config.value, "custom_message", null)
      define_auth_challenge          = lookup(lambda_config.value, "define_auth_challenge", null)
      post_authentication            = lookup(lambda_config.value, "post_authentication", null)
      post_confirmation              = lookup(lambda_config.value, "post_confirmation", null)
      pre_authentication             = lookup(lambda_config.value, "pre_authentication", null)
      pre_sign_up                    = lookup(lambda_config.value, "pre_sign_up", null)
      pre_token_generation           = lookup(lambda_config.value, "pre_token_generation", null)
      user_migration                 = lookup(lambda_config.value, "user_migration", null)
      verify_auth_challenge_response = lookup(lambda_config.value, "verify_auth_challenge_response", null)
      kms_key_id                     = lookup(lambda_config.value, "kms_key_id", null)

      dynamic "custom_email_sender" {
        for_each = length(keys(lookup(lambda_config.value, "custom_email_sender", {}))) > 0 ? [lookup(lambda_config.value, "custom_email_sender", {})] : []
        content {
          lambda_arn     = lookup(custom_email_sender.value, "lambda_arn", null)
          lambda_version = lookup(custom_email_sender.value, "lambda_version", null)
        }
      }

      dynamic "custom_sms_sender" {
        for_each = length(keys(lookup(lambda_config.value, "custom_sms_sender", {}))) > 0 ? [lookup(lambda_config.value, "custom_sms_sender", {})] : []
        content {
          lambda_arn     = lookup(custom_sms_sender.value, "lambda_arn", null)
          lambda_version = lookup(custom_sms_sender.value, "lambda_version", null)
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.schema
    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = lookup(schema.value, "developer_only_attribute", null)
      mutable                  = lookup(schema.value, "mutable", null)
      name                     = schema.value.name
      required                 = lookup(schema.value, "required", null)

      dynamic "string_attribute_constraints" {
        for_each = length(lookup(schema.value, "string_attribute_constraints", {})) > 0 ? [lookup(schema.value, "string_attribute_constraints", {})] : []
        content {
          min_length = lookup(string_attribute_constraints.value, "min_length", null)
          max_length = lookup(string_attribute_constraints.value, "max_length", null)
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = length(lookup(schema.value, "number_attribute_constraints", {})) > 0 ? [lookup(schema.value, "number_attribute_constraints", {})] : []
        content {
          min_value = lookup(number_attribute_constraints.value, "min_value", null)
          max_value = lookup(number_attribute_constraints.value, "max_value", null)
        }
      }
    }
  }

  lifecycle {
    ignore_changes = [
      estimated_number_of_users,
    ]
  }
}

###############################################################################
# Cognito User Pool Clients
###############################################################################

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.clients)

  name = each.value

  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = var.client_generate_secret

  access_token_validity  = var.client_access_token_validity
  id_token_validity      = var.client_id_token_validity
  refresh_token_validity = var.client_refresh_token_validity

  token_validity_units {
    access_token  = lookup(var.client_token_validity_units, "access_token", "minutes")
    id_token      = lookup(var.client_token_validity_units, "id_token", "minutes")
    refresh_token = lookup(var.client_token_validity_units, "refresh_token", "days")
  }

  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation

  explicit_auth_flows           = var.client_explicit_auth_flows
  prevent_user_existence_errors = var.client_prevent_user_existence_errors

  read_attributes  = var.client_read_attributes
  write_attributes = var.client_write_attributes

  callback_urls                = var.client_callback_urls
  logout_urls                  = var.client_logout_urls
  allowed_oauth_flows          = var.client_allowed_oauth_flows
  allowed_oauth_scopes         = var.client_allowed_oauth_scopes
  supported_identity_providers = var.client_supported_identity_providers
}

###############################################################################
# Cognito User Group
###############################################################################

resource "aws_cognito_user_group" "this" {
  count = var.group_name != "" ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : null
}

###############################################################################
# Cognito User Pool Domain
###############################################################################

resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.domain_certificate_arn != "" ? var.domain_certificate_arn : null
}

###############################################################################
# Route 53 Alias Record
###############################################################################

resource "aws_route53_record" "this" {
  count = var.create_route53_record && var.domain != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr_block" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "internet_gateway_name" {
  description = "Name tag for the Internet Gateway."
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the public route table."
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier_name" {
  description = "Identifier name for the public subnet."
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway."
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  description = "Name of the public IPv4 pool used for the Elastic IP."
  type        = string
  default     = "amazon"
}

variable "security_group_name" {
  description = "Name tag and name of the default security group."
  type        = string
  default     = "DefaultSecurityGroup"
}

# --- Subnet A (public) -------------------------------------------------------

variable "subnet_a_cidr_block" {
  description = "CIDR block for Subnet A."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_availability_zone" {
  description = "Availability zone for Subnet A. Empty string falls back to the first AZ in the region."
  type        = string
  default     = ""
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet A."
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A."
  type        = string
  default     = "Subnet-A-Public"
}

# --- Subnet B (private) ------------------------------------------------------

variable "subnet_b_cidr_block" {
  description = "CIDR block for Subnet B."
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_availability_zone" {
  description = "Availability zone for Subnet B. Empty string falls back to the second AZ in the region."
  type        = string
  default     = ""
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet B."
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B."
  type        = string
  default     = "Subnet-B-Private"
}

# --- Subnet C (private) ------------------------------------------------------

variable "subnet_c_cidr_block" {
  description = "CIDR block for Subnet C."
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_availability_zone" {
  description = "Availability zone for Subnet C. Empty string falls back to the third AZ in the region."
  type        = string
  default     = ""
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Whether to auto-assign public IPs to instances in Subnet C."
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C."
  type        = string
  default     = "Subnet-C-Private"
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  subnet_a_az = coalesce(var.subnet_a_availability_zone, data.aws_availability_zones.available.names[0])
  subnet_b_az = coalesce(var.subnet_b_availability_zone, data.aws_availability_zones.available.names[1])
  subnet_c_az = coalesce(var.subnet_c_availability_zone, data.aws_availability_zones.available.names[2])
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.internet_gateway_name
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr_block
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name                  = var.subnet_a_name
    PublicSubnetIdentifier = var.public_subnet_identifier_name
  }
}

resource "aws_subnet" "b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr_block
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr_block
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

###############################################################################
# Route Table and Routes (associated only with Subnet A)
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "a" {
  subnet_id      = aws_subnet.a.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Elastic IP and NAT Gateway
###############################################################################

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool_name

  tags = {
    Name = var.nat_gateway_name
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Default Security Group
###############################################################################

resource "aws_security_group" "default" {
  name        = var.security_group_name
  description = "Default security group permitting egress within the VPC CIDR only."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress within the VPC CIDR only."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr_block]
  }

  tags = {
    Name = var.security_group_name
  }
}

###############################################################################
# Outputs
###############################################################################

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway."
  value       = aws_eip.nat.public_ip
}

###############################################################################
# AWS Backup solution
#
# Provisions a KMS-encrypted backup vault, a least-privilege backup service
# role, three multi-tiered backup plans (daily / weekly / monthly), matching
# backup selections driven by tag conditions, and optional vault notifications.
###############################################################################

###############################################################################
# Input variables
###############################################################################

variable "vault_name" {
  description = "Name of the AWS Backup vault."
  type        = string
  default     = "my-backup-vault"
}

variable "backup_tag_key" {
  description = "Tag key used to select resources for each backup tier."
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron expression that controls when the daily backup runs."
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron expression that controls when the weekly backup runs."
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron expression that controls when the monthly backup runs."
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_retention_days" {
  description = "Number of days daily recovery points are retained."
  type        = number
  default     = 7
}

variable "weekly_retention_days" {
  description = "Number of days weekly recovery points are retained."
  type        = number
  default     = 31
}

variable "monthly_retention_days" {
  description = "Number of days monthly recovery points are retained."
  type        = number
  default     = 366
}

variable "enable_continuous_backup" {
  description = "Enable continuous (point-in-time recovery) backup on the daily rule."
  type        = bool
  default     = false
}

variable "enable_vault_notifications" {
  description = "Whether to provision notifications on the backup vault."
  type        = bool
  default     = false
}

variable "notification_topic_arn" {
  description = "SNS topic ARN that receives backup vault notifications."
  type        = string
  default     = ""
}

variable "notification_events" {
  description = "Backup vault events that trigger a notification."
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED",
  ]
}

variable "tags" {
  description = "Optional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  tags = var.tags

  backup_service_role_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"

  daily_plan_name   = "${var.vault_name}-daily"
  weekly_plan_name  = "${var.vault_name}-weekly"
  monthly_plan_name = "${var.vault_name}-monthly"
}

###############################################################################
# KMS key used to encrypt the backup vault
###############################################################################

resource "aws_kms_key" "backup" {
  description             = "Customer managed KMS key for the AWS Backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.vault_name}"
  target_key_id = aws_kms_key.backup.key_id
}

###############################################################################
# Backup vault + optional notifications
###############################################################################

resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_notifications" "main" {
  count = var.enable_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.notification_topic_arn
  backup_vault_events = var.notification_events
}

###############################################################################
# IAM role assumed by AWS Backup
###############################################################################

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.vault_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_service_role_policy_arn
}

###############################################################################
# Backup plans
###############################################################################

resource "aws_backup_plan" "daily" {
  name = local.daily_plan_name

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = var.daily_retention_days
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = local.tags
}

resource "aws_backup_plan" "weekly" {
  name = local.weekly_plan_name

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = var.weekly_retention_days
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = local.tags
}

resource "aws_backup_plan" "monthly" {
  name = local.monthly_plan_name

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = var.monthly_retention_days
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"
    backup_options = {
      WindowsVSS = "enabled"
    }
  }

  tags = local.tags
}

###############################################################################
# Backup selections (tag based)
###############################################################################

resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }
}

###############################################################################
# Outputs
###############################################################################

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the backup vault."
  value       = aws_kms_key.backup.arn
}

output "backup_iam_role_arn" {
  description = "ARN of the IAM role assumed by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_plan_arns" {
  description = "ARNs of the daily, weekly and monthly backup plans."
  value = {
    daily   = aws_backup_plan.daily.arn
    weekly  = aws_backup_plan.weekly.arn
    monthly = aws_backup_plan.monthly.arn
  }
}

variable "region" {
  description = "AWS region to deploy the network architecture into"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment name used as the prefix for all resource names and tags"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to every resource"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  # Spread public/private subnets across the available AZs in the region
  azs = slice(data.aws_availability_zones.available.names, 0, max(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)))

  common_tags = var.common_tags
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = data.aws_region.current.name
    }
  )
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index + 1}"
    }
  )
}

resource "aws_nat_gateway" "this" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index + 1}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_partition" "current" {}

variable "create_eks" {
  description = "Controls whether the EKS cluster should be created."
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version to use for the EKS cluster. When null, the default version is used."
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "The authentication mode for the EKS cluster. One of API_AND_CONFIG_MAP, CONFIG_MAP, or API."
  type        = string
  default     = "API_AND_CONFIG_MAP"

  validation {
    condition     = contains(["API_AND_CONFIG_MAP", "CONFIG_MAP", "API"], var.authentication_mode)
    error_message = "authentication_mode must be one of API_AND_CONFIG_MAP, CONFIG_MAP, or API."
  }
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the EKS cluster."
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  description = "A list of subnet IDs for the EKS control plane. When populated, takes precedence over subnet_ids."
  type        = list(string)
  default     = []
}

locals {
  eks_cluster_role_name = "eks-cluster"

  # Prefer control plane subnets when provided, otherwise fall back to the general subnet list.
  eks_cluster_subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
}

resource "aws_iam_role" "eks_cluster" {
  name = local.eks_cluster_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSClusterAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = local.eks_cluster_role_name
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = var.cluster_version

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  vpc_config {
    subnet_ids = local.eks_cluster_subnet_ids
  }

  # Ensure the cluster is only created once both required IAM policies are
  # attached, and that those attachments are released only after the cluster
  # itself has been destroyed.
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]
}

data "aws_caller_identity" "current" {}

locals {
  users = {
    dev = {
      user_name   = "DevUser-rwwise.dev"
      policy_name = "dev_cicd_user_policy"
    }
    test = {
      user_name   = "TestUser-rwwise.dev"
      policy_name = "test_cicd_user_policy"
    }
    prod = {
      user_name   = "ProdUser-rwwise.dev"
      policy_name = "prod_cicd_user_policy"
    }
  }

  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountID  = data.aws_caller_identity.current.account_id
    UserID     = data.aws_caller_identity.current.user_id
  }
}

data "aws_iam_policy_document" "cicd" {
  statement {
    sid    = "CICDReadOnlyListAccess"
    effect = "Allow"

    actions = [
      "codebuild:List*",
      "codebuild:BatchGet*",
      "codebuild:Get*",
      "codecommit:List*",
      "codecommit:BatchGet*",
      "codecommit:Get*",
      "cloudwatch:List*",
      "cloudwatch:Get*",
      "cloudwatch:Describe*",
      "events:List*",
      "events:Describe*",
      "logs:List*",
      "logs:Get*",
      "logs:Describe*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"

    actions = [
      "codestar-connections:ListConnections",
      "codestar-connections:GetConnection",
      "codestar-connections:GetConnectionToken",
      "codestar-connections:GetIndividualAccessToken",
      "codestar-connections:PassConnection",
      "codestar-connections:UseConnection",
    ]

    resources = ["arn:aws:codestar-connections:*:*:connection/*"]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"

    actions = [
      "codestar-notifications:DescribeNotificationRule",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"

    actions = [
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListTargets",
      "codestar-notifications:ListTagsForResource",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_user" "cicd" {
  for_each = local.users

  name = each.value.user_name
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "cicd" {
  for_each = local.users

  user = aws_iam_user.cicd[each.key].name
}

resource "aws_iam_user_policy" "cicd" {
  for_each = local.users

  name   = each.value.policy_name
  user   = aws_iam_user.cicd[each.key].name
  policy = data.aws_iam_policy_document.cicd.json
}

###############################################################################
# Terraform / Provider requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Data sources
###############################################################################

# Static provider metadata: the AWS DNS suffix (e.g. "amazonaws.com").
data "aws_partition" "current" {}

###############################################################################
# Variables (module inputs)
###############################################################################

variable "name" {
  description = "Name used to label every resource created by this module. When null or empty the default naming module falls back to \"default\"."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to the resources created by this module."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Configuration for the custom EventBridge bus. Supports an optional event_source_name (defaults to null)."
  type = object({
    event_source_name = optional(string, null)
  })
  default = {}

  validation {
    condition     = var.bus != null
    error_message = "The bus variable must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create. Each rule must define a unique name and may optionally set description, event_pattern and schedule_expression."
  type = list(object({
    name                = string
    description         = optional(string, null)
    event_pattern       = optional(string, null)
    schedule_expression = optional(string, null)
  }))
  default = []

  validation {
    condition     = var.rules != null
    error_message = "The rules variable must not be null."
  }
}

variable "targets" {
  description = "List of EventBridge targets to create. Each target links a rule to a target ARN."
  type = list(object({
    name       = string
    rule       = string
    arn        = string
    input      = optional(string, null)
    input_path = optional(string, null)
  }))
  default = []

  validation {
    condition     = var.targets != null
    error_message = "The targets variable must not be null."
  }
}

###############################################################################
# Locals (default naming module)
###############################################################################

locals {
  # Default naming module: fall back to "default" when name is null or empty.
  name       = coalesce(var.name, "default")
  create_bus = local.name != "default"
  dns_suffix = data.aws_partition.current.dns_suffix
}

###############################################################################
# EventBridge custom bus (created only when name != "default")
###############################################################################

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_bus ? 1 : 0

  name              = local.name
  event_source_name = var.bus.event_source_name
  tags              = var.tags
}

###############################################################################
# EventBridge rules (keyed by each rule's name)
###############################################################################

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for rule in var.rules : rule.name => rule }

  name                = each.value.name
  description         = each.value.description
  event_pattern       = each.value.event_pattern
  schedule_expression = each.value.schedule_expression
  event_bus_name      = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null
  tags                = var.tags
}

###############################################################################
# IAM role assumed by the EventBridge service
###############################################################################

resource "aws_iam_role" "this" {
  name = "${local.name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "events.${local.dns_suffix}"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "this" {
  name = "${local.name}-invoke-targets"
  role = aws_iam_role.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# EventBridge targets (explicit dependency on the rules)
###############################################################################

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for target in var.targets : target.name => target }

  rule           = each.value.rule
  arn            = each.value.arn
  target_id      = each.value.name
  input          = each.value.input
  input_path     = each.value.input_path
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null
  role_arn       = can(regex("stateMachine", each.value.arn)) ? aws_iam_role.this.arn : null

  depends_on = [aws_cloudwatch_event_rule.this]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  role_name         = "aws-backup-${var.name}"
  vault_name        = "vault-${var.name}-backup"
  plan_name         = "plan-${var.name}-backup"
  rule_name         = "rule-${var.name}-backup"
  selection_name    = "selection-${var.name}-backup"
  job_tag           = "${var.name}-backup"
  backup_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# IAM role assumed by AWS Backup and granted the managed backup service policy
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  name        = local.role_name
  description = "AWS Backup service role for ${var.name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupServiceAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_policy_arn
}

# ---------------------------------------------------------------------------
# Backup vault
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "this" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null

  tags = {
    Job = local.job_tag
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# ---------------------------------------------------------------------------
# Backup plan with lifecycle rules and dynamic cross-region copy actions
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "this" {
  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    recovery_point_tags = {
      Job = local.job_tag
    }

    dynamic "copy_action" {
      for_each = var.destination_vaults
      content {
        destination_vault_arn = copy_action.key

        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after
          delete_after       = copy_action.value.delete_after
        }
      }
    }
  }

  tags = {
    Job = local.job_tag
  }
}

# ---------------------------------------------------------------------------
# Backup selection bound to the IAM role and plan, filtering by resource tags
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "this" {
  name         = local.selection_name
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id

  condition {}

  selection_tag {
    type  = var.tag_selection_operation
    key   = var.tag_selection_key
    value = var.tag_selection_value
  }
}

# ---------------------------------------------------------------------------
# Optional vault event notifications
# ---------------------------------------------------------------------------
resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.subscribed_events
}

# ---------------------------------------------------------------------------
# Input variables
# ---------------------------------------------------------------------------
variable "name" {
  description = "Base name value used to build all backup resource names and tags."
  type        = string
  default     = "app"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN used to encrypt the backup vault. Leave empty to use the AWS managed key."
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "Optional JSON access policy document attached to the backup vault when non-empty."
  type        = string
  default     = ""
}

variable "schedule" {
  description = "Cron expression that defines when the backup job runs."
  type        = string
  default     = "cron(0 12 * * ? *)"
}

variable "start_window" {
  description = "Minutes after the schedule during which the backup job must start."
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Minutes after the backup job starts within which it must complete."
  type        = number
  default     = 120
}

variable "cold_storage_after" {
  description = "Number of days after creation before a recovery point transitions to cold storage."
  type        = number
  default     = 30
}

variable "delete_after" {
  description = "Number of days after creation before a recovery point is deleted."
  type        = number
  default     = 120
}

variable "destination_vaults" {
  description = "Map of destination vault ARNs to lifecycle settings used for cross-vault copy actions."
  type = map(object({
    cold_storage_after = number
    delete_after       = number
  }))
  default = {}
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN used for vault event notifications. Leave empty to disable notifications."
  type        = string
  default     = ""
}

variable "subscribed_events" {
  description = "List of vault events that trigger SNS notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "tag_selection_operation" {
  description = "Tag selection comparison operator used to match resources for backup."
  type        = string
  default     = "STRINGEQUALS"
}

variable "tag_selection_key" {
  description = "Tag key used to match resources for backup."
  type        = string
  default     = "Backup"
}

variable "tag_selection_value" {
  description = "Tag value used to match resources for backup."
  type        = string
  default     = "true"
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Controls whether a new Transit Gateway is created (true) or an existing one is looked up (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create is false. Takes precedence over the name tag filter."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag used to look up an existing Transit Gateway when create is false, and the default Name tag applied to created resources."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account VPC attachments. Valid values: enable, disable."
  type        = string
  default     = "disable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled. Valid values: enable, disable."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled. Valid values: enable, disable."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "List of valid IPv4 or IPv6 CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "tags" {
  description = "A map of global tags applied to every resource created by this module."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up. Each item may set create, name, transit_gateway_id, local_tags and tags."
  type = map(object({
    create             = optional(bool, true)
    name               = optional(string)
    transit_gateway_id = optional(string)
    local_tags         = optional(map(string), {})
    tags               = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of AWS RAM principals to share the Transit Gateway with. Keys are arbitrary identifiers, values are principal ARNs, account IDs or organization ARNs."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Explicit name for the AWS RAM resource share. Defaults to the main resource name."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  create_transit_gateway = var.create

  default_name         = "transit-gateway"
  transit_gateway_name = coalesce(var.name, local.default_name)

  transit_gateway_id = local.create_transit_gateway ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? var.id : data.aws_ec2_transit_gateway.this[0].id
  )

  transit_gateway_arn = local.create_transit_gateway ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  ram_resource_share_name = coalesce(var.ram_resource_share_name, local.transit_gateway_name)

  create_ram_share = length(var.shared_principals) > 0

  route_tables_to_create = {
    for k, v in var.route_tables : k => v if coalesce(try(v.create, null), true)
  }

  route_tables_to_lookup = {
    for k, v in var.route_tables : k => v if !coalesce(try(v.create, null), true)
  }
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = local.create_transit_gateway ? 1 : 0

  amazon_side_asn = var.amazon_side_asn

  # Default route table association and propagation are explicitly disabled so
  # that routing is always controlled through the route tables declared below.
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  auto_accept_shared_attachments = var.auto_accept_shared_attachments
  dns_support                    = var.dns_support
  vpn_ecmp_support               = var.vpn_ecmp_support
  transit_gateway_cidr_blocks    = var.transit_gateway_cidr_blocks

  tags = merge(var.tags, { Name = local.transit_gateway_name })
}

data "aws_ec2_transit_gateway" "this" {
  count = local.create_transit_gateway ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null ? [1] : []

    content {
      name   = "tag:Name"
      values = [local.transit_gateway_name]
    }
  }
}

###############################################################################
# Transit Gateway route tables
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_create

  transit_gateway_id = coalesce(each.value.transit_gateway_id, local.transit_gateway_id)

  tags = merge(
    var.tags,
    each.value.local_tags,
    each.value.tags,
    {
      Name = coalesce(each.value.name, each.key, local.transit_gateway_name)
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_lookup

  filter {
    name   = "transit-gateway-id"
    values = [coalesce(each.value.transit_gateway_id, local.transit_gateway_id)]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(each.value.name, each.key, local.transit_gateway_name)]
  }
}

###############################################################################
# AWS RAM resource share
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = local.create_ram_share ? 1 : 0

  name = local.ram_resource_share_name

  # Cross-account / external principal sharing is explicitly permitted.
  allow_external_principals = true

  tags = merge(var.tags, { Name = local.ram_resource_share_name })
}

resource "aws_ram_resource_association" "this" {
  count = local.create_ram_share ? 1 : 0

  resource_arn       = local.transit_gateway_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn

  depends_on = [aws_ram_resource_association.this]
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "The ID of the created or looked-up Transit Gateway."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "The ARN of the created or looked-up Transit Gateway."
  value       = local.transit_gateway_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of route table keys to the IDs of the created Transit Gateway route tables."
  value       = { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id }
}

output "transit_gateway_route_table_lookup_ids" {
  description = "Map of route table keys to the IDs of the looked-up Transit Gateway route tables."
  value       = { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
}

output "ram_resource_share_arn" {
  description = "ARN of the AWS RAM resource share, if one was created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

###############################################################################
# Locals
###############################################################################

locals {
  backup_tag_key = "Backup"
}

###############################################################################
# Static provider metadata (pure static lookup)
###############################################################################

data "aws_partition" "current" {}

###############################################################################
# Shared KMS key for the tiered backup architecture
###############################################################################

resource "aws_kms_key" "backup" {
  description             = "Shared KMS key for tiered AWS Backup architecture"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role used by AWS Backup (shared across all tiers)
###############################################################################

resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_service_role_for_backup" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_service_role_for_restores" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

###############################################################################
# Bronze tier
###############################################################################

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = "bronze"
  }
}

###############################################################################
# Silver tier
###############################################################################

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = "silver"
  }
}

###############################################################################
# Gold tier
###############################################################################

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = "gold"
  }
}

###############################################################################
# Premium tier
###############################################################################

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = "premium"
  }
}

variable "aws_region" {
  description = "AWS region for the Prisma Cloud security monitoring integration."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role that Prisma Cloud assumes."
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "When true, attach the inline remediation (read-write) policy to the role."
  type        = bool
  default     = false
}

locals {
  prisma_cloud_principal    = "arn:aws:iam::188619942792:root"
  security_audit_policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"

  readonly_actions = [
    "apigateway:GET",
    "cognito-identity:ListTagsForResource",
    "cognito-idp:ListTagsForResource",
    "ecr:DescribeImages",
    "ecr:GetLifecyclePolicy",
    "elasticbeanstalk:ListTagsForResource",
    "elasticfilesystem:DescribeTags",
    "glacier:GetVaultLock",
    "glacier:ListTagsForVault",
    "glue:GetSecurityConfigurations",
    "logs:GetLogEvents",
    "mq:listBrokers",
    "mq:describeBroker",
    "ram:GetResourceShares",
    "secretsmanager:DescribeSecret",
    "ssm:GetParameters",
    "ssm:ListTagsForResource",
    "sqs:SendMessage",
    "elasticmapreduce:ListSecurityConfigurations",
    "sns:listSubscriptions",
    "wafv2:ListResourcesForWebACL",
    "wafv2:ListWebACLs",
  ]

  remediation_actions = [
    "iam:UpdateAccountPasswordPolicy",
    "ec2:ModifyImageAttribute",
    "rds:ModifyDBSnapshotAttribute",
    "s3:PutBucketAcl",
    "ec2:RevokeSecurityGroupIngress",
  ]
}

resource "random_string" "external_id" {
  length  = 32
  upper   = true
  lower   = true
  numeric = true
  special = false
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "PrismaCloudAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.prisma_cloud_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

data "aws_iam_policy_document" "readonly" {
  statement {
    sid       = "PrismaCloudReadOnly"
    effect    = "Allow"
    actions   = local.readonly_actions
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "remediation" {
  count = var.read_write ? 1 : 0

  statement {
    sid       = "PrismaCloudRemediation"
    effect    = "Allow"
    actions   = local.remediation_actions
    resources = ["*"]
  }
}

resource "aws_iam_role" "prisma_cloud" {
  name                 = var.role_name
  description          = "Cross-account role assumed by Prisma Cloud for security monitoring and compliance enforcement."
  assume_role_policy   = data.aws_iam_policy_document.assume_role.json
  max_session_duration = 3600

  tags = {
    Name   = var.role_name
    Region = var.aws_region
  }
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = local.security_audit_policy_arn
}

resource "aws_iam_role_policy" "readonly" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.readonly.json
}

resource "aws_iam_role_policy" "remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.id
  policy = data.aws_iam_policy_document.remediation[0].json
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "development-be-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_name" {
  description = "Name of the public subnet"
  type        = string
  default     = "development-be-public-subnet"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_name" {
  description = "Name of the private subnet"
  type        = string
  default     = "development-be-private-subnet"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

variable "internet_gateway_name" {
  description = "Name of the internet gateway"
  type        = string
  default     = "development-be-ig"
}

variable "public_route_table_name" {
  description = "Name of the public route table"
  type        = string
  default     = "development-be-public-rt"
}

variable "security_group_name" {
  description = "Name of the security group"
  type        = string
  default     = "http_access"
}

variable "security_group_tag" {
  description = "Name tag applied to the security group"
  type        = string
  default     = "development-be-sg"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet_name
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = var.private_subnet_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.internet_gateway_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.public_route_table_name
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = var.security_group_name
  description = "Allow SSH from within the VPC and HTTP from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Restrict all outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = var.security_group_tag
  }
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Determines whether resources will be created (affects all resources)"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of additional tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "topic_tags" {
  description = "A map of additional tags to add to the topic"
  type        = map(string)
  default     = {}
}

variable "name" {
  description = "The name of the SNS topic"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether `name` is used as a prefix"
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "The SNS delivery policy"
  type        = string
  default     = null
}

variable "application_feedback" {
  description = "The application feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = any
  default     = {}
}

variable "firehose_feedback" {
  description = "The Firehose feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = any
  default     = {}
}

variable "http_feedback" {
  description = "The HTTP feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = any
  default     = {}
}

variable "lambda_feedback" {
  description = "The Lambda feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = any
  default     = {}
}

variable "sqs_feedback" {
  description = "The SQS feedback configuration (failure_role_arn, success_role_arn, success_sample_rate)"
  type        = any
  default     = {}
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "The signature version corresponds to the hashing algorithm used while creating the signature of the notifications. Ignored when `fifo_topic` is true"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: `PassThrough`, `Active`"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Boolean indicating whether or not to enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "fifo_throughput_scope" {
  description = "Enables a FIFO topic to be able to publish messages at a higher throughput. Valid values: `Topic`, `MessageGroup`"
  type        = string
  default     = null
}

variable "archive_policy" {
  description = "The archive policy for the SNS topic"
  type        = string
  default     = null
}

variable "data_protection_policy" {
  description = "A JSON policy string of the data protection policy. `fifo_topic` must be false and will be ignored if true"
  type        = string
  default     = null
}

variable "create_topic_policy" {
  description = "Determines whether a topic policy will be created"
  type        = bool
  default     = true
}

variable "enable_default_topic_policy" {
  description = "Determines whether the default topic policy will be created"
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "An external policy to be used as the topic policy when `create_topic_policy` is false"
  type        = string
  default     = null
}

variable "source_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document"
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document. Statements defined in override_policy_documents must have a sid"
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements for custom permission usage"
  type        = any
  default     = {}
}

variable "create_subscription" {
  description = "Determines whether subscriptions will be created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscriptions to create"
  type        = any
  default     = {}
}

################################################################################
# Data Sources
################################################################################

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid    = "DefaultTopicPolicy"
      effect = "Allow"

      actions = [
        "SNS:GetTopicAttributes",
        "SNS:SetTopicAttributes",
        "SNS:AddPermission",
        "SNS:RemovePermission",
        "SNS:DeleteTopic",
        "SNS:Subscribe",
        "SNS:ListSubscriptionsByTopic",
        "SNS:Publish",
      ]

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"

        values = [data.aws_caller_identity.current.account_id]
      }

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      resources = [aws_sns_topic.this[0].arn]
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

################################################################################
# SNS Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name         = var.use_name_prefix ? null : var.name
  name_prefix  = var.use_name_prefix ? "${var.name}-" : null
  display_name = var.display_name

  delivery_policy = var.delivery_policy

  application_success_feedback_role_arn    = try(var.application_feedback.success_role_arn, null)
  application_success_feedback_sample_rate = try(var.application_feedback.success_sample_rate, null)
  application_failure_feedback_role_arn    = try(var.application_feedback.failure_role_arn, null)

  firehose_success_feedback_role_arn    = try(var.firehose_feedback.success_role_arn, null)
  firehose_success_feedback_sample_rate = try(var.firehose_feedback.success_sample_rate, null)
  firehose_failure_feedback_role_arn    = try(var.firehose_feedback.failure_role_arn, null)

  http_success_feedback_role_arn    = try(var.http_feedback.success_role_arn, null)
  http_success_feedback_sample_rate = try(var.http_feedback.success_sample_rate, null)
  http_failure_feedback_role_arn    = try(var.http_feedback.failure_role_arn, null)

  lambda_success_feedback_role_arn    = try(var.lambda_feedback.success_role_arn, null)
  lambda_success_feedback_sample_rate = try(var.lambda_feedback.success_sample_rate, null)
  lambda_failure_feedback_role_arn    = try(var.lambda_feedback.failure_role_arn, null)

  sqs_success_feedback_role_arn    = try(var.sqs_feedback.success_role_arn, null)
  sqs_success_feedback_sample_rate = try(var.sqs_feedback.success_sample_rate, null)
  sqs_failure_feedback_role_arn    = try(var.sqs_feedback.failure_role_arn, null)

  kms_master_key_id = var.kms_master_key_id

  signature_version = var.fifo_topic ? null : var.signature_version

  tracing_config = var.tracing_config

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  fifo_throughput_scope       = var.fifo_throughput_scope

  archive_policy = var.archive_policy

  tags = merge(var.tags, var.topic_tags)
}

################################################################################
# SNS Topic Policy
################################################################################

resource "aws_sns_topic_policy" "this" {
  count = var.create && (var.create_topic_policy || var.topic_policy != null) ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? (var.topic_policy != null ? var.topic_policy : data.aws_iam_policy_document.this[0].json) : var.topic_policy
}

################################################################################
# SNS Topic Data Protection Policy
################################################################################

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

################################################################################
# SNS Topic Subscriptions
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create && var.create_subscription }

  topic_arn = aws_sns_topic.this[0].arn

  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint                        = try(each.value.endpoint, null)
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, null)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  protocol                        = try(each.value.protocol, null)
  raw_message_delivery            = try(each.value.raw_message_delivery, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
}

###############################################################################
# Feature-complete Amazon S3 bucket module
#
# Supports: dynamic naming, encryption (module-managed or external KMS key),
# website hosting, access control (ACL/grants/policy), lifecycle management,
# CORS, logging, transfer acceleration, cross-region replication with an
# auto-created IAM role, and S3 Object Lock.
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Explicit bucket name. When null, a name is generated from the \"corebucket-\" prefix plus a random hex string."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, appends an additional random hex string suffix to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who pays for the download and request fees. Either BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Enable default server-side encryption on the bucket (always aws:kms)."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing customer-managed KMS key. When empty, the module creates and rotates its own customer-managed key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket versioning configuration."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Delete all objects from the bucket so the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g. private, log-delivery-write). Cannot be combined with grants."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of access control grants applied through an access control policy."
  type        = list(any)
  default     = []
}

variable "policy" {
  description = "JSON bucket policy document."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to the bucket."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status: Enabled or Suspended. Null disables configuration."
  type        = string
  default     = null
}

variable "logging" {
  description = "Access logging configuration with target_bucket and target_prefix."
  type        = any
  default     = null
}

variable "website" {
  description = "Static website configuration supporting index_document, error_document, redirect_all_requests_to and routing_rules."
  type        = any
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules."
  type        = list(any)
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules."
  type        = list(any)
  default     = []
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock" {
  description = "Object Lock default retention configuration (mode plus days or years)."
  type        = any
  default     = null
}

variable "replication_rules" {
  description = "List of cross-region replication rules."
  type        = list(any)
  default     = []
}

variable "replication_role" {
  description = "ARN of an existing IAM role for replication. When empty, the module creates a dedicated role and policy."
  type        = string
  default     = ""
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Dynamic naming
###############################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "name_suffix" {
  byte_length = 4
}

locals {
  base_bucket_name  = (var.bucket_name != null && var.bucket_name != "") ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}"
  final_bucket_name = var.prefix ? "${local.base_bucket_name}-${random_id.name_suffix.hex}" : local.base_bucket_name

  object_lock_enabled = var.object_lock_enabled || var.object_lock != null
  versioning_enabled  = var.versioning || local.object_lock_enabled || length(var.replication_rules) > 0

  create_kms_key     = var.encryption && var.kms_key == ""
  effective_kms_key  = local.create_kms_key ? aws_kms_key.this[0].arn : (var.kms_key != "" ? var.kms_key : null)
  replication_role_arn = var.replication_role != "" ? var.replication_role : (length(aws_iam_role.replication) > 0 ? aws_iam_role.replication[0].arn : null)

  replication_policy_statements = concat(
    [
      {
        Sid      = "ListBucketAndGetReplicationConfiguration"
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Sid    = "ReadSourceObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersion"
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Sid    = "ReplicateToDestinationBuckets"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = [for r in var.replication_rules : "${r.destination_bucket_arn}/*"]
      }
    ],
    (var.encryption && local.effective_kms_key != null) ? [
      {
        Sid      = "KmsAccessForReplication"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey", "kms:ReEncryptFrom", "kms:ReEncryptTo"]
        Resource = [local.effective_kms_key]
      }
    ] : []
  )
}

###############################################################################
# Customer-managed KMS key (created only when no external key is supplied)
###############################################################################

resource "aws_kms_key" "this" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer-managed KMS key for S3 bucket ${local.final_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/s3-${local.final_bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.final_bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count  = (var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_caller_identity.current.account_id
      }

      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission

          grantee {
            type          = try(grant.value.type, null)
            id            = try(grant.value.id, null)
            uri           = try(grant.value.uri, null)
            email_address = try(grant.value.email_address, null)
            display_name  = try(grant.value.display_name, null)
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_logging" "this" {
  count         = var.logging != null ? 1 : 0
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, "")
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  routing_rules = try(var.website.routing_rules, null)
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = [1]
        content {
          prefix = try(rule.value.prefix, try(rule.value.filter.prefix, null))

          dynamic "tag" {
            for_each = try(rule.value.filter.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock.mode
      days  = try(var.object_lock.days, null)
      years = try(var.object_lock.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Cross-region replication
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      filter {
        prefix = try(rule.value.prefix, null)
      }

      delete_marker_replication {
        status = try(rule.value.delete_marker_replication_status, "Disabled")
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = try(rule.value.storage_class, null)
        account       = try(rule.value.destination_account, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role == "" ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.final_bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "s3.amazonaws.com" }
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role == "" ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.final_bucket_name}"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.replication_policy_statements
  })
}

###############################################################################
# Outputs
###############################################################################

output "bucket_name" {
  description = "The resolved name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "The region-specific domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for default bucket encryption."
  value       = local.effective_kms_key
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for replication."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "random_suffix" {
  description = "Whether to append a randomly generated suffix to the bucket, IAM user, and IAM policy names."
  type        = bool
  default     = true
}

variable "random_suffix_length" {
  description = "Length of the randomly generated lowercase alphanumeric suffix."
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "zedcloud"
}

variable "iam_username" {
  description = "Base name of the IAM user."
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name of the IAM policy."
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload a local image file to the S3 bucket."
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Name of the local image file to upload from the execution directory."
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Folder (key prefix) within the bucket where the image is uploaded."
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prefix the uploaded object key with the s3_folder path."
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user, access key, policy, and policy attachment."
  type        = bool
  default     = true
}

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.random_suffix_length
  special = false
  upper   = false
  numeric = true
}

locals {
  suffix              = var.random_suffix ? random_string.suffix[0].result : ""
  resolved_bucket     = var.random_suffix ? "${var.bucket_name}-${local.suffix}" : var.bucket_name
  resolved_iam_user   = var.random_suffix ? "${var.iam_username}-${local.suffix}" : var.iam_username
  resolved_iam_policy = var.random_suffix ? "${var.iam_policy_name}-${local.suffix}" : var.iam_policy_name
}

resource "aws_kms_key" "s3" {
  description             = "Customer managed KMS key for the ${local.resolved_bucket} S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = local.resolved_bucket
  }
}

resource "aws_s3_bucket" "main" {
  bucket        = local.resolved_bucket
  force_destroy = true

  tags = {
    Name = local.resolved_bucket
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.main.id
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  source = "${path.module}/${var.image_filename}"
  etag   = filemd5("${path.module}/${var.image_filename}")
}

resource "aws_iam_user" "s3" {
  count = var.create_iam_user ? 1 : 0

  name          = local.resolved_iam_user
  path          = "/"
  force_destroy = true
}

resource "aws_iam_access_key" "s3" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.s3[0].name
}

data "aws_iam_policy_document" "s3_read" {
  statement {
    sid       = "ListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.main.arn]
  }

  statement {
    sid       = "ReadObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.main.arn}/*"]
  }
}

resource "aws_iam_policy" "s3_read" {
  count = var.create_iam_user ? 1 : 0

  name        = local.resolved_iam_policy
  description = "Read-only access to the ${local.resolved_bucket} S3 bucket"
  policy      = data.aws_iam_policy_document.s3_read.json
}

resource "aws_iam_user_policy_attachment" "s3_read" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.s3[0].name
  policy_arn = aws_iam_policy.s3_read[0].arn
}

###############################################################################
# Variables
###############################################################################

variable "default_tags" {
  description = "Default tags applied to every resource via the provider default_tags map."
  type        = map(string)
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

###############################################################################
# Data sources
###############################################################################

# Static AZ metadata lookup used to spread subnets across the region.
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Local values
###############################################################################

locals {
  # Name derived from the project and environment tags.
  name = "${var.default_tags.Project}-${var.default_tags.Environment}"

  vpc_cidr = "10.14.0.0/16"

  # First three available availability zones in the region.
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Number of public and private subnets to create.
  subnet_count = 3
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.default_tags, {
    Name = "${local.name}-vpc"
  })
}

###############################################################################
# Internet gateway
###############################################################################

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name}-igw"
  })
}

###############################################################################
# Public subnets
###############################################################################

resource "aws_subnet" "public" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "${local.name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

###############################################################################
# Public route table and association
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = local.subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway (single, in the first public subnet) with Elastic IP
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${local.name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.default_tags, {
    Name = "${local.name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

###############################################################################
# Private subnets
###############################################################################

resource "aws_subnet" "private" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index + local.subnet_count)
  availability_zone = local.azs[count.index]

  tags = merge(var.default_tags, {
    Name = "${local.name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# Private route table and association
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this.id
}

resource "aws_route_table_association" "private" {
  count = local.subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Input variables
###############################################################################

variable "create_bucket" {
  description = "Controls if the S3 bucket and all associated resources should be created."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. If omitted, a random, unique name is assigned."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "The canned ACL to apply to the bucket. Set to null to disable. Defaults to private."
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to the bucket and related resources."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Sets the accelerate configuration of the bucket. Valid values: Enabled, Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer. Valid values: BucketOwner, Requester."
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerPreferred, ObjectWriter, BucketOwnerEnforced."
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Map of website configuration (index_document, error_document, redirect_all_requests_to, routing_rules)."
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing CORS rules."
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map containing versioning configuration (enabled, mfa_delete)."
  type        = any
  default     = { enabled = true }
}

variable "logging" {
  description = "Map containing access logging configuration (target_bucket, target_prefix)."
  type        = any
  default     = {}
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if an ELB log delivery policy should be attached to the bucket."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if an ALB/NLB log delivery write and ACL check policy should be attached to the bucket."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if a policy denying non-SSL (insecure) transport should be attached to the bucket."
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Controls if a custom bucket policy (var.policy) should be attached."
  type        = bool
  default     = false
}

variable "policy" {
  description = "JSON bucket policy document string to attach when attach_policy is true."
  type        = string
  default     = null
}

variable "attach_public_policy" {
  description = "Controls if an S3 public access block should be attached to the bucket."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "lifecycle_rule" {
  description = "List of maps containing object lifecycle rules."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration (role_arn, rules)."
  type        = any
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration. When empty a customer-managed KMS key is created and used."
  type        = any
  default     = {}
}

variable "object_lock_enabled" {
  description = "Whether S3 object lock should be enabled for the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Map containing object lock configuration (mode, days, years)."
  type        = any
  default     = {}
}

###############################################################################
# Local values
###############################################################################

locals {
  create_bucket = var.create_bucket

  # Object ownership is managed whenever it is explicitly requested or when a
  # canned ACL is applied, so that ACL usage remains supported on accounts
  # whose default is BucketOwnerEnforced.
  manage_object_ownership = local.create_bucket && (var.control_object_ownership || var.acl != null)
  object_ownership_value  = var.control_object_ownership ? var.object_ownership : "ObjectWriter"

  create_acl = local.create_bucket && var.acl != null && local.object_ownership_value != "BucketOwnerEnforced"

  # When no server-side encryption configuration is supplied the module creates
  # its own customer-managed KMS key and applies it as the default SSE-KMS key.
  create_kms_key     = local.create_bucket && length(var.server_side_encryption_configuration) == 0
  kms_key_arn        = one(aws_kms_key.this[*].arn)
  sse_algorithm      = length(var.server_side_encryption_configuration) > 0 ? try(var.server_side_encryption_configuration.sse_algorithm, "aws:kms") : "aws:kms"
  sse_kms_key_id     = length(var.server_side_encryption_configuration) > 0 ? try(var.server_side_encryption_configuration.kms_master_key_id, null) : local.kms_key_arn
  bucket_key_enabled = length(var.server_side_encryption_configuration) > 0 ? try(var.server_side_encryption_configuration.bucket_key_enabled, null) : true

  # Combined bucket policy.
  attach_policy_combined = local.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    (var.attach_policy && var.policy != null && var.policy != "")
  )

  # Cross-region replication.
  create_replication      = local.create_bucket && length(var.replication_configuration) > 0
  create_replication_role = local.create_replication && try(var.replication_configuration.role_arn, null) == null
  replication_role_arn    = local.create_replication_role ? one(aws_iam_role.replication[*].arn) : try(var.replication_configuration.role_arn, null)

  # Object lock default retention.
  object_lock_config = length(var.object_lock_configuration) > 0 ? var.object_lock_configuration : { mode = "GOVERNANCE", days = 1, years = null }
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket              = var.bucket
  bucket_prefix       = var.bucket_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Customer-managed KMS key (created when no SSE configuration is supplied)
###############################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer-managed SSE-KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.tags
}

###############################################################################
# Server-side encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    bucket_key_enabled = local.bucket_key_enabled

    apply_server_side_encryption_by_default {
      kms_master_key_id = local.sse_kms_key_id
      sse_algorithm     = local.sse_algorithm
    }
  }
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(tobool(var.versioning.enabled), false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, null)
  }
}

###############################################################################
# Access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(var.logging) > 0 ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, "")
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(var.website) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  routing_rules = try(var.website.routing_rules, null)
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Object ownership controls
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.manage_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = local.object_ownership_value
  }
}

###############################################################################
# Canned ACL
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

###############################################################################
# Request payment
###############################################################################

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, null) != null ? [rule.value.transition] : []
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = try(transition.value.storage_class, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, null) != null ? [rule.value.noncurrent_version_transition] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = try(noncurrent_version_transition.value.storage_class, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Cross-region replication
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_replication_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_replication_role ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.this[0].arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name   = "s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_replication ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = try(var.replication_configuration.rules, [])
    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account, null)

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.encryption_configuration, null) != null ? [rule.value.destination.encryption_configuration] : []
          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [rule.value.destination.replication_time] : []
          content {
            status = try(replication_time.value.status, "Enabled")
            time {
              minutes = try(replication_time.value.minutes, 15)
            }
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [rule.value.destination.metrics] : []
          content {
            status = try(metrics.value.status, "Enabled")
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Object lock configuration
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = try(local.object_lock_config.mode, "GOVERNANCE")
      days  = try(local.object_lock_config.days, null)
      years = try(local.object_lock_config.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Combined bucket policy
###############################################################################

data "aws_iam_policy_document" "combined" {
  count = local.attach_policy_combined ? 1 : 0

  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid       = "ELBAccessLogDelivery"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "Service"
        identifiers = ["elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "AWSLogDeliveryWrite"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid       = "AWSLogDeliveryAclCheck"
      effect    = "Allow"
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.this[0].arn]

      principals {
        type        = "Service"
        identifiers = ["elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid     = "DenyInsecureTransport"
      effect  = "Deny"
      actions = ["s3:*"]

      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*",
      ]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  source_policy_documents = var.attach_policy && var.policy != null && var.policy != "" ? [var.policy] : []
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_policy_combined ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Public access block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket && var.attach_public_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

###############################################################################
# Variables
###############################################################################

variable "awsRegion" {
  description = "AWS region to deploy the network stack into."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix used to name and tag all resources."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag applied to all resources."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names to distinguish builds."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched in the public subnets receive a public IP."
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "First availability zone. Defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Second availability zone. Defaults to the second available AZ, or to awsAz1 when it is set."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in the first AZ."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in the second AZ."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in the first AZ."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in the second AZ."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in the first AZ."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in the second AZ."
  type        = string
  default     = "10.1.120.0/24"
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  az1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  az2 = var.awsAz2 != null ? var.awsAz2 : (var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1])

  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Project     = var.projectPrefix
    Owner       = var.resourceOwner
    BuildSuffix = var.buildSuffix
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

###############################################################################
# Subnets - Public
###############################################################################

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
    Tier = "public"
  })
}

###############################################################################
# Subnets - Management
###############################################################################

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-a"
    Tier = "management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-b"
    Tier = "management"
  })
}

###############################################################################
# Subnets - Private
###############################################################################

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

###############################################################################
# Route Table (main)
###############################################################################

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rtb"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

variable "name" {
  description = "Base name used for all named resources."
  type        = string
  default     = "benchmark"
}

variable "region" {
  description = "AWS region in which resources are provisioned."
  type        = string
  default     = "us-east-1"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create."
  type        = number
  default     = 1
}

locals {
  vpc_cidr            = "10.0.0.0/16"
  subnet_newbits      = 8
  subnet_count        = 2
  subnet_cidrs        = [for i in range(local.subnet_count) : cidrsubnet(local.vpc_cidr, local.subnet_newbits, i)]
  listener_rule_start = 100
}

data "aws_availability_zones" "available" {
  region = var.region
  state  = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "this" {
  count             = local.subnet_count
  vpc_id            = aws_vpc.this.id
  cidr_block        = local.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-subnet-${count.index}"
  }
}

resource "aws_security_group" "alb" {
  name        = "${var.name}-alb-sg"
  description = "Allow all ingress and egress traffic within the VPC CIDR"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "All traffic to within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.name}-alb-sg"
  }
}

resource "aws_lb" "this" {
  name                       = "${var.name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.this[*].id

  tags = {
    Name = var.name
  }
}

resource "aws_lb_target_group" "this" {
  name     = "${var.name}-tg"
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.this.id

  health_check {
    enabled             = true
    port                = 8081
    protocol            = "HTTP"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${var.name}-tg"
  }
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "this" {
  private_key_pem = tls_private_key.this.private_key_pem

  subject {
    common_name  = "${var.name}.internal"
    organization = var.name
  }

  validity_period_hours = 8760
  is_ca_certificate     = true

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "this" {
  private_key       = tls_private_key.this.private_key_pem
  certificate_body  = tls_self_signed_cert.this.cert_pem
  certificate_chain = tls_self_signed_cert.this.cert_pem

  tags = {
    Name = "${var.name}-cert"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.this.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.this.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  tags = {
    Name = "${var.name}-https-listener"
  }
}

resource "aws_lb_listener_rule" "static" {
  count        = var.listener_rule_count
  listener_arn = aws_lb_listener.https.arn
  priority     = local.listener_rule_start + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.name}-rule-${count.index}"
  }
}

###############################################################################
# Variables
###############################################################################

variable "trail_name" {
  description = "Name of the CloudTrail trail used for centralized audit logging."
  type        = string
  default     = "management_trail"
}

variable "is_organization_trail" {
  description = "Whether the trail should be created as an organization trail."
  type        = bool
  default     = false
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group that receives the CloudTrail events."
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  description = "Whether to provision and use a customer managed KMS key for the trail and log bucket."
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the customer managed CloudTrail KMS key."
  type        = string
  default     = "alias/cloudtrail_key"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  bucket_name = "cloudtrail-bucket-${random_string.bucket_suffix.result}"

  tags = {
    ManagedBy = "Terraform"
    Purpose   = "CloudTrailAuditLogging"
  }
}

###############################################################################
# Random suffix for the globally unique CloudTrail bucket name
###############################################################################

resource "random_string" "bucket_suffix" {
  length  = 12
  upper   = false
  lower   = false
  numeric = true
  special = false
}

###############################################################################
# Customer managed KMS key (conditional)
###############################################################################

data "aws_iam_policy_document" "kms" {
  count = var.enable_kms_encryption ? 1 : 0

  # Account root retains full administrative control over the key.
  statement {
    sid    = "AllowAccountRootAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # The identity applying this configuration is allowed to administer the key.
  statement {
    sid    = "AllowCallerIdentityAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  # CloudTrail may generate data keys and describe the key to encrypt log files.
  statement {
    sid    = "AllowCloudTrailDataKeyGenerationAndDescription"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  # S3 may use the key to encrypt the trail log bucket.
  statement {
    sid    = "AllowS3UseOfKeyForBucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]
  }

  # CloudWatch Logs may use the key to encrypt the trail log group.
  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]
  }

  # Account-wide rights to decrypt the audit logs.
  statement {
    sid    = "AllowAccountWideLogDecryption"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:ReEncryptFrom",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "Customer managed KMS key for CloudTrail trail and audit log bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = local.tags
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

###############################################################################
# S3 bucket that receives the CloudTrail log files
###############################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = false

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
    }

    bucket_key_enabled = var.enable_kms_encryption
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

###############################################################################
# CloudWatch Log Group for streaming CloudTrail events
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0

  kms_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role + inline policy allowing CloudTrail to write to CloudWatch Logs
###############################################################################

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "allow_access_to_cw_logs" {
  statement {
    sid    = "AllowCreateLogStreamAndPutLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "allow_access_to_cw_logs" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.allow_access_to_cw_logs.json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "management" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  kms_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  tags = local.tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.allow_access_to_cw_logs,
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

variable "namespace" {
  description = "Optional namespace prepended to the repository name as a path prefix (frigga style)."
  type        = string
  default     = ""
}

variable "repository_name" {
  description = "Name of the ECR repository. When null or empty a random pet name is generated."
  type        = string
  default     = "ecr"
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository (MUTABLE or IMMUTABLE)."
  type        = string
  default     = "IMMUTABLE"
}

variable "image_scan_on_push" {
  description = "Whether images are scanned for vulnerabilities after being pushed to the repository."
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "Lifecycle policy document as a JSON string. When null, no lifecycle policy is created."
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "List of additional AWS account IDs granted read access to the repository."
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_pet" "this" {
  count     = (var.repository_name == null || var.repository_name == "") ? 1 : 0
  separator = "-"
}

locals {
  generate_name   = var.repository_name == null || var.repository_name == ""
  generated_name  = one(random_pet.this[*].id)
  name            = coalesce(var.repository_name, local.generated_name, "ecr")
  local_name      = join("-", compact([var.namespace, local.name]))
  repository_name = join("/", compact([var.namespace, local.name]))
}

resource "aws_ecr_repository" "this" {
  name                 = local.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.image_scan_on_push
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repository_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "read" {
  statement {
    sid    = "ECRRead"
    effect = "Allow"

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]

    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "read" {
  name        = "${local.local_name}-ecr-read"
  description = "Read access to the ${local.repository_name} ECR repository"
  policy      = data.aws_iam_policy_document.read.json
}

data "aws_iam_policy_document" "write" {
  statement {
    sid    = "ECRWrite"
    effect = "Allow"

    actions = [
      "ecr:CompleteLayerUpload",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart",
    ]

    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "write" {
  name        = "${local.local_name}-ecr-write"
  description = "Write access to the ${local.repository_name} ECR repository"
  policy      = data.aws_iam_policy_document.write.json
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCrossAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = concat(
            ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"],
            [for account_id in var.trusted_accounts : "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"]
          )
        }
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListImages",
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "az_count" {
  description = "Number of available availability zones in the region to spread the enabled subnet tiers across."
  type        = number
  default     = 2

  validation {
    condition     = var.az_count >= 1 && var.az_count <= 6
    error_message = "The az_count value must be between 1 and 6."
  }
}

variable "enable_public_subnets" {
  description = "Toggle provisioning of the public subnet tier."
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Toggle provisioning of the NAT subnet tier."
  type        = bool
  default     = false
}

variable "enable_private_subnets" {
  description = "Toggle provisioning of the private subnet tier."
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# Static provider metadata (availability zone discovery)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Derived networking calculations
# ---------------------------------------------------------------------------

locals {
  name_prefix = "dynamic-vpc"

  # Number of subnet tiers that are currently enabled.
  enabled_tier_count = (
    (var.enable_public_subnets ? 1 : 0) +
    (var.enable_nat_subnets ? 1 : 0) +
    (var.enable_private_subnets ? 1 : 0)
  )

  # Total number of subnets that will be carved out of the VPC CIDR.
  total_subnet_count = local.enabled_tier_count * var.az_count

  # Log-based bitwise split: derive the number of additional prefix bits
  # required to evenly divide the VPC CIDR into `total_subnet_count` subnets.
  # (A tiny epsilon guards the ceil() against floating point representation
  # error for exact powers of two.)
  subnet_newbits = ceil(log(max(local.total_subnet_count, 1), 2) - 1e-9)

  # The requested number of AZs, selected from the region's available zones.
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  # Offset CIDR calculations: each tier starts where the previous one ended so
  # the subnet ranges never overlap regardless of which tiers are enabled.
  nat_offset     = var.enable_public_subnets ? var.az_count : 0
  private_offset = local.nat_offset + (var.enable_nat_subnets ? var.az_count : 0)

  common_tags = {
    Project   = local.name_prefix
    ManagedBy = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })
}

# Restrict the automatically created default security group of the VPC.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default"
  })
}

# ---------------------------------------------------------------------------
# Subnet tiers (CIDRs derived via cidrsubnet with log-based bit splitting)
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.subnet_newbits, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.subnet_newbits, count.index + local.nat_offset)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-${local.azs[count.index]}"
    Tier = "nat"
  })
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.subnet_newbits, count.index + local.private_offset)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# Public tier: Internet Gateway, security group, routing
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "${local.name_prefix}-public"
  description = "Security group for the public subnet tier."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public"
  })
}

# Restrict outbound traffic to the VPC CIDR (all protocols) instead of the
# entire internet, which would allow unrestricted egress to any address.
resource "aws_vpc_security_group_egress_rule" "public_vpc" {
  count = var.enable_public_subnets ? 1 : 0

  security_group_id = aws_security_group.public[0].id
  ip_protocol       = "-1"
  cidr_ipv4         = var.vpc_cidr
  description       = "Allow all outbound traffic within the VPC for the public tier."
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public"
  })
}

# Internet route. The local VPC CIDR route is provisioned automatically by AWS
# for every route table, so it is present alongside this internet route.
resource "aws_route" "public_internet" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public tier subnets."
  value       = aws_subnet.public[*].id
}

output "nat_subnet_ids" {
  description = "IDs of the NAT tier subnets."
  value       = aws_subnet.nat[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private tier subnets."
  value       = aws_subnet.private[*].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

########################################
# Variables
########################################

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC."
  type        = string
  default     = "demo-dataflow"
}

variable "region" {
  description = "AWS region the environment is deployed into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks assigned to the public subnets."
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks assigned to the private subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_pair_name" {
  description = "Name of the EC2 key pair used to access the bastion host."
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "Instance type for the bastion host."
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Whether the bastion EBS volumes are optimized."
  type        = bool
  default     = false
}

variable "allowed_ssh_cidrs" {
  description = "CIDR blocks permitted to reach the bastion host over SSH."
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "tags" {
  description = "Base tagging map applied to every resource."
  type        = map(string)
  default = {
    Project     = "demo"
    Environment = "poc"
    ManagedBy   = "terraform"
  }
}

variable "custom_tags" {
  description = "Additional custom tags merged into the common tag set."
  type        = map(string)
  default     = {}
}

########################################
# Locals
########################################

locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = merge(
    var.tags,
    var.custom_tags,
    {
      Project     = var.project
      Environment = var.environment
      Region      = var.region
    }
  )
}

########################################
# Data Sources
########################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

########################################
# Networking
########################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demogwInternet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demoPublicRouteTable"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

########################################
# SSH Bastion
########################################

resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_pair_name
  public_key = tls_private_key.bastion.public_key_openssh

  tags = merge(local.common_tags, {
    Name = var.key_pair_name
  })
}

resource "aws_security_group" "bastion" {
  name        = "${local.name_prefix}-bastion-sg"
  description = "Security group controlling SSH access to the bastion host."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "bastion_ssh" {
  security_group_id = aws_security_group.bastion.id
  description       = "Restricted SSH access to the bastion host."
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  cidr_ipv4         = var.allowed_ssh_cidrs[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion-ssh"
  })
}

resource "aws_vpc_security_group_egress_rule" "bastion_outbound_https" {
  security_group_id = aws_security_group.bastion.id
  description       = "Permit HTTPS egress within the VPC for bastion management traffic."
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
  cidr_ipv4         = var.vpc_cidr

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion-https"
  })
}

resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = var.bastion_instance_type
  subnet_id              = aws_subnet.public[0].id
  key_name               = aws_key_pair.bastion.key_name
  vpc_security_group_ids = [aws_security_group.bastion.id]
  ebs_optimized          = var.ebs_optimized

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 30
    encrypted             = true
    delete_on_termination = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion"
    Role = "bastion"
  })
}

resource "aws_eip" "bastion" {
  domain   = "vpc"
  instance = aws_instance.bastion.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion-eip"
  })
}

###############################################################################
# Variables
###############################################################################

variable "secondary_region" {
  description = "AWS region used for the cross-region backup vault and cross-region copy actions."
  type        = string
  default     = "us-west-2"
}

variable "cross_account_copy_enabled" {
  description = "Whether to enable the cross-account copy action to the destination account."
  type        = bool
  default     = true
}

variable "cross_account_destination_account_id" {
  description = "Destination AWS account ID for cross-account backup copies."
  type        = string
  default     = "433568766270"
}

variable "cross_account_vault_name" {
  description = "Name of the backup vault in the destination account for cross-account copies."
  type        = string
  default     = "cross-account-backup-vault"
}

variable "enable_daily_backup" {
  description = "Whether to create the daily backup plan."
  type        = bool
  default     = true
}

variable "excluded_rds_instance_arns" {
  description = "List of RDS instance ARNs to exclude from all backup selections."
  type        = list(string)
  default     = []
}

###############################################################################
# Provider aliases (default provider is supplied by the deployment harness)
###############################################################################

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  # Matches every RDS database in this account (Backup plans are regional).
  rds_resources = ["arn:${local.partition}:rds:*:${local.account_id}:db:*"]

  # Backup vault that lives in the destination account.
  cross_account_vault_arn = "arn:${local.partition}:backup:${var.secondary_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_vault_name}"
}

###############################################################################
# KMS keys (customer managed, rotation enabled)
###############################################################################

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt AWS Backup vaults."
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key used to encrypt the cross-region AWS Backup vault."
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

###############################################################################
# Backup vaults (KMS encrypted)
###############################################################################

resource "aws_backup_vault" "daily" {
  name        = "daily-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "weekly" {
  name        = "weekly-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "monthly" {
  name        = "monthly-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "yearly" {
  name        = "yearly-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "cross_region" {
  provider    = aws.secondary
  name        = "cross-region-backup-vault"
  kms_key_arn = aws_kms_key.secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role used by AWS Backup
###############################################################################

resource "aws_iam_role" "backup" {
  name = "aws-backup-rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSBackupAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_service" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_iam_role_policy" "backup_kms_and_copy" {
  name = "aws-backup-kms-and-copy"
  role = aws_iam_role.backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BackupVaultKmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = [
          aws_kms_key.backup.arn,
          aws_kms_key.secondary.arn
        ]
      },
      {
        Sid    = "CopyIntoBackupVaults"
        Effect = "Allow"
        Action = [
          "backup:CopyIntoBackupVault"
        ]
        Resource = [
          aws_backup_vault.cross_region.arn,
          local.cross_account_vault_arn
        ]
      }
    ]
  })
}

###############################################################################
# Daily backup plan (2 AM UTC, 7 day retention) - optional
###############################################################################

resource "aws_backup_plan" "daily" {
  count = var.enable_daily_backup ? 1 : 0
  name  = "daily-backup-plan"

  rule {
    rule_name         = "daily"
    target_vault_name = aws_backup_vault.daily.name
    schedule          = "cron(0 2 * * ? *)"

    lifecycle {
      delete_after = 7
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn

      lifecycle {
        delete_after = 7
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_copy_enabled ? [1] : []

      content {
        destination_vault_arn = local.cross_account_vault_arn

        lifecycle {
          delete_after = 7
        }
      }
    }
  }
}

resource "aws_backup_selection" "daily" {
  count = var.enable_daily_backup ? 1 : 0

  name         = "daily-rds-selection"
  plan_id      = aws_backup_plan.daily[0].id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = local.rds_resources
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Weekly backup plan (Saturdays 2 AM UTC, 30 day retention)
###############################################################################

resource "aws_backup_plan" "weekly" {
  name = "weekly-backup-plan"

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.weekly.name
    schedule          = "cron(0 2 ? * SAT *)"

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn

      lifecycle {
        delete_after = 30
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_copy_enabled ? [1] : []

      content {
        destination_vault_arn = local.cross_account_vault_arn

        lifecycle {
          delete_after = 30
        }
      }
    }
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly-rds-selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = local.rds_resources
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Monthly backup plan (1st of month 3 AM UTC, 365 day retention)
###############################################################################

resource "aws_backup_plan" "monthly" {
  name = "monthly-backup-plan"

  rule {
    rule_name         = "monthly"
    target_vault_name = aws_backup_vault.monthly.name
    schedule          = "cron(0 3 1 * ? *)"

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn

      lifecycle {
        delete_after = 365
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_copy_enabled ? [1] : []

      content {
        destination_vault_arn = local.cross_account_vault_arn

        lifecycle {
          delete_after = 365
        }
      }
    }
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly-rds-selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = local.rds_resources
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Yearly backup plan (January 1st 4 AM UTC, 2555 day retention)
###############################################################################

resource "aws_backup_plan" "yearly" {
  name = "yearly-backup-plan"

  rule {
    rule_name         = "yearly"
    target_vault_name = aws_backup_vault.yearly.name
    schedule          = "cron(0 4 1 1 ? *)"

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn

      lifecycle {
        delete_after = 2555
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_copy_enabled ? [1] : []

      content {
        destination_vault_arn = local.cross_account_vault_arn

        lifecycle {
          delete_after = 2555
        }
      }
    }
  }
}

resource "aws_backup_selection" "yearly" {
  name         = "yearly-rds-selection"
  plan_id      = aws_backup_plan.yearly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = local.rds_resources
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Account Password Policy
###############################################################################

variable "password_policy_allow_users_to_change_password" {
  description = "Allow IAM users to change their own password."
  type        = bool
  default     = true
}

variable "password_policy_hard_expiry" {
  description = "Require an administrator to reset an expired password (hard expiry)."
  type        = bool
  default     = false
}

variable "password_policy_max_password_age" {
  description = "Number of days before an IAM user password expires."
  type        = number
  default     = 90
}

variable "password_policy_minimum_password_length" {
  description = "Minimum number of characters required in an IAM user password."
  type        = number
  default     = 14
}

variable "password_policy_password_reuse_prevention" {
  description = "Number of previous passwords that cannot be reused."
  type        = number
  default     = 24
}

variable "password_policy_require_lowercase_characters" {
  description = "Require at least one lowercase character in an IAM user password."
  type        = bool
  default     = true
}

variable "password_policy_require_uppercase_characters" {
  description = "Require at least one uppercase character in an IAM user password."
  type        = bool
  default     = true
}

variable "password_policy_require_numbers" {
  description = "Require at least one number in an IAM user password."
  type        = bool
  default     = true
}

variable "password_policy_require_symbols" {
  description = "Require at least one symbol in an IAM user password."
  type        = bool
  default     = true
}

resource "aws_iam_account_password_policy" "baseline" {
  allow_users_to_change_password = var.password_policy_allow_users_to_change_password
  hard_expiry                    = var.password_policy_hard_expiry
  max_password_age               = var.password_policy_max_password_age
  minimum_password_length        = var.password_policy_minimum_password_length
  password_reuse_prevention      = var.password_policy_password_reuse_prevention
  require_lowercase_characters   = var.password_policy_require_lowercase_characters
  require_uppercase_characters   = var.password_policy_require_uppercase_characters
  require_numbers                = var.password_policy_require_numbers
  require_symbols                = var.password_policy_require_symbols
}

###############################################################################
# Naming
###############################################################################

locals {
  administrators_group_name = "administrators"
  developpers_group_name    = "developpers"
  prod_users_group_name     = "prod_users"

  administrators_policy_name = "administrators_policy"
  developpers_policy_name    = "developpers_policy"
  prod_users_policy_name     = "prod_users_policy"
}

###############################################################################
# IAM Groups
###############################################################################

resource "aws_iam_group" "administrators" {
  name = local.administrators_group_name
}

resource "aws_iam_group" "developpers" {
  name = local.developpers_group_name
}

resource "aws_iam_group" "prod_users" {
  name = local.prod_users_group_name
}

###############################################################################
# Customer Managed IAM Policies
###############################################################################

# Developers: full EC2 and RDS access scoped to resources tagged env = dev.
resource "aws_iam_policy" "developpers_policy" {
  name        = local.developpers_policy_name
  description = "Allows full EC2 and RDS access on resources tagged env=dev."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2AndRdsOnDevTaggedResources"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      },
    ]
  })
}

# Prod users: full EC2 and RDS access scoped to resources tagged env = preprod or prod.
resource "aws_iam_policy" "prod_users_policy" {
  name        = local.prod_users_policy_name
  description = "Allows full EC2 and RDS access on resources tagged env=preprod or env=prod."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2AndRdsOnProdTaggedResources"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      },
    ]
  })
}

# Administrators: broad access via NotAction, excluding iam/organizations/account,
# conditioned on resources not tagged security=high, plus explicit exceptions.
resource "aws_iam_policy" "administrators_policy" {
  name        = local.administrators_policy_name
  description = "Broad administrative access excluding IAM, Organizations and Account management, with explicit exceptions."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBroadAccessExceptIamOrganizationsAccount"
        Effect = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*",
        ]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid    = "AllowSpecificIamOrganizationsAccountActions"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions",
        ]
        Resource = "*"
      },
    ]
  })
}

###############################################################################
# Group -> Policy Attachments
###############################################################################

resource "aws_iam_group_policy_attachment" "administrators" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

variable "region" {
  description = "AWS region in which to deploy the networking stack"
  type        = string
  default     = "us-east-1"
}

variable "resource_prefix" {
  description = "Prefix applied to the Name tag of every resource"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "List of CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound rules for the shared network ACL attached to the private subnets"
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 1024
      to_port     = 65535
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound rules for the shared network ACL attached to the private subnets"
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.resource_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnets)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.resource_prefix}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnets)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnets)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.resource_prefix}-s3-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no    = ingress.value.rule_number
      action     = ingress.value.rule_action
      protocol   = ingress.value.protocol
      from_port  = ingress.value.from_port
      to_port    = ingress.value.to_port
      cidr_block = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no    = egress.value.rule_number
      action     = egress.value.rule_action
      protocol   = egress.value.protocol
      from_port  = egress.value.from_port
      to_port    = egress.value.to_port
      cidr_block = egress.value.cidr_block
    }
  }

  tags = {
    Name = "${var.resource_prefix}-private-acl"
  }
}

resource "aws_network_acl_association" "private" {
  count          = length(var.private_subnets)
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

###############################################################################
# Self-contained AWS VPC base networking module
#
# Implements Cloud Posse null-label context conventions (namespace / tenant /
# environment / stage / name / attributes / tags / delimiter / enabled / ...)
# inline so the module has no external module dependency.
#
# Features:
#   * Dual-stack IPv4/IPv6 VPC with IPAM allocation support
#   * Additional IPv4 / IPv6 CIDR block associations (map driven)
#   * Default resource management (default VPC / SG / route table / NACL)
#   * IPv4/IPv6 internet gateway + IPv6 egress-only internet gateway
###############################################################################

###############################################################################
# Cloud Posse null-label compatible context variables
###############################################################################

variable "enabled" {
  type        = bool
  default     = true
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate a tenant"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region or environment name"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role or stage"
}

variable "name" {
  type        = string
  default     = "vpc"
  description = "ID element. Usually the component or solution name"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "ID element. Additional attributes to add to the generated ID"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to all resources"
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = "Additional key-value pairs merged into the tags of all resources"
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter used between ID elements"
}

variable "label_order" {
  type        = list(string)
  default     = ["namespace", "tenant", "environment", "stage", "name", "attributes"]
  description = "The order in which to apply the ID elements"
}

variable "label_value_case" {
  type        = string
  default     = "lower"
  description = "Convert all labels to this case. Valid values are lower, upper, or none"
}

variable "id_length_limit" {
  type        = number
  default     = 0
  description = "Limit the length of the generated ID. 0 means no limit"
}

###############################################################################
# VPC variables
###############################################################################

variable "ipv4_primary_cidr_block" {
  type        = string
  default     = "11.0.0.0/16"
  description = "Primary IPv4 CIDR block for the VPC. Ignored when ipv4_ipam_pool_id is set"
}

variable "ipv4_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID used to allocate the primary IPv4 CIDR block"
}

variable "ipv4_ipam_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length of the primary IPv4 CIDR block allocated from IPAM"
}

variable "ipv6_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID used to allocate the primary IPv6 CIDR block"
}

variable "ipv6_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length of the primary IPv6 CIDR block allocated from IPAM"
}

variable "instance_tenancy" {
  type        = string
  default     = "default"
  description = "Tenancy option for instances launched into the VPC"
}

variable "enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "Whether DNS hostnames are enabled for the VPC"
}

variable "enable_dns_support" {
  type        = bool
  default     = true
  description = "Whether DNS resolution is supported for the VPC"
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  default     = true
  description = "Whether to request an automatically generated IPv6 CIDR block for the VPC"
}

variable "ipv4_cidr_block_associations" {
  type = map(object({
    ipv4_cidr_block     = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    timeouts = optional(object({
      create = optional(string)
      delete = optional(string)
    }))
  }))
  default     = {}
  description = "Additional IPv4 CIDR block associations keyed by name"
}

variable "ipv6_cidr_block_associations" {
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    timeouts = optional(object({
      create = optional(string)
      delete = optional(string)
    }))
  }))
  default     = {}
  description = "Additional IPv6 CIDR block associations keyed by name"
}

###############################################################################
# Default resource management variables
###############################################################################

variable "manage_default_vpc" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage the account default VPC"
}

variable "manage_default_security_group" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage a default security group"
}

variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = "When true the managed default security group has all ingress and egress rules removed"
}

variable "default_security_group_ingress" {
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string))
    ipv6_cidr_blocks = optional(list(string))
    description      = optional(string)
    self             = optional(bool)
  }))
  default     = []
  description = "Ingress rules for the managed default security group (ignored when deny_all is true)"
}

variable "default_security_group_egress" {
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string))
    ipv6_cidr_blocks = optional(list(string))
    description      = optional(string)
    self             = optional(bool)
  }))
  default     = []
  description = "Egress rules for the managed default security group (ignored when deny_all is true)"
}

variable "manage_default_route_table" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage the default route table"
}

variable "default_route_table_no_routes" {
  type        = bool
  default     = false
  description = "When true all routes are removed from the managed default route table"
}

variable "default_route_table_routes" {
  type = list(object({
    cidr_block                = optional(string)
    ipv6_cidr_block           = optional(string)
    gateway_id                = optional(string)
    nat_gateway_id            = optional(string)
    egress_only_gateway_id    = optional(string)
    transit_gateway_id        = optional(string)
    vpc_peering_connection_id = optional(string)
    network_interface_id      = optional(string)
  }))
  default     = []
  description = "Routes for the managed default route table (ignored when no_routes is true)"
}

variable "manage_default_network_acl" {
  type        = bool
  default     = false
  description = "Whether to adopt and manage the default network ACL"
}

variable "default_network_acl_deny_all" {
  type        = bool
  default     = false
  description = "When true all ingress and egress rules are removed from the managed default network ACL"
}

variable "default_network_acl_ingress" {
  type = list(object({
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    rule_no         = number
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default     = []
  description = "Ingress rules for the managed default network ACL (ignored when deny_all is true)"
}

variable "default_network_acl_egress" {
  type = list(object({
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    rule_no         = number
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default     = []
  description = "Egress rules for the managed default network ACL (ignored when deny_all is true)"
}

###############################################################################
# Internet gateway variables
###############################################################################

variable "internet_gateway_enabled" {
  type        = bool
  default     = true
  description = "Whether to create an IPv4/IPv6 internet gateway for the VPC"
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  default     = false
  description = "Whether to create an IPv6 egress-only internet gateway for the VPC"
}

###############################################################################
# Locals - Cloud Posse null-label compatible ID and tag generation
###############################################################################

locals {
  enabled = var.enabled

  label_value_map = {
    namespace   = var.namespace
    tenant      = var.tenant
    environment = var.environment
    stage       = var.stage
    name        = var.name
    attributes  = join(var.delimiter, var.attributes)
  }

  label_values = [
    for key in var.label_order : lookup(local.label_value_map, key, "")
    if lookup(local.label_value_map, key, null) != null && lookup(local.label_value_map, key, "") != ""
  ]

  generated_id = join(var.delimiter, local.label_values)

  id_cased = (
    var.label_value_case == "lower" ? lower(local.generated_id) :
    var.label_value_case == "upper" ? upper(local.generated_id) :
    local.generated_id
  )

  id = var.id_length_limit > 0 ? substr(local.id_cased, 0, min(var.id_length_limit, length(local.id_cased))) : local.id_cased

  generated_context_tags = {
    Namespace   = var.namespace
    Tenant      = var.tenant
    Environment = var.environment
    Stage       = var.stage
    Attributes  = join(var.delimiter, var.attributes)
  }

  context_tags = {
    for k, v in local.generated_context_tags : k => v
    if v != null && v != ""
  }

  tags = merge(
    { "Name" = local.id },
    local.context_tags,
    var.additional_tag_map,
    var.tags,
  )

  # IPAM selection flags
  use_ipam_v4         = var.ipv4_ipam_pool_id != null
  use_ipam_v6_primary = var.ipv6_ipam_pool_id != null
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  count = var.enabled ? 1 : 0

  cidr_block          = local.use_ipam_v4 ? null : var.ipv4_primary_cidr_block
  ipv4_ipam_pool_id   = local.use_ipam_v4 ? var.ipv4_ipam_pool_id : null
  ipv4_netmask_length = local.use_ipam_v4 ? var.ipv4_ipam_netmask_length : null

  assign_generated_ipv6_cidr_block = local.use_ipam_v6_primary ? false : var.assign_generated_ipv6_cidr_block
  ipv6_ipam_pool_id                = local.use_ipam_v6_primary ? var.ipv6_ipam_pool_id : null
  ipv6_netmask_length              = local.use_ipam_v6_primary ? var.ipv6_netmask_length : null

  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = local.tags
}

###############################################################################
# Additional IPv4 CIDR block associations
###############################################################################

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = var.enabled ? var.ipv4_cidr_block_associations : {}

  vpc_id = aws_vpc.this[0].id

  cidr_block          = each.value.ipv4_ipam_pool_id == null ? each.value.ipv4_cidr_block : null
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_ipam_pool_id != null ? each.value.ipv4_netmask_length : null

  dynamic "timeouts" {
    for_each = each.value.timeouts == null ? [] : [each.value.timeouts]
    content {
      create = try(timeouts.value.create, null)
      delete = try(timeouts.value.delete, null)
    }
  }
}

###############################################################################
# Additional IPv6 CIDR block associations
###############################################################################

resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each = var.enabled ? var.ipv6_cidr_block_associations : {}

  vpc_id = aws_vpc.this[0].id

  ipv6_cidr_block     = each.value.ipv6_ipam_pool_id == null ? each.value.ipv6_cidr_block : null
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_ipam_pool_id != null ? each.value.ipv6_netmask_length : null

  dynamic "timeouts" {
    for_each = each.value.timeouts == null ? [] : [each.value.timeouts]
    content {
      create = try(timeouts.value.create, null)
      delete = try(timeouts.value.delete, null)
    }
  }
}

###############################################################################
# Default resource adoption / rule resets
###############################################################################

resource "aws_default_vpc" "this" {
  count = var.enabled && var.manage_default_vpc ? 1 : 0

  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = local.tags
}

resource "aws_default_security_group" "this" {
  count = var.enabled && var.manage_default_security_group ? 1 : 0

  vpc_id = var.manage_default_vpc ? aws_default_vpc.this[0].id : aws_vpc.this[0].id

  dynamic "ingress" {
    for_each = var.default_security_group_deny_all ? [] : var.default_security_group_ingress
    content {
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      protocol         = ingress.value.protocol
      cidr_blocks      = ingress.value.cidr_blocks
      ipv6_cidr_blocks = ingress.value.ipv6_cidr_blocks
      description      = ingress.value.description
      self             = ingress.value.self
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_deny_all ? [] : var.default_security_group_egress
    content {
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      protocol         = egress.value.protocol
      cidr_blocks      = egress.value.cidr_blocks
      ipv6_cidr_blocks = egress.value.ipv6_cidr_blocks
      description      = egress.value.description
      self             = egress.value.self
    }
  }

  tags = local.tags
}

resource "aws_default_route_table" "this" {
  count = var.enabled && var.manage_default_route_table ? 1 : 0

  default_route_table_id = var.manage_default_vpc ? aws_default_vpc.this[0].default_route_table_id : aws_vpc.this[0].default_route_table_id

  dynamic "route" {
    for_each = var.default_route_table_no_routes ? [] : var.default_route_table_routes
    content {
      cidr_block                = route.value.cidr_block
      ipv6_cidr_block           = route.value.ipv6_cidr_block
      gateway_id                = route.value.gateway_id
      nat_gateway_id            = route.value.nat_gateway_id
      egress_only_gateway_id    = route.value.egress_only_gateway_id
      transit_gateway_id        = route.value.transit_gateway_id
      vpc_peering_connection_id = route.value.vpc_peering_connection_id
      network_interface_id      = route.value.network_interface_id
    }
  }

  tags = local.tags
}

resource "aws_default_network_acl" "this" {
  count = var.enabled && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = var.manage_default_vpc ? aws_default_vpc.this[0].default_network_acl_id : aws_vpc.this[0].default_network_acl_id

  dynamic "ingress" {
    for_each = var.default_network_acl_deny_all ? [] : var.default_network_acl_ingress
    content {
      action          = ingress.value.action
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      rule_no         = ingress.value.rule_no
      cidr_block      = ingress.value.cidr_block
      ipv6_cidr_block = ingress.value.ipv6_cidr_block
      icmp_type       = ingress.value.icmp_type
      icmp_code       = ingress.value.icmp_code
    }
  }

  dynamic "egress" {
    for_each = var.default_network_acl_deny_all ? [] : var.default_network_acl_egress
    content {
      action          = egress.value.action
      from_port       = egress.value.from_port
      to_port         = egress.value.to_port
      protocol        = egress.value.protocol
      rule_no         = egress.value.rule_no
      cidr_block      = egress.value.cidr_block
      ipv6_cidr_block = egress.value.ipv6_cidr_block
      icmp_type       = egress.value.icmp_type
      icmp_code       = egress.value.icmp_code
    }
  }

  tags = local.tags
}

###############################################################################
# Internet gateways
###############################################################################

resource "aws_internet_gateway" "this" {
  count = var.enabled && var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = local.tags
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.enabled && var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = local.tags
}

###############################################################################
# Outputs
###############################################################################

output "id" {
  value       = local.id
  description = "The generated Cloud Posse style ID"
}

output "tags" {
  value       = local.tags
  description = "The merged tags applied to all resources"
}

output "vpc_id" {
  value       = try(aws_vpc.this[0].id, null)
  description = "The ID of the VPC"
}

output "vpc_arn" {
  value       = try(aws_vpc.this[0].arn, null)
  description = "The ARN of the VPC"
}

output "vpc_cidr_block" {
  value       = try(aws_vpc.this[0].cidr_block, null)
  description = "The primary IPv4 CIDR block of the VPC"
}

output "vpc_ipv6_cidr_block" {
  value       = try(aws_vpc.this[0].ipv6_cidr_block, null)
  description = "The primary IPv6 CIDR block of the VPC"
}

output "vpc_default_security_group_id" {
  value       = try(aws_vpc.this[0].default_security_group_id, null)
  description = "The ID of the security group created by default on VPC creation"
}

output "vpc_default_route_table_id" {
  value       = try(aws_vpc.this[0].default_route_table_id, null)
  description = "The ID of the default route table of the VPC"
}

output "vpc_default_network_acl_id" {
  value       = try(aws_vpc.this[0].default_network_acl_id, null)
  description = "The ID of the default network ACL of the VPC"
}

output "ipv4_cidr_block_associations" {
  value       = { for k, v in aws_vpc_ipv4_cidr_block_association.this : k => v.id }
  description = "Map of additional IPv4 CIDR block association IDs"
}

output "ipv6_cidr_block_associations" {
  value       = { for k, v in aws_vpc_ipv6_cidr_block_association.this : k => v.id }
  description = "Map of additional IPv6 CIDR block association IDs"
}

output "internet_gateway_id" {
  value       = try(aws_internet_gateway.this[0].id, null)
  description = "The ID of the IPv4/IPv6 internet gateway"
}

output "egress_only_internet_gateway_id" {
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
  description = "The ID of the IPv6 egress-only internet gateway"
}

output "default_security_group_id" {
  value       = try(aws_default_security_group.this[0].id, null)
  description = "The ID of the managed default security group"
}

output "default_route_table_id" {
  value       = try(aws_default_route_table.this[0].id, null)
  description = "The ID of the managed default route table"
}

output "default_network_acl_id" {
  value       = try(aws_default_network_acl.this[0].id, null)
  description = "The ID of the managed default network ACL"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

############################################################################
# Variables
############################################################################

variable "username" {
  description = "Name of the IAM user created for infrastructure deployment."
  type        = string
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "Name of the IAM group that owns the deployment policies."
  type        = string
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "Name of the IAM group membership resource."
  type        = string
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "Value applied as the ProjectTag tag on the IAM user and policies."
  type        = string
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Custom path used for every IAM policy created by this stack."
  type        = string
  default     = "/my_vpn_infra/"
}

############################################################################
# Locals
############################################################################

locals {
  common_tags = {
    ProjectTag = var.project_tag
  }

  create_actions = [
    "ec2:CreateKeyPair",
    "ec2:CreateVpc",
    "ec2:CreateSubnet",
    "ec2:CreateInternetGateway",
    "ec2:CreateRoute",
    "ec2:CreateRouteTable",
    "ec2:CreateLocalGatewayRouteTableVpcAssociation",
    "ec2:CreateSecurityGroup",
    "ec2:AuthorizeSecurityGroupEgress",
    "ec2:AuthorizeSecurityGroupIngress",
    "ec2:CreateReplaceRootVolumeTask",
    "ec2:CreateTags",
    "ec2:AllocateAddress",
  ]

  read_actions = [
    "ec2:DescribeAccountAttributes",
    "ec2:DescribeAddresses",
    "ec2:DescribeAvailabilityZones",
    "ec2:DescribeImages",
    "ec2:DescribeInstances",
    "ec2:DescribeInstanceAttribute",
    "ec2:DescribeInstanceStatus",
    "ec2:DescribeInstanceTypes",
    "ec2:DescribeInternetGateways",
    "ec2:DescribeKeyPairs",
    "ec2:DescribeLocalGatewayRouteTableVpcAssociations",
    "ec2:DescribeNetworkAcls",
    "ec2:DescribeNetworkInterfaces",
    "ec2:DescribeRegions",
    "ec2:DescribeRouteTables",
    "ec2:DescribeSecurityGroups",
    "ec2:DescribeSnapshots",
    "ec2:DescribeSubnets",
    "ec2:DescribeTags",
    "ec2:DescribeVolumes",
    "ec2:DescribeVpcs",
    "ec2:DescribeVpcAttribute",
    "ec2:DescribeVpcEndpoints",
  ]

  update_actions = [
    "ec2:ModifyVpcAttribute",
    "ec2:ModifySubnetAttribute",
    "ec2:ModifyInstanceAttribute",
    "ec2:ModifyNetworkInterfaceAttribute",
    "ec2:ModifySecurityGroupRules",
    "ec2:ModifyVolume",
    "ec2:AssociateAddress",
    "ec2:AssociateIamInstanceProfile",
    "ec2:AssociateRouteTable",
    "ec2:AssociateSubnetCidrBlock",
    "ec2:AssociateVpcCidrBlock",
    "ec2:ReplaceRoute",
    "ec2:ReplaceRouteTableAssociation",
    "ec2:UpdateSecurityGroupRuleDescriptionsIngress",
    "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
  ]

  delete_actions = [
    "ec2:DeleteKeyPair",
    "ec2:DeleteVpc",
    "ec2:DeleteSubnet",
    "ec2:DeleteInternetGateway",
    "ec2:DeleteRoute",
    "ec2:DeleteRouteTable",
    "ec2:DeleteSecurityGroup",
    "ec2:DeleteTags",
    "ec2:DeleteVolume",
    "ec2:DeleteSnapshot",
    "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
    "ec2:DetachInternetGateway",
    "ec2:DetachNetworkInterface",
    "ec2:DisassociateAddress",
    "ec2:DisassociateRouteTable",
    "ec2:DisassociateSubnetCidrBlock",
    "ec2:DisassociateVpcCidrBlock",
    "ec2:ReleaseAddress",
    "ec2:RevokeSecurityGroupEgress",
    "ec2:RevokeSecurityGroupIngress",
  ]

  instance_actions = [
    "ec2:RunInstances",
    "ec2:StartInstances",
    "ec2:ResetInstanceAttribute",
    "ec2:ModifyInstanceAttribute",
    "ec2:StopInstances",
    "ec2:TerminateInstances",
    "ec2:RebootInstances",
  ]

  backend_actions = [
    "dynamodb:DescribeTable",
    "dynamodb:GetItem",
    "dynamodb:PutItem",
    "dynamodb:DeleteItem",
    "s3:ListBucket",
    "s3:GetObject",
    "s3:PutObject",
    "s3:DeleteObject",
  ]
}

############################################################################
# IAM User, Group and Membership
############################################################################

resource "aws_iam_user" "infra" {
  name          = var.username
  force_destroy = true

  tags = local.common_tags
}

resource "aws_iam_group" "infra" {
  name = var.group_name
}

resource "aws_iam_group_membership" "infra" {
  name  = var.membership_name
  group = aws_iam_group.infra.name
  users = [aws_iam_user.infra.name]
}

resource "aws_iam_access_key" "infra" {
  user   = aws_iam_user.infra.name
  status = "Active"
}

############################################################################
# Custom IAM Policies
############################################################################

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Allow the user to resolve the calling AWS identity."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sts:GetCallerIdentity"]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "Allow creation of EC2 networking and compute resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.create_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "Allow read-only discovery of EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.read_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "Allow modification and association of EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.update_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "Allow deletion and detachment of EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.delete_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "Allow management of the EC2 instance lifecycle."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.instance_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Allow access to the S3 and DynamoDB Terraform remote backend."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = "*"
      },
    ]
  })

  tags = local.common_tags
}

############################################################################
# Group Policy Attachments
############################################################################

resource "aws_iam_group_policy_attachment" "basic_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

resource "aws_iam_group_policy_attachment" "create_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.create_policy.arn
}

resource "aws_iam_group_policy_attachment" "read_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.read_policy.arn
}

resource "aws_iam_group_policy_attachment" "update_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.update_policy.arn
}

resource "aws_iam_group_policy_attachment" "delete_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_group_policy_attachment" "instance_policy" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

resource "aws_iam_group_policy_attachment" "terraform_backend_access" {
  group      = aws_iam_group.infra.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

###############################################################################
# Terraform & Provider Requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "existing_vpc_id" {
  description = "Optional ID of an existing VPC. When empty a new VPC is created."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment prefix used for naming and tagging resources."
  type        = string
  default     = "DEV"
}

variable "vpc_cidr" {
  description = "Main CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "craete_private_subnet" {
  description = "When true, private subnets, a private route table and a NAT gateway are created."
  type        = bool
  default     = false
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "nat_eip_private_ip" {
  description = "Private IP address associated with the NAT gateway Elastic IP."
  type        = string
  default     = "10.0.0.5"
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  # A new VPC is created only when no existing VPC id was supplied.
  create_vpc = var.existing_vpc_id == ""

  vpc_id = local.create_vpc ? one(aws_vpc.main[*].id) : var.existing_vpc_id

  # Use the first two availability zones returned by the provider.
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  name_prefix = var.environment

  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

###############################################################################
# Public Tier
###############################################################################

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = local.vpc_id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = local.vpc_id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private Tier (optional)
###############################################################################

resource "aws_subnet" "private" {
  count = var.craete_private_subnet ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  count = var.craete_private_subnet ? 1 : 0

  domain                    = "vpc"
  associate_with_private_ip = var.nat_eip_private_ip

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  count = var.craete_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-gw"
  })

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  count = var.craete_private_subnet ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC (created or supplied)."
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (empty when disabled)."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.igw.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table (null when disabled)."
  value       = one(aws_route_table.private[*].id)
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway (null when disabled)."
  value       = one(aws_nat_gateway.main[*].id)
}

output "nat_eip_id" {
  description = "ID of the NAT gateway Elastic IP (null when disabled)."
  value       = one(aws_eip.nat[*].id)
}

output "region" {
  description = "Region the stack targets."
  value       = var.aws_region
}

###############################################################################
# Amazon SQS Messaging Module
#
# Supports standard and FIFO queues, custom queue policies, dead-letter queues
# with redrive policies, and server-side (SSE) encryption. The primary queue is
# created only when `create` is true (default). A dead-letter queue is created
# only when `create_dlq` is true (default).
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Determines whether resources will be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue. Conflicts with name_prefix. A '.fifo' suffix is appended automatically for FIFO queues."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix used to generate the queue name when name is not provided. A deterministic suffix is appended."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_dedup" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level (FIFO only)"
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group (FIFO only)"
  type        = string
  default     = "perQueue"
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds"
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message"
  type        = number
  default     = 345600
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it"
  type        = number
  default     = 262144
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue is delayed"
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling)"
  type        = number
  default     = 0
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again"
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys. Applied automatically when kms_master_key_id is not set."
  type        = bool
  default     = true
}

variable "create_queue_policy" {
  description = "Determines whether a queue policy should be created"
  type        = bool
  default     = false
}

variable "queue_policy" {
  description = "The JSON policy for the SQS queue. When provided, it overrides the source/override policy documents and custom statements."
  type        = string
  default     = null
}

variable "source_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document"
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document, overriding the source documents"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "Map of custom IAM policy statements. When a statement does not specify resources, the queue ARN is used."
  type = map(object({
    sid           = optional(string)
    effect        = optional(string)
    actions       = optional(list(string))
    not_actions   = optional(list(string))
    resources     = optional(list(string))
    not_resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    condition = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = {}
}

variable "create_dlq" {
  description = "Determines whether a dead-letter queue should be created and attached to the primary queue"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Name of the dead-letter queue. Defaults to the primary queue name suffixed with '-dlq'."
  type        = string
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "The ID of an AWS-managed CMK for the dead-letter queue. Falls back to the primary queue value."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which the dead-letter queue can reuse a data key"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Boolean to enable SSE with SQS-owned encryption keys on the dead-letter queue. Falls back to the primary queue value."
  type        = bool
  default     = null
}

variable "create_dlq_redrive_allow_policy" {
  description = "Determines whether a redrive allow policy is attached to the dead-letter queue"
  type        = bool
  default     = true
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue"
  type        = number
  default     = 5
}

variable "tags" {
  description = "A map of tags to assign to the resources"
  type        = map(string)
  default     = {}
}

###############################################################################
# Data Sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  create  = var.create
  is_fifo = var.fifo_queue

  # Base used to synthesize a name when an explicit name is not provided.
  generated_base = coalesce(var.name_prefix, "sqs")
  generated_id   = substr(md5("${data.aws_caller_identity.current.account_id}-${local.generated_base}-${local.is_fifo}"), 0, 8)

  # Resolve the primary queue base name from name / name_prefix / generated name.
  base_name = (
    var.name != null ? var.name :
    var.name_prefix != null ? "${var.name_prefix}-${local.generated_id}" :
    "sqs-${local.generated_id}"
  )

  # Automatically append the .fifo suffix for FIFO queues.
  queue_name = local.is_fifo && !endswith(local.base_name, ".fifo") ? "${local.base_name}.fifo" : local.base_name

  # Construct the queue ARN without referencing the resource to avoid a
  # dependency cycle with the dead-letter queue's redrive allow policy.
  queue_arn = format(
    "arn:%s:sqs:%s:%s:%s",
    data.aws_partition.current.partition,
    data.aws_region.current.name,
    data.aws_caller_identity.current.account_id,
    local.queue_name
  )

  # SQS-managed SSE applies automatically whenever no KMS master key is set.
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null

  # Dead-letter queue.
  dlq_enabled = local.create && var.create_dlq

  dlq_base = trimsuffix(local.queue_name, ".fifo")
  dlq_name = (
    var.dlq_name != null
    ? (local.is_fifo && !endswith(var.dlq_name, ".fifo") ? "${var.dlq_name}.fifo" : var.dlq_name)
    : (local.is_fifo ? "${local.dlq_base}-dlq.fifo" : "${local.dlq_base}-dlq")
  )

  # Dead-letter queue inherits / falls back to the primary queue encryption.
  dlq_kms_master_key_id = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_sqs_managed_sse_enabled = (
    local.dlq_kms_master_key_id != null
    ? null
    : (var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled)
  )

  # Queue policy.
  queue_policy_enabled = local.create && var.create_queue_policy
}

###############################################################################
# Primary Queue
###############################################################################

resource "aws_sqs_queue" "this" {
  count = local.create ? 1 : 0

  name = local.queue_name

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_dedup : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = local.dlq_enabled ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Dead-Letter Queue
###############################################################################

resource "aws_sqs_queue" "dlq" {
  count = local.dlq_enabled ? 1 : 0

  name = local.dlq_name

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_dedup : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? var.dlq_kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled

  # Restrict redrive permissions to the primary queue only.
  redrive_allow_policy = var.create_dlq_redrive_allow_policy ? jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [local.queue_arn]
  }) : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Queue Policy
###############################################################################

data "aws_iam_policy_document" "this" {
  count = local.queue_policy_enabled && var.queue_policy == null ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      effect        = try(statement.value.effect, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = coalesce(try(statement.value.resources, null), [aws_sqs_queue.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = coalesce(try(statement.value.principals, null), [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = coalesce(try(statement.value.not_principals, null), [])
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = coalesce(try(statement.value.condition, null), [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.queue_policy_enabled ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = var.queue_policy != null ? var.queue_policy : data.aws_iam_policy_document.this[0].json
}

###############################################################################
# Outputs
###############################################################################

output "queue_arn" {
  description = "The ARN of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The URL of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "The URL of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dlq_name" {
  description = "The name of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

locals {
  iam_path = "/system/"

  users = {
    loadbalancer  = ["test", "test2", "test3", "test4"]
    loadbalancer2 = ["test2", "test22", "test23", "test24"]
    loadbalancer3 = ["test3", "test32", "test33", "test34"]
  }

  # Flatten the per-user policy name lists into a single map keyed by
  # "<user>/<policy-name>" so each inline policy can be managed with for_each.
  user_inline_policies = merge([
    for user_name, policy_names in local.users : {
      for policy_name in policy_names : "${user_name}/${policy_name}" => {
        user_name   = user_name
        policy_name = policy_name
      }
    }
  ]...)
}

data "aws_iam_policy_document" "ec2_describe" {
  statement {
    sid       = "EC2DescribeAll"
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

resource "aws_iam_user" "this" {
  for_each = local.users

  name = each.key
  path = local.iam_path

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "this" {
  for_each = aws_iam_user.this

  user = aws_iam_user.this[each.key].name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_policy" "this" {
  for_each = local.user_inline_policies

  name   = each.value.policy_name
  user   = aws_iam_user.this[each.value.user_name].name
  policy = data.aws_iam_policy_document.ec2_describe.json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "backup_name" {
  description = "Name of the AWS Backup vault, also used to derive the backup plan and IAM role names."
  type        = string
  default     = "default"
}

variable "account_type" {
  description = "Account type. 'workload' provisions backup plans, roles and selections; 'backup' provisions only the vault."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "The account_type value must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional ARN of the KMS key used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON string containing the access policy for the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Optional minimum retention period (in days) for the vault lock. When set, a vault lock configuration is created."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention period (in days) for the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional number of days before the vault lock becomes unchangeable (compliance mode)."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to enable SNS notifications for backup vault events."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic used for backup vault notifications."
  type        = string
  default     = null
}

variable "backup_vault_events" {
  description = "List of backup vault events that trigger notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "backup_plan_schedule" {
  description = "Cron expression that defines the backup plan rule schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "selection_resources" {
  description = "Optional list of resource ARNs to include in an explicit resource-based backup selection."
  type        = list(string)
  default     = []
}

variable "copy_actions" {
  description = "List of cross-region or cross-account copy actions configured on the backup plan rule."
  type = list(object({
    destination_vault_arn   = string
    cold_storage_after_days = optional(number, 30)
    delete_after_days       = optional(number, 120)
  }))
  default = []
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_partition" "current" {}

locals {
  is_workload       = var.account_type == "workload"
  backup_plan_name  = "plan-${var.backup_name}-backup"
  backup_role_name  = "aws-backup-${var.backup_name}"
  create_vault_lock = var.min_retention_days != null

  backup_service_role_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# Backup vault
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  tags = {
    Name = var.backup_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Optional vault lock configuration (created when min_retention_days is set)
# ---------------------------------------------------------------------------
resource "aws_backup_vault_lock_configuration" "this" {
  count = local.create_vault_lock ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

# ---------------------------------------------------------------------------
# Optional vault access policy
# ---------------------------------------------------------------------------
resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# ---------------------------------------------------------------------------
# Optional vault notifications
# ---------------------------------------------------------------------------
resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

# ---------------------------------------------------------------------------
# IAM role for AWS Backup (workload accounts only)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name = local.backup_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = local.backup_role_name
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = local.backup_service_role_arn
}

# ---------------------------------------------------------------------------
# Backup plan (workload accounts only)
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = local.backup_plan_name

  rule {
    rule_name         = "backup-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_plan_schedule

    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      Backup = "true"
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after_days
          delete_after       = copy_action.value.delete_after_days
        }
      }
    }
  }

  tags = {
    Name = local.backup_plan_name
  }
}

# ---------------------------------------------------------------------------
# Tag-based backup selection (workload accounts only)
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "tags" {
  count = local.is_workload ? 1 : 0

  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "${local.backup_plan_name}-tags"
  plan_id      = aws_backup_plan.this[0].id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# ---------------------------------------------------------------------------
# Optional explicit resource-based backup selection
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "resources" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "${local.backup_plan_name}-resources"
  plan_id      = aws_backup_plan.this[0].id
  resources    = var.selection_resources
}

###############################################################################
# Terraform
###############################################################################

terraform {
  required_providers {
    random = {
      source = "hashicorp/random"
    }
  }
}

###############################################################################
# Static provider metadata lookups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Name of the AWS Config stack. Defaults to \"config\" with a petname fallback when null or empty."
  type        = string
  default     = "config"
}

###############################################################################
# Naming convention
#   Uses the supplied name, defaulting to "config", and falls back to a
#   generated petname when the supplied value is null or empty.
###############################################################################

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  name_is_empty = var.name == null || trimspace(var.name) == ""
  base_name     = local.name_is_empty ? random_pet.name.id : var.name
  name          = "${local.base_name}-${random_id.suffix.hex}"

  config_rules = {
    "cloudtrail-enabled"    = { identifier = "CLOUD_TRAIL_ENABLED",              periodic = true }
    "iam-pw-policy"         = { identifier = "IAM_PASSWORD_POLICY",              periodic = true }
    "ec2-vpc"               = { identifier = "INSTANCES_IN_VPC",                 periodic = false }
    "root-mfa-enabled"      = { identifier = "ROOT_ACCOUNT_MFA_ENABLED",         periodic = true }
    "acm-expiration-check"  = { identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK", periodic = true }
    "ebs-inuse-check"       = { identifier = "EC2_VOLUME_INUSE_CHECK",           periodic = false }
    "ec2-imdsv2-check"      = { identifier = "EC2_IMDSV2_CHECK",                 periodic = false }
    "rds-encrypted"         = { identifier = "RDS_STORAGE_ENCRYPTED",            periodic = false }
    "rds-private"           = { identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK", periodic = false }
    "rds-private-snapshots" = { identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED",  periodic = false }
  }
}

###############################################################################
# Customer managed KMS key (automatic rotation) for the SNS topic
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowConfigServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "config" {
  description             = "Customer managed KMS key for AWS Config SNS notifications"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SNS topic (named after the resource) encrypted with the CMK
###############################################################################

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowConfigServiceToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.config.arn

  depends_on = [aws_kms_key.config]
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.sns.json
}

###############################################################################
# S3 snapshot bucket
###############################################################################

resource "aws_s3_bucket" "snapshot" {
  bucket        = "${local.name}-config-snapshot-${data.aws_caller_identity.current.account_id}"
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.snapshot.arn]
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.snapshot.arn}/awsconfig/records/*"]
  }
}

resource "aws_s3_bucket_policy" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.snapshot]
}

###############################################################################
# IAM role for AWS Config
###############################################################################

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  description        = "IAM role used by AWS Config to record resource configuration"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

# AWS_ConfigRole AWS managed policy
resource "aws_iam_role_policy_attachment" "config_role" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

# Write permissions to the snapshot bucket
data "aws_iam_policy_document" "s3_write" {
  statement {
    sid    = "ConfigSnapshotBucketWrite"
    effect = "Allow"

    actions = [
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.snapshot.arn,
      "${aws_s3_bucket.snapshot.arn}/*",
    ]
  }

  statement {
    sid    = "ConfigSnapshotBucketEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.config.arn]
  }
}

resource "aws_iam_role_policy" "s3" {
  name   = "${local.name}-s3"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.s3_write.json
}

# Inline policy permitting SNS publish operations
data "aws_iam_policy_document" "sns_publish" {
  statement {
    sid    = "ConfigSNSPublish"
    effect = "Allow"

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }
}

resource "aws_iam_role_policy" "sns" {
  name   = "${local.name}-sns"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.sns_publish.json
}

###############################################################################
# AWS Config recorder + delivery channel
###############################################################################

resource "aws_config_configuration_recorder" "this" {
  name     = "${local.base_name}-recorder"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.config_role,
    aws_iam_role_policy.s3,
    aws_iam_role_policy.sns,
    aws_s3_bucket_policy.snapshot,
  ]
}

resource "aws_config_delivery_channel" "this" {
  name           = "${local.base_name}-delivery-channel"
  s3_bucket_name = aws_s3_bucket.snapshot.id
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config.arn

  depends_on = [aws_config_configuration_recorder.this]
}

resource "aws_config_configuration_recorder_status" "this" {
  name       = aws_config_configuration_recorder.this.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.this]
}

###############################################################################
# AWS Config managed rules (evaluated every 24h or on configuration changes)
###############################################################################

resource "aws_config_config_rule" "this" {
  for_each = local.config_rules

  name = each.key

  source {
    owner             = "AWS"
    source_identifier = each.value.identifier
  }

  # Periodic rules are evaluated every 24 hours; change-triggered managed rules
  # are evaluated whenever a matching resource configuration changes.
  maximum_execution_frequency = each.value.periodic ? "TwentyFour_Hours" : null

  depends_on = [aws_config_configuration_recorder_status.this]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  depends_on = [aws_config_configuration_recorder_status.this]
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr = "10.0.0.0/16"

  project = "BJIT DevOps Task"
  author  = "Ariful Islam"

  common_tags = {
    Project = local.project
    Author  = local.author
  }

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "bjit-vpc"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-igw"
  })
}

###############################################################################
# Public subnets (no auto-assign public IP)
###############################################################################

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
    Tier = "Public"
  })
}

###############################################################################
# Private subnets
###############################################################################

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
    Tier = "Private"
  })
}

###############################################################################
# Public route table (shared) + IGW route
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-public-route-table"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private route tables (one per AZ)
###############################################################################

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-private-route-table-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# S3 Gateway VPC Endpoint associated with every private route table
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "bjit-s3-gateway-endpoint"
  })
}

###############################################################################
# Security groups
# Outbound traffic in every SG is restricted to the VPC CIDR.
###############################################################################

# ALB security group - HTTP/HTTPS from anywhere
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "ALB SG allowing TCP 80-443 from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP and HTTPS from anywhere"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

# MariaDB / RDS security group - MySQL/MariaDB from VPC CIDR
resource "aws_security_group" "rds" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "RDS SG allowing MySQL/MariaDB (3306) from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL/MariaDB from VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

# Redis security group - Redis from VPC CIDR
resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Redis SG allowing Redis (6379) from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from VPC CIDR"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

# API server security group - 8080 and 22 from VPC CIDR
resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "API server SG allowing ports 8080 and 22 from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Application port 8080 from VPC CIDR"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

# File server security group - 8081 and 22 from VPC CIDR
resource "aws_security_group" "file_server" {
  name        = "bjit-file-server-SG"
  description = "File server SG allowing ports 8081 and 22 from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "File server port 8081 from VPC CIDR"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-file-server-SG"
  })
}

# Public SSH security group - SSH from VPC CIDR
resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "SSH SG allowing SSH (22) from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "base_name" {
  description = "Base name prefix applied to every resource created by this configuration."
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "CIDR blocks for the public subnets. One subnet is created per entry."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "CIDR blocks for the private subnets. Set to null (default) to skip the private tier entirely."
  type        = list(string)
  default     = null
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Public and private subnets start from the second availability zone index.
  az_offset = 1

  create_private = var.subnet_private_cidrs != null && length(var.subnet_private_cidrs) > 0

  # Interface endpoints may only have a single ENI per AZ, so they are placed in
  # the private subnets when they exist and fall back to the public subnets.
  interface_subnet_ids = local.create_private ? aws_subnet.private[*].id : aws_subnet.public[*].id

  tags = {
    Name      = var.base_name
    ManagedBy = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${var.base_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.base_name}-igw"
  })
}

###############################################################################
# Public subnets
###############################################################################

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + local.az_offset]

  tags = merge(local.tags, {
    Name = "${var.base_name}-public-${count.index}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.base_name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private subnets (conditional)
###############################################################################

resource "aws_subnet" "private" {
  count = local.create_private ? length(var.subnet_private_cidrs) : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + local.az_offset]

  tags = merge(local.tags, {
    Name = "${var.base_name}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  count = local.create_private ? length(var.subnet_public_cidrs) : 0

  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${var.base_name}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "nat" {
  count = local.create_private ? length(var.subnet_public_cidrs) : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.tags, {
    Name = "${var.base_name}-nat-${count.index}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = local.create_private ? length(var.subnet_private_cidrs) : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.base_name}-private-rt-${count.index}"
  })
}

resource "aws_route" "private_nat" {
  count = local.create_private ? length(var.subnet_private_cidrs) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[count.index % length(aws_nat_gateway.nat)].id
}

resource "aws_route_table_association" "private" {
  count = local.create_private ? length(var.subnet_private_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# VPC endpoints
###############################################################################

# S3 gateway endpoint for the public subnet tier.
resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = merge(local.tags, {
    Name = "${var.base_name}-s3-endpoint-public"
  })
}

# Dedicated S3 gateway endpoint associated with the private route tables.
resource "aws_vpc_endpoint" "s3_private" {
  count = local.create_private ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.tags, {
    Name = "${var.base_name}-s3-endpoint-private"
  })
}

###############################################################################
# ECR security group
###############################################################################

resource "aws_security_group" "ecr" {
  name_prefix = "${var.base_name}-ecr-"
  description = "Controls access to the ECR interface VPC endpoints."
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.subnet_public_cidrs
    content {
      description = "HTTPS from public subnet ${ingress.value}"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  dynamic "ingress" {
    for_each = local.create_private ? var.subnet_private_cidrs : []
    content {
      description = "HTTPS from private subnet ${ingress.value}"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, {
    Name = "${var.base_name}-ecr-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# ECR interface VPC endpoints
###############################################################################

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.interface_subnet_ids
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = merge(local.tags, {
    Name = "${var.base_name}-ecr-api-endpoint"
  })
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.interface_subnet_ids
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = merge(local.tags, {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  })
}

locals {
