  pub_sub_1_cidr     = "10.0.1.0/24"
  pub_sub_2_cidr     = "10.0.2.0/24"
  pvt_sub_1_cidr     = "10.0.3.0/24"
  pvt_sub_2_cidr     = "10.0.4.0/24"
  igw_name           = "T-igw"
  pub_rt_1_name      = "RT_PUBRT-1"
  pub_rt_2_name      = "RT_PUBRT-2"
  pvt_rt_1_name      = "RT_PVTRT-1"
  pvt_rt_2_name      = "RT_PVTRT-2"
  nat_name           = "T-NAT1"
  public_sg_name     = "allow_tls"
  private_sg_name    = "pvt-seg"
  admin_cidr         = "203.0.113.0/24"
  default_route_cidr = "0.0.0.0/0"
}

data "aws_availability_zones" "available" {
