resource "aws_subnet" "pvt_sub_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.pvt_sub_2_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "pvt-sub-2"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.igw_name
  }
}

# ---------------------------------------------------------------------------
# Public route tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "pub_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.default_route_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = local.pub_rt_1_name
  }
}

resource "aws_route_table" "pub_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.default_route_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = local.pub_rt_2_name
  }
}

resource "aws_route_table_association" "pub_assoc_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.pub_rt_1.id
}

resource "aws_route_table_association" "pub_assoc_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

# ---------------------------------------------------------------------------
# Elastic IPs and NAT Gateways
# ---------------------------------------------------------------------------

resource "aws_eip" "nat_1" {
  domain = "vpc"

  tags = {
    Name = local.nat_name
  }
}

resource "aws_eip" "nat_2" {
  domain = "vpc"

  tags = {
    Name = local.nat_name
  }
}

resource "aws_nat_gateway" "nat_1" {
  allocation_id = aws_eip.nat_1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = local.nat_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat_2" {
  allocation_id = aws_eip.nat_2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = local.nat_name
  }

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Private route tables (both route through the first NAT gateway)
# ---------------------------------------------------------------------------

resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.default_route_cidr
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = {
    Name = local.pvt_rt_1_name
  }
}

resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.default_route_cidr
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = {
    Name = local.pvt_rt_2_name
  }
}

resource "aws_route_table_association" "pvt_assoc_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

resource "aws_route_table_association" "pvt_assoc_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "allow_tls" {
  name        = local.public_sg_name
  description = "Public tier: HTTP/HTTPS from anywhere, SSH from admin range"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.default_route_cidr]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.default_route_cidr]
  }

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.admin_cidr]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = local.public_sg_name
  }
}

resource "aws_security_group" "pvt_seg" {
  name        = local.private_sg_name
  description = "Private tier: traffic only from/to the public security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from public tier"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public tier"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public tier"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Egress exclusively to the public tier"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = local.private_sg_name
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition
  api_name   = "APIGW DynamoDB Serverless Pattern Demo"
  table_name = "Pets"
  index_name = "PetType-index"
  stage_name = "v1"
  log_group  = "/aws/APIGW/terraform"
}

###############################################################################
# DynamoDB table "Pets" with the "PetType-index" global secondary index
###############################################################################

resource "aws_dynamodb_table" "pets" {
  name           = local.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = local.index_name
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role used by API Gateway to call DynamoDB directly
###############################################################################

resource "aws_iam_role" "apigw_dynamodb" {
  name = "apigw-dynamodb-terraform-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name = "apigw-dynamodb-terraform-policy"
  role = aws_iam_role.apigw_dynamodb.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

###############################################################################
# CloudWatch role / account settings for API Gateway logging
###############################################################################

resource "aws_iam_role" "apigw_cloudwatch" {
  name = "apigw-dynamodb-terraform-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  role       = aws_iam_role.apigw_cloudwatch.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch]
}

###############################################################################
# CloudWatch log group and resource policy for log delivery
###############################################################################

resource "aws_cloudwatch_log_group" "apigw" {
  name              = local.log_group
  retention_in_days = 30
}

resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name = "apigw-dynamodb-terraform-log-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_api_gateway_rest_api.this.arn
          }
        }
      }
    ]
  })
}

###############################################################################
# REST API
###############################################################################

resource "aws_api_gateway_rest_api" "this" {
  name        = local.api_name
  description = "Serverless direct API Gateway to DynamoDB integration pattern"
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

###############################################################################
# POST /pets -> DynamoDB PutItem
###############################################################################

resource "aws_api_gateway_method" "pets_post" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "pets_post" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.pets_post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${local.partition}:apigateway:${local.region}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "Item": {
    "id": { "S": "$context.requestId" },
    "PetType": { "S": "$input.path('$.PetType')" },
    "PetName": { "S": "$input.path('$.PetName')" },
    "PetPrice": { "N": "$input.path('$.PetPrice')" },
    "PetBoolean": { "BOOL": true }
  }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "pets_post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.pets_post.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "pets_post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.pets_post.http_method
  status_code = aws_api_gateway_method_response.pets_post_200.status_code

  depends_on = [aws_api_gateway_integration.pets_post]
}

###############################################################################
# GET /pets/{PetType} -> DynamoDB Query against PetType-index
###############################################################################

resource "aws_api_gateway_method" "pet_type_get" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "pet_type_get" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.pet_type_get.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${local.partition}:apigateway:${local.region}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
  "TableName": "Pets",
  "IndexName": "PetType-index",
  "KeyConditionExpression": "PetType = :v1",
  "ExpressionAttributeValues": {
    ":v1": { "S": "$util.urlDecode($input.params('PetType'))" }
  }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "pet_type_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.pet_type_get.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "pet_type_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.pet_type_get.http_method
  status_code = aws_api_gateway_method_response.pet_type_get_200.status_code

  response_templates = {
    "application/json" = <<EOF
{
  "items": [
#foreach($item in $input.path('$.Items'))
    {
      "id": "$item.id.S",
      "PetType": "$item.PetType.S",
      "PetName": "$item.PetName.S",
      "PetPrice": "$item.PetPrice.N"
    }#if($foreach.hasNext),#end
#end
  ]
}
EOF
  }

  depends_on = [aws_api_gateway_integration.pet_type_get]
}

###############################################################################
# Deployment and stage
###############################################################################

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_method.pets_post.id,
      aws_api_gateway_method.pet_type_get.id,
      aws_api_gateway_integration.pets_post.id,
      aws_api_gateway_integration.pet_type_get.id,
      aws_api_gateway_integration_response.pets_post_200.id,
      aws_api_gateway_integration_response.pet_type_get_200.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "this" {
  deployment_id = aws_api_gateway_deployment.this.id
  rest_api_id   = aws_api_gateway_rest_api.this.id
  stage_name    = local.stage_name

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [aws_api_gateway_account.this]
}

resource "aws_api_gateway_method_settings" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  stage_name  = aws_api_gateway_stage.this.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled    = true
    logging_level      = "INFO"
    data_trace_enabled = false
  }
}

###############################################################################
# API key, usage plan and binding
###############################################################################

resource "aws_api_gateway_api_key" "this" {
  name        = "apigw-dynamodb-terraform-api-key"
  description = "API key for the API Gateway DynamoDB serverless pattern demo"
  enabled     = true
}

resource "aws_api_gateway_usage_plan" "this" {
  name        = "apigw-dynamodb-terraform-usage-plan"
  description = "Usage plan for the API Gateway DynamoDB serverless pattern demo"

  api_stages {
    api_id = aws_api_gateway_rest_api.this.id
    stage  = aws_api_gateway_stage.this.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "this" {
  key_id        = aws_api_gateway_api_key.this.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.this.id
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Base name used to derive the S3 buckets created by this configuration."
  type        = string
  default     = "sadcloud"
}

variable "no_versioning" {
  description = "When true, versioning is disabled on the primary bucket."
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "When true, the customer-managed KMS default encryption on the primary bucket is omitted."
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "When true, static website hosting is enabled on the primary bucket."
  type        = bool
  default     = false
}

variable "bucket_acl" {
  description = "Canned ACL applied to the logging bucket."
  type        = string
  default     = "log-delivery-write"
}

variable "no_logging" {
  description = "When true, the logging bucket and the primary bucket logging configuration are omitted."
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "When true, attach a bucket policy denying non-TLS (cleartext) access to the primary bucket."
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "When true, create a public read-only (s3:GetObject) bucket."
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "When true, create a public read-write (s3:*) bucket."
  type        = bool
  default     = false
}

locals {
  policy_version = "2012-10-17"
  common_tags = {
    ManagedBy = "Terraform"
    Purpose   = "s3-security-testing"
  }
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "main" {
  bucket_prefix = var.name
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

# Object ownership - required before any canned ACL can be applied.
resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_versioning" "main" {
  count = var.no_versioning ? 0 : 1

  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Dedicated customer-managed KMS key with automatic rotation.
resource "aws_kms_key" "main" {
  count = var.no_default_encryption ? 0 : 1

  description         = "Customer managed key for ${var.name} S3 default encryption"
  enable_key_rotation = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-kms"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.no_default_encryption ? 0 : 1

  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main[0].arn
    }
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

# Deny all cleartext (non-TLS) access to the primary bucket when enabled.
resource "aws_s3_bucket_policy" "main_cleartext_deny" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# Logging bucket (created unless no_logging is true)
###############################################################################

resource "aws_s3_bucket" "logging" {
  count = var.no_logging ? 0 : 1

  bucket        = "${var.name}-logging"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-logging"
  })
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "logging" {
  count = var.no_logging ? 0 : 1

  description         = "Customer managed key for ${var.name}-logging S3 default encryption"
  enable_key_rotation = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-logging-kms"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logging[0].arn
    }
  }
}

# Point the primary bucket's server access logging at the logging bucket.
resource "aws_s3_bucket_logging" "main" {
  count = var.no_logging ? 0 : 1

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

###############################################################################
# Optional public read-only bucket (s3:GetObject)
###############################################################################

resource "aws_s3_bucket" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket        = "${var.name}-getonly"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-getonly"
  })
}

# Public access block restrictions completely disabled for testing.
resource "aws_s3_bucket_public_access_block" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.getonly]
}

###############################################################################
# Optional fully public read-write bucket (s3:*)
###############################################################################

resource "aws_s3_bucket" "public" {
  count = var.s3_public ? 1 : 0

  bucket        = "${var.name}-public"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-public"
  })
}

# Public access block restrictions completely disabled for testing.
resource "aws_s3_bucket_public_access_block" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.public]
}

###############################################################################
# Data sources (static provider / well-known metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  managed_policy_arn_prefix = "arn:${local.partition}:iam::aws:policy"

  # Shared EC2 service trust policy used by the DRS conversion, replication,
  # recovery instance and recovery instance with launch actions roles.
  ec2_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

###############################################################################
# Elastic Disaster Recovery policy baseline
###############################################################################

resource "aws_iam_policy" "agent" {
  name        = "AWSElasticDisasterRecoveryAgentPolicy"
  description = "Permissions used by the AWS Elastic Disaster Recovery agent running on source servers."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SendAgentTelemetry"
        Effect = "Allow"
        Action = [
          "drs:SendClientLogs",
          "drs:SendClientMetrics",
        ]
        Resource = "*"
      },
      {
        Sid    = "SourceServerAccess"
        Effect = "Allow"
        Action = [
          "drs:DescribeSourceServers",
          "drs:GetAgentInstallationAssetsForAccount",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "failback" {
  name        = "AWSElasticDisasterRecoveryFailbackPolicy"
  description = "Permissions used by the AWS Elastic Disaster Recovery failback client."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FailbackAndReverseReplication"
        Effect = "Allow"
        Action = [
          "drs:SendClientLogs",
          "drs:SendClientMetrics",
          "drs:DescribeRecoveryInstances",
          "drs:ReverseReplication",
          "drs:GetFailbackReplicationConfiguration",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "conversion_server" {
  name        = "AWSElasticDisasterRecoveryConversionServerPolicy"
  description = "Permissions used by AWS Elastic Disaster Recovery conversion servers."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConversionServerAccess"
        Effect = "Allow"
        Action = [
          "drs:SendClientLogs",
          "drs:SendClientMetrics",
          "drs:DescribeConversionJobs",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "recovery_instance" {
  name        = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
  description = "Permissions used by AWS Elastic Disaster Recovery recovery instances."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RecoveryInstanceAccess"
        Effect = "Allow"
        Action = [
          "drs:SendClientLogs",
          "drs:SendClientMetrics",
          "drs:DescribeRecoveryInstances",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "replication_server" {
  name        = "AWSElasticDisasterRecoveryReplicationServerPolicy"
  description = "Permissions used by AWS Elastic Disaster Recovery replication servers."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReplicationServerAccess"
        Effect = "Allow"
        Action = [
          "drs:SendClientLogs",
          "drs:SendClientMetrics",
          "drs:DescribeSourceServers",
          "drs:DescribeReplicationConfigurationTemplates",
        ]
        Resource = "*"
      },
    ]
  })
}

###############################################################################
# Service roles under /service-role/
###############################################################################

# --- AWSElasticDisasterRecoveryAgentRole -------------------------------------
resource "aws_iam_role" "agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDRSServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity",
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = aws_iam_policy.agent.arn
}

# --- AWSElasticDisasterRecoveryFailbackRole ----------------------------------
resource "aws_iam_role" "failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDRSServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity",
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = aws_iam_policy.failback.arn
}

# --- AWSElasticDisasterRecoveryConversionServerRole --------------------------
resource "aws_iam_role" "conversion_server" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = "/service-role/"
  assume_role_policy = local.ec2_assume_role_policy
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = aws_iam_policy.conversion_server.arn
}

# --- AWSElasticDisasterRecoveryRecoveryInstanceRole --------------------------
resource "aws_iam_role" "recovery_instance" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = "/service-role/"
  assume_role_policy = local.ec2_assume_role_policy
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = aws_iam_policy.recovery_instance.arn
}

# --- AWSElasticDisasterRecoveryReplicationServerRole -------------------------
resource "aws_iam_role" "replication_server" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = "/service-role/"
  assume_role_policy = local.ec2_assume_role_policy
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = aws_iam_policy.replication_server.arn
}

# --- AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole ---------
resource "aws_iam_role" "recovery_instance_with_launch_actions" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = "/service-role/"
  assume_role_policy = local.ec2_assume_role_policy
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_drs" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = aws_iam_policy.recovery_instance.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_ssm" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonSSMManagedInstanceCore"
}

###############################################################################
# Initializer role (root path) + custom InitializePolicy
###############################################################################

resource "aws_iam_role" "initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCallingIdentityToAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "initialize" {
  name        = "AWSElasticDisasterRecoveryInitializerPolicy"
  description = "Permissions required to initialize and operate AWS Elastic Disaster Recovery."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InitializeDRSService"
        Effect   = "Allow"
        Action   = "drs:InitializeService"
        Resource = "*"
      },
      {
        Sid      = "CreateDRSServiceLinkedRole"
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:${local.partition}:iam::*:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
      },
      {
        Sid    = "InstanceProfileManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:GetInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile",
          "iam:DeleteInstanceProfile",
        ]
        Resource = "arn:${local.partition}:iam::*:instance-profile/*"
      },
      {
        Sid      = "PassRoleToEC2AndDRS"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "arn:${local.partition}:iam::*:role/*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com",
            ]
          }
        }
      },
      {
        Sid      = "FullEC2Access"
        Effect   = "Allow"
        Action   = "ec2:*"
        Resource = "*"
      },
      {
        Sid    = "AttachDisasterRecoveryManagedPolicies"
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:DetachRolePolicy",
        ]
        Resource = "arn:${local.partition}:iam::*:role/*"
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = [
              aws_iam_policy.agent.arn,
              aws_iam_policy.conversion_server.arn,
              aws_iam_policy.recovery_instance.arn,
              aws_iam_policy.replication_server.arn,
              aws_iam_policy.failback.arn,
            ]
          }
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize.arn
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  description = "Number of EC2 instances to deploy."
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "ami_id" {
  description = "Optional AMI ID. When null, the latest Amazon Linux 2 AMI is used."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_name         = "VPC_from_Terraform"
  sg_tag           = "Terraform_SG_HTTP_HTTPS_SSH"
  instance_name    = "Terraform_Instance"
  ebs_volume_tag   = "Terraform_EBS_Volume1"
  root_volume_size = 20
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = local.vpc_name
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

###############################################################################
# Security Group
###############################################################################

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from the VPC and HTTP/HTTPS from everywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR block"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from everywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from everywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress limited to the VPC CIDR block"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = local.sg_tag
  }
}

###############################################################################
# Compute
###############################################################################

resource "aws_instance" "main" {
  count = var.instance_count

  ami                    = var.ami_id != null ? var.ami_id : data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = local.root_volume_size
    volume_type = "gp2"
    encrypted   = true

    tags = {
      Name = local.ebs_volume_tag
    }
  }

  tags = {
    Name = local.instance_name
  }
}

data "aws_partition" "current" {}

locals {
  tags = {
    ManagedBy = "Terraform"
    Purpose   = "ECS containerized deployments with autoscaling and CodeDeploy blue/green"
  }

  code_deploy_role_managed_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

# ---------------------------------------------------------------------------
# 1. ecsServiceRole
#    Assumed by ecs.amazonaws.com and s3.amazonaws.com.
#    Inline policy: ecsTaskRolePolicy
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_service_role" {
  name = "ecsServiceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEcsAndS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs.amazonaws.com",
            "s3.amazonaws.com",
          ]
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name = "ecsTaskRolePolicy"
  role = aws_iam_role.ecs_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ElasticLoadBalancingAccess"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:DescribeTargetGroupAttributes",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
        ]
        Resource = "*"
      },
      {
        Sid    = "Ec2Access"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeNetworkInterfaces",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupEgress",
        ]
        Resource = "*"
      },
      {
        Sid    = "SsmAccess"
        Effect = "Allow"
        Action = [
          "ssm:DescribeParameters",
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets",
        ]
        Resource = "*"
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeDeployAccess"
        Effect = "Allow"
        Action = [
          "codedeploy:CreateDeployment",
          "codedeploy:GetApplication",
          "codedeploy:GetApplicationRevision",
          "codedeploy:GetDeployment",
          "codedeploy:GetDeploymentConfig",
          "codedeploy:RegisterApplicationRevision",
        ]
        Resource = "*"
      },
      {
        Sid    = "SnsAccess"
        Effect = "Allow"
        Action = [
          "sns:GetTopicAttributes",
          "sns:ListTopics",
          "sns:Publish",
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchAccess"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:PutMetricData",
        ]
        Resource = "*"
      },
      {
        Sid    = "LambdaAccess"
        Effect = "Allow"
        Action = [
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:InvokeFunction",
          "lambda:ListFunctions",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# 2. ecsExecTaskRole
#    Assumed by ecs-tasks.amazonaws.com and s3.amazonaws.com.
#    Inline policies: ecsExecRolePolicy, ecsExecution_additional
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_exec_task_role" {
  name = "ecsExecTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEcsTasksAndS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com",
          ]
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name = "ecsExecRolePolicy"
  role = aws_iam_role.ecs_exec_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcrAccess"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
        ]
        Resource = "*"
      },
      {
        Sid    = "EcrRepositoryAccess"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
        ]
        Resource = "*"
      },
      {
        Sid    = "EcsServiceDescription"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetSecretValue",
        ]
        Resource = "*"
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
        ]
        Resource = "*"
      },
      {
        Sid    = "SsmAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name = "ecsExecution_additional"
  role = aws_iam_role.ecs_exec_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcsServiceListAndDescribe"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:ListServices",
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. ecsTaskRole
#    Assumed by ecs-tasks.amazonaws.com and s3.amazonaws.com.
#    Inline policy: ecsTaskRole_additional
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecsTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEcsTasksAndS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com",
          ]
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name = "ecsTaskRole_additional"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcsServiceListAndDescribe"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:ListServices",
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# 4. ecs_autoscale_role
#    Assumed by application-autoscaling.amazonaws.com.
#    Inline policy: ecs_autoscale_role_policy
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_autoscale_role" {
  name = "ecs_autoscale_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApplicationAutoscalingAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name = "ecs_autoscale_role_policy"
  role = aws_iam_role.ecs_autoscale_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcsServiceDescribeAndUpdate"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:UpdateService",
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchAlarmAccess"
        Effect = "Allow"
        Action = [
          "cloudwatch:DeleteAlarms",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:GetMetricData",
          "cloudwatch:PutMetricAlarm",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# 5. ecs_codedeploy_role
#    Assumed by codedeploy.amazonaws.com.
#    Managed policy: AWSCodeDeployRole
#    Inline policies: ecs_codedeploy_role_policy,
#                     ecs_codedeploy_role_policy_task,
#                     ecs_codedeploy_role_policy_task_exec
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_codedeploy_role" {
  name = "ecs_codedeploy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeDeployAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_role_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = local.code_deploy_role_managed_policy_arn
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name = "ecs_codedeploy_role_policy"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcsTaskSetAccess"
        Effect = "Allow"
        Action = [
          "ecs:CreateTaskSet",
          "ecs:DeleteTaskSet",
          "ecs:DescribeServices",
          "ecs:DescribeTaskSets",
          "ecs:UpdateService",
          "ecs:UpdateServicePrimaryTaskSet",
        ]
        Resource = "*"
      },
      {
        Sid    = "ElasticLoadBalancingAccess"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:ModifyRule",
        ]
        Resource = "*"
      },
      {
        Sid    = "LambdaAccess"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchAccess"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
        ]
        Resource = "*"
      },
      {
        Sid    = "SnsAccess"
        Effect = "Allow"
        Action = [
          "sns:Publish",
        ]
        Resource = "*"
      },
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucket",
          "s3:PutObject",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name = "ecs_codedeploy_role_policy_task"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PassTaskRole"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          aws_iam_role.ecs_task_role.arn,
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ecs-tasks.amazonaws.com"
          }
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name = "ecs_codedeploy_role_policy_task_exec"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PassTaskExecutionRole"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          aws_iam_role.ecs_exec_task_role.arn,
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ecs-tasks.amazonaws.com"
          }
        }
      },
    ]
  })
}

#############################################
# Availability Zones
#############################################

data "aws_availability_zones" "available" {
  state = "available"
}

#############################################
# Local Values
#############################################

locals {
  external_vpc_tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }

  internal_vpc_tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }

  subnet_names = ["Subnet0-1a", "Subnet1-1b", "Subnet2-1c", "Subnet3-1d"]

  external_subnet_cidrs = ["10.41.0.0/24", "10.41.1.0/24", "10.41.2.0/24", "10.41.3.0/24"]

  internal_subnet_cidrs = ["10.40.0.0/24", "10.40.1.0/24", "10.40.2.0/24", "10.40.3.0/24"]
}

#############################################
# External VPC
#############################################

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.external_vpc_tags
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "Production External - default"
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_subnet" "external" {
  count = 4

  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = local.subnet_names[count.index]
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external.id
  }

  tags = {
    Name = "External Route Table"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external" {
  count = 4

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "Production External - default"
  }
}

#############################################
# Internal VPC
#############################################

resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.internal_vpc_tags
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name = "Production Internal - default"
  }
}

resource "aws_subnet" "internal" {
  count = 4

  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = local.subnet_names[count.index]
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  tags = {
    Name = "Production Internal - default"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "resource_prefix" {
  description = "Prefix applied to all resource names."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ARN of an existing ACM certificate for the HTTPS listener. When null a self-signed certificate is generated and imported into ACM."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional URL override used for the WEBHOOK_URL environment variable."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks to run."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image used for the n8n task."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  azs           = slice(data.aws_availability_zones.available.names, 0, 3)
  private_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  efs_volume_name = "${var.resource_prefix}-efs"
  log_group_name  = "${var.resource_prefix}-logs"

  webhook_url = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"

  generated_certificate_arn = one(aws_acm_certificate.self_signed[*].arn)
  certificate_arn           = coalesce(var.certificate_arn, local.generated_certificate_arn)
}

###############################################################################
# VPC and networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.resource_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.resource_prefix}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.resource_prefix}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.resource_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb-sg"
  description = "Ingress for the n8n application load balancer."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs" {
  name        = "${var.resource_prefix}-ecs-sg"
  description = "Ingress for the n8n ECS tasks from the load balancer."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n traffic from the load balancer"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-ecs-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs-sg"
  description = "NFS access for the n8n EFS file system."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-efs-sg"
  }
}

###############################################################################
# Self-signed certificate (generated when no certificate_arn is supplied)
###############################################################################

resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = "${var.resource_prefix}.internal"
    organization = "n8n"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count             = var.certificate_arn == null ? 1 : 0
  certificate_body  = tls_self_signed_cert.self_signed[0].cert_pem
  private_key       = tls_private_key.self_signed[0].private_key_pem
  certificate_chain = tls_self_signed_cert.self_signed[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Application Load Balancer
###############################################################################

resource "aws_lb" "main" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.resource_prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name        = "${var.resource_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    matcher             = "200"
  }

  tags = {
    Name = "${var.resource_prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

###############################################################################
# EFS file system, access point and mount targets
###############################################################################

resource "aws_efs_file_system" "main" {
  creation_token = "${var.resource_prefix}-efs"
  encrypted      = true

  tags = {
    Name = "${var.resource_prefix}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.resource_prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "main" {
  count           = 3
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# CloudWatch log group
###############################################################################

resource "aws_cloudwatch_log_group" "main" {
  name              = local.log_group_name
  retention_in_days = 1

  tags = {
    Name = local.log_group_name
  }
}

###############################################################################
# IAM roles for the ECS task and execution roles
###############################################################################

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "container_permissions" {
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.main.arn,
      "${aws_cloudwatch_log_group.main.arn}:*",
    ]
  }

  statement {
    sid    = "EfsClientAccess"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
    ]

    resources = [aws_efs_file_system.main.arn]
  }
}

resource "aws_iam_role" "task" {
  name               = "${var.resource_prefix}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy" "task" {
  name   = "${var.resource_prefix}-task-policy"
  role   = aws_iam_role.task.id
  policy = data.aws_iam_policy_document.container_permissions.json
}

resource "aws_iam_role" "execution" {
  name               = "${var.resource_prefix}-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
}

resource "aws_iam_role_policy" "execution" {
  name   = "${var.resource_prefix}-execution-policy"
  role   = aws_iam_role.execution.id
  policy = data.aws_iam_policy_document.container_permissions.json
}

###############################################################################
# ECS cluster and capacity provider
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "${var.resource_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.resource_prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

###############################################################################
# ECS task definition
###############################################################################

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.resource_prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = local.efs_volume_name

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = var.resource_prefix
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = local.efs_volume_name
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"

        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.resource_prefix
        }
      }
    }
  ])

  tags = {
    Name = "${var.resource_prefix}-task"
  }
}

###############################################################################
# ECS service
###############################################################################

resource "aws_ecs_service" "main" {
  name            = "${var.resource_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = var.resource_prefix
    container_port   = 5678
  }

  depends_on = [aws_lb_listener.https]

  tags = {
    Name = "${var.resource_prefix}-service"
  }
}

###############################################################################
# Isolated AWS development network topology for a Lambda + RDS setup.
#   - VPC "lambda-rds-dev" (10.32.0.0/20)
#   - DB / Lambda / Bastion subnets across two AZs
#   - Internet Gateway + public route table (bastion)
#   - Locked-down default SG/NACL and three least-privilege security groups
###############################################################################

locals {
  vpc_name = "lambda-rds-dev"
  vpc_cidr = "10.32.0.0/20"
}

# Static provider metadata lookup (no pre-existing infrastructure required).
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC
###############################################################################
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

# Manage the VPC default security group so that it has NO ingress/egress rules.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-default-sg"
  }
}

# Manage the VPC default network ACL: allow all ingress/egress traffic.
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

###############################################################################
# Subnets
###############################################################################
resource "aws_subnet" "db_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "db_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "bastion" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

###############################################################################
# Internet Gateway + public route table
###############################################################################
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################
resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "PostgreSQL database security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Lambda functions security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# --- PostgreSQL DB security group rules -------------------------------------

# Egress strictly to the VPC CIDR block.
resource "aws_security_group_rule" "postgres_egress_vpc" {
  type              = "egress"
  description       = "Allow egress only within the VPC CIDR block"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.postgres_db.id
}

# Ingress on PostgreSQL 5432 from the bastion host security group.
resource "aws_security_group_rule" "postgres_ingress_bastion" {
  type                     = "ingress"
  description              = "Allow PostgreSQL access from the bastion host"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.bastion_host.id
  security_group_id        = aws_security_group.postgres_db.id
}

# Ingress on PostgreSQL 5432 from the Lambda functions security group.
resource "aws_security_group_rule" "postgres_ingress_lambda" {
  type                     = "ingress"
  description              = "Allow PostgreSQL access from Lambda functions"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lambda_functions.id
  security_group_id        = aws_security_group.postgres_db.id
}

# --- Lambda functions security group rules ----------------------------------

# Egress strictly to the VPC CIDR block.
resource "aws_security_group_rule" "lambda_egress_vpc" {
  type              = "egress"
  description       = "Allow egress only within the VPC CIDR block"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.lambda_functions.id
}

# --- Bastion host security group rules --------------------------------------

# Inbound SSH (22) only from within the VPC CIDR block.
resource "aws_security_group_rule" "bastion_ingress_ssh" {
  type              = "ingress"
  description       = "Allow SSH only from within the VPC CIDR block"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.bastion_host.id
}

# Egress restricted exclusively to the PostgreSQL database security group.
resource "aws_security_group_rule" "bastion_egress_postgres" {
  type                     = "egress"
  description              = "Allow egress only to the PostgreSQL database security group"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.postgres_db.id
  security_group_id        = aws_security_group.bastion_host.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

# ---------------------------------------------------------------------------
# Static metadata lookups (well-known provider metadata only)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Shared configuration
# ---------------------------------------------------------------------------
locals {
  vpc_cidr = "10.255.0.0/16"

  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

# ---------------------------------------------------------------------------
# RDS subnets (multi-AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "rds_1a" {
  vpc_id                  = aws_vpc.quasar.id
  cidr_block              = "10.255.100.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id                  = aws_vpc.quasar.id
  cidr_block              = "10.255.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

# ---------------------------------------------------------------------------
# Security group: Bastion
# ---------------------------------------------------------------------------
resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host access - SSH from the admin range only"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from the admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

# ---------------------------------------------------------------------------
# Security group: HA Proxy
# ---------------------------------------------------------------------------
resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA Proxy - public HTTP/HTTPS and SSH from the bastion"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

# ---------------------------------------------------------------------------
# Security group: Jenkins
# ---------------------------------------------------------------------------
resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI - SSH from the bastion and port 8080 from HA Proxy"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI from the HA Proxy security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

# ---------------------------------------------------------------------------
# Security group: ETL
# ---------------------------------------------------------------------------
resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute - SSH from the bastion and Jenkins"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from the Jenkins security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

# ---------------------------------------------------------------------------
# Security group: PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL - port 5432 from anywhere and from the ETL security group"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from the ETL security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

###############################################################################
# Locals
###############################################################################

locals {
  create     = var.create
  create_dlq = var.create && var.create_dlq

  # Human-readable name with any ".fifo" suffix stripped, then re-applied only
  # for FIFO queues (AWS requires FIFO queue names to end in ".fifo").
  name_base  = trimsuffix(var.name, ".fifo")
  queue_name = "${local.name_base}${var.fifo_queue ? ".fifo" : ""}"

  # DLQ name: explicit dlq_name wins, otherwise <name><dlq_name_suffix>.
  dlq_name_base  = trimsuffix(coalesce(var.dlq_name, "${local.name_base}${var.dlq_name_suffix}"), ".fifo")
  dlq_queue_name = "${local.dlq_name_base}${var.fifo_queue ? ".fifo" : ""}"

  # SQS-managed SSE is the default; it is disabled automatically when a
  # customer-managed KMS key is supplied (the two options are mutually exclusive).
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false

  # DLQ encryption inherits the main queue unless explicitly overridden.
  dlq_kms_master_key_id = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_data_key_reuse_period_seconds = (
    var.dlq_kms_data_key_reuse_period_seconds != null
    ? var.dlq_kms_data_key_reuse_period_seconds
    : var.kms_data_key_reuse_period_seconds
  )
  dlq_sqs_managed_sse_enabled = (
    local.dlq_kms_master_key_id != null
    ? false
    : (var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled)
  )
}

###############################################################################
# Module inputs
###############################################################################

variable "create" {
  description = "Controls whether the SQS resources managed by this module should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable name for the queue. Any \".fifo\" suffix is stripped and re-applied automatically for FIFO queues."
  type        = string
  default     = "sqs-queue"
}

variable "use_name_prefix" {
  description = "Determines whether the provided name is used as a name prefix (allowing Terraform to append a unique suffix) instead of the exact queue name."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to the queues."
  type        = map(string)
  default     = {}
}

###############################################################################
# Main queue parameters
###############################################################################

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level (messageGroup or queue). Only valid for FIFO queues."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group (perQueue or perMessageGroupId). Only valid for FIFO queues."
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds."
  type        = number
  default     = 30
}

###############################################################################
# Main queue encryption
###############################################################################

variable "sqs_managed_sse_enabled" {
  description = "Enables SQS-managed server-side encryption (SSE) of messages. Ignored when a custom kms_master_key_id is provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a customer-managed KMS key (or alias) used for SQS server-side encryption. When set, SQS-managed SSE is disabled."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again."
  type        = number
  default     = null
}

###############################################################################
# Main queue policy
###############################################################################

variable "create_queue_policy" {
  description = "Controls whether a queue policy is created for the main queue."
  type        = bool
  default     = false
}

variable "queue_policy" {
  description = "A JSON policy document that is merged (as a source document) with the generated queue policy."
  type        = string
  default     = null
}

variable "queue_policy_override" {
  description = "A JSON policy document that overrides the generated queue policy document."
  type        = string
  default     = null
}

variable "queue_policy_statements" {
  description = "A map of custom IAM policy statement definitions to merge into the main queue policy."
  type        = any
  default     = {}
}

###############################################################################
# Dead-letter queue (DLQ) parameters
###############################################################################

variable "create_dlq" {
  description = "Controls whether a dead-letter queue is provisioned and attached to the main queue via a redrive policy."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Explicit name for the dead-letter queue. Defaults to <name><dlq_name_suffix>."
  type        = string
  default     = null
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the main queue name to derive the default dead-letter queue name."
  type        = string
  default     = "-dlq"
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "dlq_content_based_deduplication" {
  description = "Overrides content_based_deduplication for the DLQ. Inherits the main queue value when null."
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Overrides deduplication_scope for the DLQ. Inherits the main queue value when null."
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Overrides fifo_throughput_limit for the DLQ. Inherits the main queue value when null."
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Overrides delay_seconds for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Overrides max_message_size for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Overrides message_retention_seconds for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Overrides receive_wait_time_seconds for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Overrides visibility_timeout_seconds for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Overrides sqs_managed_sse_enabled for the DLQ. Inherits the main queue value when null."
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Overrides kms_master_key_id for the DLQ. Inherits the main queue value when null."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Overrides kms_data_key_reuse_period_seconds for the DLQ. Inherits the main queue value when null."
  type        = number
  default     = null
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether a redrive allow policy is attached to the DLQ, restricting redrive permission to the source queue."
  type        = bool
  default     = true
}

variable "dlq_redrive_allow_policy" {
  description = "A JSON redrive allow policy document for the DLQ. Defaults to a 'byQueue' policy scoped to the main queue ARN."
  type        = string
  default     = null
}

###############################################################################
# DLQ queue policy
###############################################################################

variable "create_dlq_queue_policy" {
  description = "Controls whether a queue policy is created for the dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_queue_policy" {
  description = "A JSON policy document that is merged (as a source document) with the generated DLQ policy."
  type        = string
  default     = null
}

variable "dlq_queue_policy_override" {
  description = "A JSON policy document that overrides the generated DLQ policy document."
  type        = string
  default     = null
}

variable "dlq_queue_policy_statements" {
  description = "A map of custom IAM policy statement definitions to merge into the DLQ policy."
  type        = any
  default     = {}
}

###############################################################################
# Main queue
###############################################################################

resource "aws_sqs_queue" "this" {
  count = local.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.queue_name
  name_prefix = var.use_name_prefix ? local.queue_name : null

  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_queue                  = var.fifo_queue
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds             = var.delay_seconds
  max_message_size          = var.max_message_size
  message_retention_seconds = var.message_retention_seconds
  receive_wait_time_seconds = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = local.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags
}

###############################################################################
# Dead-letter queue
###############################################################################

resource "aws_sqs_queue" "dlq" {
  count = local.create_dlq ? 1 : 0

  name        = var.use_name_prefix ? null : local.dlq_queue_name
  name_prefix = var.use_name_prefix ? local.dlq_queue_name : null

  # Inherit FIFO characteristics unless overridden by DLQ-specific parameters.
  content_based_deduplication = var.fifo_queue ? (
    var.dlq_content_based_deduplication != null ? var.dlq_content_based_deduplication : var.content_based_deduplication
  ) : null
  deduplication_scope = var.fifo_queue ? (
    var.dlq_deduplication_scope != null ? var.dlq_deduplication_scope : var.deduplication_scope
  ) : null
  fifo_queue = var.fifo_queue
  fifo_throughput_limit = var.fifo_queue ? (
    var.dlq_fifo_throughput_limit != null ? var.dlq_fifo_throughput_limit : var.fifo_throughput_limit
  ) : null

  delay_seconds             = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  max_message_size          = var.dlq_max_message_size != null ? var.dlq_max_message_size : var.max_message_size
  message_retention_seconds = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds
  receive_wait_time_seconds = var.dlq_receive_wait_time_seconds != null ? var.dlq_receive_wait_time_seconds : var.receive_wait_time_seconds
  visibility_timeout_seconds = (
    var.dlq_visibility_timeout_seconds != null ? var.dlq_visibility_timeout_seconds : var.visibility_timeout_seconds
  )

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled

  tags = var.tags
}

# The redrive allow policy is managed as a separate resource (instead of an
# inline DLQ attribute) so the DLQ can reference the main queue ARN without
# creating a dependency cycle with the main queue's redrive policy.
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = local.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = var.dlq_redrive_allow_policy != null ? var.dlq_redrive_allow_policy : jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

###############################################################################
# Queue policies
###############################################################################

data "aws_iam_policy_document" "this" {
  count = local.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.queue_policy != null ? [var.queue_policy] : []
  override_policy_documents = var.queue_policy_override != null ? [var.queue_policy_override] : []

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

data "aws_iam_policy_document" "dlq" {
  count = local.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.dlq_queue_policy != null ? [var.dlq_queue_policy] : []
  override_policy_documents = var.dlq_queue_policy_override != null ? [var.dlq_queue_policy_override] : []

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.this[0].json
}

resource "aws_sqs_queue_policy" "dlq" {
  count = local.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq[0].json
}

###############################################################################
# Outputs
###############################################################################

output "queue_id" {
  description = "The URL of the main queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the main queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_name" {
  description = "The name of the main queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_id" {
  description = "The URL of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_name" {
  description = "The name of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Master control that toggles creation of every resource managed by this template."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the AWS Lambda function that is the target of the blue/green deployment."
  type        = string
  default     = ""
}

variable "alias_name" {
  description = "Name of the Lambda function alias used by the blue/green deployment."
  type        = string
  default     = ""
}

variable "current_version" {
  description = "Current published version of the Lambda function."
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Target published version of the Lambda function to shift traffic to."
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked before traffic is allowed (BeforeAllowTraffic hook)."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked after traffic is allowed (AfterAllowTraffic hook)."
  type        = string
  default     = ""
}

variable "app_name" {
  description = "Name of the CodeDeploy application."
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether a CodeDeploy application should be created."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to reuse an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "create_deployment_group" {
  description = "Whether a CodeDeploy deployment group should be created."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to reuse an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group. Defaults to '<app_name>-deployment-group'."
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "Name of the CodeDeploy deployment configuration for the deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "automatic_rollback_enabled" {
  description = "Whether automatic rollback is enabled for the deployment group."
  type        = bool
  default     = true
}

variable "automatic_rollback_events" {
  description = "Events that trigger an automatic rollback for the deployment group."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_enabled" {
  description = "Whether CloudWatch alarm monitoring is enabled for the deployment group."
  type        = bool
  default     = false
}

variable "alarm_names" {
  description = "List of CloudWatch alarm names monitored by the deployment group."
  type        = list(string)
  default     = []
}

variable "notification_triggers" {
  description = "Notification triggers (e.g. SNS topics) attached to the deployment group."
  type = list(object({
    trigger_name       = string
    trigger_target_arn = string
    trigger_events     = list(string)
  }))
  default = []
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role assumed by CodeDeploy."
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "Explicit name for the CodeDeploy IAM role. When empty a unique name prefix is used."
  type        = string
  default     = ""
}

variable "codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy IAM role to use when create_codedeploy_role is false."
  type        = string
  default     = ""
}

variable "codedeploy_service_principals" {
  description = "Service principals allowed to assume the CodeDeploy IAM role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline IAM policy granting lambda:InvokeFunction for the lifecycle hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline IAM policy granting sns:Publish for the notification triggers."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to render the AppSpec revision and deployment script (and optionally run the deployment)."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between deployment status polls when monitoring a deployment."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Whether the generated script should poll and wait for the deployment to complete."
  type        = bool
  default     = true
}

variable "save_deploy_script" {
  description = "Whether to save the generated deployment script to a local file."
  type        = bool
  default     = false
}

variable "deploy_script_path" {
  description = "Path where the generated deployment script is saved. Defaults to '<module path>/deploy.sh'."
  type        = string
  default     = ""
}

variable "run_deployment" {
  description = "Whether to execute the generated deployment script through a null_resource local-exec provisioner."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "When true a random UUID is added to the null_resource triggers to force a new deployment run."
  type        = bool
  default     = false
}

variable "deployment_description" {
  description = "Description recorded on the CodeDeploy deployment."
  type        = string
  default     = "Blue/green deployment for Lambda function."
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static / well-known provider metadata only)
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# Well-known AWS managed policy that grants CodeDeploy the permissions it needs
# to manage Lambda traffic shifting. Resolved by name so the correct partition
# path is used automatically.
data "aws_iam_policy" "codedeploy_lambda" {
  count = local.create_codedeploy_role ? 1 : 0

  name = "AWSCodeDeployRoleForLambda"
}

###############################################################################
# Locals
###############################################################################

locals {
  create_codedeploy_role  = var.create && var.create_codedeploy_role
  create_app              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_deployment       = var.create && var.create_deployment

  app_name = var.app_name

  deployment_group_name = (
    var.deployment_group_name != "" ? var.deployment_group_name : "${var.app_name}-deployment-group"
  )

  service_role_arn = try(aws_iam_role.codedeploy[0].arn, var.codedeploy_role_arn)

  hook_arns = compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn])

  lambda_function_arn = var.function_name != "" ? format(
    "arn:%s:lambda:%s:%s:function:%s",
    data.aws_partition.current.partition,
    data.aws_region.current.name,
    data.aws_caller_identity.current.account_id,
    var.function_name,
  ) : ""

  # Resources granted lambda:InvokeFunction: use explicit hook ARNs when
  # supplied, otherwise fall back to the target Lambda function itself.
  hooks_policy_resources = length(local.hook_arns) > 0 ? local.hook_arns : compact([local.lambda_function_arn])

  trigger_target_arns = distinct([for t in var.notification_triggers : t.trigger_target_arn])

  deploy_script_path = var.deploy_script_path != "" ? var.deploy_script_path : "${path.module}/deploy.sh"

  app_spec_hooks = (
    var.before_allow_traffic_hook_arn != "" || var.after_allow_traffic_hook_arn != ""
  ) ? [
    merge(
      var.before_allow_traffic_hook_arn != "" ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
      var.after_allow_traffic_hook_arn != "" ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {},
    )
  ] : []

  app_spec = {
    version = "0.0"
    Resources = [
      {
        (var.function_name != "" ? var.function_name : "LambdaFunction") = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = local.app_spec_hooks
  }

  app_spec_content = jsonencode(local.app_spec)

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.app_spec_content
    }
  })

  deploy_script = <<EOT
#!/bin/bash
set -eu

APP_NAME='${local.app_name}'
DEPLOYMENT_GROUP_NAME='${local.deployment_group_name}'
DEPLOYMENT_CONFIG_NAME='${var.deployment_config_name}'

echo "Creating CodeDeploy deployment for $APP_NAME ($DEPLOYMENT_GROUP_NAME)"

DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
  --application-name "$APP_NAME" \
  --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
  --deployment-config-name "$DEPLOYMENT_CONFIG_NAME" \
  --description '${var.deployment_description}' \
  --revision '${local.revision_json}' \
  --query 'deploymentId' \
  --output text)

echo "Deployment ID: $DEPLOYMENT_ID"

if [ '${var.monitor_deployment}' = 'true' ]; then
  while true; do
    STATUS=$(${var.aws_cli_command} deploy get-deployment \
      --deployment-id "$DEPLOYMENT_ID" \
      --query 'deploymentInfo.status' \
      --output text)
    echo "Deployment status: $STATUS"
    case "$STATUS" in
      Succeeded)
        break
        ;;
      Failed|Stopped)
        echo "Deployment finished with status $STATUS"
        exit 1
        ;;
      *)
        sleep ${var.get_deployment_sleep_timer}
        ;;
    esac
  done
fi

echo "Deployment finished successfully"
EOT
}

###############################################################################
# CodeDeploy application
###############################################################################

resource "aws_codedeploy_app" "this" {
  count = local.create_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"

  tags = var.tags
}

###############################################################################
# CodeDeploy IAM role
###############################################################################

data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = local.create_codedeploy_role ? 1 : 0

  statement {
    sid     = "AllowCodeDeployServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = local.create_codedeploy_role ? 1 : 0

  name        = var.codedeploy_role_name != "" ? var.codedeploy_role_name : null
  name_prefix = var.codedeploy_role_name == "" ? "codedeploy-lambda-" : null

  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = local.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = data.aws_iam_policy.codedeploy_lambda[0].arn
}

# Inline policy granting lambda:InvokeFunction for the lifecycle hooks.
data "aws_iam_policy_document" "hooks" {
  count = local.create_codedeploy_role && var.attach_hooks_policy && length(local.hooks_policy_resources) > 0 ? 1 : 0

  statement {
    sid       = "InvokeLambdaTrafficHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hooks_policy_resources
  }
}

resource "aws_iam_role_policy" "hooks" {
  count = local.create_codedeploy_role && var.attach_hooks_policy && length(local.hooks_policy_resources) > 0 ? 1 : 0

  name   = "codedeploy-lambda-hooks"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

# Inline policy granting sns:Publish for notification triggers.
data "aws_iam_policy_document" "triggers" {
  count = local.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0

  statement {
    sid       = "PublishDeploymentNotifications"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = local.trigger_target_arns
  }
}

resource "aws_iam_role_policy" "triggers" {
  count = local.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0

  name   = "codedeploy-lambda-triggers"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

###############################################################################
# CodeDeploy deployment group
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group ? 1 : 0

  app_name               = local.app_name
  deployment_group_name  = local.deployment_group_name
  service_role_arn       = local.service_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.automatic_rollback_enabled
    events  = var.automatic_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.alarm_enabled && length(var.alarm_names) > 0 ? [1] : []

    content {
      enabled = true
      alarms  = var.alarm_names
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.notification_triggers

    content {
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
      trigger_events     = trigger_configuration.value.trigger_events
    }
  }

  tags = var.tags
}

###############################################################################
# Deployment script + optional deployment execution
###############################################################################

resource "local_file" "deploy_script" {
  count = local.create_deployment && var.save_deploy_script ? 1 : 0

  content         = local.deploy_script
  filename        = local.deploy_script_path
  file_permission = "0755"
}

resource "null_resource" "deploy" {
  count = local.create_deployment && var.run_deployment ? 1 : 0

  triggers = merge(
    {
      app_name              = local.app_name
      deployment_group_name = local.deployment_group_name
      revision              = local.revision_json
    },
    var.force_deploy ? { force_deploy = uuid() } : {},
  )

  provisioner "local-exec" {
    command = local.deploy_script
  }

  depends_on = [
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application."
  value       = try(aws_codedeploy_app.this[0].name, null)
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  value       = try(aws_codedeploy_deployment_group.this[0].deployment_group_name, local.deployment_group_name)
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy IAM role."
  value       = local.service_role_arn
}

output "app_spec_content" {
  description = "Rendered AppSpec JSON content used for the deployment revision."
  value       = local.app_spec_content
}

output "deployment_revision_json" {
  description = "CodeDeploy revision JSON payload referencing the AppSpec content."
  value       = local.revision_json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "name_prefix" {
  description = "Prefix used for the VPC Name tag. A random integer (1-100) is appended to it."
  type        = string
  default     = "tf-project"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "max_subnet_count" {
  description = "Maximum number of availability zones (and therefore subnets per tier) the subnets are spread across."
  type        = number
  default     = 3
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for the public web subnets. The number of subnets equals the list length."
  type        = list(string)
  default     = ["10.16.0.0/20", "10.16.16.0/20", "10.16.32.0/20"]
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for the private application subnets. The number of subnets equals the list length."
  type        = list(string)
  default     = ["10.16.48.0/20", "10.16.64.0/20", "10.16.80.0/20"]
}

variable "database_subnet_cidrs" {
  description = "List of CIDR blocks for the private database subnets. The number of subnets equals the list length."
  type        = list(string)
  default     = ["10.16.96.0/20", "10.16.112.0/20", "10.16.128.0/20"]
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for the private reserved subnets. The number of subnets equals the list length."
  type        = list(string)
  default     = ["10.16.144.0/20", "10.16.160.0/20", "10.16.176.0/20"]
}

variable "interface_endpoints" {
  description = "Map of interface VPC endpoints to create, keyed by a short logical name."
  type = map(object({
    service_name        = string
    subnet_ids          = optional(list(string), [])
    private_dns_enabled = optional(bool, true)
  }))
  default = {}
}

variable "gateway_endpoint_service_name" {
  description = "Service name for an optional gateway VPC endpoint (e.g. com.amazonaws.<region>.s3). Empty string disables it."
  type        = string
  default     = ""
}

###############################################################################
# Discovery / randomness
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

resource "random_integer" "vpc_name_suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "az" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
}

###############################################################################
# Derived values
###############################################################################

locals {
  name = "${var.name_prefix}-${random_integer.vpc_name_suffix.result}"

  # Randomly shuffled availability zones, limited to max_subnet_count.
  azs = random_shuffle.az.result

  tiers = {
    web = {
      cidrs     = var.web_subnet_cidrs
      public_ip = true
    }
    app = {
      cidrs     = var.app_subnet_cidrs
      public_ip = false
    }
    database = {
      cidrs     = var.database_subnet_cidrs
      public_ip = false
    }
    reserved = {
      cidrs     = var.reserved_subnet_cidrs
      public_ip = false
    }
  }

  # Flatten every tier's CIDR list into a single map keyed by "<tier>-<index>".
  subnets = merge([
    for tier, cfg in local.tiers : {
      for idx, cidr in cfg.cidrs : "${tier}-${idx}" => {
        tier      = tier
        cidr      = cidr
        az        = local.azs[idx % length(local.azs)]
        public_ip = cfg.public_ip
      }
    }
  ]...)

  web_subnet_keys     = [for k, v in local.subnets : k if v.tier == "web"]
  private_subnet_keys = [for k, v in local.subnets : k if v.tier != "web"]

  create_igw        = length(local.web_subnet_keys) > 0
  create_private_rt = length(local.private_subnet_keys) > 0
}

locals {
  web_subnet_ids     = [for k in local.web_subnet_keys : aws_subnet.this[k].id]
  private_subnet_ids = [for k in local.private_subnet_keys : aws_subnet.this[k].id]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

###############################################################################
# Internet gateway (conditional on web subnets)
###############################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.name}-igw"
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.this.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = each.value.public_ip

  tags = {
    Name = "${local.name}-${each.key}"
    Tier = each.value.tier
  }
}

###############################################################################
# Public routing (dedicated public route table for the web tier)
###############################################################################

resource "aws_route_table" "public" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.name}-public"
  }
}

resource "aws_route" "public_internet" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = { for k, v in local.subnets : k => v if v.tier == "web" }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Private routing (single shared route table for app, database and reserved)
###############################################################################

resource "aws_route_table" "private" {
  count = local.create_private_rt ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.name}-private"
  }
}

resource "aws_route_table_association" "private" {
  for_each = { for k, v in local.subnets : k => v if v.tier != "web" }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Interface VPC endpoints (dynamic map configuration)
###############################################################################

resource "aws_security_group" "endpoint" {
  count = length(var.interface_endpoints) > 0 ? 1 : 0

  name_prefix = "${local.name}-endpoint-"
  description = "Allows HTTPS traffic to interface VPC endpoints from within the VPC."
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "${local.name}-endpoint"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "endpoint_ingress" {
  count = length(var.interface_endpoints) > 0 ? 1 : 0

  type              = "ingress"
  description       = "HTTPS from within the VPC"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.endpoint[0].id
}

resource "aws_security_group_rule" "endpoint_egress" {
  count = length(var.interface_endpoints) > 0 ? 1 : 0

  type              = "egress"
  description       = "HTTPS back to the VPC"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.endpoint[0].id
}

resource "aws_vpc_endpoint" "interface" {
  for_each = var.interface_endpoints

  vpc_id              = aws_vpc.this.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = length(each.value.subnet_ids) > 0 ? each.value.subnet_ids : local.private_subnet_ids
  security_group_ids  = [aws_security_group.endpoint[0].id]
  private_dns_enabled = each.value.private_dns_enabled

  tags = {
    Name = "${local.name}-${each.key}"
  }
}

###############################################################################
# Gateway VPC endpoint (conditional, associated with the private route table)
###############################################################################

resource "aws_vpc_endpoint" "gateway" {
  count = var.gateway_endpoint_service_name != "" && local.create_private_rt ? 1 : 0

  vpc_id            = aws_vpc.this.id
  service_name      = var.gateway_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id]

  tags = {
    Name = "${local.name}-gateway"
  }
}

###############################################################################
# Outputs
###############################################################################

output "name" {
  description = "Resolved name of the VPC (prefix + random suffix)."
  value       = local.name
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Randomly shuffled availability zones used for the subnets."
  value       = local.azs
}

output "web_subnet_ids" {
  description = "IDs of the public web subnets."
  value       = local.web_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of all private subnets (app, database and reserved)."
  value       = local.private_subnet_ids
}

output "subnet_ids" {
  description = "Map of every subnet key to its ID."
  value       = { for k, v in aws_subnet.this : k => v.id }
}

output "internet_gateway_id" {
  description = "ID of the internet gateway, if created."
  value       = one(aws_internet_gateway.this[*].id)
}

output "public_route_table_id" {
  description = "ID of the public route table, if created."
  value       = one(aws_route_table.public[*].id)
}

output "private_route_table_id" {
  description = "ID of the shared private route table, if created."
  value       = one(aws_route_table.private[*].id)
}

output "interface_endpoint_ids" {
  description = "Map of interface endpoint keys to their IDs."
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "gateway_endpoint_id" {
  description = "ID of the gateway endpoint, if created."
  value       = one(aws_vpc_endpoint.gateway[*].id)
}

###############################################################################
# Variables
###############################################################################

variable "domain_name" {
  description = "Internal DNS domain name used by the VPC DHCP option set and the private Route 53 hosted zone."
  type        = string
  default     = "internal"
}

variable "dns_servers" {
  description = "DNS resolvers for the VPC DHCP option set (VPC built-in resolver plus a standard public DNS server)."
  type        = list(string)
  default     = ["AmazonProvidedDNS", "8.8.8.8"]
}

variable "admin_cidrs" {
  description = "List of administrator CIDR blocks permitted to SSH into instances via the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

###############################################################################
# Data sources
###############################################################################

# Static provider metadata lookup - no pre-existing infrastructure required.
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr = "10.0.0.0/16"

  # Ordered map of subnet name -> CIDR block.
  subnets = {
    reserved   = "10.0.0.0/24"
    sandbox    = "10.0.1.0/24"
    web        = "10.0.2.0/24"
    database   = "10.0.3.0/24"
    gameserver = "10.0.4.0/22"
  }

  # Spread the five subnets across the region's available AZs (element wraps).
  subnet_az = {
    reserved   = element(data.aws_availability_zones.available.names, 0)
    sandbox    = element(data.aws_availability_zones.available.names, 0)
    web        = element(data.aws_availability_zones.available.names, 1)
    database   = element(data.aws_availability_zones.available.names, 1)
    gameserver = element(data.aws_availability_zones.available.names, 2)
  }
}

###############################################################################
# VPC and networking core
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

# DHCP option set: internal domain name + VPC resolver and public DNS server.
resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.domain_name
  domain_name_servers = var.dns_servers

  tags = {
    Name = "main"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

# Private hosted zone for the internal domain, associated with the VPC.
resource "aws_route53_zone" "internal" {
  name    = var.domain_name
  comment = "Private hosted zone for the internal ${var.domain_name} domain"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = var.domain_name
  }
}

###############################################################################
# Subnets (no public IP auto-assignment) and per-subnet route tables
###############################################################################

resource "aws_subnet" "main" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = local.subnet_az[each.key]
  map_public_ip_on_launch = false

  tags = {
    Name = each.key
  }
}

resource "aws_route_table" "main" {
  for_each = local.subnets

  vpc_id = aws_vpc.main.id

  tags = {
    Name = each.key
  }
}

resource "aws_route" "default" {
  for_each = local.subnets

  route_table_id         = aws_route_table.main[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route_table_association" "main" {
  for_each = local.subnets

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.main[each.key].id
}

###############################################################################
# Network ACLs
###############################################################################

# Sandbox: allow all TCP inbound and outbound.
resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["sandbox"].id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "sandbox"
  }
}

# Web: inbound SSH, HTTP, HTTPS and ephemeral ports; all TCP outbound.
resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["web"].id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "web"
  }
}

# Database: only TCP to and from the web and gameserver subnet CIDRs.
resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["database"].id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = local.subnets["web"]
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = local.subnets["gameserver"]
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = local.subnets["web"]
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = local.subnets["gameserver"]
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "database"
  }
}

# Gameserver: inbound SSH, game ports (TCP/UDP) and ephemeral (TCP/UDP); all TCP/UDP outbound.
resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["gameserver"].id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    protocol   = "udp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    protocol   = "udp"
    rule_no    = 140
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  ingress {
    protocol   = "udp"
    rule_no    = 160
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "udp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "gameserver"
  }
}

###############################################################################
# Security groups
###############################################################################

# Home SSH: SSH from admin CIDRs and from itself, egress restricted to the VPC.
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from administrator CIDRs and from self; egress limited to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from administrator CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Home SSH"
  }
}

# Packer SSH: SSH from the VPC CIDR and from itself, egress restricted to the VPC.
resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from the VPC CIDR and from self; egress limited to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "SSH from members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "Packer SSH"
  }
}

variable "env" {
  description = "Environment name used to prefix resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the three public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the three private application subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "database_subnet_cidrs" {
  description = "CIDR blocks for the three private database subnets"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""

  # First three availability zones in the current region
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
  }
}

# ---------------------------------------------------------------------------
# Public tier
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# NAT egress: three Elastic IPs and three NAT Gateways in the public subnets
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-gateway-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Private application tier (one dedicated route table per AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}private-rt-${count.index + 1}"
  }
}

resource "aws_route" "private_nat" {
  count = 3

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Private database tier (shared route table, local route only)
# ---------------------------------------------------------------------------
resource "aws_subnet" "database" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.database_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}database-subnet-${count.index + 1}"
  }
}

# The shared database route table is intentionally configured with only the
# implicit local route that matches the VPC CIDR block; no outbound route is
# added so the database tier has no direct internet egress path.
resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}database-rt"
  }
}

resource "aws_route_table_association" "database" {
  count = 3

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database.id
}

###############################################################################
# Secure, production-grade private S3 storage bucket
#
# Features:
#   - Optional account-alias / random name prefixes
#   - Bucket policy that extends a custom policy with TLS-enforcement and
#     S3 service principal write access for inventory/analytics
#   - Public access block, ownership controls, SSE, versioning, lifecycle,
#     analytics, inventory, logging, transfer acceleration, ACL and CORS
###############################################################################

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "base_bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prepend the AWS IAM account alias to the bucket name."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Prepend a random hex prefix to the bucket name."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional custom bucket policy (JSON string) to merge with the managed statements."
  type        = string
  default     = null
}

variable "enable_s3_public_access_block" {
  description = "Whether to enable the S3 public access block configuration."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket (e.g. BucketOwnerEnforced)."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "s3_bucket_acl" {
  description = "Optional canned ACL to apply to the bucket. Leave null to use object ownership controls."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "Optional KMS key id/ARN. When set, enables aws:kms encryption instead of AES256."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether S3 bucket keys are enabled for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status of the bucket (Enabled, Suspended, Disabled)."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Whether to force destroy the bucket even when it contains objects."
  type        = bool
  default     = false
}

variable "enable_analytics" {
  description = "Whether storage class analytics configuration is enabled."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Whether the bucket inventory configuration is enabled."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "External target bucket for access logging. When set, logging is enabled."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled/Suspended). When not null it is configured."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Tags to apply to the bucket."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Static provider metadata / account information
# ---------------------------------------------------------------------------
data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_id" "this" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

# ---------------------------------------------------------------------------
# Computed naming
# ---------------------------------------------------------------------------
locals {
  prefix_parts = compact([
    var.use_account_alias_prefix ? data.aws_iam_account_alias.current[0].account_alias : "",
    var.use_random_suffix ? random_id.this[0].hex : "",
  ])

  bucket_name = length(local.prefix_parts) > 0 ? "${join("-", local.prefix_parts)}-${var.base_bucket_name}" : var.base_bucket_name
}

# ---------------------------------------------------------------------------
# Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Ownership controls
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# ---------------------------------------------------------------------------
# Public access block
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Server-side encryption
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

# ---------------------------------------------------------------------------
# Versioning
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

# ---------------------------------------------------------------------------
# Lifecycle configuration
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "analytics-export-expiration"
    status = var.enable_analytics ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "inventory-export-expiration"
    status = var.enable_bucket_inventory ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }
}

# ---------------------------------------------------------------------------
# Storage class analytics
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "bucket-analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          format     = "CSV"
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# ---------------------------------------------------------------------------
# Bucket inventory
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket                   = aws_s3_bucket.this.id
  name                     = "bucket-inventory"
  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# ---------------------------------------------------------------------------
# Access logging (conditional)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# ---------------------------------------------------------------------------
# Transfer acceleration (conditional)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# ---------------------------------------------------------------------------
# Bucket ACL (conditional)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ---------------------------------------------------------------------------
# CORS configuration (dynamic)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# ---------------------------------------------------------------------------
# Bucket policy
# ---------------------------------------------------------------------------
locals {
  custom_policy_statements = try(jsondecode(var.custom_bucket_policy).Statement, [])

  managed_policy_statements = [
    {
      Sid       = "DenyUnencryptedTransport"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource = [
        aws_s3_bucket.this.arn,
        "${aws_s3_bucket.this.arn}/*",
      ]
      Condition = {
        Bool = {
          "aws:SecureTransport" = "false"
        }
      }
    },
    {
      Sid       = "AllowS3InventoryAndAnalytics"
      Effect    = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = [
        "s3:PutObject",
      ]
      Resource = [
        "${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*",
        "${aws_s3_bucket.this.arn}/_AWSBucketInventory/*",
      ]
      Condition = {
        StringEquals = {
          "s3:x-amz-acl" = "bucket-owner-full-control"
        }
      }
    },
  ]

  bucket_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = concat(local.custom_policy_statements, local.managed_policy_statements)
  })
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = local.bucket_policy
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "bucket_id" {
  description = "The name/id of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

###############################################################################
# Versatile Amazon S3 bucket module
#
# Supports:
#   - Server-side encryption (AES256 / aws:kms / aws:kms:dsse / disabled)
#   - Public access block
#   - Canned ACLs and JSON-style grant based access control policies
#   - Bucket ownership controls
#   - Versioning and MFA delete
#   - Bucket logging
#   - S3 Object Lock
#   - Static website hosting
#   - Intelligent tiering
#   - CloudWatch request metrics
#   - CORS rules
#   - Lifecycle configuration rules
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "create_bucket" {
  description = "Controls if the S3 bucket and its associated resources should be created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error"
  type        = bool
  default     = false
}

variable "environment" {
  description = "The environment name used within the default tags"
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "A map of additional tags to add to all supported resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Server-side encryption
# ---------------------------------------------------------------------------
variable "sse_algorithm" {
  description = "The server-side encryption algorithm to use. Valid values are AES256, aws:kms, aws:kms:dsse and none (disables encryption configuration)"
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "aws:kms", "aws:kms:dsse", "none"], var.sse_algorithm)
    error_message = "The sse_algorithm value must be one of: AES256, aws:kms, aws:kms:dsse, none."
  }
}

variable "kms_master_key_id" {
  description = "The AWS KMS master key ID used for the SSE-KMS encryption"
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# Public access block
# ---------------------------------------------------------------------------
variable "block_public_access" {
  description = "Controls if the S3 bucket public access block resource should be created"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# ACLs and grants
# ---------------------------------------------------------------------------
variable "acl" {
  description = "The canned ACL to apply to the bucket. Set to null to disable the ACL resource"
  type        = string
  default     = null
}

variable "owner_id" {
  description = "The canonical user ID of the owner. Defaults to the caller identity canonical user ID"
  type        = string
  default     = null
}

variable "grants" {
  description = "A list of access grant objects used to build an access control policy for the bucket"
  type = list(object({
    id          = string
    type        = string
    permissions = list(string)
    uri         = string
  }))
  default = []
}

# ---------------------------------------------------------------------------
# Ownership controls
# ---------------------------------------------------------------------------
variable "control_object_ownership" {
  description = "Whether to manage the S3 bucket ownership controls resource"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting used when control_object_ownership is true"
  type        = string
  default     = "ObjectWriter"
}

# ---------------------------------------------------------------------------
# Versioning
# ---------------------------------------------------------------------------
variable "versioning_enabled" {
  description = "Whether versioning is enabled for the bucket (defaults to disabled)"
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Whether MFA delete is enabled for the bucket (defaults to disabled)"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
variable "bucket_logging" {
  description = "Controls if bucket logging should be enabled"
  type        = bool
  default     = false
}

variable "target_bucket" {
  description = "The name of the bucket that will receive the log objects"
  type        = string
  default     = ""
}

variable "target_prefix" {
  description = "The prefix used for log object keys"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Object lock
# ---------------------------------------------------------------------------
variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled for the bucket"
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Map of S3 Object Lock configuration options. Mode defaults to GOVERNANCE"
  type        = any
  default = {
    mode = "GOVERNANCE"
  }
}

# ---------------------------------------------------------------------------
# Static website hosting
# ---------------------------------------------------------------------------
variable "website" {
  description = "Map of static website hosting configuration options"
  type        = any
  default     = {}
}

# ---------------------------------------------------------------------------
# Intelligent tiering
# ---------------------------------------------------------------------------
variable "intelligent_tiering" {
  description = "List of intelligent tiering configuration maps"
  type        = any
  default     = []
}

# ---------------------------------------------------------------------------
# CloudWatch metrics
# ---------------------------------------------------------------------------
variable "metric_configuration" {
  description = "List of bucket metric (CloudWatch request metrics) configuration maps"
  type        = any
  default     = []
}

# ---------------------------------------------------------------------------
# CORS
# ---------------------------------------------------------------------------
variable "cors_rule" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

# ---------------------------------------------------------------------------
# Lifecycle
# ---------------------------------------------------------------------------
variable "lifecycle_rule" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

###############################################################################
# Locals
###############################################################################

locals {
  create = var.create_bucket

  default_tags = merge(
    var.tags,
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    }
  )

  create_sse               = var.create_bucket && var.sse_algorithm != "none"
  create_public_access     = var.create_bucket && var.block_public_access
  create_acl               = var.create_bucket && (var.acl != null || length(var.grants) > 0)
  create_ownership_control = var.create_bucket && var.control_object_ownership
  create_logging           = var.create_bucket && var.bucket_logging
  create_object_lock       = var.create_bucket && var.object_lock_enabled
  create_website           = var.create_bucket && length(try(var.website, {})) > 0
  create_cors              = var.create_bucket && length(var.cors_rule) > 0
  create_lifecycle         = var.create_bucket && length(var.lifecycle_rule) > 0

  # Flatten grants so every grant entry carries a single permission
  grants = flatten([
    for grant in var.grants : [
      for permission in grant.permissions : {
        id         = grant.id
        type       = grant.type
        uri        = grant.uri
        permission = permission
      }
    ]
  ])

  versioning_status = var.versioning_enabled || var.object_lock_enabled ? "Enabled" : "Suspended"
  mfa_delete_status = var.versioning_enabled && var.mfa_delete ? "Enabled" : "Disabled"
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  count = local.create ? 1 : 0

  bucket              = var.bucket
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Public access block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_public_access ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

###############################################################################
# Server-side encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_sse ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
      sse_algorithm     = var.sse_algorithm
    }

    bucket_key_enabled = var.sse_algorithm == "aws:kms" && var.kms_master_key_id != "" ? var.bucket_key_enabled : null
  }
}

###############################################################################
# Ownership controls
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_ownership_control ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

###############################################################################
# ACLs / grants
###############################################################################

data "aws_canonical_user_id" "current" {
  count = local.create_acl ? 1 : 0
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "access_control_policy" {
    for_each = length(local.grants) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants

        content {
          permission = grant.value.permission

          grantee {
            id   = grant.value.id != "" ? grant.value.id : null
            type = grant.value.type
            uri  = grant.value.uri != "" ? grant.value.uri : null
          }
        }
      }

      owner {
        id = var.owner_id != null ? var.owner_id : data.aws_canonical_user_id.current[0].id
      }
    }
  }

  acl = length(local.grants) == 0 ? var.acl : null

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  count = local.create ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = local.versioning_status
    mfa_delete = local.mfa_delete_status
  }

  depends_on = [
    aws_s3_bucket_acl.this,
    aws_s3_bucket_ownership_controls.this,
  ]
}

###############################################################################
# Logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_logging ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.target_bucket
  target_prefix = var.target_prefix
}

###############################################################################
# Object Lock
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_object_lock ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = length(try(var.object_lock_configuration, {})) > 0 ? [var.object_lock_configuration] : []

    content {
      default_retention {
        mode  = try(rule.value.mode, "GOVERNANCE")
        days  = try(rule.value.days, null)
        years = try(rule.value.years, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_website ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try([var.website.index_document], [])

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website.error_document], [])

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try([var.website.redirect_all_requests_to], [])

    content {
      host_name = split("/", redirect_all_requests_to.value)[0]
      protocol  = try(compact(split("/", redirect_all_requests_to.value))[1], null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])

    content {
      dynamic "condition" {
        for_each = try([routing_rule.value.condition], [])

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

###############################################################################
# Intelligent tiering
###############################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = { for idx, cfg in var.intelligent_tiering : idx => cfg if var.create_bucket }

  bucket = aws_s3_bucket.this[0].id
  name   = try(each.value.name, "intelligent-tiering-${each.key}")

  status = try(each.value.status, null)

  dynamic "filter" {
    for_each = length(try(each.value.filter, {})) > 0 ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)

      tags = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = try(each.value.tiering, [])

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

###############################################################################
# CloudWatch request metrics
###############################################################################

resource "aws_s3_bucket_metric" "this" {
  for_each = { for idx, cfg in var.metric_configuration : idx => cfg if var.create_bucket }

  bucket = aws_s3_bucket.this[0].id
  name   = try(each.value.name, each.key)

  dynamic "filter" {
    for_each = length(try(each.value.filter, {})) > 0 ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)

      tags = try(filter.value.tags, null)
    }
  }
}

###############################################################################
# CORS configuration
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_cors ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_lifecycle ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = length(try(rule.value.filter, {})) > 0 ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, [])

            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, 0) > 0 ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])

        content {
          noncurrent_days           = try(noncurrent_version_transition.value.days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "expiration" {
        for_each = length(try(rule.value.expiration, {})) > 0 ? [rule.value.expiration] : []

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = length(try(rule.value.noncurrent_version_expiration, {})) > 0 ? [rule.value.noncurrent_version_expiration] : []

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.days, null)
        }
      }
    }
  }
}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || length(var.name) <= 63
    error_message = "The bucket name must be 63 characters or fewer."
  }
}

variable "name_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. If omitted, no prefix is used."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "The bucket name prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "The object_ownership value must be one of BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  }
}

variable "acl" {
  description = "The canned ACL to apply. Only used when object_ownership is set to ObjectWriter."
  type        = string
  default     = "private"
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for server-side encryption. When provided the SSE algorithm defaults to aws:kms."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS. Only applied when a kms_key_arn is provided."
  type        = bool
  default     = true
}

variable "versioning_enabled" {
  description = "Whether to enable bucket versioning. When false the versioning status defaults to Suspended."
  type        = bool
  default     = false
}

variable "policy" {
  description = "A custom JSON bucket policy document to merge with the enforced SSL-only and logging permission statements."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs allowed to deliver access logs (via logging.s3.amazonaws.com) into this bucket."
  type        = list(string)
  default     = []
}

variable "eventbridge" {
  description = "Whether to enable EventBridge notifications for the S3 bucket."
  type        = bool
  default     = false
}

variable "logging" {
  description = "Map of server access logging configuration. Object Lock and server access logging are mutually exclusive."
  type = map(object({
    target_bucket = string
    target_prefix = optional(string)
  }))
  default = {}
}

variable "object_lock_enabled" {
  description = "Whether to enable S3 Object Lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object Lock default retention configuration. Required when object_lock_enabled is true."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_configuration" {
  description = "Multi-rule cross-region replication configuration with priorities and source selection criteria."
  type = object({
    role = string
    rules = list(object({
      id       = string
      priority = optional(number)
      status   = optional(bool, true)
      filter = optional(object({
        prefix = optional(string)
        tag = optional(object({
          key   = string
          value = string
        }))
        and = optional(object({
          prefix = optional(string)
          tags   = optional(map(string))
        }))
      }))
      delete_marker_replication_status = optional(string, "Disabled")
      source_selection_criteria = optional(object({
        replica_modifications = optional(object({
          status = string
        }))
        sse_kms_encrypted_objects = optional(object({
          status = string
        }))
      }))
      destination = object({
        bucket        = string
        storage_class = optional(string)
        access_control_translation = optional(object({
          owner = string
        }))
        encryption_configuration = optional(object({
          replica_kms_key_id = string
        }))
        metrics = optional(object({
          status = string
          event_threshold = optional(object({
            minutes = number
          }))
        }))
        replication_time = optional(object({
          status = string
          time = optional(object({
            minutes = number
          }))
        }))
      })
    }))
  })
  default = null
}

variable "inventory_configurations" {
  description = "List of S3 Inventory configurations. Destinations may target Parquet output with SSE-S3 or SSE-KMS encryption on a schedule."
  type = list(object({
    name                     = string
    included_object_versions = string
    enabled                  = optional(bool, true)
    frequency                = string
    optional_fields          = optional(list(string))
    filter = optional(object({
      prefix = optional(string)
    }))
    destination = object({
      bucket_arn = string
      account_id = optional(string)
      prefix     = optional(string)
      format     = string
      encryption = optional(object({
        sse_s3 = optional(bool)
        sse_kms = optional(object({
          key_id = string
        }))
      }))
    })
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules for the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules handling object expiration, transitions, noncurrent versions and incomplete multipart upload aborts."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    filter = optional(object({
      prefix                   = optional(string)
      object_size_greater_than = optional(number)
      object_size_less_than    = optional(number)
      tag = optional(object({
        key   = string
        value = string
      }))
      and = optional(object({
        prefix                   = optional(string)
        tags                     = optional(map(string))
        object_size_greater_than = optional(number)
        object_size_less_than    = optional(number)
      }))
    }))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
    expiration = optional(object({
      date                         = optional(string)
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      date          = optional(string)
      days          = optional(number)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
    }))
    noncurrent_version_transition = optional(list(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
      storage_class             = string
    })), [])
  }))
  default = []
}

variable "tags" {
  description = "A map of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  sse_algorithm = var.kms_key_arn != null ? "aws:kms" : "AES256"
  bucket_key    = var.kms_key_arn != null ? var.bucket_key_enabled : false
  versioning    = var.object_lock_enabled || var.versioning_enabled ? "Enabled" : "Suspended"
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket        = var.name
  bucket_prefix = var.name_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Object ownership and ACL (ACLs only provisioned for ObjectWriter)
################################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

################################################################################
# Public access block
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

################################################################################
# Server-side encryption
################################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = var.kms_key_arn
      sse_algorithm     = local.sse_algorithm
    }

    bucket_key_enabled = local.bucket_key
  }
}

################################################################################
# Versioning
################################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning
  }
}

################################################################################
# Bucket policy: custom JSON + enforced SSL-only + conditional logging permissions
################################################################################

data "aws_iam_policy_document" "this" {
  source_policy_documents = compact([var.policy])

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "AllowLoggingServicePutObject"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this.arn}/*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.this.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# EventBridge notifications
################################################################################

resource "aws_s3_bucket_notification" "this" {
  count = var.eventbridge ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

################################################################################
# Server access logging (mutually exclusive with Object Lock)
################################################################################

resource "aws_s3_bucket_logging" "this" {
  for_each = var.logging

  bucket        = aws_s3_bucket.this.id
  target_bucket = each.value.target_bucket
  target_prefix = coalesce(each.value.target_prefix, "")

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Server access logging cannot be enabled on a bucket that has Object Lock enabled."
    }
  }
}

################################################################################
# Object Lock (mutually exclusive with source bucket logging)
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.object_lock_configuration != null
      error_message = "object_lock_configuration must be provided when object_lock_enabled is true."
    }

    precondition {
      condition     = length(var.logging) == 0
      error_message = "Object Lock cannot be enabled on a bucket that is configured as a server access logging target."
    }
  }
}

################################################################################
# Cross-region replication
################################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = var.replication_configuration.rules

    content {
      id       = rule.value.id
      priority = try(rule.value.priority, null)
      status   = try(rule.value.status, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tag, null) != null ? [filter.value.tag] : []

            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }

          dynamic "and" {
            for_each = try(filter.value.and, null) != null ? [filter.value.and] : []

            content {
              prefix = try(and.value.prefix, null)
              tags   = try(and.value.tags, null)
            }
          }
        }
      }

      delete_marker_replication {
        status = try(rule.value.delete_marker_replication_status, "Disabled")
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "replica_modifications" {
            for_each = try(source_selection_criteria.value.replica_modifications, null) != null ? [source_selection_criteria.value.replica_modifications] : []

            content {
              status = replica_modifications.value.status
            }
          }

          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []

            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) != null ? [rule.value.destination.access_control_translation] : []

          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.encryption_configuration, null) != null ? [rule.value.destination.encryption_configuration] : []

          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [rule.value.destination.metrics] : []

          content {
            status = metrics.value.status

            dynamic "event_threshold" {
              for_each = try(metrics.value.event_threshold, null) != null ? [metrics.value.event_threshold] : []

              content {
                minutes = event_threshold.value.minutes
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [rule.value.destination.replication_time] : []

          content {
            status = replication_time.value.status

            dynamic "time" {
              for_each = try(replication_time.value.time, null) != null ? [replication_time.value.time] : []

              content {
                minutes = time.value.minutes
              }
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Inventory
################################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for idx, cfg in var.inventory_configurations : idx => cfg }

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = each.value.included_object_versions
  enabled                  = each.value.enabled
  optional_fields          = try(each.value.optional_fields, null)

  schedule {
    frequency = each.value.frequency
  }

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
    }
  }

  destination {
    bucket {
      format     = each.value.destination.format
      bucket_arn = each.value.destination.bucket_arn
      account_id = try(each.value.destination.account_id, null)
      prefix     = try(each.value.destination.prefix, null)

      dynamic "encryption" {
        for_each = try(each.value.destination.encryption, null) != null ? [each.value.destination.encryption] : []

        content {
          dynamic "sse_s3" {
            for_each = try(encryption.value.sse_s3, false) ? [1] : []

            content {}
          }

          dynamic "sse_kms" {
            for_each = try(encryption.value.sse_kms, null) != null ? [encryption.value.sse_kms] : []

            content {
              key_id = sse_kms.value.key_id
            }
          }
        }
      }
    }
  }
}

################################################################################
# CORS
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

################################################################################
# Lifecycle
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : [{}]

        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)

          dynamic "tag" {
            for_each = try(filter.value.tag, null) != null ? [filter.value.tag] : []

            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }

          dynamic "and" {
            for_each = try(filter.value.and, null) != null ? [filter.value.and] : []

            content {
              prefix                   = try(and.value.prefix, null)
              tags                     = try(and.value.tags, null)
              object_size_greater_than = try(and.value.object_size_greater_than, null)
              object_size_less_than    = try(and.value.object_size_less_than, null)
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ---------------------------------------------------------------------------
# Account-wide security baselines and IAM governance structure.
#
# This configuration is fully self-contained: every resource it references is
# declared within this file. No pre-existing infrastructure is assumed.
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------

variable "group_name_prefix" {
  description = "Prefix applied to the developer and admin IAM group names."
  type        = string
  default     = "app"
}

variable "remote_state_bucket_name" {
  description = "Globally unique name of the S3 bucket used to store Terraform remote state."
  type        = string
  default     = "app-terraform-remote-state"
}

variable "allowed_region" {
  description = "The single designated AWS region in which developers may create S3 buckets."
  type        = string
  default     = "us-east-1"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = var.allowed_region

  # IAM group names are account-unique and the group resource has no
  # name_prefix argument, so a short unique suffix keeps repeated deployments
  # from colliding while preserving the configurable prefix-derived names.
  unique_suffix = substr(uuid(), 0, 8)

  developer_group_name = "${var.group_name_prefix}_developer"
  admin_group_name     = "${var.group_name_prefix}_admin"

  # AWS-managed policies attached to the developer group.
  developer_managed_policies = toset([
    "IAMReadOnlyAccess",
    "IAMUserChangePassword",
    "IAMUserSSHKeys",
  ])

  # Predetermined service-linked role paths that developers may manage.
  ec2_autoscaling_service_linked_roles = toset([
    "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
    "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spot.amazonaws.com/AWSServiceRoleForEC2Spot",
    "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spotfleet.amazonaws.com/AWSServiceRoleForEC2SpotFleet",
  ])
}

# ---------------------------------------------------------------------------
# Account-wide IAM password policy
# ---------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
}

# ---------------------------------------------------------------------------
# Account-level S3 public access block
# ---------------------------------------------------------------------------

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Designated remote-state S3 bucket (created here so it can be referenced by
# the developer policy without hardcoding a bucket ARN).
# ---------------------------------------------------------------------------

# The bucket name lives in a global namespace; bucket_prefix yields a unique
# name on every deployment so repeated applies never collide.
resource "aws_s3_bucket" "remote_state" {
  bucket_prefix = "${var.remote_state_bucket_name}-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "remote_state" {
  description             = "Customer managed KMS key used to encrypt the Terraform remote-state bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "remote_state" {
  name          = "alias/${aws_s3_bucket.remote_state.bucket}"
  target_key_id = aws_kms_key.remote_state.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.remote_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# IAM groups
# ---------------------------------------------------------------------------

resource "aws_iam_group" "developer" {
  name = "${local.developer_group_name}-${local.unique_suffix}"
}

resource "aws_iam_group" "admin" {
  name = "${local.admin_group_name}-${local.unique_suffix}"
}

# ---------------------------------------------------------------------------
# Developer group: AWS-managed policy attachments
# ---------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developer_managed" {
  for_each = local.developer_managed_policies

  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/${each.value}"
}

# ---------------------------------------------------------------------------
# Developer group: custom policy - manage personal access keys
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "developer_access_keys" {
  statement {
    sid    = "ManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:GetUser",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
    ]
  }
}

resource "aws_iam_policy" "developer_access_keys" {
  name_prefix = "${var.group_name_prefix}_developer_access_keys-"
  description = "Allows developers to manage their own IAM access keys."
  policy      = data.aws_iam_policy_document.developer_access_keys.json
}

resource "aws_iam_group_policy_attachment" "developer_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_access_keys.arn
}

# ---------------------------------------------------------------------------
# Developer group: custom policy - manage own virtual MFA device
# (deactivation requires an MFA-authenticated session)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "developer_mfa" {
  statement {
    sid    = "ManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
    ]
  }

  statement {
    sid    = "ListAndManageOwnMFA"
    effect = "Allow"

    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListUsers",
      "iam:GetUser",
    ]

    resources = ["*"]
  }

  statement {
    sid       = "RequireMFAForDeactivateMFADevice"
    effect    = "Deny"
    actions   = ["iam:DeactivateMFADevice"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_mfa" {
  name_prefix = "${var.group_name_prefix}_developer_mfa-"
  description = "Allows developers to manage their own virtual MFA device; deactivation requires MFA."
  policy      = data.aws_iam_policy_document.developer_mfa.json
}

resource "aws_iam_group_policy_attachment" "developer_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa.arn
}

# ---------------------------------------------------------------------------
# Developer group: custom policy - MFA-gated S3 access
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "developer_s3_mfa" {
  # Bucket creation is restricted to the single designated region.
  statement {
    sid       = "DenyS3CreateBucketOutsideDesignatedRegion"
    effect    = "Deny"
    actions   = ["s3:CreateBucket"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [local.region]
    }
  }

  # The dedicated remote-state bucket and its contents are off limits.
  statement {
    sid    = "DenyRemoteStateBucketAccess"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.remote_state.arn,
      "${aws_s3_bucket.remote_state.arn}/*",
    ]
  }

  # General S3 access is only granted to MFA-authenticated sessions.
  statement {
    sid    = "AllowS3WithMFA"
    effect = "Allow"

    actions = [
      "s3:ListAllMyBuckets",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "developer_s3_mfa" {
  name_prefix = "${var.group_name_prefix}_developer_s3_mfa-"
  description = "MFA-gated S3 access with region restrictions and remote-state bucket protection."
  policy      = data.aws_iam_policy_document.developer_s3_mfa.json
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

# ---------------------------------------------------------------------------
# Developer group: custom policy - MFA-gated compute/observability access
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "developer_compute_mfa" {
  statement {
    sid    = "AllowComputeAndObservabilityWithMFA"
    effect = "Allow"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]

    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "ManageEC2AndAutoScalingServiceLinkedRolesWithMFA"
    effect = "Allow"

    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:PassRole",
    ]

    resources = local.ec2_autoscaling_service_linked_roles

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "developer_compute_mfa" {
  name_prefix = "${var.group_name_prefix}_developer_compute_mfa-"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling and their service-linked roles."
  policy      = data.aws_iam_policy_document.developer_compute_mfa.json
}

resource "aws_iam_group_policy_attachment" "developer_compute_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute_mfa.arn
}

# ---------------------------------------------------------------------------
# Administrative access: role assumable by the account root principal
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name_prefix          = "admin-"
  description          = "Administrative role assumed by the account root principal and delegated users."
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 3600
}

# Full administrative access, conditioned on an MFA-authenticated session.
data "aws_iam_policy_document" "admin_full_access" {
  statement {
    sid       = "FullAdministrativeAccessWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_full_access" {
  name_prefix = "${var.group_name_prefix}_admin_full_access_mfa-"
  description = "Grants full administrative access only when MFA is present."
  policy      = data.aws_iam_policy_document.admin_full_access.json
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

# ---------------------------------------------------------------------------
# Admin group: policy allowing members to assume the admin role with MFA
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_assume_role_group" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_assume_role_group" {
  name_prefix = "${var.group_name_prefix}_assume_admin_role-"
  description = "Allows admin group members to assume the admin role when MFA is present."
  policy      = data.aws_iam_policy_document.admin_assume_role_group.json
}

resource "aws_iam_group_policy_attachment" "admin_assume_role_group" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role_group.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

variable "aws_region" {
  description = "AWS region used to scope availability zone selection."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the primary multi-tier VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnets" {
  description = "List of 16 subnet definitions, each containing a CIDR block, a target availability zone, and a name tag."
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24", availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24", availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24", availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24", availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24", availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24", availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24", availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24", availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24", availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24", availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  available_azs = data.aws_availability_zones.available.names

  subnets = [
    for s in var.subnets : {
      name              = s.name
      cidr_block        = s.cidr_block
      availability_zone = contains(local.available_azs, s.availability_zone) ? s.availability_zone : "${var.aws_region}a"
    }
  ]

  private_tier_1 = { for i, s in local.subnets : s.name => s if i < 4 }
  private_tier_2 = { for i, s in local.subnets : s.name => s if i >= 4 && i < 8 }
  public_tier    = { for i, s in local.subnets : s.name => s if i >= 8 && i < 12 }
  spare_tier     = { for i, s in local.subnets : s.name => s if i >= 12 }

  first_private_subnet_name = local.subnets[0].name
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "deployme-natgw-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private_tier_1[local.first_private_subnet_name].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "deployme-natgw"
  }
}

resource "aws_subnet" "private_tier_1" {
  for_each = local.private_tier_1

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = {
    Name = each.value.name
  }
}

resource "aws_subnet" "private_tier_2" {
  for_each = local.private_tier_2

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = {
    Name = each.value.name
  }
}

resource "aws_subnet" "public_tier" {
  for_each = local.public_tier

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = each.value.name
  }
}

resource "aws_subnet" "spare_tier" {
  for_each = local.spare_tier

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = {
    Name = each.value.name
  }
}

resource "aws_route_table" "private_main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_main_route_table_association" "private_main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private_main.id
}

resource "aws_route_table_association" "private_tier_1" {
  for_each = local.private_tier_1

  subnet_id      = aws_subnet.private_tier_1[each.key].id
  route_table_id = aws_route_table.private_main.id
}

resource "aws_route_table_association" "private_tier_2" {
  for_each = local.private_tier_2

  subnet_id      = aws_subnet.private_tier_2[each.key].id
  route_table_id = aws_route_table.private_main.id
}

resource "aws_route_table_association" "public_tier" {
  for_each = local.public_tier

  subnet_id      = aws_subnet.public_tier[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "spare_tier" {
  for_each = local.spare_tier

  subnet_id      = aws_subnet.spare_tier[each.key].id
  route_table_id = aws_route_table.spare.id
}

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound web traffic and restrict outbound to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTP from anywhere."
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTPS from anywhere."
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow SSH only from within the VPC CIDR block."
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic only within the VPC CIDR block."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

output "server_public_ip" {
  description = "Public IP address of the NAT gateway Elastic IP."
  value       = aws_eip.nat.public_ip
}

###############################################################################
# Flexible network security module
#
# Manages AWS security groups, managed prefix lists and dynamic ingress/egress
# rules. Standard labels/tags are produced by the standard tf-labels module
# (opsstation fork) referenced directly from its git source.
###############################################################################

###############################################################################
# Standard labels (remote git module)
###############################################################################

module "labels" {
  source = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"

  enabled     = var.enable
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

###############################################################################
# Variables
###############################################################################

variable "enable" {
  description = "Flag that governs whether the module creates any resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name used to build the label id and resource names."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment used to build the label id."
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "Value used for the ManagedBy tag."
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of label attributes combined into the label id."
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL associated with the security group module."
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

variable "vpc_id" {
  description = "ID of the VPC that hosts the security group. When empty a VPC is created."
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC created when vpc_id is not supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "new_sg" {
  description = "Whether to create a new security group."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "Existing security group id used for rules when new_sg is false."
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Whether to create an EC2 managed prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the managed prefix list."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Dynamic entries populated into the managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "prefix_list_ids" {
  description = "Externally supplied prefix list ids. When set no prefix list is created."
  type        = list(string)
  default     = []
}

variable "ingress_cidr_rules" {
  description = "Ingress rules that permit traffic from IPv4/IPv6 CIDR blocks."
  type = map(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    ip_protocol = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
  }))
  default = {
    https-from-vpc = {
      description = "Allow HTTPS from the VPC CIDR range"
      from_port   = 443
      to_port     = 443
      ip_protocol = "tcp"
      cidr_ipv4   = "10.0.0.0/16"
    }
  }
}

variable "ingress_self_rules" {
  description = "Self-referencing ingress rules."
  type = map(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    ip_protocol = string
  }))
  default = {
    self = {
      description = "Allow traffic between members of this security group"
      from_port   = 0
      to_port     = 0
      ip_protocol = "-1"
    }
  }
}

variable "ingress_source_sg_rules" {
  description = "Ingress rules that permit traffic from source security group ids."
  type = map(object({
    description              = optional(string)
    from_port                = number
    to_port                  = number
    ip_protocol              = string
    source_security_group_id = string
  }))
  default = {}
}

variable "ingress_prefix_list_rules" {
  description = "Ingress rules that permit traffic from managed prefix list ids."
  type = map(object({
    description    = optional(string)
    from_port      = number
    to_port        = number
    ip_protocol    = string
    prefix_list_id = optional(string)
  }))
  default = {}
}

variable "egress_cidr_rules" {
  description = "Egress rules that permit traffic to IPv4/IPv6 CIDR blocks."
  type = map(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    ip_protocol = string
    cidr_ipv4   = optional(string)
    cidr_ipv6   = optional(string)
  }))
  default = {
    https-to-vpc = {
      description = "Allow HTTPS to the VPC CIDR range"
      from_port   = 443
      to_port     = 443
      ip_protocol = "tcp"
      cidr_ipv4   = "10.0.0.0/16"
    }
  }
}

variable "egress_self_rules" {
  description = "Self-referencing egress rules."
  type = map(object({
    description = optional(string)
    from_port   = number
    to_port     = number
    ip_protocol = string
  }))
  default = {}
}

variable "egress_source_sg_rules" {
  description = "Egress rules that permit traffic to destination security group ids."
  type = map(object({
    description                   = optional(string)
    from_port                     = number
    to_port                       = number
    ip_protocol                   = string
    destination_security_group_id = string
  }))
  default = {}
}

variable "egress_prefix_list_rules" {
  description = "Egress rules that permit traffic to managed prefix list ids."
  type = map(object({
    description    = optional(string)
    from_port      = number
    to_port        = number
    ip_protocol    = string
    prefix_list_id = optional(string)
  }))
  default = {}
}

###############################################################################
# Local values
###############################################################################

locals {
  label_id = module.labels.id
  tags     = merge(module.labels.tags, var.tags)

  create_sg = var.enable && var.new_sg

  # Rules can be applied to either the new or an existing security group.
  manage_rules = var.enable && (var.new_sg || var.existing_sg_id != null)

  # Resolve the target security group id without failing when the new security
  # group is not created.
  sg_id = var.new_sg ? one(aws_security_group.this[*].id) : var.existing_sg_id

  # Prefix list rules default to the created prefix list, falling back to the
  # first externally supplied prefix list id.
  created_prefix_list_id  = one(aws_ec2_managed_prefix_list.this[*].id)
  external_prefix_list_id = try(var.prefix_list_ids[0], null)
  default_prefix_list_id = (
    local.created_prefix_list_id != null
    ? local.created_prefix_list_id
    : local.external_prefix_list_id
  )

  vpc_id = var.vpc_id != "" ? var.vpc_id : one(aws_vpc.this[*].id)
}

###############################################################################
# Networking - VPC created for the greenfield account
###############################################################################

resource "aws_vpc" "this" {
  count = var.enable && var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.label_id}-vpc" })
}

###############################################################################
# Security group
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_sg ? 1 : 0

  name        = "${local.label_id}-sg"
  description = "Managed security group for ${local.label_id}"
  vpc_id      = local.vpc_id

  tags = local.tags

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0

  name           = "${local.label_id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = local.tags
}

###############################################################################
# Ingress rules - CIDR blocks (IPv4/IPv6)
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "cidr" {
  for_each = local.manage_rules ? var.ingress_cidr_rules : {}

  security_group_id = local.sg_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6

  tags = local.tags
}

###############################################################################
# Ingress rules - self referencing
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "self" {
  for_each = local.manage_rules ? var.ingress_self_rules : {}

  security_group_id            = local.sg_id
  description                  = each.value.description
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol
  referenced_security_group_id = local.sg_id

  tags = local.tags
}

###############################################################################
# Ingress rules - source security group ids
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "source_sg" {
  for_each = local.manage_rules ? var.ingress_source_sg_rules : {}

  security_group_id            = local.sg_id
  description                  = each.value.description
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol
  referenced_security_group_id = each.value.source_security_group_id

  tags = local.tags
}

###############################################################################
# Ingress rules - managed prefix list ids
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "prefix_list" {
  for_each = local.manage_rules ? var.ingress_prefix_list_rules : {}

  security_group_id = local.sg_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol
  prefix_list_id    = coalesce(each.value.prefix_list_id, local.default_prefix_list_id)

  tags = local.tags
}

###############################################################################
# Egress rules - CIDR blocks (IPv4/IPv6)
###############################################################################

resource "aws_vpc_security_group_egress_rule" "cidr" {
  for_each = local.manage_rules ? var.egress_cidr_rules : {}

  security_group_id = local.sg_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol
  cidr_ipv4         = each.value.cidr_ipv4
  cidr_ipv6         = each.value.cidr_ipv6

  tags = local.tags
}

###############################################################################
# Egress rules - self referencing
###############################################################################

resource "aws_vpc_security_group_egress_rule" "self" {
  for_each = local.manage_rules ? var.egress_self_rules : {}

  security_group_id            = local.sg_id
  description                  = each.value.description
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol
  referenced_security_group_id = local.sg_id

  tags = local.tags
}

###############################################################################
# Egress rules - destination security group ids
###############################################################################

resource "aws_vpc_security_group_egress_rule" "destination_sg" {
  for_each = local.manage_rules ? var.egress_source_sg_rules : {}

  security_group_id            = local.sg_id
  description                  = each.value.description
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol
  referenced_security_group_id = each.value.destination_security_group_id

  tags = local.tags
}

###############################################################################
# Egress rules - managed prefix list ids
###############################################################################

resource "aws_vpc_security_group_egress_rule" "prefix_list" {
  for_each = local.manage_rules ? var.egress_prefix_list_rules : {}

  security_group_id = local.sg_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol
  prefix_list_id    = coalesce(each.value.prefix_list_id, local.default_prefix_list_id)

  tags = local.tags
}

###############################################################################
# Static provider metadata lookups (local / well-known only)
###############################################################################
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables
###############################################################################
variable "environment" {
  description = "Environment name used to construct the ECS IAM role names."
  type        = string
  default     = "dev"
}

###############################################################################
# Local values
###############################################################################
locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  # AWS-managed policy ARNs (well-known, global)
  secrets_manager_read_write_arn = "arn:${local.partition}:iam::aws:policy/SecretsManagerReadWrite"
  s3_full_access_arn             = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
  ecs_task_execution_arn         = "arn:${local.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
  ec2_container_service_arn      = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"

  # Account-scoped resource ARN patterns
  secrets_manager_arn = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
  kms_key_arn         = "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
  lambda_function_arn = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
  lambda_log_group    = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"
  state_machine_arn   = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:*"
  s3_object_arn       = "arn:${local.partition}:s3:::*/*"
  s3_bucket_arn       = "arn:${local.partition}:s3:::*"

  # Trust policies
  ecs_tasks_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  events_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  lambda_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  states_trust_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "states.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  # Reusable self-service human identity actions
  self_service_credentials_actions = [
    "iam:ChangePassword",
    "iam:GetUser",
    "iam:CreateAccessKey",
    "iam:DeleteAccessKey",
    "iam:ListAccessKeys",
    "iam:UpdateAccessKey",
    "iam:CreateVirtualMFADevice",
    "iam:DeleteVirtualMFADevice",
    "iam:EnableMFADevice",
    "iam:DeactivateMFADevice",
    "iam:ResyncMFADevice",
    "iam:ListMFADevices",
    "iam:ListVirtualMFADevices",
    "iam:UploadSSHPublicKey",
    "iam:DeleteSSHPublicKey",
    "iam:ListSSHPublicKeys",
    "iam:UpdateSSHPublicKey",
    "iam:GetSSHPublicKey"
  ]
}

###############################################################################
# Account-wide IAM password policy
###############################################################################
resource "aws_iam_account_password_policy" "account_baseline" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

###############################################################################
# ECS task role
###############################################################################
resource "aws_iam_role" "ecs_task_role" {
  name        = "ecs-task-role-for-${var.environment}"
  description = "ECS task role for ${var.environment} workloads."

  assume_role_policy = local.ecs_tasks_trust_policy
}

resource "aws_iam_role_policy_attachment" "ecs_task_role_secrets_manager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = local.secrets_manager_read_write_arn
}

resource "aws_iam_role_policy_attachment" "ecs_task_role_s3_full_access" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = local.s3_full_access_arn
}

resource "aws_iam_role_policy" "ecs_task_role_ssm_messages" {
  name = "ecs-task-role-ssm-messages"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SsmMessagesChannelAccess"
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# ECS execution role
###############################################################################
resource "aws_iam_role" "ecs_execution_role" {
  name        = "ecs-execution-role-for-${var.environment}"
  description = "ECS execution role for ${var.environment} workloads."

  assume_role_policy = local.ecs_tasks_trust_policy
}

resource "aws_iam_role_policy_attachment" "ecs_execution_role_task_execution" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = local.ecs_task_execution_arn
}

resource "aws_iam_role_policy_attachment" "ecs_execution_role_ec2_container_service" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = local.ec2_container_service_arn
}

resource "aws_iam_role_policy" "ecs_execution_role_secrets_kms" {
  name = "ecs-execution-role-secrets-kms"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SecretsManagerRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = local.secrets_manager_arn
      },
      {
        Sid    = "KmsDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = local.kms_key_arn
      }
    ]
  })
}

###############################################################################
# EventBridge-assumable ECS events role
###############################################################################
resource "aws_iam_role" "ecs_events_role" {
  name        = "ecs_events_role-for-${var.environment}"
  description = "EventBridge-assumable ECS events role for ${var.environment} workloads."

  assume_role_policy = local.events_trust_policy
}

resource "aws_iam_role_policy_attachment" "ecs_events_role_task_execution" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = local.ecs_task_execution_arn
}

resource "aws_iam_role_policy_attachment" "ecs_events_role_ec2_container_service" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = local.ec2_container_service_arn
}

###############################################################################
# "public" Lambda role
###############################################################################
resource "aws_iam_role" "lambda_public_role" {
  name        = "lambda-public-role"
  description = "Execution role for public Lambda functions."

  assume_role_policy = local.lambda_trust_policy
}

resource "aws_iam_role_policy" "lambda_public_role_cloudwatch" {
  name = "lambda-public-role-cloudwatch-logs"
  role = aws_iam_role.lambda_public_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.lambda_log_group
      }
    ]
  })
}

###############################################################################
# "VPC" Lambda role
###############################################################################
resource "aws_iam_role" "lambda_vpc_role" {
  name        = "lambda-vpc-role"
  description = "Execution role for VPC-attached Lambda functions."

  assume_role_policy = local.lambda_trust_policy
}

resource "aws_iam_role_policy" "lambda_vpc_role" {
  name = "lambda-vpc-role-policy"
  role = aws_iam_role.lambda_vpc_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.lambda_log_group
      },
      {
        Sid    = "ManageEni"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces"
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = local.secrets_manager_arn
      },
      {
        Sid    = "InvokeLambda"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = local.lambda_function_arn
      }
    ]
  })
}

###############################################################################
# Step Functions state machine role
###############################################################################
resource "aws_iam_role" "step_functions_role" {
  name        = "step-functions-role"
  description = "Execution role for Step Functions state machines."

  assume_role_policy = local.states_trust_policy
}

resource "aws_iam_role_policy" "step_functions_role" {
  name = "step-functions-role-policy"
  role = aws_iam_role.step_functions_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LogDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogDelivery",
          "logs:GetLogDelivery",
          "logs:UpdateLogDelivery",
          "logs:DeleteLogDelivery",
          "logs:ListLogDeliveries"
        ]
        Resource = "*"
      },
      {
        Sid    = "LogResourcePolicies"
        Effect = "Allow"
        Action = [
          "logs:PutResourcePolicy",
          "logs:DescribeResourcePolicies",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      },
      {
        Sid    = "InvokeLambda"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = local.lambda_function_arn
      },
      {
        Sid    = "DescribeAlarms"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# EventBridge execution role (Step Functions target)
###############################################################################
resource "aws_iam_role" "eventbridge_execution_role" {
  name        = "eventbridge-execution-role"
  description = "EventBridge role used to start Step Functions state machines."

  assume_role_policy = local.events_trust_policy
}

resource "aws_iam_role_policy" "eventbridge_execution_role" {
  name = "eventbridge-execution-role-policy"
  role = aws_iam_role.eventbridge_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartStateMachineExecution"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = local.state_machine_arn
      }
    ]
  })
}

###############################################################################
# Human user governance policy: developers (limited MFA)
###############################################################################
resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer governance policy with MFA-conditioned access to secrets, CloudWatch and ECS."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = local.s3_object_arn
      },
      {
        Sid    = "S3BucketListing"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = local.s3_bucket_arn
      },
      {
        Sid    = "SecretsManagerReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "CloudWatchReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DescribeAlarmHistory",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "EcsReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "ecs:DescribeClusters",
          "ecs:DescribeServices",
          "ecs:DescribeTasks",
          "ecs:DescribeTaskDefinition",
          "ecs:ListClusters",
          "ecs:ListServices",
          "ecs:ListTasks",
          "ecs:ListTaskDefinitions"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceCredentials"
        Effect = "Allow"
        Action = local.self_service_credentials_actions
        Resource = "*"
      },
      {
        Sid    = "DenyWithoutMFA"
        Effect = "Deny"
        NotAction = concat([
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:GetUser",
          "sts:GetSessionToken"
        ])
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# Human user governance policy: billing (limited MFA)
###############################################################################
resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing governance policy with MFA-conditioned access to billing, budgets, cost explorer, payments and tax APIs."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingAccessWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "aws-portal:ViewAccount",
          "budgets:ViewBudget",
          "budgets:DescribeBudgets",
          "ce:DescribeCostCategoryDefinition",
          "ce:GetCostAndUsage",
          "ce:GetCostForecast",
          "ce:GetDimensionValues",
          "ce:GetReservationCoverage",
          "ce:GetReservationPurchaseRecommendation",
          "ce:GetReservationUtilization",
          "ce:GetUsageForecast",
          "payments:GetPaymentInstrument",
          "payments:ListPaymentInstruments",
          "payments:ListPaymentPreferences",
          "tax:GetTaxRegistration",
          "tax:ListTaxRegistrations"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceMFAPasswordManagement"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Terraforest CI/CD Pipeline Orchestration Framework
#
# A data-driven Terraform module that reads a YAML configuration document
# (referenced by the `config` variable, either a file path or an inline YAML
# document) and dynamically provisions:
#   - S3 artifact and build-cache buckets
#   - An optional default CodePipeline IAM role under path "/terraforest/"
#   - CodeStar connections for Bitbucket / GitHub / GitHub Enterprise Server
#   - CodePipelines with dynamic stages and source / approval / build / invoke
#     actions (CodeCommit, S3, ECR, CodeStar sources)
#   - EventBridge rules + targets that start pipelines through dedicated custom
#     IAM roles named "terrabits-<pipeline>" using codepipeline:StartPipelineExecution
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "config" {
  description = <<-DESC
    Location of the YAML configuration document that drives the framework.
    May be either a path to a local YAML file or an inline YAML document.
  DESC
  type        = string
  default     = <<-EOT
    project_name: demo
    create_default_role: true

    artifact_bucket:
      name: demo-pipeline-artifacts
    cache_bucket:
      name: demo-pipeline-cache

    codestar_connections:
      - name: demo-github-connection
        provider_type: GitHub

    pipelines:
      - name: demo-pipeline
        stages:
          - name: Source
            actions:
              - name: Source
                category: Source
                owner: AWS
                provider: S3
                version: "1"
                output_artifacts:
                  - source_output
                configuration:
                  S3ObjectKey: source.zip
                  PollForSourceChanges: "false"
          - name: Approve
            actions:
              - name: ManualApproval
                category: Approval
                owner: AWS
                provider: Manual
                version: "1"

    event_rules:
      - name: demo-branch-rule
        pipeline: demo-pipeline
        trigger_type: codecommit_branch
        repository_name: demo-repository
        branches:
          - main
      - name: demo-tag-rule
        pipeline: demo-pipeline
        trigger_type: codecommit_tag
        repository_name: demo-repository
        tags:
          - "v*"
      - name: demo-schedule-rule
        pipeline: demo-pipeline
        trigger_type: schedule
        schedule_expression: "cron(0 0 * * ? *)"
      - name: demo-pattern-rule
        pipeline: demo-pipeline
        trigger_type: pattern
        event_pattern:
          source:
            - aws.codebuild
          detail-type:
            - CodeBuild Build State Change
  EOT
}

variable "tags" {
  description = "Tags applied to every taggable resource created by the framework."
  type        = map(string)
  default = {
    ManagedBy = "terraforest"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Configuration parsing
###############################################################################

locals {
  # The variable may be a path to a YAML file or an inline YAML document.
  raw_config = trimspace(try(file(var.config), var.config))
  cfg        = yamldecode(local.raw_config)

  account_id        = data.aws_caller_identity.current.account_id
  region            = data.aws_region.current.name
  partition         = data.aws_partition.current.partition

  project_name        = try(local.cfg.project_name, "terraforest")
  create_default_role = try(local.cfg.create_default_role, true)

  codestar_connections = try(local.cfg.codestar_connections, [])
  pipelines_raw        = try(local.cfg.pipelines, [])
  event_rules_raw      = try(local.cfg.event_rules, [])

  # Bucket names are suffixed with the account id so that the globally unique
  # S3 namespace is satisfied without sacrificing the data-driven name.
  bucket_defs = {
    artifacts = {
      name = lower("${coalesce(try(local.cfg.artifact_bucket.name, null), "${local.project_name}-artifacts")}-${local.account_id}")
    }
    cache = {
      name = lower("${coalesce(try(local.cfg.cache_bucket.name, null), "${local.project_name}-cache")}-${local.account_id}")
    }
  }
}

###############################################################################
# S3 artifact + build cache buckets
###############################################################################

resource "aws_s3_bucket" "this" {
  for_each = local.bucket_defs

  bucket        = each.value.name
  force_destroy = false

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  for_each = aws_s3_bucket.this

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  for_each = aws_s3_bucket.this

  bucket = each.value.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "this" {
  for_each = aws_s3_bucket.this

  bucket = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  for_each = aws_s3_bucket.this

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  for_each = aws_s3_bucket.this

  bucket = each.value.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }
}

###############################################################################
# KMS key protecting pipeline artifacts and cache
###############################################################################

resource "aws_kms_key" "this" {
  description             = "${local.project_name} CI/CD artifact encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAccess"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.project_name}-cicd"
  target_key_id = aws_kms_key.this.key_id
}

###############################################################################
# CodeStar connections (Bitbucket / GitHub / GitHub Enterprise Server)
###############################################################################

resource "aws_codestarconnections_connection" "this" {
  for_each = { for c in local.codestar_connections : c.name => c }

  name          = each.value.name
  provider_type = each.value.provider_type

  tags = var.tags
}

###############################################################################
# Default CodePipeline IAM role (path "/terraforest/")
###############################################################################

resource "aws_iam_role" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0

  name = "${local.project_name}-codepipeline-role"
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "codepipeline_default" {
  count = local.create_default_role ? 1 : 0

  name = "terraforest-codepipeline-policy"
  role = aws_iam_role.codepipeline_default[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = local.codepipeline_policy_statements
  })
}

locals {
  artifact_bucket_arn = aws_s3_bucket.this["artifacts"].arn
  cache_bucket_arn    = aws_s3_bucket.this["cache"].arn

  codestar_arns = [for c in aws_codestarconnections_connection.this : c.arn]

  codepipeline_policy_statements = concat(
    [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation"
        ]
        Resource = [
          local.artifact_bucket_arn,
          "${local.artifact_bucket_arn}/*",
          local.cache_bucket_arn,
          "${local.cache_bucket_arn}/*"
        ]
      },
      {
        Sid    = "ArtifactKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.this.arn]
      },
      {
        Sid    = "CodeCommitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:*"]
      },
      {
        Sid    = "CodeBuildAccess"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGetBuilds",
          "codebuild:StartBuild",
          "codebuild:StopBuild"
        ]
        Resource = ["arn:${local.partition}:codebuild:${local.region}:${local.account_id}:project/*"]
      },
      {
        Sid    = "LambdaInvokeAccess"
        Effect = "Allow"
        Action = ["lambda:InvokeFunction"]
        Resource = ["arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"]
      },
      {
        Sid    = "EcrAccess"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:PutImage",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload"
        ]
        Resource = ["arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"]
      },
      {
        Sid      = "EcrAuthorizationToken"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = ["*"]
      }
    ],
    length(local.codestar_arns) > 0 ? [
      {
        Sid      = "CodeStarConnectionsAccess"
        Effect   = "Allow"
        Action   = ["codestar-connections:UseConnection"]
        Resource = local.codestar_arns
      }
    ] : []
  )
}

###############################################################################
# CodePipelines (dynamic stages / actions)
###############################################################################

locals {
  default_pipeline_role_arn = try(aws_iam_role.codepipeline_default[0].arn, null)

  pipelines = {
    for p in local.pipelines_raw : p.name => {
      name     = p.name
      role_arn = try(p.role_arn, null)
      stages = [
        for s in try(p.stages, []) : {
          name = s.name
          actions = [
            for a in try(s.actions, []) : {
              name             = a.name
              category         = a.category
              owner            = try(a.owner, "AWS")
              provider         = a.provider
              version          = tostring(try(a.version, "1"))
              input_artifacts  = try(a.input_artifacts, null)
              output_artifacts = try(a.output_artifacts, null)
              run_order        = try(a.run_order, null)
              role_arn         = try(a.role_arn, null)
              namespace        = try(a.namespace, null)
              configuration = merge(
                { for k, v in try(a.configuration, {}) : k => tostring(v) },
                # The framework-owned artifact bucket is used for S3 sources.
                (a.category == "Source" && a.provider == "S3"
                  ? { S3Bucket = aws_s3_bucket.this["artifacts"].bucket }
                  : {}
                )
              )
            }
          ]
        }
      ]
    }
  }
}

resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name     = each.value.name
  role_arn = coalesce(each.value.role_arn, local.default_pipeline_role_arn)

  artifact_store {
    location = aws_s3_bucket.this["artifacts"].bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.this.arn
      type = "KMS"
    }
  }

  dynamic "stage" {
    for_each = each.value.stages
    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions
        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          run_order        = action.value.run_order
          role_arn         = action.value.role_arn
          namespace        = action.value.namespace
          configuration    = action.value.configuration
        }
      }
    }
  }

  tags = var.tags
}

###############################################################################
# EventBridge rules + targets with dedicated "terrabits-<pipeline>" IAM roles
###############################################################################

locals {
  event_rules = {
    for r in local.event_rules_raw : r.name => {
      name                = r.name
      pipeline            = r.pipeline
      description         = try(r.description, "EventBridge trigger starting pipeline ${r.pipeline}")
      schedule_expression = r.trigger_type == "schedule" ? try(r.schedule_expression, null) : null
      event_pattern = (
        r.trigger_type == "schedule" ? null :
        r.trigger_type == "codecommit_branch" ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${r.repository_name}"]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["branch"]
            referenceName = try(r.branches, ["*"])
          }
        }) :
        r.trigger_type == "codecommit_tag" ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${r.repository_name}"]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["tag"]
            referenceName = try(r.tags, ["*"])
          }
        }) :
        r.trigger_type == "pattern" ? jsonencode(try(r.event_pattern, {})) :
        null
      )
    }
  }

  event_pipeline_names = distinct([for r in local.event_rules_raw : r.pipeline])
}

resource "aws_iam_role" "terrabits" {
  for_each = toset(local.event_pipeline_names)

  name = "terrabits-${each.value}"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "terrabits" {
  for_each = toset(local.event_pipeline_names)

  name = "terrabits-start-pipeline"
  role = aws_iam_role.terrabits[each.value].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartPipelineExecution"
        Effect   = "Allow"
        Action   = ["codepipeline:StartPipelineExecution"]
        Resource = [aws_codepipeline.this[each.value].arn]
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.event_rules

  name                = each.value.name
  description         = each.value.description
  schedule_expression = each.value.schedule_expression
  event_pattern       = each.value.event_pattern

  tags = var.tags
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.event_rules

  rule      = aws_cloudwatch_event_rule.this[each.key].name
  target_id = "codepipeline-${each.value.pipeline}"
  arn       = aws_codepipeline.this[each.value.pipeline].arn
  role_arn  = aws_iam_role.terrabits[each.value.pipeline].arn
}

###############################################################################
# Secure AWS Transfer Family SFTP server backed by an encrypted Amazon EFS
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "server_name" {
  description = "Name of the AWS Transfer Family SFTP server. The auto-generated IAM role is named \"<server_name>-role\"."
  type        = string
  default     = "sftp-server"
}

variable "vpc_id" {
  description = "VPC ID used for the SFTP VPC endpoint and the EFS mount targets. Leave empty to create a PUBLIC SFTP endpoint and no mount targets."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs used for the EFS mount targets and the SFTP VPC endpoint. Leave empty to create no mount targets."
  type        = list(string)
  default     = []
}

variable "performance_mode" {
  description = "EFS performance mode."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either \"generalPurpose\" or \"maxIO\"."
  }
}

variable "throughput_mode" {
  description = "EFS throughput mode."
  type        = string
  default     = "bursting"

  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "throughput_mode must be one of \"bursting\", \"provisioned\" or \"elastic\"."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput (MiB/s) for the EFS file system. Only applied when throughput_mode is \"provisioned\"."
  type        = number
  default     = null
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS customer-managed key used to encrypt the EFS file system. Leave empty to rely on create_kms_key or AWS-managed encryption."
  type        = string
  default     = ""
}

variable "create_kms_key" {
  description = "Create a KMS customer-managed key for EFS encryption when kms_key_arn is not supplied."
  type        = bool
  default     = false
}

variable "is_public" {
  description = "Allocate Elastic IP addresses for the VPC SFTP endpoint so it is reachable from the internet."
  type        = bool
  default     = false
}

variable "enable_security_groups" {
  description = "Create dedicated security groups and rules for the SFTP and EFS interfaces."
  type        = bool
  default     = true
}

variable "sftp_ingress_cidr_blocks" {
  description = "CIDR blocks allowed to reach the SFTP endpoint on port 22."
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "sftp_role_arn" {
  description = "Existing IAM role ARN assumed by SFTP users. When empty, a role named \"<server_name>-role\" is created."
  type        = string
  default     = ""

  validation {
    condition     = var.sftp_role_arn == "" || can(regex("^arn:[a-z0-9-]+:iam::[0-9]{12}:role/", var.sftp_role_arn))
    error_message = "sftp_role_arn must be a valid IAM role ARN or an empty string."
  }
}

variable "logging_enabled" {
  description = "Enable CloudWatch logging for the SFTP server using a dedicated IAM logging role and policy."
  type        = bool
  default     = true
}

variable "sftp_users" {
  description = "Map of SFTP users. Each key is the user name; values define POSIX ownership, SSH public keys and directory restriction."
  type = map(object({
    posix_uid       = number
    posix_gid       = number
    ssh_public_keys = list(string)
    restricted      = optional(bool, true)
  }))
  default = {}
}

variable "additional_access_points" {
  description = "Map of additional EFS access points for general storage paths."
  type = map(object({
    path        = string
    posix_uid   = optional(number, 1000)
    posix_gid   = optional(number, 1000)
    permissions = optional(string, "0755")
  }))
  default = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  name = var.server_name

  create_vpc_endpoint    = var.vpc_id != ""
  manage_security_groups = var.vpc_id != "" && var.enable_security_groups

  endpoint_type = var.vpc_id != "" ? "VPC" : "PUBLIC"

  kms_key_arn = (
    var.kms_key_arn != "" ? var.kms_key_arn :
    var.create_kms_key ? one(aws_kms_key.efs[*].arn) : null
  )

  sftp_role_arn = (
    var.sftp_role_arn != "" ? var.sftp_role_arn :
    one(aws_iam_role.sftp[*].arn)
  )

  user_access_point_ids = {
    for user_name in keys(var.sftp_users) :
    user_name => aws_efs_access_point.user[user_name].id
  }

  user_ssh_keys = {
    for pair in flatten([
      for user_name, user in var.sftp_users : [
        for idx, key in user.ssh_public_keys : {
          id        = "${user_name}-${idx}"
          user_name = user_name
          body      = key
        }
      ]
    ]) : pair.id => {
      user_name = pair.user_name
      body      = pair.body
    }
  }
}

###############################################################################
# KMS customer-managed key (optional)
###############################################################################

resource "aws_kms_key" "efs" {
  count = var.create_kms_key && var.kms_key_arn == "" ? 1 : 0

  description             = "Customer managed key used to encrypt the ${local.name} EFS file system"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "${local.name}-efs-kms"
  }
}

resource "aws_kms_alias" "efs" {
  count = var.create_kms_key && var.kms_key_arn == "" ? 1 : 0

  name          = "alias/${local.name}-efs"
  target_key_id = aws_kms_key.efs[0].key_id
}

###############################################################################
# EFS file system
###############################################################################

resource "aws_efs_file_system" "this" {
  creation_token   = "${local.name}-efs"
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode

  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  encrypted  = true
  kms_key_id = local.kms_key_arn

  tags = {
    Name = "${local.name}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# EFS access points - per SFTP user
###############################################################################

resource "aws_efs_access_point" "user" {
  for_each = var.sftp_users

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  root_directory {
    path = "/${each.key}"

    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${local.name}-user-${each.key}"
  }
}

###############################################################################
# EFS access points - additional general storage paths
###############################################################################

resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  root_directory {
    path = each.value.path

    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = each.value.permissions
    }
  }

  tags = {
    Name = "${local.name}-${each.key}"
  }
}

###############################################################################
# EFS mount targets (only when subnet IDs are supplied)
###############################################################################

resource "aws_efs_mount_target" "this" {
  count = length(var.subnet_ids)

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = local.manage_security_groups ? aws_security_group.efs[*].id : null
}

###############################################################################
# Dedicated security groups and rules (optional)
###############################################################################

resource "aws_security_group" "sftp" {
  count = local.manage_security_groups ? 1 : 0

  name        = "${local.name}-sftp-sg"
  description = "SFTP interface for ${local.name}"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${local.name}-sftp-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "efs" {
  count = local.manage_security_groups ? 1 : 0

  name        = "${local.name}-efs-sg"
  description = "EFS interface for ${local.name}"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${local.name}-efs-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "sftp" {
  count = local.manage_security_groups ? length(var.sftp_ingress_cidr_blocks) : 0

  security_group_id = aws_security_group.sftp[0].id
  cidr_ipv4         = var.sftp_ingress_cidr_blocks[count.index]
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  description       = "SFTP access from allowed CIDR blocks"
}

resource "aws_vpc_security_group_egress_rule" "sftp_to_efs" {
  count = local.manage_security_groups ? 1 : 0

  security_group_id            = aws_security_group.sftp[0].id
  referenced_security_group_id = aws_security_group.efs[0].id
  from_port                    = 2049
  to_port                      = 2049
  ip_protocol                  = "tcp"
  description                  = "Allow the SFTP server to mount EFS"
}

resource "aws_vpc_security_group_ingress_rule" "efs_from_sftp" {
  count = local.manage_security_groups ? 1 : 0

  security_group_id            = aws_security_group.efs[0].id
  referenced_security_group_id = aws_security_group.sftp[0].id
  from_port                    = 2049
  to_port                      = 2049
  ip_protocol                  = "tcp"
  description                  = "Allow NFS traffic from the SFTP server"
}

###############################################################################
# Elastic IP addresses for the VPC SFTP endpoint (optional)
###############################################################################

resource "aws_eip" "sftp" {
  count = local.create_vpc_endpoint && var.is_public ? length(var.subnet_ids) : 0

  domain = "vpc"

  tags = {
    Name = "${local.name}-sftp-eip-${count.index}"
  }
}

###############################################################################
# IAM role for SFTP users (auto-generated unless sftp_role_arn is provided)
###############################################################################

resource "aws_iam_role" "sftp" {
  count = var.sftp_role_arn == "" ? 1 : 0

  name = "${local.name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "transfer.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = {
    Name = "${local.name}-role"
  }
}

resource "aws_iam_role_policy" "sftp_efs" {
  count = var.sftp_role_arn == "" ? 1 : 0

  name = "${local.name}-efs-access"
  role = aws_iam_role.sftp[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "EFSClientAccess"
      Effect = "Allow"
      Action = [
        "elasticfilesystem:ClientMount",
        "elasticfilesystem:ClientWrite",
        "elasticfilesystem:ClientRootAccess"
      ]
      Resource = aws_efs_file_system.this.arn
    }]
  })
}

###############################################################################
# IAM logging role and policy (optional)
###############################################################################

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0

  name = "${local.name}-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "transfer.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = {
    Name = "${local.name}-logging-role"
  }
}

resource "aws_iam_role_policy" "logging" {
  count = var.logging_enabled ? 1 : 0

  name = "${local.name}-logging-policy"
  role = aws_iam_role.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "CloudWatchLogs"
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:DescribeLogStreams",
        "logs:PutLogEvents"
      ]
      Resource = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"
    }]
  })
}

###############################################################################
# AWS Transfer Family SFTP server
###############################################################################

resource "aws_transfer_server" "this" {
  domain                 = "EFS"
  endpoint_type          = local.endpoint_type
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  protocols              = ["SFTP"]

  logging_role = var.logging_enabled ? one(aws_iam_role.logging[*].arn) : null

  dynamic "endpoint_details" {
    for_each = local.create_vpc_endpoint ? [1] : []

    content {
      vpc_id                 = var.vpc_id
      subnet_ids             = var.subnet_ids
      security_group_ids     = local.manage_security_groups ? aws_security_group.sftp[*].id : null
      address_allocation_ids = var.is_public ? aws_eip.sftp[*].id : null
    }
  }

  tags = {
    Name = local.name
  }
}

###############################################################################
# SFTP users
###############################################################################

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id = aws_transfer_server.this.id
  user_name = each.key
  role      = local.sftp_role_arn

  home_directory_type = each.value.restricted ? "LOGICAL" : "PATH"
  home_directory      = each.value.restricted ? null : "/${local.user_access_point_ids[each.key]}"

  dynamic "home_directory_mappings" {
    for_each = each.value.restricted ? [1] : []

    content {
      entry  = "/"
      target = "/${local.user_access_point_ids[each.key]}"
    }
  }

  posix_profile {
    uid = each.value.posix_uid
    gid = each.value.posix_gid
  }

  tags = {
    Name = "${local.name}-user-${each.key}"
  }
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = each.value.user_name
  body      = each.value.body
}

###############################################################################
# Outputs
###############################################################################

output "sftp_server_id" {
  description = "ID of the AWS Transfer Family SFTP server."
  value       = aws_transfer_server.this.id
}

output "sftp_server_endpoint" {
  description = "Endpoint of the AWS Transfer Family SFTP server."
  value       = aws_transfer_server.this.endpoint
}

output "efs_file_system_id" {
  description = "ID of the EFS file system backing the SFTP server."
  value       = aws_efs_file_system.this.id
}

output "sftp_role_arn" {
  description = "IAM role ARN assumed by SFTP users."
  value       = local.sftp_role_arn
}

output "availability_zones" {
  description = "Availability zones available to the account."
  value       = data.aws_availability_zones.available.names
}

###############################################################################
# Reusable, highly configurable Amazon S3 bucket
#
# Default behaviour (no inputs supplied):
#   * creates a single bucket with an automatically generated name
#   * encrypts it with SSE-KMS using a new customer managed KMS key that has
#     key rotation enabled and a 7 day deletion window
#   * attaches a public access block that blocks public ACLs & policies,
#     ignores public ACLs and restricts public buckets
#
# Provisioning is gated by two boolean toggles that both default to true:
#   create_bucket  -> the S3 bucket and all of its sub-resources
#   create_kms_key -> the default customer managed KMS key
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "create_bucket" {
  description = "Controls whether the S3 bucket (and the resources that depend on it) should be created."
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Controls whether a new customer managed KMS key (rotation enabled, 7 day deletion window) should be created for the default SSE-KMS encryption."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Explicit name of the S3 bucket. If omitted, an automatically generated unique name is used. Conflicts with bucket_prefix."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix used to generate an automatically unique bucket name. Conflicts with bucket."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Whether S3 object lock should be enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object lock configuration, including the default retention, applied when object_lock_enabled is true."
  type        = any
  default     = {}
}

variable "tags" {
  description = "A map of tags to assign to the bucket and the KMS key."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "The canned ACL to apply to the bucket."
  type        = string
  default     = null
}

variable "grant" {
  description = "A list of explicit ACL grants applied through an access control policy."
  type        = list(any)
  default     = []
}

variable "website" {
  description = "Static website hosting configuration."
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "A list of CORS rules."
  type        = list(any)
  default     = []
}

variable "versioning" {
  description = "Bucket versioning configuration."
  type        = any
  default     = {}
}

variable "logging" {
  description = "Access logging configuration pointing at a target bucket."
  type        = any
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Enabled or Suspended)."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer (BucketOwner or Requester)."
  type        = string
  default     = null
}

variable "lifecycle_rule" {
  description = "A list of lifecycle rules."
  type        = list(any)
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration."
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "A list of intelligent tiering configurations."
  type        = list(any)
  default     = []
}

variable "control_object_ownership" {
  description = "Whether to manage the bucket ownership controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting used when control_object_ownership is enabled."
  type        = string
  default     = "ObjectWriter"
}

variable "server_side_encryption_configuration" {
  description = "Caller supplied server-side encryption configuration that replaces the default KMS encryption. A list of rule maps."
  type        = any
  default     = []
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls whether a bucket policy statement granting classic ELB access log delivery is attached."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls whether a bucket policy statement granting ALB/NLB access log delivery is attached."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls whether a bucket policy statement denying any request made without secure transport is attached."
  type        = bool
  default     = false
}

variable "attach_require_latest_tls_policy" {
  description = "Controls whether a bucket policy statement denying requests using TLS older than 1.2 is attached."
  type        = bool
  default     = false
}

variable "policy" {
  description = "A user supplied JSON bucket policy that is merged into the combined bucket policy."
  type        = string
  default     = null
}

###############################################################################
# Data sources (static / well-known provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_canonical_user_id" "current" {
  count = local.create_bucket && length(var.grant) > 0 ? 1 : 0
}

###############################################################################
# Locals
###############################################################################

locals {
  create_bucket  = var.create_bucket
  create_kms_key = var.create_kms_key

  # The combined bucket policy is built when any policy toggle is enabled or a
  # user supplied policy is provided.
  attach_bucket_policy = local.create_bucket && anytrue([
    var.attach_elb_log_delivery_policy,
    var.attach_lb_log_delivery_policy,
    var.attach_deny_insecure_transport_policy,
    var.attach_require_latest_tls_policy,
    var.policy != null && var.policy != "",
  ])

  # Default encryption: SSE-KMS backed by a newly created customer managed key.
  default_sse_rules = local.create_kms_key ? [{
    apply_server_side_encryption_by_default = {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = try(aws_kms_key.this[0].arn, null)
    }
    bucket_key_enabled = true
  }] : []

  # A caller supplied encryption configuration replaces the default KMS one.
  sse_rules = length(var.server_side_encryption_configuration) > 0 ? var.server_side_encryption_configuration : local.default_sse_rules
}

###############################################################################
# Default customer managed KMS key
###############################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed KMS key used for default S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket              = var.bucket
  bucket_prefix       = var.bucket_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Default / caller supplied encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket && length(local.sse_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = local.sse_rules

    content {
      bucket_key_enabled = try(rule.value.bucket_key_enabled, null)

      dynamic "apply_server_side_encryption_by_default" {
        for_each = try(rule.value.apply_server_side_encryption_by_default, null) != null ? [rule.value.apply_server_side_encryption_by_default] : []

        content {
          sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
          kms_master_key_id = try(apply_server_side_encryption_by_default.value.kms_master_key_id, null)
        }
      }
    }
  }
}

###############################################################################
# Combined bucket policy
###############################################################################

data "aws_iam_policy_document" "combined" {
  count = local.attach_bucket_policy ? 1 : 0

  # Merge a user supplied JSON policy when one is provided.
  source_policy_documents = var.policy != null && var.policy != "" ? [var.policy] : []

  # Classic ELB access log delivery.
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []

    content {
      sid    = "AllowElbAccessLogDelivery"
      effect = "Allow"

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  # ALB / NLB access log delivery.
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []

    content {
      sid    = "AllowAlbNlbAccessLogDelivery"
      effect = "Allow"

      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/*"]

      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  # Deny any request made without secure transport.
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []

    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"

      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Deny requests using TLS versions older than 1.2.
  dynamic "statement" {
    for_each = var.attach_require_latest_tls_policy ? [1] : []

    content {
      sid    = "DenyOutdatedTLS"
      effect = "Deny"

      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]

      principals {
        type        = "*"
        identifiers = ["*"]
      }

      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_bucket_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

###############################################################################
# Public access block
#
# Applied after the bucket policy so that the two never conflict.
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_policy.this]
}

###############################################################################
# Object ownership controls
#
# Applied after the bucket policy so that the two never conflict.
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

###############################################################################
# ACL / explicit grants
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket && (var.acl != null || length(var.grant) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [1] : []

    content {
      owner {
        id = data.aws_canonical_user_id.current[0].id
      }

      dynamic "grant" {
        for_each = var.grant

        content {
          permission = grant.value.permission

          grantee {
            id            = try(grant.value.grantee.id, null)
            type          = grant.value.grantee.type
            uri           = try(grant.value.grantee.uri, null)
            email_address = try(grant.value.grantee.email_address, null)
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(var.versioning) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning.enabled, false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, null)
  }
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(var.website) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = length(try(var.website.redirect_all_requests_to, {})) > 0 ? [var.website.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])

    content {
      dynamic "condition" {
        for_each = length(try(routing_rule.value.condition, {})) > 0 ? [routing_rule.value.condition] : []

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(var.logging) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, null)

  dynamic "target_object_key_format" {
    for_each = length(try(var.logging.target_object_key_format, {})) > 0 ? [var.logging.target_object_key_format] : []

    content {
      dynamic "simple_prefix" {
        for_each = try(target_object_key_format.value.simple_prefix, null) != null ? [1] : []

        content {}
      }
    }
  }
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

###############################################################################
# Requester pays
###############################################################################

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

###############################################################################
# Lifecycle rules
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = length(try(rule.value.filter, {})) > 0 ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "and" {
            for_each = try(filter.value.and, [])

            content {
              prefix = try(and.value.prefix, null)
              tags   = try(and.value.tags, null)
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = length(try(rule.value.expiration, {})) > 0 ? [rule.value.expiration] : []

        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])

        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = length(try(rule.value.noncurrent_version_expiration, {})) > 0 ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = length(try(rule.value.abort_incomplete_multipart_upload, {})) > 0 ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }
    }
  }
}

###############################################################################
# Cross-region replication
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && length(var.replication_configuration) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = try(var.replication_configuration.rules, [])

    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = [try(rule.value.filter, {})]

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "and" {
            for_each = try(filter.value.and, [])

            content {
              prefix = try(and.value.prefix, null)
              tags   = try(and.value.tags, null)
            }
          }
        }
      }

      delete_marker_replication {
        status = try(rule.value.delete_marker_replication_status, "Disabled")
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Intelligent tiering
###############################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = local.create_bucket && length(var.intelligent_tiering) > 0 ? { for idx, cfg in var.intelligent_tiering : tostring(idx) => cfg } : {}

  bucket = aws_s3_bucket.this[0].id
  name   = try(each.value.name, "intelligent-tiering")
  status = try(each.value.status, "Enabled")

  dynamic "filter" {
    for_each = length(try(each.value.filter, {})) > 0 ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

###############################################################################
# Object lock with default retention
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_enabled && length(var.object_lock_configuration) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.default_retention.mode
      days  = try(var.object_lock_configuration.default_retention.days, null)
      years = try(var.object_lock_configuration.default_retention.years, null)
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "target_stack" {
  description = "Logical name of the target stack used to namespace IAM roles."
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Short git hash identifying the deployed stack revision."
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Long, zero-padded git hash placeholder for the deployed stack."
  type        = string
  default     = "benchmark0000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "Name of the S3 bucket that stores stack artifacts and datasets."
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "S3 object key of the primary dataset consumed by the stack."
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "S3 object key of the destigmatized dataset consumed by the stack."
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "S3 object key of the genomic dataset consumed by the stack."
  type        = string
  default     = "genomic_dataset.csv"
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  partition   = data.aws_partition.current.partition
  name_suffix = "${var.target_stack}-${var.stack_githash}"

  bucket_arn = "arn:${local.partition}:s3:::${var.stack_s3_bucket}"

  common_tags = {
    Stack            = var.target_stack
    StackGitHash     = var.stack_githash
    StackGitHashLong = var.stack_githash_long
    ManagedBy        = "terraform"
  }

  # AWS managed policies every microservice tier receives.
  managed_policy_arns = [
    "arn:${local.partition}:iam::aws:policy/CloudWatchAgentServerPolicy",
    "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore",
  ]

  # Non-tier-specific S3 object prefixes required by every microservice:
  # shared configuration, SSL certificates and common security tooling.
  common_object_prefixes = [
    "config/",
    "ssl-certs/",
    "security-tools/",
  ]

  # Dataset object keys exposed as stack inputs.
  dataset_object_keys = [
    var.dataset_s3_object_key,
    var.destigmatized_dataset_s3_object_key,
    var.genomic_dataset_s3_object_key,
  ]

  # One entry per microservice tier. The map key is the role-specific prefix
  # that is combined with the target stack and git hash to form the IAM role
  # and instance profile names.
  role_configs = {
    "wildfly-deployment-s3" = {
      artifact_prefixes = ["wildfly/"]
      list_bucket       = true
    }
    "httpd-deployment-s3" = {
      artifact_prefixes = ["httpd/"]
      list_bucket       = true
    }
    "auth-hpds-deployment-s3" = {
      artifact_prefixes = ["auth-hpds/"]
      list_bucket       = true
    }
    "open-hpds-deployment-s3" = {
      artifact_prefixes = ["open-hpds/"]
      list_bucket       = true
    }
    "dictionary-deployment-s3" = {
      artifact_prefixes = ["dictionary/"]
      list_bucket       = true
    }
  }

  # Flattened map of managed policy attachments (role x managed policy).
  role_policy_attachments = {
    for item in flatten([
      for role_key in keys(local.role_configs) : [
        for policy_arn in local.managed_policy_arns : {
          key        = "${role_key}--${basename(policy_arn)}"
          role_key   = role_key
          policy_arn = policy_arn
        }
      ]
    ]) : item.key => item
  }
}

###############################################################################
# IAM roles (EC2 assume role) with matching instance profiles
###############################################################################

resource "aws_iam_role" "microservice" {
  for_each = local.role_configs

  name = "${each.key}-${local.name_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_instance_profile" "microservice" {
  for_each = local.role_configs

  name = "${each.key}-${local.name_suffix}"
  role = aws_iam_role.microservice[each.key].name

  tags = local.common_tags
}

###############################################################################
# Managed policy attachments (CloudWatch agent + SSM core)
###############################################################################

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = local.role_policy_attachments

  role       = aws_iam_role.microservice[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

###############################################################################
# Inline least-privilege policy per microservice tier
###############################################################################

resource "aws_iam_role_policy" "microservice" {
  for_each = local.role_configs

  name = "${each.key}-${local.name_suffix}-policy"
  role = aws_iam_role.microservice[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid      = "AllowEC2Tagging"
          Effect   = "Allow"
          Action   = ["ec2:CreateTags"]
          Resource = "arn:${local.partition}:ec2:*:*:instance/*"
        },
        {
          Sid      = "AllowCloudWatchPutMetricData"
          Effect   = "Allow"
          Action   = ["cloudwatch:PutMetricData"]
          Resource = "*"
        },
        {
          Sid    = "AllowS3ArtifactRead"
          Effect = "Allow"
          Action = ["s3:GetObject"]
          Resource = concat(
            [for prefix in each.value.artifact_prefixes : "${local.bucket_arn}/${prefix}*"],
            [for prefix in local.common_object_prefixes : "${local.bucket_arn}/${prefix}*"],
            [for key in local.dataset_object_keys : "${local.bucket_arn}/${key}"]
          )
        }
      ],
      each.value.list_bucket ? [
        {
          Sid      = "AllowS3ListBucket"
          Effect   = "Allow"
          Action   = ["s3:ListBucket"]
          Resource = local.bucket_arn
          Condition = {
            StringLike = {
              "s3:prefix" = concat(
                [for prefix in each.value.artifact_prefixes : "${prefix}*"],
                [for prefix in local.common_object_prefixes : "${prefix}*"]
              )
            }
          }
        }
      ] : []
    )
  })
}

###############################################################################
# Terraform AWS Security Group module (self-contained, single file)
#
# Supports:
#   - Creating a new security group OR attaching rules to an existing one
#   - Module-level creation toggle (create) and new-group toggle (create_sg)
#   - Configurable create_before_destroy lifecycle + revoke_rules_on_delete
#   - Separate flexible ingress/egress rule lists for the new and existing paths
#   - Optional customer-managed EC2 prefix list
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Controls whether the module creates any resources."
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Controls whether a new security group is created. When false, rules are attached to the existing security group identified by existing_sg_id."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "ID of the VPC that the new security group is created in. When null and create_sg is true, a VPC is created."
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC created when vpc_id is null."
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_sg_id" {
  description = "ID of an existing security group to attach rules to when create_sg is false."
  type        = string
  default     = null
}

variable "sg_name" {
  description = "Name of the security group created by the module."
  type        = string
  default     = "example-security-group"
}

variable "sg_description" {
  description = "Description of the security group created by the module."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "sg_create_before_destroy" {
  description = "Whether the newly created security group uses the create_before_destroy lifecycle."
  type        = bool
  default     = false
}

variable "sg_revoke_rules_on_delete" {
  description = "Whether to revoke all ingress and egress rules before deleting the newly created security group."
  type        = bool
  default     = false
}

variable "ingress_rules" {
  description = "List of ingress rule objects applied to the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = optional(string, "-1")
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules : length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null
      ]) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "egress_rules" {
  description = "List of egress rule objects applied to the newly created security group. When left empty the security group keeps AWS's built-in default egress rule which allows all outbound IPv4 traffic. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = optional(string, "-1")
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.egress_rules : length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null
      ]) == 1
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_ingress_rules" {
  description = "List of ingress rule objects applied to the existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = optional(string, "-1")
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_sg_ingress_rules : length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null
      ]) == 1
    ])
    error_message = "Each existing security group ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_egress_rules" {
  description = "List of egress rule objects applied to the existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  type = list(object({
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
    ip_protocol                  = optional(string, "-1")
    from_port                    = optional(number)
    to_port                      = optional(number)
    description                  = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.existing_sg_egress_rules : length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null
      ]) == 1
    ])
    error_message = "Each existing security group egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the customer-managed EC2 prefix list created by the module."
  type        = string
  default     = "example-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family of the customer-managed EC2 prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the customer-managed EC2 prefix list can hold."
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "List of CIDR entries used to populate the customer-managed EC2 prefix list."
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_ids" {
  description = "List of existing prefix list IDs. When non-empty, no new prefix list is created."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to the resources created by the module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  create                = var.create
  create_sg             = var.create && var.create_sg
  create_existing_rules = var.create && !var.create_sg && var.existing_sg_id != null && var.existing_sg_id != ""

  # VPC: use the supplied VPC ID, otherwise fall back to a VPC created here.
  vpc_id = coalesce(var.vpc_id, try(aws_vpc.this[0].id, null))

  # ID of the newly created security group (respecting the lifecycle toggle).
  created_sg_id = var.sg_create_before_destroy ? try(aws_security_group.this_cbd[0].id, null) : try(aws_security_group.this[0].id, null)

  # Effective security group that rules are attached to.
  security_group_id = local.create_sg ? local.created_sg_id : var.existing_sg_id
}

###############################################################################
# Optional supporting VPC (only when no vpc_id is supplied)
###############################################################################

resource "aws_vpc" "this" {
  count = local.create_sg && var.vpc_id == null ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${var.sg_name}-vpc" })
}

###############################################################################
# Optional customer-managed EC2 prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr = entry.value
    }
  }

  tags = var.tags
}

###############################################################################
# Newly created security group
#
# Two resources are declared because Terraform's create_before_destroy
# meta-argument must be a static literal and cannot reference a variable.
# Exactly one of them is active based on sg_create_before_destroy.
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_sg && !var.sg_create_before_destroy ? 1 : 0

  name                   = var.sg_name
  description            = var.sg_description
  vpc_id                 = local.vpc_id
  revoke_rules_on_delete = var.sg_revoke_rules_on_delete

  tags = var.tags

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      description      = ingress.value.description
      from_port        = coalesce(ingress.value.from_port, 0)
      to_port          = coalesce(ingress.value.to_port, 0)
      protocol         = ingress.value.ip_protocol
      cidr_blocks      = ingress.value.cidr_ipv4 != null ? [ingress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = ingress.value.cidr_ipv6 != null ? [ingress.value.cidr_ipv6] : null
      security_groups  = ingress.value.referenced_security_group_id != null ? [ingress.value.referenced_security_group_id] : null
      prefix_list_ids  = ingress.value.prefix_list_id != null ? [ingress.value.prefix_list_id] : null
    }
  }

  dynamic "egress" {
    for_each = var.egress_rules
    content {
      description      = egress.value.description
      from_port        = coalesce(egress.value.from_port, 0)
      to_port          = coalesce(egress.value.to_port, 0)
      protocol         = egress.value.ip_protocol
      cidr_blocks      = egress.value.cidr_ipv4 != null ? [egress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = egress.value.cidr_ipv6 != null ? [egress.value.cidr_ipv6] : null
      security_groups  = egress.value.referenced_security_group_id != null ? [egress.value.referenced_security_group_id] : null
      prefix_list_ids  = egress.value.prefix_list_id != null ? [egress.value.prefix_list_id] : null
    }
  }

  lifecycle {
    create_before_destroy = false
  }
}

resource "aws_security_group" "this_cbd" {
  count = local.create_sg && var.sg_create_before_destroy ? 1 : 0

  name_prefix            = "${var.sg_name}-"
  description            = var.sg_description
  vpc_id                 = local.vpc_id
  revoke_rules_on_delete = var.sg_revoke_rules_on_delete

  tags = var.tags

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      description      = ingress.value.description
      from_port        = coalesce(ingress.value.from_port, 0)
      to_port          = coalesce(ingress.value.to_port, 0)
      protocol         = ingress.value.ip_protocol
      cidr_blocks      = ingress.value.cidr_ipv4 != null ? [ingress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = ingress.value.cidr_ipv6 != null ? [ingress.value.cidr_ipv6] : null
      security_groups  = ingress.value.referenced_security_group_id != null ? [ingress.value.referenced_security_group_id] : null
      prefix_list_ids  = ingress.value.prefix_list_id != null ? [ingress.value.prefix_list_id] : null
    }
  }

  dynamic "egress" {
    for_each = var.egress_rules
    content {
      description      = egress.value.description
      from_port        = coalesce(egress.value.from_port, 0)
      to_port          = coalesce(egress.value.to_port, 0)
      protocol         = egress.value.ip_protocol
      cidr_blocks      = egress.value.cidr_ipv4 != null ? [egress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = egress.value.cidr_ipv6 != null ? [egress.value.cidr_ipv6] : null
      security_groups  = egress.value.referenced_security_group_id != null ? [egress.value.referenced_security_group_id] : null
      prefix_list_ids  = egress.value.prefix_list_id != null ? [egress.value.prefix_list_id] : null
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Rules attached to an existing security group
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.create_existing_rules ? { for idx, rule in var.existing_sg_ingress_rules : tostring(idx) => rule } : {}

  security_group_id = var.existing_sg_id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port

  description = each.value.description

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.create_existing_rules ? { for idx, rule in var.existing_sg_egress_rules : tostring(idx) => rule } : {}

  security_group_id = var.existing_sg_id

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id

  ip_protocol = each.value.ip_protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port

  description = each.value.description

  tags = var.tags
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the security group that rules are attached to (created or existing)."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group, if one was created."
  value       = local.create_sg ? (var.sg_create_before_destroy ? try(aws_security_group.this_cbd[0].arn, null) : try(aws_security_group.this[0].arn, null)) : null
}

output "vpc_id" {
  description = "ID of the VPC used by the module."
  value       = local.vpc_id
}

output "prefix_list_id" {
  description = "ID of the customer-managed prefix list created by the module, if any."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

###############################################################################
# Variables
###############################################################################

variable "project_name" {
  description = "Project name used as a prefix for namespaced IAM resources."
  type        = string
  default     = "Cv-React-App"
}

variable "aws_region" {
  description = "AWS region used for pipeline artifacts and regional ARNs."
  type        = string
  default     = "us-east-1"
}

###############################################################################
# Data sources (static provider metadata / well-known public AMI-independent
# lookups only - no pre-existing account infrastructure is discovered here)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = var.aws_region

  common_tags = {
    Project   = var.project_name
    ManagedBy = "Terraform"
  }

  # Well-known AWS managed policy ARNs (global, not account specific)
  policy_ec2_role_for_codedeploy = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
  policy_ec2_full_access         = "arn:${local.partition}:iam::aws:policy/AmazonEC2FullAccess"
  policy_s3_full_access          = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
  policy_codedeploy_role         = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
  policy_cloudwatch_agent_server = "arn:${local.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"

  # Well-known CodePipeline managed artifact bucket in the target region
  codepipeline_artifact_bucket = "codepipeline-${local.region}-${local.account_id}"
}

###############################################################################
# Trust policy documents
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    sid     = "AllowCodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    sid     = "AllowCodeBuildAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    sid     = "AllowCodePipelineAndServicesAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com",
        "cloudformation.amazonaws.com",
        "codecommit.amazonaws.com",
        "lambda.amazonaws.com",
        "s3.amazonaws.com",
        "ec2.amazonaws.com",
        "elasticbeanstalk.amazonaws.com",
        "events.amazonaws.com",
        "sns.amazonaws.com",
      ]
    }

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

###############################################################################
# EC2 CodeDeploy service role + instance profile
###############################################################################

resource "aws_iam_role" "ec2_codedeploy" {
  name               = "${var.project_name}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_role_for_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = local.policy_ec2_role_for_codedeploy
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full_access" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = local.policy_ec2_full_access
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_full_access" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = local.policy_s3_full_access
}

resource "aws_iam_instance_profile" "ec2_codedeploy" {
  name = "${var.project_name}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy.name
  tags = local.common_tags
}

###############################################################################
# CodeDeploy service role
###############################################################################

resource "aws_iam_role" "codedeploy" {
  name               = "${var.project_name}_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_role" {
  role       = aws_iam_role.codedeploy.name
  policy_arn = local.policy_codedeploy_role
}

resource "aws_iam_role_policy_attachment" "codedeploy_s3_full_access" {
  role       = aws_iam_role.codedeploy.name
  policy_arn = local.policy_s3_full_access
}

###############################################################################
# EC2 CloudWatch Agent service role + instance profile
###############################################################################

resource "aws_iam_role" "cloudwatch_agent" {
  name               = "${var.project_name}_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_server" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = local.policy_cloudwatch_agent_server
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_full_access" {
  role       = aws_iam_role.cloudwatch_agent.name
  policy_arn = local.policy_s3_full_access
}

resource "aws_iam_instance_profile" "cloudwatch_agent" {
  name = "${var.project_name}_cloudwatch_agent_instance_profile"
  role = aws_iam_role.cloudwatch_agent.name
  tags = local.common_tags
}

###############################################################################
# CodeBuild role (managed S3 Full Access + inline logging / artifacts / reports)
###############################################################################

resource "aws_iam_role" "codebuild" {
  name               = "CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full_access" {
  role       = aws_iam_role.codebuild.name
  policy_arn = local.policy_s3_full_access
}

data "aws_iam_policy_document" "codebuild_inline" {
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*:*",
    ]
  }

  statement {
    sid    = "CodePipelineArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket",
      "s3:PutObject",
    ]
    resources = [
      "arn:${local.partition}:s3:::${local.codepipeline_artifact_bucket}",
      "arn:${local.partition}:s3:::${local.codepipeline_artifact_bucket}/*",
    ]
  }

  statement {
    sid    = "CodeBuildReports"
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases",
      "codebuild:BatchPutCodeCoverages",
    ]
    resources = [
      "arn:${local.partition}:codebuild:${local.region}:${local.account_id}:report-group/*",
    ]
  }
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name   = "${var.project_name}_codebuild_inline_policy"
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild_inline.json
}

###############################################################################
# CodePipeline role (multi-service + root trust, broad pipeline inline policy)
###############################################################################

resource "aws_iam_role" "codepipeline" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "codepipeline_inline" {
  statement {
    sid    = "CodeStarConnections"
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection",
      "codestar-connections:GetConnection",
      "codestar-connections:GetConnectionToken",
      "codestar-connections:ListConnections",
      "codestar-connections:PassConnection",
    ]
    resources = [
      "arn:${local.partition}:codestar-connections:${local.region}:${local.account_id}:connection/*",
    ]
  }

  statement {
    sid    = "S3ArtifactAccess"
    effect = "Allow"
    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:PutObject",
      "s3:PutObjectAcl",
    ]
    resources = [
      "arn:${local.partition}:s3:::${local.codepipeline_artifact_bucket}",
      "arn:${local.partition}:s3:::${local.codepipeline_artifact_bucket}/*",
    ]
  }

  statement {
    sid    = "CodeCommit"
    effect = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:UploadArchive",
      "codecommit:CancelUploadArchive",
      "codecommit:ListBranches",
      "codecommit:ListRepositories",
      "codecommit:GetObjectIdentifier",
      "codecommit:ListTagsForResource",
    ]
    resources = [
      "arn:${local.partition}:codecommit:${local.region}:${local.account_id}:*",
    ]
  }

  statement {
    sid    = "CodeDeploy"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetApplication",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:ListDeployments",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentConfigs",
      "codedeploy:ListApplicationRevisions",
    ]
    resources = [
      "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:*",
    ]
  }

  statement {
    sid    = "Lambda"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions",
      "lambda:ListAliases",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetAlias",
      "lambda:UpdateFunctionCode",
    ]
    resources = [
      "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*",
    ]
  }

  statement {
    sid    = "CodeBuild"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:BatchGetBuildBatches",
      "codebuild:StartBuild",
      "codebuild:StartBuildBatch",
      "codebuild:StopBuild",
      "codebuild:StopBuildBatch",
      "codebuild:ListBuilds",
      "codebuild:ListBuildsForProject",
      "codebuild:ListProjects",
    ]
    resources = [
      "arn:${local.partition}:codebuild:${local.region}:${local.account_id}:project/*",
    ]
  }

  statement {
    sid    = "CloudFormation"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeChangeSet",
      "cloudformation:CreateChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:UpdateStack",
      "cloudformation:ValidateTemplate",
      "cloudformation:GetTemplate",
      "cloudformation:ListStacks",
      "cloudformation:SetStackPolicy",
    ]
    resources = [
      "arn:${local.partition}:cloudformation:${local.region}:${local.account_id}:stack/*/*",
    ]
  }

  statement {
    sid    = "IAMPassRoleToPipelineRoles"
    effect = "Allow"
    actions = [
      "iam:PassRole",
    ]
    resources = [
      aws_iam_role.ec2_codedeploy.arn,
      aws_iam_role.codedeploy.arn,
      aws_iam_role.cloudwatch_agent.arn,
      aws_iam_role.codebuild.arn,
      aws_iam_role.codepipeline.arn,
    ]
  }

  statement {
    sid    = "SupportingInfrastructureServices"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeTags",
      "ec2:RunInstances",
      "ec2:TerminateInstances",
      "ec2:CreateTags",
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeScalingActivities",
      "elasticbeanstalk:DescribeApplications",
      "elasticbeanstalk:DescribeEnvironments",
      "elasticbeanstalk:DescribeEvents",
      "sns:Publish",
      "cloudwatch:PutMetricData",
      "events:PutRule",
      "events:PutTargets",
      "events:DescribeRule",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name   = "${var.project_name}_codepipeline_inline_policy"
  role   = aws_iam_role.codepipeline.id
  policy = data.aws_iam_policy_document.codepipeline_inline.json
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Deployment environment used to tag every resource."
  type        = string
  default     = "dev"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
  }

  ssm_prefix = {
    invitations = "/file-service/dynamodb/invitations/"
    files       = "/file-service/dynamodb/files/"
    hashes      = "/hashes-service/dynamodb/hashes/"
    storage     = "/file-service/dynamodb/storage/"
    wallets     = "/wallet-service/dynamodb/wallets/"
  }
}

###############################################################################
# DynamoDB tables
###############################################################################

