  tags = local.common_tags
}

resource "aws_ssm_parameter" "invitations_name" {
  name  = "${local.ssm_prefix.invitations}name"
  type  = "String"
  value = aws_dynamodb_table.near_files_invitations.name

  tags = local.common_tags
}

resource "aws_ssm_parameter" "invitations_stream_arn" {
  name  = "${local.ssm_prefix.invitations}stream_arn"
  type  = "String"
  value = aws_dynamodb_table.near_files_invitations.stream_arn

  tags = local.common_tags
}

# near-files
resource "aws_ssm_parameter" "files_arn" {
  name  = "${local.ssm_prefix.files}arn"
  type  = "String"
