  tags = local.common_tags
}

resource "aws_ssm_parameter" "files_stream_arn" {
  name  = "${local.ssm_prefix.files}stream_arn"
  type  = "String"
  value = aws_dynamodb_table.near_files.stream_arn

  tags = local.common_tags
}

# near-hashes
resource "aws_ssm_parameter" "hashes_arn" {
  name  = "${local.ssm_prefix.hashes}arn"
  type  = "String"
  value = aws_dynamodb_table.near_hashes.arn

  tags = local.common_tags
}

resource "aws_ssm_parameter" "hashes_name" {
  name  = "${local.ssm_prefix.hashes}name"
  type  = "String"
  value = aws_dynamodb_table.near_hashes.name

  tags = local.common_tags
}

resource "aws_ssm_parameter" "hashes_stream_arn" {
  name  = "${local.ssm_prefix.hashes}stream_arn"
  type  = "String"
  value = aws_dynamodb_table.near_hashes.stream_arn

  tags = local.common_tags
}

# near-storage
resource "aws_ssm_parameter" "storage_arn" {
  name  = "${local.ssm_prefix.storage}arn"
  type  = "String"
  value = aws_dynamodb_table.near_storage.arn

  tags = local.common_tags
}

resource "aws_ssm_parameter" "storage_name" {
  name  = "${local.ssm_prefix.storage}name"
  type  = "String"
  value = aws_dynamodb_table.near_storage.name

  tags = local.common_tags
}

resource "aws_ssm_parameter" "storage_stream_arn" {
  name  = "${local.ssm_prefix.storage}stream_arn"
  type  = "String"
  value = aws_dynamodb_table.near_storage.stream_arn

