# near-wallets
resource "aws_ssm_parameter" "wallets_arn" {
  name  = "${local.ssm_prefix.wallets}arn"
  type  = "String"
  value = aws_dynamodb_table.near_wallets.arn

  tags = local.common_tags
}

resource "aws_ssm_parameter" "wallets_name" {
  name  = "${local.ssm_prefix.wallets}name"
  type  = "String"
  value = aws_dynamodb_table.near_wallets.name

