########################################################################
# Variables and locals
########################################################################

variable "admin_cidr" {
  description = "CIDR block that is allowed to SSH into the chaos EC2 instances."
  type        = string
  default     = "192.0.2.0/24"
}

variable "instance_type" {
  description = "EC2 instance type used by the Auto Scaling Group."
  type        = string
  default     = "t3.micro"
}

locals {
  chaos_tag_key   = "ChaosTarget"
  chaos_tag_value = "true"
  name_prefix     = "chaos"

  common_tags = {
    Project = "chaos-engineering"
    Managed = "terraform"
  }
}

########################################################################
# Static provider metadata / well-known lookups
########################################################################

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

# Latest Amazon ECS-optimized Amazon Linux 2 AMI (public AWS-owned AMI).
data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

########################################################################
# Networking: VPC, public subnet, IGW, routing
########################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Single public subnet. Note: the subnet does NOT auto-assign public IPs;
# the launch template is responsible for associating a public IP.
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.name_prefix}-public-subnet"
    (local.chaos_tag_key)    = local.chaos_tag_value
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

########################################################################
# SSH key pair (generated so the configuration is fully self-contained)
########################################################################

resource "tls_private_key" "admin" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "admin" {
  key_name_prefix = "${local.name_prefix}-admin-key-"
  public_key      = tls_private_key.admin.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-key"
  })
}

########################################################################
# EC2 security group - SSH restricted to the admin CIDR only
########################################################################

resource "aws_security_group" "ec2" {
  name_prefix = "${local.name_prefix}-ec2-"
  description = "SSH access for chaos EC2 instances"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "ec2_ssh_ingress" {
  type              = "ingress"
  description       = "SSH from admin CIDR"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.admin_cidr]
  security_group_id = aws_security_group.ec2.id
}

resource "aws_security_group_rule" "ec2_egress_https" {
  type              = "egress"
  description       = "HTTPS to VPC interface endpoints (SSM, ECS, ECR, Logs)"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.ec2.id
}

resource "aws_security_group_rule" "ec2_egress_dns_udp" {
  type              = "egress"
  description       = "DNS resolution via the VPC resolver"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.ec2.id
}

resource "aws_security_group_rule" "ec2_egress_dns_tcp" {
  type              = "egress"
  description       = "DNS resolution via the VPC resolver (TCP fallback)"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.ec2.id
}

########################################################################
# VPC endpoints so instances can reach AWS services (ECS, SSM, ECR,
# Logs, S3) without opening internet egress from the security group.
########################################################################

resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "${local.name_prefix}-vpce-"
  description = "Allow HTTPS from chaos instances to VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "vpc_endpoints_ingress_https" {
  type                     = "ingress"
  description              = "HTTPS from the chaos EC2 instances"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.ec2.id
  security_group_id        = aws_security_group.vpc_endpoints.id
}

locals {
  interface_endpoints = {
    ssm         = "ssm"
    ssmmessages = "ssmmessages"
    ec2messages = "ec2messages"
    ecs         = "ecs"
    ecs_agent   = "ecs-agent"
    ecr_api     = "ecr.api"
    ecr_dkr     = "ecr.dkr"
    logs        = "logs"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${each.key}"
  })
}

# Gateway endpoint for S3 (used by ECR image layers and FIS logging).
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3"
  })
}

########################################################################
# IAM: EC2 instance role/profile (ECS + SSM)
########################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2" {
  name_prefix        = "${local.name_prefix}-ec2-instance-role-"
  description        = "Instance role for chaos ECS/SSM managed instances"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name_prefix = "${local.name_prefix}-ec2-instance-profile-"
  role        = aws_iam_role.ec2.name

  tags = local.common_tags
}

########################################################################
# Launch template: ECS-optimized AMI, IMDSv2 required, public IP
########################################################################

resource "aws_launch_template" "ecs" {
  name_prefix   = "${local.name_prefix}-ecs-"
  description   = "Launch template for chaos ECS instances"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = var.instance_type
  key_name      = aws_key_pair.admin.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2.name
  }

  # The subnet does not auto-assign public IPs, so request one explicitly.
  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.ec2.id]
    delete_on_termination       = true
  }

  # Enforce IMDSv2 (tokens required).
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "disabled"
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name                  = "${local.name_prefix}-ecs-instance"
      (local.chaos_tag_key) = local.chaos_tag_value
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name                  = "${local.name_prefix}-ecs-volume"
      (local.chaos_tag_key) = local.chaos_tag_value
    })
  }

  tags = local.common_tags
}

########################################################################
# Auto Scaling Group of ECS instances
########################################################################

resource "aws_autoscaling_group" "ecs" {
  name_prefix               = "${local.name_prefix}-ecs-asg-"
  vpc_zone_identifier       = [aws_subnet.public.id]
  desired_capacity    = 2
  min_size            = 1
  max_size            = 3

  wait_for_capacity_timeout = "0"

  launch_template {
    id      = aws_launch_template.ecs.id
    version = "$Latest"
  }

  tag {
    key                 = "Name"
    value               = "${local.name_prefix}-ecs-asg-instance"
    propagate_at_launch = true
  }

  tag {
    key                 = local.chaos_tag_key
    value               = local.chaos_tag_value
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
  }
}

########################################################################
# KMS key for FIS log encryption (usable by AWS log delivery)
########################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAccountAccess"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowAwsLogDelivery"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type = "Service"
      identifiers = [
        "logging.s3.amazonaws.com",
        "delivery.logs.amazonaws.com",
      ]
    }
  }

  statement {
    sid    = "AllowFisRoleUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.fis.arn]
    }
  }
}

resource "aws_kms_key" "fis" {
  description             = "CMK for FIS experiment log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-fis-logs"
  })
}

resource "aws_kms_alias" "fis" {
  name_prefix   = "alias/${local.name_prefix}-fis-logs-"
  target_key_id = aws_kms_key.fis.key_id
}

########################################################################
# S3 bucket for FIS experiment logs
########################################################################

resource "aws_s3_bucket" "fis_logs" {
  bucket_prefix = "${local.name_prefix}-fis-experiment-logs-"
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-fis-experiment-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "fis_logs_bucket" {
  statement {
    sid     = "AllowFisServiceWrite"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid     = "AllowAwsLogDeliveryWrite"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
  }

  statement {
    sid     = "AllowAwsLogDeliveryAclCheck"
    effect  = "Allow"
    actions = ["s3:GetBucketAcl"]

    resources = [aws_s3_bucket.fis_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_logs_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.fis_logs]
}

########################################################################
# IAM role that AWS FIS assumes to run the experiments
########################################################################

data "aws_iam_policy_document" "fis_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "fis" {
  name_prefix        = "${local.name_prefix}-fis-execution-role-"
  description        = "Role assumed by AWS Fault Injection Simulator"
  assume_role_policy = data.aws_iam_policy_document.fis_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "fis_permissions" {
  statement {
    sid    = "Ec2FaultInjection"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeSubnets",
      "ec2:DescribeImages",
      "ec2:DescribeNetworkAcls",
      "ec2:DescribeRouteTables",
      "ec2:DescribeTags",
      "ec2:StopInstances",
      "ec2:TerminateInstances",
      "ec2:RebootInstances",
      "ec2:CreateNetworkAclEntry",
      "ec2:DeleteNetworkAclEntry",
      "ec2:ReplaceNetworkAclEntry",
      "ec2:PauseVolumeIO",
      "ec2:ResumeVolumeIO",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "SsmFaultInjection"
    effect = "Allow"

    actions = [
      "ssm:SendCommand",
      "ssm:CancelCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "ssm:GetCommandInvocation",
      "ssm:DescribeInstanceInformation",
    ]

    resources = ["*"]
  }

  statement {
    sid       = "ResourceTagResolution"
    effect    = "Allow"
    actions   = ["tag:GetResources"]
    resources = ["*"]
  }

  statement {
    sid       = "FisLoggingToS3"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]
  }

  statement {
    sid    = "FisLoggingEncryption"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.fis.arn]
  }
}

resource "aws_iam_role_policy" "fis" {
  name_prefix = "${local.name_prefix}-fis-fault-injection-"
  role        = aws_iam_role.fis.id
  policy      = data.aws_iam_policy_document.fis_permissions.json
}

########################################################################
# AWS FIS experiment templates
########################################################################

# 1. API-level internal-error fault against EC2's DescribeImages API.
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "Inject internal-error faults into the EC2 DescribeImages API"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name        = "ec2-api-internal-error"
    action_id   = "aws:ec2:api"
    description = "Inject an internal error into the EC2 DescribeImages API"

    parameter {
      key   = "api"
      value = "DescribeImages"
    }

    target {
      key   = "Instances"
      value = "chaos-ec2-instances"
    }
  }

  target {
    name           = "chaos-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = "2"

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "api-internal-error/"
    }
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

# 2. EBS volume I/O pause.
resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "Pause I/O on tagged EBS volumes"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name        = "ebs-pause-io"
    action_id   = "aws:ebs:pause-volume-io"
    description = "Pause I/O operations for the targeted EBS volumes"

    parameter {
      key   = "duration"
      value = "PT5M"
    }

    target {
      key   = "Volumes"
      value = "chaos-ebs-volumes"
    }
  }

  target {
    name           = "chaos-ebs-volumes"
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = "2"

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "ebs-pause-io/"
    }
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

# 3. EC2 CPU stress (via SSM agent).
resource "aws_fis_experiment_template" "cpu_stress" {
  description = "Run CPU stress on tagged EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name        = "ec2-cpu-stress"
    action_id   = "aws:ssm:send-command"
    description = "Run the AWSFIS-Run-CPU-Stress document on the targeted instances"

    parameter {
      key   = "documentArn"
      value = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key   = "documentParameters"
      value = jsonencode({ DurationSeconds = "120", CPU = "0" })
    }

    parameter {
      key   = "duration"
      value = "PT2M"
    }

    target {
      key   = "Instances"
      value = "chaos-ec2-instances"
    }
  }

  target {
    name           = "chaos-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = "2"

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "cpu-stress/"
    }
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

# 4. EC2 instance termination.
resource "aws_fis_experiment_template" "terminate_instances" {
  description = "Terminate tagged EC2 instances"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name        = "ec2-terminate-instances"
    action_id   = "aws:ec2:terminate-instances"
    description = "Terminate the targeted EC2 instances"

    target {
      key   = "Instances"
      value = "chaos-ec2-instances"
    }
  }

  target {
    name           = "chaos-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = "2"

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "terminate-instances/"
    }
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

# 5. Network connectivity disruption on the public subnet.
resource "aws_fis_experiment_template" "network_disruption" {
  description = "Disrupt network connectivity for the tagged subnet"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name        = "network-disrupt-connectivity"
    action_id   = "aws:network:disrupt-connectivity"
    description = "Disrupt network connectivity for the targeted subnet"

    parameter {
      key   = "scope"
      value = "all"
    }

    parameter {
      key   = "duration"
      value = "PT5M"
    }

    target {
      key   = "Subnets"
      value = "chaos-public-subnet"
    }
  }

  target {
    name           = "chaos-public-subnet"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = "2"

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.bucket
      prefix      = "network-disruption/"
    }
  }

  depends_on = [
    aws_iam_role_policy.fis,
    aws_s3_bucket_policy.fis_logs,
  ]
}

########################################################################
# Outputs
########################################################################

output "ssh_private_key_pem" {
  description = "Private key for SSH access to the chaos instances."
  value       = tls_private_key.admin.private_key_pem
  sensitive   = true
}

output "fis_role_arn" {
  description = "ARN of the IAM role assumed by AWS FIS."
  value       = aws_iam_role.fis.arn
}

output "fis_logs_bucket" {
  description = "Name of the S3 bucket that stores FIS experiment logs."
  value       = aws_s3_bucket.fis_logs.bucket
}

###############################################################################
# Terraform / Provider requirements
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

###############################################################################
# Input variables
###############################################################################

variable "create_vpc" {
  description = "Controls if the VPC and its associated resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name to be used on all resources as an identifier."
  type        = string
  default     = "vpc"
}

variable "cidr" {
  description = "The IPv4 CIDR block for the VPC. Ignored when ipv4_ipam_pool_id is set."
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "ID of an IPv4 IPAM pool to allocate the VPC CIDR from."
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length of the IPv4 CIDR to allocate from the IPAM pool."
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC."
  type        = list(string)
  default     = []
}

variable "enable_dns_hostnames" {
  description = "Whether to enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether to enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances (default or dedicated)."
  type        = string
  default     = "default"
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Whether to request an Amazon-provided IPv6 CIDR block for the VPC."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be created for the VPC."
  type        = bool
  default     = true
}

variable "create_egress_only_igw" {
  description = "Controls if an egress-only Internet Gateway should be created for IPv6 traffic."
  type        = bool
  default     = false
}

variable "public_subnets" {
  description = "Map of public subnet definitions. The map key is used as the subnet identifier."
  type = map(object({
    cidr_block                      = string
    availability_zone               = optional(string)
    ipv6_cidr_block                 = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
    map_public_ip_on_launch         = optional(bool, true)
    tags                            = optional(map(string), {})
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnet definitions. The map key is used as the subnet identifier."
  type = map(object({
    cidr_block                      = string
    availability_zone               = optional(string)
    ipv6_cidr_block                 = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
    map_public_ip_on_launch         = optional(bool, false)
    nat_gateway_key                 = optional(string)
    network_acl_key                 = optional(string)
    tags                            = optional(map(string), {})
  }))
  default = {}
}

variable "nat_gateways" {
  description = "Map of NAT Gateway definitions. Each entry deploys a NAT gateway in the referenced public subnet."
  type = map(object({
    subnet_key        = string
    connectivity_type = optional(string, "public")
    allocation_id     = optional(string)
    tags              = optional(map(string), {})
  }))
  default = {}
}

variable "public_network_acl_ingress" {
  description = "Ingress rules for the public network ACL. Defaults to allow-all."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default = []
}

variable "public_network_acl_egress" {
  description = "Egress rules for the public network ACL. Defaults to allow-all."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default = []
}

variable "private_network_acls" {
  description = "Map of dedicated private network ACLs. Private subnets reference these via network_acl_key."
  type = map(object({
    ingress = optional(list(object({
      rule_no         = number
      action          = string
      from_port       = number
      to_port         = number
      protocol        = string
      cidr_block      = optional(string)
      ipv6_cidr_block = optional(string)
      icmp_type       = optional(number)
      icmp_code       = optional(number)
    })), [])
    egress = optional(list(object({
      rule_no         = number
      action          = string
      from_port       = number
      to_port         = number
      protocol        = string
      cidr_block      = optional(string)
      ipv6_cidr_block = optional(string)
      icmp_type       = optional(number)
      icmp_code       = optional(number)
    })), [])
    tags = optional(map(string), {})
  }))
  default = {}
}

variable "create_dhcp_options" {
  description = "Controls if a DHCP option set should be created."
  type        = bool
  default     = false
}

variable "dhcp_options" {
  description = "DHCP option set configuration."
  type = object({
    domain_name          = optional(string)
    domain_name_servers  = optional(list(string))
    ntp_servers          = optional(list(string))
    netbios_name_servers = optional(list(string))
    netbios_node_type    = optional(string)
  })
  default = {}
}

variable "create_dhcp_options_association" {
  description = "Controls if the DHCP option set should be associated with the VPC."
  type        = bool
  default     = true
}

variable "flow_logs" {
  description = "Map of VPC flow log definitions across supported log destinations."
  type = map(object({
    destination_type         = optional(string, "cloud-watch-logs")
    destination_arn          = optional(string)
    iam_role_arn             = optional(string)
    traffic_type             = optional(string, "ALL")
    max_aggregation_interval = optional(number, 600)
    log_format               = optional(string)
    log_group_retention_days = optional(number, 30)
    log_group_kms_key_id     = optional(string)
    tags                     = optional(map(string), {})
  }))
  default = {}
}

variable "manage_default_security_group" {
  description = "Controls if the default security group of the VPC should be managed."
  type        = bool
  default     = false
}

variable "default_security_group_ingress" {
  description = "Ingress rules for the default security group."
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
    prefix_list_ids  = optional(list(string), [])
    security_groups  = optional(list(string), [])
    self             = optional(bool, false)
    description      = optional(string)
  }))
  default = []
}

variable "default_security_group_egress" {
  description = "Egress rules for the default security group."
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
    prefix_list_ids  = optional(list(string), [])
    security_groups  = optional(list(string), [])
    self             = optional(bool, false)
    description      = optional(string)
  }))
  default = []
}

variable "manage_default_network_acl" {
  description = "Controls if the default network ACL of the VPC should be managed."
  type        = bool
  default     = false
}

variable "default_network_acl_ingress" {
  description = "Ingress rules for the default network ACL. Defaults to allow-all for IPv4 and IPv6."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default = [
    {
      rule_no    = 100
      action     = "allow"
      from_port  = 0
      to_port    = 0
      protocol   = "-1"
      cidr_block = "0.0.0.0/0"
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      ipv6_cidr_block = "::/0"
    },
  ]
}

variable "default_network_acl_egress" {
  description = "Egress rules for the default network ACL. Defaults to allow-all for IPv4 and IPv6."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    icmp_type       = optional(number)
    icmp_code       = optional(number)
  }))
  default = [
    {
      rule_no    = 100
      action     = "allow"
      from_port  = 0
      to_port    = 0
      protocol   = "-1"
      cidr_block = "0.0.0.0/0"
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      ipv6_cidr_block = "::/0"
    },
  ]
}

variable "manage_default_route_table" {
  description = "Controls if the default route table of the VPC should be managed."
  type        = bool
  default     = false
}

variable "default_route_table_routes" {
  description = "Routes to add to the default route table."
  type = list(object({
    cidr_block                = optional(string)
    ipv6_cidr_block           = optional(string)
    gateway_id                = optional(string)
    nat_gateway_id            = optional(string)
    egress_only_gateway_id    = optional(string)
    transit_gateway_id        = optional(string)
    vpc_peering_connection_id = optional(string)
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################

locals {
  azs = slice(
    data.aws_availability_zones.available.names,
    0,
    min(3, length(data.aws_availability_zones.available.names))
  )

  public_indexes  = { for idx, k in keys(var.public_subnets) : k => idx }
  private_indexes = { for idx, k in keys(var.private_subnets) : k => idx }

  private_route_table_keys = toset([
    for k, v in var.private_subnets : v.nat_gateway_key != null ? v.nat_gateway_key : "none"
  ])

  flow_logs_cloudwatch_log_group = {
    for k, v in var.flow_logs : k => v
    if v.destination_type == "cloud-watch-logs" && v.destination_arn == null
  }

  flow_logs_s3_bucket = {
    for k, v in var.flow_logs : k => v
    if v.destination_type == "s3" && v.destination_arn == null
  }

  create_flow_log_cloudwatch_role = var.create_vpc && length([
    for k, v in var.flow_logs : k if v.destination_type == "cloud-watch-logs"
  ]) > 0

  create_flow_log_s3_bucket = var.create_vpc && length(local.flow_logs_s3_bucket) > 0

  flow_log_destinations = {
    for k, v in var.flow_logs : k => (
      v.destination_arn != null ? v.destination_arn :
      v.destination_type == "cloud-watch-logs" ? try(aws_cloudwatch_log_group.flow_log[k].arn, null) :
      v.destination_type == "s3" ? try(aws_s3_bucket.flow_log[0].arn, null) :
      null
    )
  }

  default_nacl_ingress = [
    {
      rule_no         = 100
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      cidr_block      = "0.0.0.0/0"
      ipv6_cidr_block = null
      icmp_type       = null
      icmp_code       = null
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      cidr_block      = null
      ipv6_cidr_block = "::/0"
      icmp_type       = null
      icmp_code       = null
    },
  ]

  default_nacl_egress = [
    {
      rule_no         = 100
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      cidr_block      = "0.0.0.0/0"
      ipv6_cidr_block = null
      icmp_type       = null
      icmp_code       = null
    },
    {
      rule_no         = 101
      action          = "allow"
      from_port       = 0
      to_port         = 0
      protocol        = "-1"
      cidr_block      = null
      ipv6_cidr_block = "::/0"
      icmp_type       = null
      icmp_code       = null
    },
  ]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block                       = var.ipv4_ipam_pool_id != null ? null : var.cidr
  ipv4_ipam_pool_id                = var.ipv4_ipam_pool_id
  ipv4_netmask_length              = var.ipv4_ipam_pool_id != null ? var.ipv4_netmask_length : null
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  instance_tenancy                 = var.instance_tenancy

  tags = merge(var.tags, { Name = var.name })
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = var.create_vpc ? toset(var.secondary_cidr_blocks) : toset([])

  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

###############################################################################
# Internet Gateways
###############################################################################

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-igw" })
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.create_vpc && var.create_egress_only_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-eigw" })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  for_each = var.create_vpc ? var.public_subnets : {}

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr_block
  availability_zone = coalesce(
    each.value.availability_zone,
    local.azs[local.public_indexes[each.key] % length(local.azs)]
  )
  ipv6_cidr_block = each.value.ipv6_cidr_block != null ? each.value.ipv6_cidr_block : (
    var.assign_generated_ipv6_cidr_block ? try(
      cidrsubnet(aws_vpc.this[0].ipv6_cidr_block, 8, local.public_indexes[each.key]), null
    ) : null
  )
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation
  map_public_ip_on_launch         = each.value.map_public_ip_on_launch

  tags = merge(var.tags, each.value.tags, { Name = "${var.name}-public-${each.key}" })
}

resource "aws_subnet" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr_block
  availability_zone = coalesce(
    each.value.availability_zone,
    local.azs[local.private_indexes[each.key] % length(local.azs)]
  )
  ipv6_cidr_block = each.value.ipv6_cidr_block != null ? each.value.ipv6_cidr_block : (
    var.assign_generated_ipv6_cidr_block ? try(
      cidrsubnet(aws_vpc.this[0].ipv6_cidr_block, 8, local.private_indexes[each.key] + 128), null
    ) : null
  )
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation
  map_public_ip_on_launch         = each.value.map_public_ip_on_launch

  tags = merge(var.tags, each.value.tags, { Name = "${var.name}-private-${each.key}" })
}

###############################################################################
# NAT Gateways and Elastic IPs
###############################################################################

resource "aws_eip" "nat" {
  for_each = {
    for k, v in var.nat_gateways : k => v
    if var.create_vpc && v.connectivity_type == "public" && v.allocation_id == null
  }

  domain = "vpc"

  tags = merge(var.tags, each.value.tags, { Name = "${var.name}-nat-eip-${each.key}" })
}

resource "aws_nat_gateway" "this" {
  for_each = var.create_vpc ? var.nat_gateways : {}

  allocation_id = each.value.connectivity_type == "public" ? (
    each.value.allocation_id != null ? each.value.allocation_id : try(aws_eip.nat[each.key].id, null)
  ) : null
  subnet_id         = aws_subnet.public[each.value.subnet_key].id
  connectivity_type = each.value.connectivity_type

  tags = merge(var.tags, each.value.tags, { Name = "${var.name}-nat-${each.key}" })

  depends_on = [aws_internet_gateway.this]
}

###############################################################################
# Public routing
###############################################################################

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-public" })
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route" "public_ipv6_internet_gateway" {
  count = var.create_vpc && var.create_igw && var.assign_generated_ipv6_cidr_block && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id              = aws_route_table.public[0].id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = var.create_vpc ? var.public_subnets : {}

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Private routing
###############################################################################

resource "aws_route_table" "private" {
  for_each = var.create_vpc ? local.private_route_table_keys : toset([])

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-private-${each.key}" })
}

resource "aws_route" "private_nat_gateway" {
  for_each = {
    for k in local.private_route_table_keys : k => k
    if k != "none" && var.create_vpc && contains(keys(var.nat_gateways), k)
  }

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.key].id
}

resource "aws_route" "private_ipv6_egress_only_gateway" {
  for_each = {
    for k in local.private_route_table_keys : k => k
    if var.create_vpc && var.create_egress_only_igw
  }

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  subnet_id = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[
    each.value.nat_gateway_key != null ? each.value.nat_gateway_key : "none"
  ].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [for k in sort(keys(var.public_subnets)) : aws_subnet.public[k].id]

  dynamic "ingress" {
    for_each = length(var.public_network_acl_ingress) > 0 ? var.public_network_acl_ingress : local.default_nacl_ingress
    content {
      rule_no         = ingress.value.rule_no
      action          = ingress.value.action
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      cidr_block      = ingress.value.cidr_block
      ipv6_cidr_block = ingress.value.ipv6_cidr_block
      icmp_type       = ingress.value.icmp_type
      icmp_code       = ingress.value.icmp_code
    }
  }

  dynamic "egress" {
    for_each = length(var.public_network_acl_egress) > 0 ? var.public_network_acl_egress : local.default_nacl_egress
    content {
      rule_no         = egress.value.rule_no
      action          = egress.value.action
      from_port       = egress.value.from_port
      to_port         = egress.value.to_port
      protocol        = egress.value.protocol
      cidr_block      = egress.value.cidr_block
      ipv6_cidr_block = egress.value.ipv6_cidr_block
      icmp_type       = egress.value.icmp_type
      icmp_code       = egress.value.icmp_code
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-public" })
}

resource "aws_network_acl" "private" {
  for_each = var.create_vpc ? var.private_network_acls : {}

  vpc_id = aws_vpc.this[0].id
  subnet_ids = [
    for sk, sv in var.private_subnets : aws_subnet.private[sk].id
    if sv.network_acl_key == each.key
  ]

  dynamic "ingress" {
    for_each = length(each.value.ingress) > 0 ? each.value.ingress : local.default_nacl_ingress
    content {
      rule_no         = ingress.value.rule_no
      action          = ingress.value.action
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      cidr_block      = ingress.value.cidr_block
      ipv6_cidr_block = ingress.value.ipv6_cidr_block
      icmp_type       = ingress.value.icmp_type
      icmp_code       = ingress.value.icmp_code
    }
  }

  dynamic "egress" {
    for_each = length(each.value.egress) > 0 ? each.value.egress : local.default_nacl_egress
    content {
      rule_no         = egress.value.rule_no
      action          = egress.value.action
      from_port       = egress.value.from_port
      to_port         = egress.value.to_port
      protocol        = egress.value.protocol
      cidr_block      = egress.value.cidr_block
      ipv6_cidr_block = egress.value.ipv6_cidr_block
      icmp_type       = egress.value.icmp_type
      icmp_code       = egress.value.icmp_code
    }
  }

  tags = merge(var.tags, each.value.tags, { Name = "${var.name}-private-${each.key}" })
}

###############################################################################
# DHCP options
###############################################################################

resource "aws_vpc_dhcp_options" "this" {
  count = var.create_vpc && var.create_dhcp_options ? 1 : 0

  domain_name          = var.dhcp_options.domain_name
  domain_name_servers  = var.dhcp_options.domain_name_servers
  ntp_servers          = var.dhcp_options.ntp_servers
  netbios_name_servers = var.dhcp_options.netbios_name_servers
  netbios_node_type    = var.dhcp_options.netbios_node_type

  tags = merge(var.tags, { Name = "${var.name}-dhcp" })
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.create_vpc && var.create_dhcp_options && var.create_dhcp_options_association ? 1 : 0

  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

###############################################################################
# Flow logs
###############################################################################

resource "aws_iam_role" "flow_log" {
  count = local.create_flow_log_cloudwatch_role ? 1 : 0

  name = "${var.name}-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "flow_log" {
  count = local.create_flow_log_cloudwatch_role ? 1 : 0

  name = "${var.name}-flow-log-policy"
  role = aws_iam_role.flow_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "flow_log" {
  for_each = var.create_vpc ? local.flow_logs_cloudwatch_log_group : {}

  name              = "/aws/vpc/flow-logs/${var.name}/${each.key}"
  retention_in_days = each.value.log_group_retention_days
  kms_key_id        = each.value.log_group_kms_key_id

  tags = merge(var.tags, each.value.tags)
}

resource "aws_s3_bucket" "flow_log" {
  count = local.create_flow_log_s3_bucket ? 1 : 0

  bucket = "${var.name}-flow-logs-${data.aws_caller_identity.current.account_id}"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "flow_log" {
  count = local.create_flow_log_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_log" {
  count = local.create_flow_log_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "flow_log" {
  count = local.create_flow_log_s3_bucket ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSLogDeliveryWrite"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.flow_log[0].arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid    = "AWSLogDeliveryAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.flow_log[0].arn
      },
    ]
  })
}

resource "aws_flow_log" "this" {
  for_each = var.create_vpc ? var.flow_logs : {}

  vpc_id                   = aws_vpc.this[0].id
  traffic_type             = each.value.traffic_type
  max_aggregation_interval = each.value.max_aggregation_interval
  log_destination_type     = each.value.destination_type
  log_destination          = local.flow_log_destinations[each.key]
  iam_role_arn = each.value.destination_type == "cloud-watch-logs" ? (
    each.value.iam_role_arn != null ? each.value.iam_role_arn : try(aws_iam_role.flow_log[0].arn, null)
  ) : null
  log_format = each.value.log_format

  tags = merge(var.tags, each.value.tags)
}

###############################################################################
# Default VPC resource governance
###############################################################################

resource "aws_default_security_group" "this" {
  count = var.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  dynamic "ingress" {
    for_each = var.default_security_group_ingress
    content {
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      protocol         = ingress.value.protocol
      cidr_blocks      = ingress.value.cidr_blocks
      ipv6_cidr_blocks = ingress.value.ipv6_cidr_blocks
      prefix_list_ids  = ingress.value.prefix_list_ids
      security_groups  = ingress.value.security_groups
      self             = ingress.value.self
      description      = ingress.value.description
    }
  }

  dynamic "egress" {
    for_each = var.default_security_group_egress
    content {
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      protocol         = egress.value.protocol
      cidr_blocks      = egress.value.cidr_blocks
      ipv6_cidr_blocks = egress.value.ipv6_cidr_blocks
      prefix_list_ids  = egress.value.prefix_list_ids
      security_groups  = egress.value.security_groups
      self             = egress.value.self
      description      = egress.value.description
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-default-sg" })
}

resource "aws_default_network_acl" "this" {
  count = var.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  dynamic "ingress" {
    for_each = var.default_network_acl_ingress
    content {
      rule_no         = ingress.value.rule_no
      action          = ingress.value.action
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      cidr_block      = ingress.value.cidr_block
      ipv6_cidr_block = ingress.value.ipv6_cidr_block
      icmp_type       = ingress.value.icmp_type
      icmp_code       = ingress.value.icmp_code
    }
  }

  dynamic "egress" {
    for_each = var.default_network_acl_egress
    content {
      rule_no         = egress.value.rule_no
      action          = egress.value.action
      from_port       = egress.value.from_port
      to_port         = egress.value.to_port
      protocol        = egress.value.protocol
      cidr_block      = egress.value.cidr_block
      ipv6_cidr_block = egress.value.ipv6_cidr_block
      icmp_type       = egress.value.icmp_type
      icmp_code       = egress.value.icmp_code
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-default" })
}

resource "aws_default_route_table" "this" {
  count = var.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id

  dynamic "route" {
    for_each = var.default_route_table_routes
    content {
      cidr_block                = route.value.cidr_block
      ipv6_cidr_block           = route.value.ipv6_cidr_block
      gateway_id                = route.value.gateway_id
      nat_gateway_id            = route.value.nat_gateway_id
      egress_only_gateway_id    = route.value.egress_only_gateway_id
      transit_gateway_id        = route.value.transit_gateway_id
      vpc_peering_connection_id = route.value.vpc_peering_connection_id
    }
  }

  tags = merge(var.tags, { Name = "${var.name}-default-rt" })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "vpc_ipv6_cidr_block" {
  description = "The IPv6 CIDR block associated with the VPC."
  value       = try(aws_vpc.this[0].ipv6_cidr_block, null)
}

output "igw_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "egress_only_igw_id" {
  description = "The ID of the egress-only Internet Gateway."
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}

output "public_subnet_ids" {
  description = "Map of public subnet key to subnet ID."
  value       = { for k, v in aws_subnet.public : k => v.id }
}

output "private_subnet_ids" {
  description = "Map of private subnet key to subnet ID."
  value       = { for k, v in aws_subnet.private : k => v.id }
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "Map of private route table key to route table ID."
  value       = { for k, v in aws_route_table.private : k => v.id }
}

output "nat_gateway_ids" {
  description = "Map of NAT gateway key to NAT gateway ID."
  value       = { for k, v in aws_nat_gateway.this : k => v.id }
}

output "public_network_acl_id" {
  description = "The ID of the public network ACL."
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_ids" {
  description = "Map of private network ACL key to network ACL ID."
  value       = { for k, v in aws_network_acl.private : k => v.id }
}

output "dhcp_options_id" {
  description = "The ID of the DHCP option set."
  value       = try(aws_vpc_dhcp_options.this[0].id, null)
}

output "flow_log_ids" {
  description = "Map of flow log key to flow log ID."
  value       = { for k, v in aws_flow_log.this : k => v.id }
}

###############################################################################
# AWS Transfer Family SFTP server solution
#
# Supports:
#   - PUBLIC / VPC / VPC_ENDPOINT endpoints
#   - Automated user provisioning (IAM role + policy + Transfer user + SSH keys)
#   - Optional Route 53 CNAME mapping
#   - Dynamic logging role bound to AWSTransferLoggingAccess
#   - API Gateway identity provider authorization role (CloudWatch logging)
#   - Optional FTPS certificates, login banner, security policy, host keys,
#     structured CloudWatch log destinations and protocol details
###############################################################################

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Explicit name for the Transfer server. When empty, a two-word hyphenated random pet name is generated."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Server endpoint type: PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of PUBLIC, VPC or VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled on the Transfer server."
  type        = list(string)
  default     = ["SFTP"]
}

variable "domain" {
  description = "Storage backend domain for the Transfer server: S3 or EFS."
  type        = string
  default     = "S3"
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY or AWS_DIRECTORY_SERVICE."
  type        = string
  default     = "SERVICE_MANAGED"
}

variable "logging_role_arn" {
  description = "Explicit IAM role ARN used for Transfer logging. When empty a role bound to AWSTransferLoggingAccess is created."
  type        = string
  default     = ""
}

variable "security_policy_name" {
  description = "Transfer security policy name."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate" {
  description = "ACM certificate ARN for FTPS."
  type        = string
  default     = ""
}

variable "host_key" {
  description = "SSH private key (PEM) used as host key."
  type        = string
  default     = ""
}

variable "custom_login_banner" {
  description = "Login banner shown to users after authentication."
  type        = string
  default     = ""
}

variable "pre_authentication_login_banner" {
  description = "Login banner shown to users before authentication."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Force destroy the Transfer server even when users exist."
  type        = bool
  default     = false
}

variable "structured_log_destinations" {
  description = "List of CloudWatch Log Group ARNs for structured logging."
  type        = list(string)
  default     = []
}

variable "endpoint_details" {
  description = "Endpoint details for VPC/VPC_ENDPOINT endpoints. Leave null to auto-provision networking."
  type = object({
    vpc_id                 = optional(string, "")
    subnet_ids             = optional(list(string), [])
    security_group_ids     = optional(list(string), [])
    address_allocation_ids = optional(list(string), [])
    vpc_endpoint_id        = optional(string, "")
  })
  default = null
}

variable "protocol_details" {
  description = "Optional protocol details (AS2, passive IP, set-stat option, TLS session resumption)."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = null
}

variable "identity_provider" {
  description = "API Gateway identity provider configuration."
  type = object({
    url             = optional(string, "")
    invocation_role = optional(string, "")
  })
  default = null
}

variable "route53_zone_name" {
  description = "Domain name of the Route 53 hosted zone to create for the SFTP CNAME. Empty disables DNS mapping."
  type        = string
  default     = ""
}

variable "route53_record_name" {
  description = "Sub-domain used for the CNAME record mapping to the Transfer endpoint."
  type        = string
  default     = "sftp"
}

variable "route53_ttl" {
  description = "TTL for the Route 53 CNAME record."
  type        = number
  default     = 300
}

variable "users" {
  description = "Map of SFTP users to provision."
  type = map(object({
    bucket              = string
    home_directory      = optional(string, "")
    home_directory_type = optional(string, "PATH")
    policy              = optional(string)
    tags                = optional(map(string), {})
  }))
  default = {}
}

variable "user_ssh_keys" {
  description = "Map of user name to list of SSH public keys."
  type        = map(list(string))
  default     = {}
}

variable "apigw_log_retention_days" {
  description = "Retention (days) for the API Gateway identity provider CloudWatch log group."
  type        = number
  default     = 30
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Server name: explicit variable, else two-word hyphenated random pet
###############################################################################

resource "random_pet" "this" {
  separator = "-"
  length    = 2
}

###############################################################################
# IAM trust policy shared by Transfer roles
###############################################################################

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "TransferAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  partition   = data.aws_partition.current.partition
  region      = data.aws_region.current.region
  server_name = var.name != "" ? var.name : random_pet.this.id

  endpoint_details = var.endpoint_details != null ? var.endpoint_details : {
    vpc_id                 = ""
    subnet_ids             = []
    security_group_ids     = []
    address_allocation_ids = []
    vpc_endpoint_id        = ""
  }

  subnet_ids = local.endpoint_details.subnet_ids

  # Auto-provision a security group when hosted in a VPC without supplied ones.
  create_network_sg = var.endpoint_type == "VPC" && length(local.endpoint_details.security_group_ids) == 0 && local.endpoint_details.vpc_id != ""

  # Auto-provision an Elastic IP per subnet when none are supplied.
  create_network_eip = var.endpoint_type == "VPC" && length(local.endpoint_details.address_allocation_ids) == 0 && length(local.subnet_ids) > 0

  effective_security_group_ids     = local.create_network_sg ? [aws_security_group.transfer[0].id] : local.endpoint_details.security_group_ids
  effective_address_allocation_ids = local.create_network_eip ? aws_eip.transfer[*].id : local.endpoint_details.address_allocation_ids

  # Logging role: explicit ARN wins, otherwise the dynamically created role.
  logging_role_arn = var.logging_role_arn != "" ? var.logging_role_arn : (length(aws_iam_role.transfer_logging) > 0 ? aws_iam_role.transfer_logging[0].arn : null)

  # API Gateway invocation role: explicit value wins, otherwise created role.
  invocation_role = try(var.identity_provider.invocation_role, "") != "" ? var.identity_provider.invocation_role : (var.identity_provider_type == "API_GATEWAY" ? aws_iam_role.apigw[0].arn : null)

  # S3 key prefix (bucket plus optional prefix) used to scope object permissions.
  user_object_prefix = {
    for k, v in var.users : k => trim(v.home_directory, "/") != "" ? "${v.bucket}/${trim(v.home_directory, "/")}" : v.bucket
  }

  # SFTP home directory (S3 path form) for each user.
  user_home_directory = {
    for k, v in var.users : k => trim(v.home_directory, "/") != "" ? "/${v.bucket}/${trim(v.home_directory, "/")}" : "/${v.bucket}"
  }

  # Distinct buckets referenced by users, created when enabled.
  user_buckets = toset([for u in values(var.users) : u.bucket])

  # Flattened SSH public keys for users that exist in the users map.
  user_ssh_key_pairs = {
    for pair in flatten([
      for user, keys in var.user_ssh_keys : [
        for idx, key in keys : {
          id   = "${user}-${idx}"
          user = user
          key  = key
        }
      ] if contains(keys(var.users), user)
    ]) : pair.id => pair
  }
}

###############################################################################
# Logging IAM role bound to AWSTransferLoggingAccess
###############################################################################

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  name_prefix        = "${local.server_name}-logging-"
  description        = "IAM role for AWS Transfer Family logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = length(aws_iam_role.transfer_logging)

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# API Gateway identity provider authorization role + logging
###############################################################################

resource "aws_iam_role" "apigw" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name_prefix        = "${local.server_name}-apigw-"
  description        = "IAM role for AWS Transfer API Gateway identity provider"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

resource "aws_cloudwatch_log_group" "apigw" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name              = "/aws/transfer/${local.server_name}/apigateway"
  retention_in_days = var.apigw_log_retention_days
  tags              = var.tags
}

resource "aws_iam_role_policy" "apigw" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0

  name = "${local.server_name}-apigw-logging"
  role = aws_iam_role.apigw[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.apigw[0].arn,
          "${aws_cloudwatch_log_group.apigw[0].arn}:*",
        ]
      },
    ]
  })
}

###############################################################################
# Auto-provisioned VPC networking (security group + Elastic IPs)
###############################################################################

resource "aws_security_group" "transfer" {
  count = local.create_network_sg ? 1 : 0

  name_prefix = "${local.server_name}-sftp-"
  description = "Security group for AWS Transfer Family SFTP server"
  vpc_id      = local.endpoint_details.vpc_id

  tags = merge(var.tags, { Name = "${local.server_name}-sftp" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "transfer_sftp" {
  count = local.create_network_sg ? 1 : 0

  security_group_id = aws_security_group.transfer[0].id
  description       = "SFTP access"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_eip" "transfer" {
  count = local.create_network_eip ? length(local.subnet_ids) : 0

  domain = "vpc"

  tags = merge(var.tags, { Name = "${local.server_name}-eip-${count.index}" })
}

###############################################################################
# Transfer server
###############################################################################

resource "aws_transfer_server" "this" {
  endpoint_type               = var.endpoint_type
  protocols                   = var.protocols
  domain                      = var.domain
  identity_provider_type      = var.identity_provider_type
  logging_role                = local.logging_role_arn
  security_policy_name        = var.security_policy_name
  certificate                 = var.certificate != "" ? var.certificate : null
  host_key                    = var.host_key != "" ? var.host_key : null
  post_authentication_login_banner = var.custom_login_banner != "" ? var.custom_login_banner : null
  pre_authentication_login_banner  = var.pre_authentication_login_banner != "" ? var.pre_authentication_login_banner : null
  force_destroy               = var.force_destroy
  url                         = try(var.identity_provider.url, "") != "" ? var.identity_provider.url : null
  invocation_role             = local.invocation_role
  structured_log_destinations = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null

  tags = merge(var.tags, { Name = local.server_name })

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [1]

    content {
      vpc_id                 = local.endpoint_details.vpc_id != "" ? local.endpoint_details.vpc_id : null
      subnet_ids             = length(local.subnet_ids) > 0 ? local.subnet_ids : null
      security_group_ids     = length(local.effective_security_group_ids) > 0 ? local.effective_security_group_ids : null
      address_allocation_ids = length(local.effective_address_allocation_ids) > 0 ? local.effective_address_allocation_ids : null
      vpc_endpoint_id        = local.endpoint_details.vpc_endpoint_id != "" ? local.endpoint_details.vpc_endpoint_id : null
    }
  }

  dynamic "protocol_details" {
    for_each = var.protocol_details != null ? [var.protocol_details] : []

    content {
      as2_transports              = protocol_details.value.as2_transports
      passive_ip                  = protocol_details.value.passive_ip
      set_stat_option             = protocol_details.value.set_stat_option
      tls_session_resumption_mode = protocol_details.value.tls_session_resumption_mode
    }
  }
}

###############################################################################
# Route 53 DNS mapping
###############################################################################

resource "aws_route53_zone" "this" {
  count = var.route53_zone_name != "" ? 1 : 0

  name = var.route53_zone_name
  tags = var.tags
}

resource "aws_route53_record" "transfer" {
  count = var.route53_zone_name != "" ? 1 : 0

  zone_id = aws_route53_zone.this[0].zone_id
  name    = "${var.route53_record_name}.${var.route53_zone_name}"
  type    = "CNAME"
  ttl     = var.route53_ttl
  records = [aws_transfer_server.this.endpoint]
}

###############################################################################
# Per-user S3 home directory buckets
###############################################################################

resource "aws_s3_bucket" "user" {
  for_each = local.user_buckets

  bucket        = each.value
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "user" {
  for_each = aws_s3_bucket.user

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "user" {
  for_each = aws_s3_bucket.user

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "user" {
  for_each = aws_s3_bucket.user

  bucket = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Per-user IAM roles and policies
###############################################################################

data "aws_iam_policy_document" "user" {
  for_each = var.users

  statement {
    sid     = "AllowListHomeBucket"
    effect  = "Allow"
    actions = ["s3:ListBucket", "s3:GetBucketLocation"]

    resources = [
      "arn:${local.partition}:s3:::${each.value.bucket}",
    ]
  }

  statement {
    sid     = "AllowObjectAccessInHomeDirectory"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:GetObjectVersion", "s3:PutObject", "s3:DeleteObject", "s3:DeleteObjectVersion"]

    resources = [
      "arn:${local.partition}:s3:::${local.user_object_prefix[each.key]}/*",
    ]
  }
}

resource "aws_iam_role" "user" {
  for_each = var.users

  name_prefix        = "${local.server_name}-${each.key}-"
  description        = "IAM role for Transfer user ${each.key}"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = merge(var.tags, each.value.tags)
}

resource "aws_iam_role_policy" "user" {
  for_each = var.users

  name   = "${local.server_name}-${each.key}-s3-home"
  role   = aws_iam_role.user[each.key].id
  policy = data.aws_iam_policy_document.user[each.key].json
}

###############################################################################
# Transfer users
###############################################################################

resource "aws_transfer_user" "this" {
  for_each = var.users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.user[each.key].arn
  home_directory      = aws_transfer_server.this.domain == "S3" ? local.user_home_directory[each.key] : each.value.home_directory
  home_directory_type = each.value.home_directory_type
  policy              = each.value.policy
  tags                = merge(var.tags, each.value.tags)
}

###############################################################################
# SSH public keys associated with each Transfer user
###############################################################################

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_ssh_key_pairs

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.value.user].user_name
  body      = each.value.key
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  cluster_name = "md-k8s"
  vpc_cidr     = "192.168.0.0/16"

  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
  public_subnets  = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
  private_subnets = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]

  common_tags = {
    Project = "md-k8s"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                                          = "${local.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb"                      = "1"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  })
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                                          = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb"             = "1"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
  })
}

###############################################################################
# Internet gateway + public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public"
  })
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway + shared private routing
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private"
  })
}

resource "aws_route_table_association" "private" {
  count = length(local.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Database subnet group
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "md-k8s-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "md-k8s-private-subnet-group"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# EKS cluster IAM role
###############################################################################

resource "aws_iam_role" "cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-cluster-role"
  })
}

resource "aws_iam_role_policy_attachment" "cluster_managed" {
  for_each = toset([
    "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy",
    "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController",
  ])

  role       = aws_iam_role.cluster.name
  policy_arn = each.value
}

# Small custom policy: describe EC2 networking resources.
resource "aws_iam_role_policy" "cluster_ec2_describe" {
  name = "${local.cluster_name}-ec2-describe"
  role = aws_iam_role.cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeEC2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeRouteTables",
          "ec2:DescribeVpcs",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeAvailabilityZones",
        ]
        Resource = "*"
      }
    ]
  })
}

# Small custom policy: publish CloudWatch metrics.
resource "aws_iam_role_policy" "cluster_cloudwatch" {
  name = "${local.cluster_name}-cloudwatch"
  role = aws_iam_role.cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# KMS key for envelope encryption of Kubernetes secrets
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "EKS secrets envelope encryption key for ${local.cluster_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEKSClusterUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.cluster.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant",
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-eks"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Security groups
###############################################################################

# Control plane security group.
resource "aws_security_group" "cluster" {
  name        = "${local.cluster_name}-cluster"
  description = "EKS control plane security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-cluster"
  })
}

# Shared node security group.
resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node"
  description = "EKS shared node security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name                                          = "${local.cluster_name}-node"
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
  })
}

# Allow nodes to communicate with each other.
resource "aws_security_group_rule" "node_ingress_self" {
  description       = "Allow nodes to communicate with each other"
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node.id
}

# Allow the cluster's control plane security group to reach nodes.
resource "aws_security_group_rule" "node_ingress_cluster" {
  description              = "Allow the control plane security group to communicate with nodes"
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster.id
  security_group_id        = aws_security_group.node.id
}

###############################################################################
# EKS cluster (control plane only)
###############################################################################

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.30"

  enabled_cluster_log_types = [
    "api",
    "audit",
    "authenticator",
    "controllerManager",
    "scheduler",
  ]

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    endpoint_private_access = true
    endpoint_public_access  = false
    security_group_ids      = [aws_security_group.cluster.id]
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.cluster_managed,
    aws_iam_role_policy.cluster_ec2_describe,
    aws_iam_role_policy.cluster_cloudwatch,
  ]
}

###############################################################################
# Highly configurable, general-purpose S3 bucket
#
# This template creates a single general-purpose S3 bucket plus all of its
# optional, input-driven features. Naming and tagging are handled by a
# dedicated label module so every resource shares a consistent identifier and
# tag set. Public access is ALWAYS blocked and the bucket is versioned and
# encrypted by default.
###############################################################################

###############################################################################
# Label module (consistent naming + tagging)
###############################################################################

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled     = var.enabled
  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  label_order = var.label_order
  tags        = var.tags
}

###############################################################################
# Local derived values
###############################################################################

data "aws_caller_identity" "current" {}
data "aws_canonical_user_id" "current" {}

# S3 bucket names are globally unique; a short random suffix guarantees the
# label-derived name is available in the shared S3 namespace.
resource "random_id" "this" {
  byte_length = 4
}

locals {
  name_suffix = random_id.this.hex
  bucket_name = lower("${module.label.id}-${local.name_suffix}")
  # Only create a customer managed key when KMS is requested and no key is given.
  create_kms_key = var.enabled && var.kms_enabled && var.kms_key_id == ""
  use_kms        = var.enabled && (var.kms_enabled || var.kms_key_id != "")

  # KMS master key: user supplied id/alias/arn, or the key we create, or null.
  kms_key_arn = local.use_kms ? (var.kms_key_id != "" ? var.kms_key_id : one(aws_kms_key.this[*].arn)) : null

  sse_algorithm = local.use_kms ? "aws:kms" : "AES256"

  # ACL handling
  create_acl = var.enabled && (var.acl != "" || length(var.grants) > 0)
  object_ownership = var.object_ownership != "" ? var.object_ownership : (
    local.create_acl ? "ObjectWriter" : "BucketOwnerEnforced"
  )

  # Object lock requires versioning to be enabled.
  versioning_status = (var.versioning_enabled || var.object_lock_enabled) ? "Enabled" : "Suspended"

  # Access log bucket name
  log_bucket_name = lower("${module.label.id}-logs-${local.name_suffix}")

  common_tags = module.label.tags
}

###############################################################################
# KMS key (customer managed, automatic rotation)
###############################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed KMS key for ${module.label.id} S3 bucket encryption"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# Primary S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  count = var.enabled ? 1 : 0

  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status = local.versioning_status
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = local.use_kms
  }
}

###############################################################################
# Optional ACL (canned ACL and / or fine-grained grants)
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = (var.acl != "" && length(var.grants) == 0) ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      dynamic "grant" {
        for_each = var.grants
        content {
          permission = grant.value.permission

          grantee {
            id   = try(grant.value.id, null)
            type = grant.value.type
            uri  = try(grant.value.uri, null)
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Optional lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.enabled && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = try(rule.value.status, "Enabled")

      filter {
        prefix = try(rule.value.prefix, "")
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration_days, null) != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition_days, null) != null ? [rule.value.noncurrent_version_transition_days] : []
        content {
          noncurrent_days = noncurrent_version_transition.value
          storage_class   = try(rule.value.noncurrent_version_transition_storage_class, "GLACIER")
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration_days, null) != null ? [rule.value.noncurrent_version_expiration_days] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Optional static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.enabled && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.website.index_document
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  routing_rules = try(var.website.routing_rules, null)
}

###############################################################################
# Optional CORS configuration
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.enabled && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Optional object lock configuration with default retention
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.enabled && var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Optional acceleration status
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.enabled && var.acceleration_status != "" ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

###############################################################################
# Optional requester pays
###############################################################################

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.enabled && var.requester_pays ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = "Requester"
}

###############################################################################
# Optional bucket policy (composed from an IAM policy document)
###############################################################################

data "aws_iam_policy_document" "this" {
  count = var.enabled && length(var.bucket_policy_statements) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = var.bucket_policy_statements
    content {
      sid           = try(statement.value.sid, null)
      effect        = try(statement.value.effect, "Allow")
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.enabled && length(var.bucket_policy_statements) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.this[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Optional access logging (dedicated target bucket)
###############################################################################

resource "aws_s3_bucket" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket        = local.log_bucket_name
  force_destroy = var.force_destroy

  tags = merge(local.common_tags, {
    Name = local.log_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  versioning_configuration {
    status = "Enabled"
  }

  depends_on = [aws_s3_bucket_ownership_controls.log]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  statement {
    sid     = "S3ServerAccessLogDelivery"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.log[0].arn}/${var.logging_target_prefix}*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "log" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.log[0].id
  policy = data.aws_iam_policy_document.log[0].json

  depends_on = [aws_s3_bucket_public_access_block.log]
}

resource "aws_s3_bucket_logging" "this" {
  count = var.enabled && var.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = aws_s3_bucket.log[0].id
  target_prefix = var.logging_target_prefix
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The ID (name) of the S3 bucket."
  value       = var.enabled ? aws_s3_bucket.this[0].id : null
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = var.enabled ? aws_s3_bucket.this[0].arn : null
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = var.enabled ? aws_s3_bucket.this[0].bucket_domain_name : null
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = var.enabled ? aws_s3_bucket.this[0].bucket_regional_domain_name : null
}

output "bucket_tags" {
  description = "The tags applied to the S3 bucket."
  value       = local.common_tags
}

###############################################################################
# Variables
###############################################################################

variable "enabled" {
  description = "Set to false to prevent the module from creating any resources."
  type        = bool
  default     = true
}

variable "namespace" {
  description = "Namespace (e.g. an organization or team abbreviation)."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment (e.g. 'ue1', 'us-east-1')."
  type        = string
  default     = ""
}

variable "stage" {
  description = "Stage (e.g. 'prod', 'staging', 'dev')."
  type        = string
  default     = ""
}

variable "name" {
  description = "The name of the bucket as it appears in the label id."
  type        = string
  default     = "s3-bucket"
}

variable "attributes" {
  description = "Additional attributes to add to the label id."
  type        = list(string)
  default     = []
}

variable "delimiter" {
  description = "Delimiter to be used between label parts."
  type        = string
  default     = "-"
}

variable "label_order" {
  description = "The order in which to apply the label parts."
  type        = list(string)
  default     = ["namespace", "environment", "stage", "name", "attributes"]
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Whether to delete the bucket even when it contains objects (moot while prevent_destroy is set)."
  type        = bool
  default     = false
}

###############################################################################
# Encryption
###############################################################################

variable "kms_enabled" {
  description = "Enable SSE-KMS. When no kms_key_id is supplied a customer managed key with automatic rotation is created."
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "Existing KMS key id/alias/ARN to use. When set it takes precedence over the created key."
  type        = string
  default     = ""
}

variable "kms_deletion_window_in_days" {
  description = "KMS key deletion window in days (7-30)."
  type        = number
  default     = 7
}

###############################################################################
# Versioning / object lock
###############################################################################

variable "versioning_enabled" {
  description = "Enable versioning on the bucket."
  type        = bool
  default     = true
}

variable "object_lock_enabled" {
  description = "Enable S3 object lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode for object lock (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Default retention period in days for object lock."
  type        = number
  default     = 30
}

###############################################################################
# Ownership / ACL
###############################################################################

variable "object_ownership" {
  description = "Object ownership setting. Empty string auto-selects BucketOwnerEnforced, or ObjectWriter when ACLs are used."
  type        = string
  default     = ""
}

variable "acl" {
  description = "Canned ACL to apply to the bucket (e.g. 'private', 'log-delivery-write')."
  type        = string
  default     = ""
}

variable "grants" {
  description = "Fine-grained ACL grants. Each item: { permission, type, id, uri, email }."
  type        = list(any)
  default     = []
}

###############################################################################
# Lifecycle
###############################################################################

variable "lifecycle_rules" {
  description = "List of lifecycle rules. Supports transitions (STANDARD_IA/GLACIER/DEEP_ARCHIVE), expiration and noncurrent version handling."
  type        = list(any)
  default = [
    {
      id                             = "default"
      status                         = "Enabled"
      prefix                         = ""
      transitions = [
        { days = 30, storage_class = "STANDARD_IA" },
        { days = 90, storage_class = "GLACIER" },
        { days = 180, storage_class = "DEEP_ARCHIVE" }
      ]
      expiration_days                           = 365
      noncurrent_version_transition_days        = 30
      noncurrent_version_transition_storage_class = "GLACIER"
      noncurrent_version_expiration_days        = 90
      abort_incomplete_multipart_upload_days    = 7
    }
  ]
}

###############################################################################
# Website
###############################################################################

variable "website" {
  description = "Static website hosting configuration: { index_document, error_document, routing_rules }. Null disables website hosting."
  type        = any
  default     = null
}

###############################################################################
# CORS
###############################################################################

variable "cors_rules" {
  description = "List of CORS rules: { allowed_methods, allowed_origins, allowed_headers, expose_headers, max_age_seconds }."
  type        = list(any)
  default     = []
}

###############################################################################
# Networking / billing
###############################################################################

variable "acceleration_status" {
  description = "Transfer acceleration status: 'Enabled' or 'Suspended'. Empty string disables the configuration."
  type        = string
  default     = ""
}

variable "requester_pays" {
  description = "Enable requester pays on the bucket."
  type        = bool
  default     = false
}

###############################################################################
# Bucket policy
###############################################################################

variable "bucket_policy_statements" {
  description = "List of IAM policy statements composed into a bucket policy. Each item may set sid, effect, actions, not_actions, resources, not_resources, principals, conditions."
  type        = list(any)
  default     = []
}

###############################################################################
# Access logging
###############################################################################

variable "logging_enabled" {
  description = "Enable server access logging to a dedicated target bucket created by this template."
  type        = bool
  default     = false
}

variable "logging_target_prefix" {
  description = "Prefix (key path) within the target bucket for access log objects."
  type        = string
  default     = "logs/"
}

###############################################################################
# Variables
###############################################################################

variable "vpc_name" {
  description = "Name to assign to the VPC and its associated resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/18"
}

variable "aws_region" {
  description = "AWS region used for tagging and availability zone discovery."
  type        = string
  default     = "us-east-1"
}

variable "num_availability_zones" {
  description = "Number of availability zones to use. Set to 0 to use all available AZs in the region."
  type        = number
  default     = 0
}

variable "enable_public_subnets" {
  description = "Toggle creation of public subnets."
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Toggle creation of private subnets."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Toggle creation of the NAT gateway (requires public subnets)."
  type        = bool
  default     = true
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Name        = var.vpc_name
    Region      = var.aws_region
    ManagedBy   = "terraform"
  }

  num_azs = var.num_availability_zones > 0 ? var.num_availability_zones : length(data.aws_availability_zones.available.names)

  azs = slice(data.aws_availability_zones.available.names, 0, local.num_azs)

  create_public  = var.enable_public_subnets
  create_private = var.enable_private_subnets
  # A NAT gateway requires at least one public subnet to live in.
  create_nat = var.enable_nat_gateway && local.create_public

  public_subnet_count  = local.create_public ? local.num_azs : 0
  private_subnet_count = local.create_private ? local.num_azs : 0
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Public Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${count.index + 1}"
    Tier = "public"
  })
}

###############################################################################
# Private Subnets
###############################################################################

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + local.num_azs)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${count.index + 1}"
    Tier = "private"
  })
}

###############################################################################
# NAT Gateway
###############################################################################

resource "aws_eip" "nat" {
  count = local.create_nat ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Public Route Table
###############################################################################

resource "aws_route_table" "public" {
  count = local.create_public ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Private Route Table
###############################################################################

resource "aws_route_table" "private" {
  count = local.create_private ? 1 : 0

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = local.create_nat ? [1] : []

    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  count = local.create_public ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl" "private" {
  count = local.create_private ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway, if created."
  value       = local.create_nat ? aws_nat_gateway.main[0].id : null
}

###########################################################################
# Multi-tier, dual-stack (IPv4/IPv6) AWS network architecture
#
# Creates:
#   * A VPC ("main-vpc", 10.16.0.0/16, Amazon-provided IPv6, DNS enabled)
#   * IPv4 (/20) and IPv6 (/64) subnets calculated with the
#     hashicorp/subnets/cidr module (v1.0.0)
#   * An Internet Gateway ("main-igw-vpc-<vpc-id>")
#   * A public route table ("public-rt-web") with IPv4 + IPv6 default routes
#   * Tiered security groups (web_sg / app_sg / db_sg)
###########################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###########################################################################
# Variables
###########################################################################

variable "is_ipv6_enabled" {
  description = "Enable dual-stack (IPv4/IPv6) and assign an Amazon-provided IPv6 CIDR block to the VPC."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC."
  type        = string
  default     = "main-vpc"
}

variable "ipv4_new_bits" {
  description = "Additional bits used to carve IPv4 subnets (/16 base + 4 = /20 subnets)."
  type        = number
  default     = 4
}

variable "ipv6_new_bits" {
  description = "Additional bits used to carve IPv6 subnets (/56 base + 8 = /64 subnets)."
  type        = number
  default     = 8
}

variable "sn_details" {
  description = <<-EOT
    Optional override for the subnet definitions. Each object describes a
    subnet name, its target availability zone and whether it is public.
    When left empty (the default) a 12-subnet layout across three
    availability zones is generated automatically for the web (public),
    app (private), database (private) and reserved (private) tiers.
  EOT
  type = list(object({
    name   = string
    az     = string
    public = bool
  }))
  default = []
}

###########################################################################
# Availability zones (static provider metadata - never hardcoded)
###########################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###########################################################################
# Locals - resolve the subnet (sn_details) layout
###########################################################################

locals {
  az_count = min(3, length(data.aws_availability_zones.available.names))
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  tier_definitions = [
    { name = "web", public = true },
    { name = "app", public = false },
    { name = "database", public = false },
    { name = "reserved", public = false },
  ]

  # 4 tiers x 3 availability zones = 12 subnets by default.
  generated_sn_details = flatten([
    for tier in local.tier_definitions : [
      for idx, az in local.azs : {
        name   = "${tier.name}-${idx + 1}"
        az     = az
        public = tier.public
      }
    ]
  ])

  sn_details = length(var.sn_details) > 0 ? var.sn_details : local.generated_sn_details

  # Fallback base for the IPv6 calculator when dual-stack is disabled; the
  # resulting IPv6 subnets are discarded in that case (see aws_subnet below).
  ipv6_base_cidr = var.is_ipv6_enabled ? aws_vpc.main.ipv6_cidr_block : "2001:db8::/56"
}

###########################################################################
# VPC
###########################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = var.vpc_name
  }
}

###########################################################################
# Subnet CIDR calculation (hashicorp/subnets/cidr v1.0.0)
###########################################################################

module "vpc_ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.vpc_cidr

  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = var.ipv4_new_bits
    }
  ]
}

module "vpc_ipv6_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = local.ipv6_base_cidr

  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = var.ipv6_new_bits
    }
  ]
}

###########################################################################
# Subnets
###########################################################################

resource "aws_subnet" "main" {
  for_each = { for s in local.sn_details : s.name => s }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az
  cidr_block        = module.vpc_ipv4_subnets.network_cidr_blocks[each.key]

  ipv6_cidr_block                 = var.is_ipv6_enabled ? module.vpc_ipv6_subnets.network_cidr_blocks[each.key] : null
  assign_ipv6_address_on_creation = var.is_ipv6_enabled

  tags = {
    Name   = "sn-${each.value.name}"
    Tier   = each.value.name
    Public = tostring(each.value.public)
  }
}

###########################################################################
# Internet Gateway
###########################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

###########################################################################
# Public route table + default routes (IPv4 and IPv6)
###########################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = { for s in local.sn_details : s.name => s if s.public }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

###########################################################################
# Tier security groups
###########################################################################

resource "aws_security_group" "web" {
  name        = "web_sg"
  description = "Web tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app" {
  name        = "app_sg"
  description = "Application tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db" {
  name        = "db_sg"
  description = "Database tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

###########################################################################
# Security group rules
###########################################################################

# web_sg: inbound TLS from the internet
resource "aws_vpc_security_group_ingress_rule" "web_https" {
  security_group_id = aws_security_group.web.id
  description       = "Allow HTTPS (TLS) from the internet"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

# web_sg: inbound SSH restricted to the VPC IPv4 CIDR block
resource "aws_vpc_security_group_ingress_rule" "web_ssh" {
  security_group_id = aws_security_group.web.id
  description       = "Allow SSH only from within the VPC"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

# web_sg: outbound TLS to the application tier
resource "aws_vpc_security_group_egress_rule" "web_to_app" {
  security_group_id            = aws_security_group.web.id
  description                  = "Allow TLS to the app tier"
  referenced_security_group_id = aws_security_group.app.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# app_sg: inbound TLS only from the web tier
resource "aws_vpc_security_group_ingress_rule" "app_from_web" {
  security_group_id            = aws_security_group.app.id
  description                  = "Allow TLS from the web tier"
  referenced_security_group_id = aws_security_group.web.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# app_sg: outbound TLS to the database tier
resource "aws_vpc_security_group_egress_rule" "app_to_db" {
  security_group_id            = aws_security_group.app.id
  description                  = "Allow TLS to the database tier"
  referenced_security_group_id = aws_security_group.db.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# db_sg: inbound TLS only from the application tier
resource "aws_vpc_security_group_ingress_rule" "db_from_app" {
  security_group_id            = aws_security_group.db.id
  description                  = "Allow TLS from the application tier"
  referenced_security_group_id = aws_security_group.app.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "0.11.1"
    }
  }
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Randomized two-word pet name used as the Lambda execution role prefix
###############################################################################

resource "random_pet" "canary_prefix" {
  length    = 2
  separator = "-"
}

# Unique suffix so globally/account unique names (S3 bucket, KMS alias) never
# collide when the same template is applied repeatedly in one account.
resource "random_id" "suffix" {
  byte_length = 4
}

###############################################################################
# Variables
###############################################################################

variable "s3_bucket_name" {
  description = "Name of the S3 bucket used to store canary artifacts."
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "enable_s3_versioning" {
  description = "Whether versioning is enabled on the canary artifact bucket."
  type        = bool
  default     = false
}

variable "enable_kms_key" {
  description = "Whether to create and use the customer managed KMS key."
  type        = bool
  default     = true
}

variable "kms_deletion_window_in_days" {
  description = "The waiting period, in days, before the KMS key is deleted."
  type        = number
  default     = 10
}

variable "kms_alias_name" {
  description = "Alias name for the customer managed KMS key."
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic used to publish canary alerts."
  type        = string
  default     = "benchmark-canary-topic"
}

variable "notification_email" {
  description = "Email address that receives canary failure notifications."
  type        = string
  default     = "nobody@example.com"
}

variable "canary_schedule_expression" {
  description = "Default schedule expression applied to canaries."
  type        = string
  default     = "rate(5 minutes)"
}

variable "canary_timeout_in_seconds" {
  description = "The maximum amount of time the canary can run, in seconds."
  type        = number
  default     = 120
}

variable "canary_handler" {
  description = "Entry point of the canary script."
  type        = string
  default     = "index.handler"
}

variable "canary_runtime_version" {
  description = "Runtime version of the canary script."
  type        = string
  default     = "syn-nodejs-puppeteer-9.0"
}

variable "enable_success_percent_alarm" {
  description = "Whether to create the optional success percent metric alarm."
  type        = bool
  default     = false
}

variable "success_percent_threshold" {
  description = "Success percent threshold (percentage) for the success alarm."
  type        = number
  default     = 90
}

variable "vpc_cidr_block" {
  description = "CIDR block assigned to the VPC hosting the canaries."
  type        = string
  default     = "10.20.0.0/16"
}

variable "vpc_canaries" {
  description = "Map of CloudWatch Synthetics canary configurations to deploy inside the VPC."
  type = map(object({
    schedule_expression = optional(string, "rate(5 minutes)")
    subnet_ids          = optional(list(string), [])
    security_group_ids  = optional(list(string), [])
    zip_file            = optional(string)
    s3_bucket           = optional(string)
    s3_key              = optional(string)
    s3_version          = optional(string)
  }))
  default = {}
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      Project   = "benchmark-canary-monitoring"
      ManagedBy = "terraform"
    },
    var.tags,
  )

  # Returns the KMS key ARN when the key is enabled, otherwise null.
  kms_key_arn = one(aws_kms_key.canary[*].arn)

  # Final resource names: keep the requested base names, but append a unique
  # suffix so repeated applies in the same account/region do not collide.
  artifact_bucket_name = "${var.s3_bucket_name}-${random_id.suffix.hex}"
  kms_alias_full_name   = "${var.kms_alias_name}-${random_id.suffix.hex}"

  # Default canary configuration that uses the locally generated zip artifact.
  default_canary = {
    "benchmark-canary" = {
      schedule_expression = var.canary_schedule_expression
      subnet_ids          = aws_subnet.canary[*].id
      security_group_ids  = [aws_security_group.canary.id]
      zip_file            = data.archive_file.canary.output_path
      s3_bucket           = null
      s3_key              = null
      s3_version          = null
    }
  }

  # Iterate over the caller supplied map, falling back to a working default.
  vpc_canaries = length(var.vpc_canaries) > 0 ? var.vpc_canaries : local.default_canary
}

###############################################################################
# VPC networking for the in-VPC canaries
###############################################################################

resource "aws_vpc" "canary" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "benchmark-canary-vpc" })
}

resource "aws_subnet" "canary" {
  count             = 2
  vpc_id            = aws_vpc.canary.id
  cidr_block        = cidrsubnet(aws_vpc.canary.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "benchmark-canary-subnet-${count.index}" })
}

resource "aws_security_group" "canary" {
  name_prefix = "benchmark-canary-"
  description = "Security group for CloudWatch Synthetics canaries running inside the VPC."
  vpc_id      = aws_vpc.canary.id

  egress {
    description = "Allow outbound HTTPS traffic within the VPC for canary health checks."
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.canary.cidr_block]
  }

  egress {
    description = "Allow outbound DNS resolution within the VPC for canary health checks."
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = [aws_vpc.canary.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "benchmark-canary-sg" })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# KMS key used to encrypt canary artifacts and the SNS topic
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "canary" {
  count = var.enable_kms_key ? 1 : 0

  description             = "Customer managed key protecting canary artifacts and alerting."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "canary" {
  count = var.enable_kms_key ? 1 : 0

  name          = local.kms_alias_full_name
  target_key_id = aws_kms_key.canary[0].key_id
}

###############################################################################
# S3 bucket storing canary artifacts
###############################################################################

resource "aws_s3_bucket" "canary" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "canary" {
  bucket = aws_s3_bucket.canary.id

  versioning_configuration {
    status = var.enable_s3_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary" {
  bucket = aws_s3_bucket.canary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_key ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = var.enable_kms_key
  }
}

###############################################################################
# IAM execution role for the canaries
###############################################################################

resource "aws_iam_role" "canary" {
  name_prefix = "${random_pet.canary_prefix.id}-canary-"
  description = "Execution role assumed by CloudWatch Synthetics canaries."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })

  tags = local.common_tags
}

data "aws_iam_policy_document" "canary" {
  statement {
    sid    = "CanaryArtifactObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.canary.arn}/*"]
  }

  statement {
    sid    = "CanaryArtifactBucketListing"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.canary.arn]
  }

  statement {
    sid    = "CloudWatchMetricsWrite"
    effect = "Allow"

    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsWrite"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:*:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/*",
    ]
  }

  statement {
    sid    = "NetworkInterfaceManagement"
    effect = "Allow"

    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:AssignPrivateIpAddresses",
      "ec2:UnassignPrivateIpAddresses",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
    ]

    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.enable_kms_key ? [1] : []

    content {
      sid    = "KMSAccessForArtifacts"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey",
      ]

      resources = [local.kms_key_arn]
    }
  }
}

resource "aws_iam_role_policy" "canary" {
  name   = "canary-permissions"
  role   = aws_iam_role.canary.id
  policy = data.aws_iam_policy_document.canary.json
}

# Managed policy granting the ENI + log permissions required for Lambda-backed
# canaries that run inside a VPC.
resource "aws_iam_role_policy_attachment" "canary_vpc_access" {
  role       = aws_iam_role.canary.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

# Allow newly created IAM policies to propagate before the canary (and its
# Lambda execution role) is used inside the VPC.
resource "time_sleep" "iam_propagation" {
  create_duration = "30s"

  depends_on = [
    aws_iam_role_policy.canary,
    aws_iam_role_policy_attachment.canary_vpc_access,
  ]
}

###############################################################################
# SNS topic + email subscription for failure notifications
###############################################################################

resource "aws_sns_topic" "canary" {
  name              = var.sns_topic_name
  kms_master_key_id = local.kms_key_arn

  tags = local.common_tags
}

resource "aws_sns_topic_subscription" "email" {
  topic_arn = aws_sns_topic.canary.arn
  protocol  = "email"
  endpoint  = var.notification_email
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.canary.arn]
  }

  statement {
    sid    = "AllowOwnerAccountManagement"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
    ]

    resources = [aws_sns_topic.canary.arn]
  }
}

resource "aws_sns_topic_policy" "canary" {
  arn    = aws_sns_topic.canary.arn
  policy = data.aws_iam_policy_document.sns.json
}

###############################################################################
# Inline canary script packaged as a zip artifact
###############################################################################

data "archive_file" "canary" {
  type        = "zip"
  output_path = "${path.module}/canary.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      const synthetics = require('Synthetics');
      const log = require('SyntheticsLogger');

      const healthCheck = async function () {
        const url = 'https://example.com';
        const page = await synthetics.getPage();
        const response = await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
        if (!response || response.status() > 399) {
          throw new Error('Health check failed for ' + url);
        }
        await page.screenshot({ path: '/tmp/canary-screenshot.png' });
        log.info('Health check passed for ' + url);
      };

      exports.handler = async () => {
        return await healthCheck();
      };
    EOT
  }
}

###############################################################################
# CloudWatch Synthetics canaries (iterate over the VPC canary map)
###############################################################################

resource "aws_synthetics_canary" "this" {
  for_each = local.vpc_canaries

  name                 = "${each.key}-${random_id.suffix.hex}"
  artifact_s3_location = "s3://${aws_s3_bucket.canary.bucket}/canary/${each.key}"
  execution_role_arn   = aws_iam_role.canary.arn
  handler              = var.canary_handler
  runtime_version      = var.canary_runtime_version
  start_canary         = true

  zip_file   = each.value.zip_file
  s3_bucket  = each.value.s3_bucket
  s3_key     = each.value.s3_key
  s3_version = each.value.s3_version

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = var.canary_timeout_in_seconds
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  tags = local.common_tags

  depends_on = [time_sleep.iam_propagation]
}

###############################################################################
# Alarms
###############################################################################

resource "aws_cloudwatch_metric_alarm" "canary_failed" {
  for_each = local.vpc_canaries

  alarm_name          = "${each.key}-failed-${random_id.suffix.hex}"
  alarm_description   = "Triggers when the ${each.key} canary reports one or more failures."
  namespace           = "CloudWatchSynthetics"
  metric_name         = "Failed"
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  threshold           = 1
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.canary.arn]
  ok_actions          = [aws_sns_topic.canary.arn]

  dimensions = {
    CanaryName = aws_synthetics_canary.this[each.key].name
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "canary_success_percent" {
  for_each = var.enable_success_percent_alarm ? local.vpc_canaries : {}

  alarm_name          = "${each.key}-success-percent-${random_id.suffix.hex}"
  alarm_description   = "Triggers when the ${each.key} canary success rate falls below ${var.success_percent_threshold} percent."
  namespace           = "CloudWatchSynthetics"
  metric_name         = "SuccessPercent"
  statistic           = "Average"
  period              = 60
  evaluation_periods  = 1
  comparison_operator = "LessThanThreshold"
  threshold           = var.success_percent_threshold
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.canary.arn]
  ok_actions          = [aws_sns_topic.canary.arn]

  dimensions = {
    CanaryName = aws_synthetics_canary.this[each.key].name
  }

  tags = local.common_tags
}

###############################################################################
# Outputs
###############################################################################

output "canary_names" {
  description = "Names of the deployed CloudWatch Synthetics canaries."
  value       = [for canary in aws_synthetics_canary.this : canary.name]
}

output "canary_artifact_bucket" {
  description = "Name of the S3 bucket storing canary artifacts."
  value       = aws_s3_bucket.canary.bucket
}

output "canary_execution_role_arn" {
  description = "ARN of the canary execution IAM role."
  value       = aws_iam_role.canary.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic receiving canary alerts."
  value       = aws_sns_topic.canary.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key, when enabled."
  value       = local.kms_key_arn
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Controls if the VPC and all associated resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name to be used as a prefix for all resources created by this module."
  type        = string
  default     = "vpc"
}

variable "cidr_block" {
  description = "The IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "A boolean flag to enable/disable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "A boolean flag to enable/disable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "azs" {
  description = "A list of availability zone names or IDs to spread the subnets across. When empty, the available AZs for the current region are used."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "A list of CIDR blocks for the public subnets."
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "A list of CIDR blocks for the private subnets."
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "A list of CIDR blocks for the isolated intra (private-only) subnets."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix to append to public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix to append to private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix to append to intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit list of public subnet Name tags. When supplied, auto-generated names are not used."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit list of private subnet Name tags. When supplied, auto-generated names are not used."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit list of intra subnet Name tags. When supplied, auto-generated names are not used."
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "A boolean flag to auto-assign public IP addresses on instance launch in public subnets."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be created and attached to the public route table."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways (and their Elastic IPs) should be created for the private subnets."
  type        = bool
  default     = false
}

variable "nat_gateway_destination_cidr_block" {
  description = "Destination CIDR block used for the private subnet NAT gateway routes."
  type        = string
  default     = "0.0.0.0/0"
}

variable "tags" {
  description = "A map of additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

################################################################################
# Data Sources
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Locals
################################################################################

locals {
  # Use the caller supplied AZs when present, otherwise fall back to the AZs
  # advertised by the provider for the current region.
  azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  # NAT gateways may only be created when the VPC, the toggle, a public tier and
  # a private tier are all present.
  create_nat = (
    var.create_vpc
    && var.enable_nat_gateway
    && length(var.public_subnets) > 0
    && length(var.private_subnets) > 0
  )

  # NAT gateways (and Elastic IPs) are created up to the smaller of the public
  # or private subnet counts.
  nat_gateway_count = local.create_nat ? min(length(var.public_subnets), length(var.private_subnets)) : 0
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.cidr_block
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(var.tags, { Name = var.name })
}

################################################################################
# Public Tier
################################################################################

resource "aws_subnet" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? length(var.public_subnets) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    var.tags,
    {
      Name = try(
        var.public_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.public_subnet_suffix, element(local.azs, count.index))
      )
    }
  )
}

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = var.name })
}

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-${var.public_subnet_suffix}" })
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? length(var.public_subnets) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# Private Tier
################################################################################

resource "aws_subnet" "private" {
  count = var.create_vpc && length(var.private_subnets) > 0 ? length(var.private_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(
    var.tags,
    {
      Name = try(
        var.private_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.private_subnet_suffix, element(local.azs, count.index))
      )
    }
  )
}

resource "aws_route_table" "private" {
  count = var.create_vpc && length(var.private_subnets) > 0 ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = "${var.name}-${var.private_subnet_suffix}-${element(local.azs, count.index)}" }
  )
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc && length(var.private_subnets) > 0 ? length(var.private_subnets) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.tags, { Name = "${var.name}-nat-eip-${element(local.azs, count.index)}" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, { Name = "${var.name}-nat-${element(local.azs, count.index)}" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route" "private_nat_gateway" {
  count = local.create_nat ? length(var.private_subnets) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = var.nat_gateway_destination_cidr_block
  nat_gateway_id         = aws_nat_gateway.this[count.index % local.nat_gateway_count].id
}

################################################################################
# Intra (Isolated) Tier
################################################################################

resource "aws_subnet" "intra" {
  count = var.create_vpc && length(var.intra_subnets) > 0 ? length(var.intra_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnets[count.index]
  availability_zone = element(local.azs, count.index)

  tags = merge(
    var.tags,
    {
      Name = try(
        var.intra_subnet_names[count.index],
        format("%s-%s-%s", var.name, var.intra_subnet_suffix, element(local.azs, count.index))
      )
    }
  )
}

resource "aws_route_table" "intra" {
  count = var.create_vpc && length(var.intra_subnets) > 0 ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = "${var.name}-${var.intra_subnet_suffix}-${element(local.azs, count.index)}" }
  )
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc && length(var.intra_subnets) > 0 ? length(var.intra_subnets) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "public_subnet_ids" {
  description = "List of IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of IDs of the intra subnets."
  value       = aws_subnet.intra[*].id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "List of IDs of the NAT Gateways."
  value       = aws_nat_gateway.this[*].id
}

output "nat_elastic_ip_ids" {
  description = "List of allocation IDs of the NAT Gateway Elastic IPs."
  value       = aws_eip.nat[*].id
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of IDs of the private route tables."
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of IDs of the intra route tables."
  value       = aws_route_table.intra[*].id
}

locals {
  api_type = var.api_type == "rest" ? "rest" : "http"
  api_name = var.api_name != null ? var.api_name : "benchmark-api"
  stage_name = "${var.environment_name}-stage"
  is_http    = local.api_type == "http"
  is_rest    = local.api_type == "rest"
  create_vpc_link = var.vpc_link_config != null
}

# ---------------------------------------------------------------------------
# Networking – VPC and subnets (required for VPC links, NLB, etc.)
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.api_name}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = local.create_vpc_link ? length(var.private_subnet_cidrs) : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.api_name}-private-${count.index}"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.api_name}-public-${count.index}"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Security Group for VPC Link / NLB (only when VPC link is enabled)
# ---------------------------------------------------------------------------
resource "aws_security_group" "vpc_link" {
  count = local.create_vpc_link ? 1 : 0

  name        = "${local.api_name}-vpc-link-sg"
  description = "Security group for API Gateway VPC link"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.api_name}-vpc-link-sg"
  }
}

# ---------------------------------------------------------------------------
# HTTP API (v2) resources
# ---------------------------------------------------------------------------
resource "aws_apigatewayv2_api" "http" {
  count = local.is_http ? 1 : 0

  name          = local.api_name
  protocol_type = "HTTP"

  tags = {
    Environment = var.environment_name
  }
}

# HTTP – stage (auto-deployed)
resource "aws_apigatewayv2_stage" "http" {
  count = local.is_http ? 1 : 0

  api_id = aws_apigatewayv2_api.http[0].id
  name   = local.stage_name

  auto_deploy = true

  tags = {
    Environment = var.environment_name
  }
}

# HTTP – VPC link
resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.is_http && local.create_vpc_link ? 1 : 0

  name               = "${local.api_name}-http-vpc-link"
  security_group_ids = [aws_security_group.vpc_link[0].id]
  subnet_ids         = aws_subnet.private[*].id

  tags = {
    Environment = var.environment_name
  }
}

# HTTP – dynamic route mappings
resource "aws_apigatewayv2_route" "http" {
  for_each = local.is_http ? var.http_routes : {}

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.key
  target    = each.value.target != null ? "integrations/${aws_apigatewayv2_integration.http_integration[each.key].id}" : null

  depends_on = [aws_apigatewayv2_integration.http_integration]
}

resource "aws_apigatewayv2_integration" "http_integration" {
  for_each = local.is_http ? var.http_routes : {}

  api_id           = aws_apigatewayv2_api.http[0].id
  integration_type = each.value.integration_type != null ? each.value.integration_type : "AWS_PROXY"

  connection_id    = local.create_vpc_link ? aws_apigatewayv2_vpc_link.http[0].id : null
  connection_type  = local.create_vpc_link ? "VPC_LINK" : "INTERNET"

  integration_uri        = each.value.integration_uri
  payload_format_version = "2.0"
}

# HTTP – custom domain
resource "aws_apigatewayv2_domain_name" "http" {
  count = local.is_http && var.domain_name != null ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate.api[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = local.is_http && var.domain_name != null ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

# HTTP – Route53 alias A record
resource "aws_route53_record" "http_alias" {
  count = local.is_http && var.domain_name != null && var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# ---------------------------------------------------------------------------
# REST API (v1) resources
# ---------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0

  name        = local.api_name
  description = "REST API created by dual-mode module"

  policy = local.is_rest && var.rest_ip_source_restriction != null ? data.aws_iam_policy_document.rest_resource_policy[0].json : null

  tags = {
    Environment = var.environment_name
  }
}

# REST – resource policy for IP source restriction
data "aws_iam_policy_document" "rest_resource_policy" {
  count = local.is_rest && var.rest_ip_source_restriction != null ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["execute-api:Invoke"]
    resources = ["arn:aws:execute-api:*:*:*"]

    condition {
      test     = "IpAddress"
      variable = "aws:SourceIp"
      values   = var.rest_ip_source_restriction
    }
  }

  statement {
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["execute-api:Invoke"]
    resources = ["arn:aws:execute-api:*:*:*"]

    condition {
      test     = "NotIpAddress"
      variable = "aws:SourceIp"
      values   = var.rest_ip_source_restriction
    }
  }
}

# REST – dynamic resource path mapping
resource "aws_api_gateway_resource" "rest" {
  for_each = local.is_rest ? var.rest_resources : {}

  parent_id   = each.value.parent_id != null ? each.value.parent_id : aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.key
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
}

# REST – route methods with path parameter overrides
resource "aws_api_gateway_method" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = each.value.resource_id
  http_method   = each.value.http_method
  authorization = each.value.authorization != null ? each.value.authorization : "NONE"
  authorizer_id = each.value.authorizer_id != null ? each.value.authorizer_id : null

  request_parameters = each.value.request_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = each.value.resource_id
  http_method = each.value.http_method

  integration_http_method = each.value.integration_http_method != null ? each.value.integration_http_method : "POST"
  type                    = each.value.integration_type != null ? each.value.integration_type : "AWS_PROXY"
  uri                     = each.value.integration_uri

  connection_type = local.create_vpc_link ? "VPC_LINK" : null
  connection_id   = local.create_vpc_link ? aws_api_gateway_vpc_link.rest[0].id : null
}

# REST – stage
resource "aws_api_gateway_deployment" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode(var.rest_methods))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = local.is_rest ? 1 : 0

  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id

  tags = {
    Environment = var.environment_name
  }
}

# REST – custom domain
resource "aws_api_gateway_domain_name" "rest" {
  count = local.is_rest && var.domain_name != null ? 1 : 0

  domain_name = var.domain_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  security_policy = "TLS_1_2"

  certificate_arn = aws_acm_certificate.api[0].arn
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count = local.is_rest && var.domain_name != null ? 1 : 0

  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

# REST – Route53 alias A record
resource "aws_route53_record" "rest_alias" {
  count = local.is_rest && var.domain_name != null && var.route53_zone_id != null ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

# REST – usage plan and API keys saved as SecureString SSM parameters
resource "aws_api_gateway_api_key" "rest" {
  for_each = local.is_rest ? var.rest_api_keys : {}

  name        = each.value.name
  description = each.value.description
  enabled     = each.value.enabled != null ? each.value.enabled : true

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest && length(var.rest_api_keys) > 0 ? 1 : 0

  name        = "${local.api_name}-usage-plan"
  description = "Usage plan for ${local.api_name}"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  quota_settings {
    limit  = var.usage_plan_quota
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = var.usage_plan_burst_limit
    rate_limit  = var.usage_plan_rate_limit
  }

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  for_each = local.is_rest ? var.rest_api_keys : {}

  key_id        = aws_api_gateway_api_key.rest[each.key].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  for_each = local.is_rest ? var.rest_api_keys : {}

  name  = "/api-gateway/${local.api_name}/api-key/${each.key}"
  type  = "SecureString"
  value = aws_api_gateway_api_key.rest[each.key].value

  lifecycle {
    prevent_destroy = true
  }
}

# REST – VPC link (via NLB)
resource "aws_lb" "nlb" {
  count = local.is_rest && local.create_vpc_link ? 1 : 0

  name               = "${local.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = aws_subnet.private[*].id

  enable_deletion_protection = false

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_lb_target_group" "nlb" {
  count = local.is_rest && local.create_vpc_link ? 1 : 0

  name        = "${local.api_name}-nlb-tg"
  port        = var.vpc_link_config.target_port
  protocol    = "TCP"
  vpc_id      = aws_vpc.main.id
  target_type = "alb"

  health_check {
    protocol = "HTTPS"
    port     = "traffic-port"
    path     = "/"
  }

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count = local.is_rest && local.create_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = var.vpc_link_config.target_alb_id
  port             = var.vpc_link_config.target_port
}

resource "aws_lb_listener" "nlb" {
  count = local.is_rest && local.create_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.vpc_link_config.target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.is_rest && local.create_vpc_link ? 1 : 0

  name        = "${local.api_name}-rest-vpc-link"
  description = "VPC Link for REST API"
  target_arns = [aws_lb.nlb[0].arn]

  tags = {
    Environment = var.environment_name
  }
}

# ---------------------------------------------------------------------------
# Shared ACM certificate (for custom domain – both HTTP and REST)
# ---------------------------------------------------------------------------
resource "aws_acm_certificate" "api" {
  count = var.domain_name != null ? 1 : 0

  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Environment = var.environment_name
  }
}

# ---------------------------------------------------------------------------
# Custom Lambda Authorizer (REST API) – Node.js 16.x
# ---------------------------------------------------------------------------
resource "aws_lambda_function" "authorizer" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  filename         = each.value.zip_path
  function_name    = "${local.api_name}-authorizer-${each.key}"
  role            = aws_iam_role.authorizer_invocation[each.key].arn
  handler         = each.value.handler
  runtime         = "nodejs16.x"
  source_code_hash = filebase64sha256(each.value.zip_path)

  environment {
    variables = each.value.environment_variables
  }

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_iam_role" "authorizer_invocation" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  name = "${local.api_name}-authorizer-role-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Environment = var.environment_name
  }
}

resource "aws_iam_role_policy_attachment" "authorizer_execution" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  role       = aws_iam_role.authorizer_invocation[each.key].name
  policy_arn = aws_iam_policy.authorizer_execution[each.key].arn
}

resource "aws_iam_policy" "authorizer_execution" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  name        = "${local.api_name}-authorizer-policy-${each.key}"
  description = "Execution policy for Lambda authorizer ${each.key}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
    ]
  })
}

resource "aws_lambda_permission" "authorizer" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  statement_id  = "AllowAPIGatewayInvoke-${each.key}"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[each.key].function_name
  principal     = "apigateway.amazonaws.com"
}

resource "aws_api_gateway_authorizer" "rest" {
  for_each = local.is_rest ? var.rest_authorizers : {}

  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  name          = "${local.api_name}-authorizer-${each.key}"
  type          = "TOKEN"
  identity_source = each.value.identity_source != null ? each.value.identity_source : "method.request.header.Authorization"
  authorizer_uri = aws_lambda_function.authorizer[each.key].invoke_arn
  authorizer_credentials = aws_iam_role.authorizer_invocation[each.key].arn
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "api_type" {
  description = "Type of API to create: 'http' or 'rest'"
  type        = string
  default     = "http"
}

variable "api_name" {
  description = "Name of the API"
  type        = string
  default     = null
}

variable "environment_name" {
  description = "Environment name used for stage naming"
  type        = string
  default     = "dev"
}

variable "domain_name" {
  description = "Custom domain name for the API (optional)"
  type        = string
  default     = null
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for alias records (optional)"
  type        = string
  default     = null
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets (required when vpc_link_config is set)"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

# HTTP-specific variables
variable "http_routes" {
  description = "Map of HTTP route definitions keyed by route key"
  type = map(object({
    integration_type = optional(string)
    integration_uri  = string
    target           = optional(string)
  }))
  default = {}
}

# REST-specific variables
variable "rest_resources" {
  description = "Map of REST resource path parts keyed by path"
  type = map(object({
    parent_id = optional(string)
  }))
  default = {}
}

variable "rest_methods" {
  description = "Map of REST method configurations"
  type = map(object({
    resource_id             = string
    http_method             = string
    authorization           = optional(string)
    authorizer_id           = optional(string)
    request_parameters      = optional(map(bool))
    integration_type        = optional(string)
    integration_http_method = optional(string)
    integration_uri         = optional(string)
  }))
  default = {}
}

variable "rest_ip_source_restriction" {
  description = "List of IP CIDRs allowed to access the REST API (optional)"
  type        = list(string)
  default     = null
}

variable "rest_api_keys" {
  description = "Map of API keys for REST API usage plans"
  type = map(object({
    name        = string
    description = optional(string)
    enabled     = optional(bool)
  }))
  default = {}
}

variable "usage_plan_quota" {
  description = "Monthly quota limit for REST API usage plan"
  type        = number
  default     = 1000
}

variable "usage_plan_burst_limit" {
  description = "Burst rate limit for REST API usage plan"
  type        = number
  default     = 100
}

variable "usage_plan_rate_limit" {
  description = "Steady-state rate limit for REST API usage plan"
  type        = number
  default     = 50
}

variable "vpc_link_config" {
  description = "Configuration for VPC link (optional). Set to enable VPC link support."
  type = object({
    target_port    = optional(number, 443)
    target_alb_id  = string
  })
  default = null
}

variable "rest_authorizers" {
  description = "Map of custom Lambda authorizer configurations for REST API"
  type = map(object({
    zip_path              = string
    handler               = string
    identity_source       = optional(string)
    environment_variables = optional(map(string))
  }))
  default = {}
}

# Data sources for dynamic metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# Random suffix for S3 bucket name
resource "random_string" "bucket_suffix" {
  length  = 8
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  # === DYNAMICALLY GENERATED NAMES ===
  bucket_name     = "cloudtrail-logs-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}-${random_string.bucket_suffix.result}"
  cloudtrail_name = "comprehensive-trail"
  log_group_name  = "cloudtrail-log-group"
  iam_role_name   = "CloudWatchLogsIngestionRole"
  kms_alias_name  = "cloudtrail-kms-key"
  sns_topic_name  = "cloudtrail-alerts"

  # === CONFIGURABLE PARAMETERS WITH DEFAULTS ===
  # S3 bucket
  bucket_force_destroy      = true
  bucket_versioning_enabled = false

  # CloudWatch Log Group
  log_retention_days = 90

  # CloudTrail
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_logging                = true
  is_organization_trail         = false
  read_write_type               = "All"
  include_management_events     = true

  # SNS
  sns_topic_enabled      = false
  optional_sns_topic_arn = ""

  # KMS
  optional_role_arn = ""

  # === DERIVED LOCALS ===

  # KMS key policy statements
  optional_role_statements = local.optional_role_arn != "" ? [
    {
      Sid      = "Allow Optional Role Decryption"
      Effect   = "Allow"
      Principal = {
        AWS = local.optional_role_arn
      }
      Action   = ["kms:Decrypt", "kms:DescribeKey", "kms:ReEncrypt*"]
      Resource = "*"
    }
  ] : []

  kms_statements = concat([
    {
      Sid      = "Allow Root IAM Users"
      Effect   = "Allow"
      Principal = {
        AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      }
      Action   = ["kms:*"]
      Resource = "*"
    },
    {
      Sid      = "Allow CloudTrail Encryption Context"
      Effect   = "Allow"
      Principal = {
        Service = "cloudtrail.amazonaws.com"
      }
      Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:ReEncrypt*"]
      Resource = "*"
    },
    {
      Sid      = "Allow CloudWatch Logs"
      Effect   = "Allow"
      Principal = {
        Service = "logs.amazonaws.com"
      }
      Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:ReEncrypt*"]
      Resource = "*"
    },
    {
      Sid      = "Allow S3 Bucket SSE-KMS"
      Effect   = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey", "kms:ReEncrypt*"]
      Resource = "*"
    }
  ], local.optional_role_statements)

  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "cloudtrail-kms-key-policy"
    Statement = local.kms_statements
  })

  # S3 bucket policy permitting CloudTrail ACL checks and put-object actions
  s3_bucket_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "S3BucketPolicyForCloudTrail"
    Statement = [
      {
        Sid      = "CloudTrailAclCheckAndPutObject"
        Effect   = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = ["s3:GetBucketAcl", "s3:PutObject"]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
          "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
        ]
      }
    ]
  })

  # SNS topic policy allowing CloudTrail publishing
  sns_topic_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "SNSTopicPolicyForCloudTrail"
    Statement = [
      {
        Sid      = "AllowCloudTrailPublish"
        Effect   = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = ["sns:Publish"]
        Resource = "arn:${data.aws_partition.current.partition}:sns:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${local.sns_topic_name}"
      }
    ]
  })
}

# ============================================================
# KMS KEY – Dedicated CloudTrail encryption key
# ============================================================
resource "aws_kms_key" "cloudtrail" {
  description             = "Dedicated KMS key for CloudTrail log file encryption with automatic annual rotation"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = 365
  policy                  = local.kms_key_policy
}

# KMS Alias
resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${local.kms_alias_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# ============================================================
# S3 BUCKET – CloudTrail log storage
# ============================================================
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = local.bucket_force_destroy
  policy        = local.s3_bucket_policy
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = local.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

# ============================================================
# CLOUDWATCH LOG GROUP – 90-day retention
# ============================================================
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = local.log_retention_days
}

# ============================================================
# IAM ROLE & POLICY – CloudWatch Logs ingestion for CloudTrail
# ============================================================
resource "aws_iam_role" "cloudwatch_logs_ingestion" {
  name = local.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowCloudTrailToAssumeRole"
        Effect   = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = ["sts:AssumeRole"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_logs_ingestion" {
  name = "CloudWatchLogsIngestionPolicy"
  role = aws_iam_role.cloudwatch_logs_ingestion.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailLogStreamCreationAndPutEvents"
        Effect = "Allow"
        Action = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}:*"
        ]
      }
    ]
  })
}

# ============================================================
# CLOUDTRAIL TRAIL
# ============================================================
resource "aws_cloudtrail" "main" {
  name                          = local.cloudtrail_name
  s3_bucket_name                = local.bucket_name
  s3_key_prefix                 = ""
  include_global_service_events = local.include_global_service_events
  is_multi_region_trail         = local.is_multi_region_trail
  enable_log_file_validation    = true
  is_organization_trail         = local.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn

  event_selector {
    read_write_type          = local.read_write_type
    include_management_events = local.include_management_events
  }
}

# ============================================================
# SNS TOPIC – Optional alert topic (disabled by default)
# ============================================================
resource "aws_sns_topic" "cloudtrail" {
  count  = local.sns_topic_enabled ? 1 : 0
  name   = local.sns_topic_name
  policy = local.sns_topic_policy
}

variable "enabled" {
  description = "Global enabling flag for EBS security settings"
  type        = bool
  default     = true
}

variable "enable_encryption_by_default" {
  description = "Enable default EBS encryption for the region"
  type        = bool
  default     = true
}

variable "block_public_snapshots" {
  description = "Block public access to EBS snapshots"
  type        = bool
  default     = true
}

variable "block_public_snapshots_state" {
  description = "State for blocking public access to EBS snapshots"
  type        = string
  default     = "block-all-sharing"
}

variable "region" {
  description = "Target AWS region; defaults to provider's current region"
  type        = string
  default     = null
}

data "aws_region" "current" {}

locals {
  region = var.region != null ? var.region : data.aws_region.current.name
}

resource "aws_ebs_encryption_by_default" "this" {
  count   = var.enabled && var.enable_encryption_by_default ? 1 : 0
  enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = var.enabled && var.block_public_snapshots ? 1 : 0
  state = var.block_public_snapshots_state

  lifecycle {
    prevent_destroy = true
  }
}

variable "username" {
  description = "Username for the IAM deployment user"
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags applied to provisioned resources"
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs for artifact storage access"
  type        = list(string)
  default     = []
}

variable "s3_bucket_sub_paths" {
  description = "Map of bucket ARN to sub-path pattern (default '*')"
  type        = map(string)
  default     = {}
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs for code update access"
  type        = list(string)
  default     = []
}

locals {
  s3_list_statements = length(var.s3_bucket_arns) > 0 ? [
    for bucket_arn in var.s3_bucket_arns : {
      Effect   = "Allow"
      Action   = ["s3:ListBucket"]
      Resource = bucket_arn
    }
  ] : []

  s3_object_statements = length(var.s3_bucket_arns) > 0 ? [
    for bucket_arn in var.s3_bucket_arns : {
      Effect   = "Allow"
      Action   = ["s3:GetObject", "s3:PutObject", "s3:GetObjectAcl", "s3:PutObjectAcl", "s3:DeleteObject"]
      Resource = "${bucket_arn}/${lookup(var.s3_bucket_sub_paths, bucket_arn, "*")}"
    }
  ] : []

  lambda_statements = length(var.lambda_function_arns) > 0 ? [
    for func_arn in var.lambda_function_arns : {
      Effect   = "Allow"
      Action   = ["lambda:UpdateFunctionCode"]
      Resource = func_arn
    }
  ] : []

  s3_policy_document = length(var.s3_bucket_arns) > 0 ? {
    Version   = "2012-10-17"
    Statement = concat(local.s3_list_statements, local.s3_object_statements)
  } : null

  lambda_policy_document = length(var.lambda_function_arns) > 0 ? {
    Version   = "2012-10-17"
    Statement = local.lambda_statements
  } : null
}

resource "aws_iam_user" "deployment" {
  name = var.username
  tags = var.tags
}

resource "aws_iam_user_policy" "s3" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0
  name   = "${var.username}-s3-artifact-access"
  user   = aws_iam_user.deployment.name
  policy = jsonencode(local.s3_policy_document)
}

resource "aws_iam_user_policy" "lambda" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0
  name   = "${var.username}-lambda-code-update"
  user   = aws_iam_user.deployment.name
  policy = jsonencode(local.lambda_policy_document)
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "custom_name" {
  description = "Custom name for the S3 bucket"
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Domain name for the website (requires zone_id)"
  type        = string
  default     = ""
}

variable "zone_id" {
  description = "Route 53 hosted zone ID (required when domain_name is non-empty)"
  type        = string
  default     = ""
}

variable "bucket_versioning" {
  description = "Enable S3 bucket versioning"
  type        = bool
  default     = false
}

variable "enable_www_aliases" {
  description = "Enable www domain aliases with wildcard subject alternative names"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# Random ID for the fallback bucket name
# ---------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# ---------------------------------------------------------------------------
# Locals – computed bucket name
# ---------------------------------------------------------------------------
locals {
  bucket_name = var.custom_name != "" ? var.custom_name : (
    var.domain_name != "" ? var.domain_name : format("webapp-template-%s", random_id.bucket_suffix.hex)
  )
}

# ---------------------------------------------------------------------------
# Conditionals – only relevant when a domain is given
# ---------------------------------------------------------------------------
locals {
  has_domain = var.domain_name != "" && var.zone_id != ""
}

# ---------------------------------------------------------------------------
# S3 bucket – private, block all public access
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = var.bucket_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudfront.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# KMS key – customer-managed, allows CloudFront decryption
# ---------------------------------------------------------------------------
locals {
  # We need a stable reference to the CloudFront distribution ARN for the
  # KMS policy.  Terraform cannot forward-reference attributes of resources
  # defined later in the same file, but we can use the resource's own
  # identity once known.  The KMS policy must list CloudFront as a principal
  # that can decrypt.  Because the CloudFront distribution ARN is not known
  # until creation, we grant "cloudfront.amazonaws.com" (the CloudFront
  # service principal) the Decrypt right, scoped by a condition on the S3
  # bucket resource.
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "cloudfront" {
  description             = "KMS key for S3 SSE-KMS – CloudFront decryption"
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "RootAdminAccess"
        Effect = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Get*",
          "kms:List*",
          "kms:ScheduleKeyDeletion",
          "kms:PutKeyPolicy",
          "kms:TagResource",
          "kms:UntagResource"
        ]
        Resource = "*"
      },
      {
        Sid = "AllowCloudFrontDecrypt"
        Effect = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext" = jsonencode({
              "service" : "s3",
              "arn"     : aws_s3_bucket.this.arn
            })
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Bucket policy – allow s3:GetObject only when source is the CloudFront
# distribution.  We reference the distribution via its ARN.
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "cloudfront_only" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "CloudFrontGetObject"
        Effect = "Allow"
        Principal = "*"
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# CloudFront – Origin Access Control (signing)
# ---------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "this" {
  name        = local.bucket_name
  description = "Origin Access Control for ${local.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_protocol     = "sigv4"
  signing_behavior     = "always"
}

# ---------------------------------------------------------------------------
# WAFv2 – CloudFront-scoped web ACL
# ---------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "cloudfront" {
  name        = "cloudfront-acl-${local.bucket_name}"
  description = "CloudFront-scoped WAFv2 ACL"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cloudfront-acl-${replace(local.bucket_name, ".", "-")}"
    sampled_requests_enabled   = true
  }
}



# ---------------------------------------------------------------------------
# CloudFront distribution
# ---------------------------------------------------------------------------
locals {
  # Custom cache policy names (created below)
  caching_optimized_policy_id = aws_cloudfront_cache_policy.caching_optimized.id
  caching_disabled_policy_id  = aws_cloudfront_cache_policy.caching_disabled.id
}

# ---------------------------------------------------------------------------
# CloudFront cache policies (replacements for AWS-managed policies)
# ---------------------------------------------------------------------------
resource "aws_cloudfront_cache_policy" "caching_optimized" {
  name        = "custom-caching-optimized-${local.bucket_name}"
  comment     = "Optimised caching – equivalent to AWS-managed CachingOptimized"
  default_ttl = 86400
  max_ttl     = 31536000
  min_ttl     = 0

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }
    headers_config {
      header_behavior = "none"
    }
    query_strings_config {
      query_string_behavior = "none"
    }
    enable_accept_encoding_brotli = true
    enable_accept_encoding_gzip   = true
  }
}

resource "aws_cloudfront_cache_policy" "caching_disabled" {
  name        = "custom-caching-disabled-${local.bucket_name}"
  comment     = "Caching disabled – equivalent to AWS-managed CachingDisabled"
  default_ttl = 0
  max_ttl     = 0
  min_ttl     = 0

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }
    headers_config {
      header_behavior = "none"
    }
    query_strings_config {
      query_string_behavior = "none"
    }
    enable_accept_encoding_brotli = false
    enable_accept_encoding_gzip   = false
  }
}

resource "aws_cloudfront_distribution" "this" {
  # The ARN attribute we need for the bucket policy and WAF association.
  # Terraform synthesises this as:
  #   arn:aws:cloudfront::${aws_cloudfront_distribution.this.id}

  enabled = true

  aliases = local.has_domain ? (
    var.enable_www_aliases ? [var.domain_name, "www.${var.domain_name}"] : [var.domain_name]
  ) : []

  origin {
    domain_name = aws_s3_bucket.this.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.this.id
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    target_origin_id       = aws_s3_bucket.this.id
    viewer_protocol_policy = "https-only"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true
    smooth_streaming       = false

    cache_policy_id = local.caching_optimized_policy_id
  }

  # Ordered cache behaviour for /index.html – caching disabled
  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = aws_s3_bucket.this.id
    viewer_protocol_policy = "https-only"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true
    smooth_streaming       = false

    cache_policy_id = local.caching_disabled_policy_id
  }

  custom_error_response {
    error_code         = 403
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code         = 404
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  default_root_object = "index.html"
  price_class         = "PriceClass_100"

  is_ipv6_enabled = true

  http_version = "http2"

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  # Viewer certificate – ACM when domain present, default CloudFront cert otherwise
  dynamic "viewer_certificate" {
    for_each = local.has_domain ? [1] : []
    content {
      acm_certificate_arn      = aws_acm_certificate.this[0].arn
      ssl_support_method       = "sni-only"
      minimum_protocol_version = "TLSv1.2_2021"
    }
  }

  dynamic "viewer_certificate" {
    for_each = local.has_domain ? [] : [1]
    content {
      cloudfront_default_certificate = true
      minimum_protocol_version       = "TLSv1.2_2021"
    }
  }

  # WAFv2 web ACL ID – directly on the distribution
  web_acl_id = aws_wafv2_web_acl.cloudfront.arn
}

# ---------------------------------------------------------------------------
# ACM certificate (AWS Certificate Manager) – us-east-1, DNS validation via
# Route 53
# ---------------------------------------------------------------------------
resource "aws_acm_certificate" "this" {
  count = local.has_domain ? 1 : 0

  domain_name       = var.domain_name
  subject_alternative_names = var.enable_www_aliases ? ["*.${var.domain_name}"] : []
  validation_method = "DNS"
  region            = "us-east-1"

  lifecycle {
    prevent_destroy = true
  }
}

# Route 53 DNS validation records
resource "aws_route53_record" "validation" {
  count = local.has_domain ? length(aws_acm_certificate.this[0].domain_validation_options) : 0

  zone_id = var.zone_id
  name    = aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_name
  type    = aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_type
  ttl     = 60
  records = [aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_value]

  allow_overwrite = true
}

# Certificate validation – wait for it to be issued
resource "aws_acm_certificate_validation" "this" {
  count = local.has_domain ? 1 : 0

  certificate_arn = aws_acm_certificate.this[0].arn
}

# ---------------------------------------------------------------------------
# Route 53 alias A records pointing to the CloudFront distribution
# ---------------------------------------------------------------------------
resource "aws_route53_record" "a_root" {
  count = local.has_domain ? 1 : 0

  zone_id = var.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "a_www" {
  count = local.has_domain && var.enable_www_aliases ? 1 : 0

  zone_id = var.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "region" {
  description = "AWS region where resources will be provisioned"
  type        = string
  default     = "us-east-1"
}

variable "base_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.20.0.0/16"
}

variable "availability_zone_names" {
  description = "Comma-separated list of availability zone names (default: auto-select first 3 available zones)"
  type        = string
  default     = ""
}

variable "multi_az_nat_gateway" {
  description = "Deploy NAT gateways per availability zone (1 = true, 0 = false)"
  type        = number
  default     = 1
}

variable "single_nat_gateway" {
  description = "Deploy a single NAT gateway (1 = true, 0 = false)"
  type        = number
  default     = 0
}

variable "enable_s3_vpc_endpoint" {
  description = "Enable S3 VPC Gateway endpoint"
  type        = bool
  default     = true
}

locals {
  global_tags = {
    Author      = "Fairwinds"
    "Managed By" = "Terraform"
  }

  # Resolve the three AZ names from user input or data source
  az_names_raw = length(var.availability_zone_names) > 0 ? split(",", var.availability_zone_names) : slice(sort(data.aws_availability_zones.available.names), 0, 3)
  az_names     = slice(local.az_names_raw, 0, 3)

  # Extract the first two octets of the base CIDR (e.g. "10.20")
  base_octets = split(".", cidrhost(var.base_cidr, 0))
  base_prefix = "${local.base_octets[0]}.${local.base_octets[1]}"

  # Subnet CIDR suffixes per AZ index
  admin_suffixes          = [".0.0/21", ".8.0/21", ".16.0/21"]
  public_suffixes         = [".32.0/21", ".40.0/21", ".48.0/21"]
  private_prod_suffixes   = [".64.0/21", ".72.0/21", ".80.0/21"]
  private_working_suffixes = [".96.0/21", ".104.0/21", ".112.0/21"]

  # Full subnet CIDRs per AZ index
  admin_cidrs          = [for s in local.admin_suffixes : "${local.base_prefix}${s}"]
  public_cidrs         = [for s in local.public_suffixes : "${local.base_prefix}${s}"]
  private_prod_cidrs   = [for s in local.private_prod_suffixes : "${local.base_prefix}${s}"]
  private_working_cidrs = [for s in local.private_working_suffixes : "${local.base_prefix}${s}"]

  # Condition controlling per-AZ NAT gateway deployment
  create_per_az_nat = var.multi_az_nat_gateway == 1 && var.single_nat_gateway == 0
}

resource "aws_vpc" "main" {
  cidr_block           = var.base_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.global_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "vpc" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.global_tags, {
    Name = "vpc"
  })
}

# --------------------------------------------------------------------------
# Route tables
# --------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.global_tags, {
    Name = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.vpc.id
}

resource "aws_route_table" "private" {
  count = length(local.az_names)

  vpc_id = aws_vpc.main.id

  tags = merge(local.global_tags, {
    Name = "private_az${count.index + 1}"
  })
}

# --------------------------------------------------------------------------
# Subnets
# --------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = length(local.az_names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.global_tags, {
    Name = "public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = length(local.az_names)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "admin" {
  count = length(local.az_names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.admin_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.global_tags, {
    Name = "admin-${count.index + 1}"
    Tier = "admin"
  })
}

resource "aws_route_table_association" "admin" {
  count = length(local.az_names)

  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_subnet" "private_prod" {
  count = length(local.az_names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_prod_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.global_tags, {
    Name = "private-prod-${count.index + 1}"
    Tier = "private_production"
  })
}

resource "aws_route_table_association" "private_prod" {
  count = length(local.az_names)

  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_subnet" "private_working" {
  count = length(local.az_names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_working_cidrs[count.index]
  availability_zone = local.az_names[count.index]

  tags = merge(local.global_tags, {
    Name = "private-working-${count.index + 1}"
    Tier = "private_working"
  })
}

resource "aws_route_table_association" "private_working" {
  count = length(local.az_names)

  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# --------------------------------------------------------------------------
# NAT Gateways (per AZ)
# --------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = local.create_per_az_nat ? length(local.az_names) : 0

  domain = "vpc"

  tags = merge(local.global_tags, {
    Name = "nat-az${count.index + 1}"
  })
}

resource "aws_nat_gateway" "main" {
  count = local.create_per_az_nat ? length(local.az_names) : 0

  connectivity_type = "public"
  subnet_id         = aws_subnet.public[count.index].id
  allocation_id     = aws_eip.nat[count.index].id

  tags = merge(local.global_tags, {
    Name = "nat-az${count.index + 1}"
  })
}

resource "aws_route" "private_nat" {
  count = local.create_per_az_nat ? length(local.az_names) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

# --------------------------------------------------------------------------
# S3 VPC Gateway Endpoint (conditional)
# --------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${var.region}.s3"

  route_table_ids = aws_route_table.private[*].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "*"
        Effect    = "Allow"
        Principal = "*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(local.global_tags, {
    Name = "s3-gateway-endpoint"
  })
}

# =============================================================================
# Terraform configuration for a self-contained production-style web backend
# platform on AWS Fargate with companion RDS PostgreSQL, ECR, and CI/CD IAM.
# =============================================================================

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  app_port        = var.app_port != null ? var.app_port : 80
  healthcheck_path = var.healthcheck_path != null ? var.healthcheck_path : "/"
  github_org      = var.github_organization
  region          = data.aws_region.current.region
  account_id      = data.aws_caller_identity.current.account_id
  azs             = slice(data.aws_availability_zones.available.names, 0, 2)
}

# ---------------------------------------------------------------------------
# Permitted data sources
# ---------------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "app_port" {
  description = "Application container port"
  type        = number
  default     = 80
}

variable "healthcheck_path" {
  description = "Health check path for the ALB target group"
  type        = string
  default     = "/"
}

variable "github_organization" {
  description = "GitHub organization or account name for OIDC trust"
  type        = string
  default     = "placeholder-org"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets – 2 public + 2 private across two AZs
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# ---------------------------------------------------------------------------
# Route tables
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Self-signed certificate via ACM (imported)
# ---------------------------------------------------------------------------
resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name = "example.local"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "selfsigned" {
  certificate_body  = tls_self_signed_cert.alb.cert_pem
  private_key       = tls_private_key.alb.private_key_pem_pkcs8

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "selfsigned-alb"
  }
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------
# SG: Load balancer – inbound http/https from everywhere.
# Outbound: only within VPC.
resource "aws_security_group" "lb" {
  name        = "lb-sg"
  description = "Load balancer security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lb-sg"
  }
}

resource "aws_security_group_rule" "lb_in_80" {
  security_group_id = aws_security_group.lb.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "lb_in_443" {
  security_group_id = aws_security_group.lb.id
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "lb_out_vpc" {
  security_group_id = aws_security_group.lb.id
  type              = "egress"
  from_port         = 0
  to_port           = 65535
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# SG: Application containers – ingress only from LB, outbound only within VPC.
resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Application container security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app-sg"
  }
}

resource "aws_security_group_rule" "app_in_lb" {
  security_group_id        = aws_security_group.app.id
  type                     = "ingress"
  from_port                = 0
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lb.id
}

resource "aws_security_group_rule" "app_out_vpc" {
  security_group_id = aws_security_group.app.id
  type              = "egress"
  from_port         = 0
  to_port           = 65535
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# SG: Database – ingress only from app containers on port 5432, outbound only within VPC.
resource "aws_security_group" "db" {
  name        = "db-sg"
  description = "Database security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db-sg"
  }
}

resource "aws_security_group_rule" "db_in_app" {
  security_group_id        = aws_security_group.db.id
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app.id
}

resource "aws_security_group_rule" "db_out_vpc" {
  security_group_id = aws_security_group.db.id
  type              = "egress"
  from_port         = 0
  to_port           = 65535
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL (small, single-AZ, encrypted storage)
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "main-dbsg"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main-dbsg"
  }
}

resource "aws_db_instance" "postgres" {
  identifier        = "main-pg"
  engine            = "postgres"
  engine_version    = "14"
  instance_class    = "small"
  allocated_storage = 20

  db_name     = "mydb"
  username    = "postgres"
  password    = "postgres"
  port        = 5432

  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db.id]
  storage_encrypted       = true
  backup_retention_period = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "main-pg"
  }
}

# ---------------------------------------------------------------------------
# ECR repository (immutable tags, scan-on-push, untagged expiry 14 days)
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "app" {
  name                 = "app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "app-ecr"
  }
}

resource "aws_ecr_lifecycle_policy" "untagged" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countNumber = 14
          countUnit   = "days"
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ECS cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "main-cluster"

  tags = {
    Name = "main-cluster"
  }
}

# ---------------------------------------------------------------------------
# ECS execution role (standard managed permissions: pull images, write logs)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ecs-execution-role"
  }
}

resource "aws_iam_role_policy" "ecs_execution_custom" {
  name = "ecs-execution-custom"
  role = aws_iam_role.ecs_execution.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# ECS task role (used by containers – will be passed via CI/CD role)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ecs-task-role"
  }
}

# ---------------------------------------------------------------------------
# ECS task definition (placeholder nginx)
# ---------------------------------------------------------------------------
resource "aws_ecs_task_definition" "app" {
  family                   = "app"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([
    {
      name  = "app"
      image = "${local.account_id}.dkr.ecr.${local.region}.amazonaws.com/${aws_ecr_repository.app.name}:latest"
      portMappings = [
        {
          containerPort = local.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "POSTGRES_CONNECTION_STRING"
          value = "postgresql://postgres:postgres@${aws_db_instance.postgres.address}:5432/mydb"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = "/ecs/app"
          "awslogs-stream-prefix" = "app"
          "awslogs-create-group"  = "true"
        }
      }
    }
  ])

  tags = {
    Name = "app-td"
  }
}

# ---------------------------------------------------------------------------
# ECS service (Fargate, 20% on-demand / 80% spot)
# ---------------------------------------------------------------------------
resource "aws_ecs_service" "app" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2

  scheduling_strategy = "REPLICA"

  network_configuration {
    security_groups = [aws_security_group.app.id]
    subnets         = aws_subnet.private[*].id
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = local.app_port
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 80
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 20
  }

  tags = {
    Name = "app-service"
  }
}

# ---------------------------------------------------------------------------
# Application Load Balancer (internal, drops invalid headers)
# ---------------------------------------------------------------------------
resource "aws_lb" "main" {
  name            = "main-alb"
  internal        = true
  security_groups = [aws_security_group.lb.id]
  subnets         = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  tags = {
    Name = "main-alb"
  }
}

# HTTP listener (port 80) → redirect to HTTPS
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      protocol    = "HTTPS"
      port        = "443"
      status_code = "HTTP_301"
    }
  }
}

# HTTPS listener (port 443) → forward to target group
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELB-SSL-2017-01"
  certificate_arn   = aws_acm_certificate.selfsigned.id

  default_action {
    type = "forward"
    forward {
      target_group {
        arn = aws_lb_target_group.app.arn
      }
    }
  }
}

# Target group
resource "aws_lb_target_group" "app" {
  name     = "app-tg"
  port     = local.app_port
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled           = true
    path              = local.healthcheck_path
    healthy_threshold = 2
    interval          = 30
    timeout           = 5
  }

  tags = {
    Name = "app-tg"
  }
}

# ---------------------------------------------------------------------------
# GitHub Actions OIDC identity provider
# ---------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  thumbprint_list = ["a031c9b1bca5d947cda14ff8009fcba76f1cb5fe", "ebc0fa90c362a25ac7d0a675779ec4aaf40d0ac8", "4083691d5d1a68af9d5ba42939e60d00243b7353"]
  client_id_list  = ["sts.amazonaws.com"]
}

# ---------------------------------------------------------------------------
# CI/CD deploy role – assumable by GitHub Actions from the given org
# ---------------------------------------------------------------------------
resource "aws_iam_role" "cicd_deploy" {
  name = "cicd-deploy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:sub" = "repo:${local.github_org}/*"
          }
        }
      }
    ]
  })

  tags = {
    Name = "cicd-deploy-role"
  }
}

resource "aws_iam_role_policy" "cicd_deploy" {
  name = "cicd-deploy-policy"
  role = aws_iam_role.cicd_deploy.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = aws_ecr_repository.app.arn
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:DeregisterTaskDefinition",
          "ecs:ListTaskDefinitions"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:UpdateService",
          "ecs:DescribeServices"
        ]
        Resource = aws_ecs_service.app.arn
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_task.arn
      }
    ]
  })
}

# Input Variables
variable "cluster_tag" {
  type    = string
  default = "default"
}

variable "enable_key_rotation" {
  type    = bool
  default = false
}

variable "machine_roles" {
  type    = map(set(string))
  default = {}
}

# Data Sources (static provider metadata)
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Locals
locals {
  arn_prefix = "arn:${data.aws_partition.current.partition}:secretsmanager:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:secret:"

  secret_names = {
    consul-agent-token        = "resinstack-consul-agent-token-${var.cluster_tag}"
    consul-gossip-key          = "resinstack-consul-gossip-key-${var.cluster_tag}"
    nomad-client-consul-token = "resinstack-nomad-client-consul-token-${var.cluster_tag}"
    nomad-gossip-key          = "resinstack-nomad-gossip-key-${var.cluster_tag}"
    nomad-server-consul-token = "resinstack-nomad-server-consul-token-${var.cluster_tag}"
    nomad-vault-token         = "resinstack-nomad-vault-token-${var.cluster_tag}"
    vault-consul-token        = "resinstack-vault-consul-token-${var.cluster_tag}"
  }
}

# KMS Key for Vault Unsealing
resource "aws_kms_key" "vault_unseal" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  rotation_period_in_days = 365
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Secrets Manager Secrets
resource "aws_secretsmanager_secret" "consul_agent_token" {
  name = local.secret_names["consul-agent-token"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "consul_gossip_key" {
  name = local.secret_names["consul-gossip-key"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "nomad_client_consul_token" {
  name = local.secret_names["nomad-client-consul-token"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "nomad_gossip_key" {
  name = local.secret_names["nomad-gossip-key"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "nomad_server_consul_token" {
  name = local.secret_names["nomad-server-consul-token"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "nomad_vault_token" {
  name = local.secret_names["nomad-vault-token"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "vault_consul_token" {
  name = local.secret_names["vault-consul-token"]
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# IAM Policies

# Policy for unsealing Vault via KMS
resource "aws_iam_policy" "vault_kms" {
  name        = "resinstack-vault-kms-${var.cluster_tag}"
  description = "Permits unsealing Vault via KMS operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
        Resource = [aws_kms_key.vault_unseal.arn]
      }
    ]
  })
}

# Policy for describing EC2 instances (ResinStackReadTags)
resource "aws_iam_policy" "read_tags" {
  name        = "resinstack-read-tags-${var.cluster_tag}"
  description = "ResinStackReadTags - Permits describing EC2 instances"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = ["*"]
      }
    ]
  })
}

# Policy for retrieving client secret values from Secrets Manager
resource "aws_iam_policy" "client_keys" {
  name        = "resinstack-client-keys-${var.cluster_tag}"
  description = "Permits retrieving client secret values from Secrets Manager"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          "${local.arn_prefix}resinstack-consul-agent-token-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-consul-gossip-key-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-nomad-client-consul-token-${var.cluster_tag}-*"
        ]
      }
    ]
  })
}

# Policy for retrieving Nomad server secret values from Secrets Manager
resource "aws_iam_policy" "nomad_keys" {
  name        = "resinstack-nomad-keys-${var.cluster_tag}"
  description = "Permits retrieving Nomad server secret values from Secrets Manager"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          "${local.arn_prefix}resinstack-consul-agent-token-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-consul-gossip-key-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-nomad-gossip-key-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-nomad-server-consul-token-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-nomad-vault-token-${var.cluster_tag}-*"
        ]
      }
    ]
  })
}

# Policy for retrieving Consul server secret values from Secrets Manager
resource "aws_iam_policy" "consul_keys" {
  name        = "resinstack-consul-keys-${var.cluster_tag}"
  description = "Permits retrieving Consul server secret values from Secrets Manager"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          "${local.arn_prefix}resinstack-consul-gossip-key-${var.cluster_tag}-*"
        ]
      }
    ]
  })
}

# Policy for retrieving Vault server secret values from Secrets Manager
resource "aws_iam_policy" "vault_keys" {
  name        = "resinstack-vault-keys-${var.cluster_tag}"
  description = "Permits retrieving Vault server secret values from Secrets Manager"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [
          "${local.arn_prefix}resinstack-consul-gossip-key-${var.cluster_tag}-*",
          "${local.arn_prefix}resinstack-vault-consul-token-${var.cluster_tag}-*"
        ]
      }
    ]
  })
}

# Machine Roles (dynamically created from machine_roles variable)
resource "aws_iam_role" "machine" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  max_session_duration = 43200
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action    = ["sts:AssumeRole"]
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# Instance Profiles (dynamically created from machine_roles variable)
resource "aws_iam_instance_profile" "machine" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.machine[each.key].name
}

# Policy Attachments (conditionally attached based on policy identifiers in each role)

resource "aws_iam_role_policy_attachment" "read_tags" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "read-tags")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.read_tags.arn
}

resource "aws_iam_role_policy_attachment" "vault_kms" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "vault-kms")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.vault_kms.arn
}

resource "aws_iam_role_policy_attachment" "client_keys" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "client-keys")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.client_keys.arn
}

resource "aws_iam_role_policy_attachment" "nomad_keys" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "nomad-keys")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.nomad_keys.arn
}

resource "aws_iam_role_policy_attachment" "consul_keys" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "consul-keys")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.consul_keys.arn
}

resource "aws_iam_role_policy_attachment" "vault_keys" {
  for_each = {
    for role_name, identifiers in var.machine_roles :
    role_name => role_name if contains(tolist(identifiers), "vault-keys")
  }

  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.vault_keys.arn
}

# Outputs
output "vault_kms_key_id" {
  value = aws_kms_key.vault_unseal.key_id
}

output "secret_names" {
  value = local.secret_names
}

output "machine_role_names" {
  value = {
    for role_name, _ in var.machine_roles :
    role_name => aws_iam_role.machine[role_name].name
  }
}

output "instance_profile_names" {
  value = {
    for role_name, _ in var.machine_roles :
    role_name => aws_iam_instance_profile.machine[role_name].name
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  env_prefix = "elluis_codes_limited_network"
  az_names   = data.aws_availability_zones.available.names
  az_offsets = [11, 22, 33]
}

resource "aws_vpc" "main" {
  cidr_block           = "64.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = local.env_prefix
    Environment = local.env_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.env_prefix}-igw"
    Environment = local.env_prefix
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, local.az_offsets[count.index])
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.env_prefix}-public-${count.index}"
    Environment = local.env_prefix
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, local.az_offsets[count.index] + 100)
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.env_prefix}-private-${count.index}"
    Environment = local.env_prefix
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.env_prefix}-public-rt"
    Environment = local.env_prefix
  }
}

resource "aws_route" "public_to_igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  tags = {
    Name        = "${local.env_prefix}-nat-eip-${count.index}"
    Environment = local.env_prefix
  }
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name        = "${local.env_prefix}-nat-${count.index}"
    Environment = local.env_prefix
  }
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.env_prefix}-private-rt-${count.index}"
    Environment = local.env_prefix
  }
}

resource "aws_route" "private_to_nat" {
  count = 3

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id

  lifecycle {
    ignore_changes = [
      nat_gateway_id,
      route_table_id,
    ]
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "creation_token" {
  description = "EFS file system creation token"
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "EFS performance mode (generalPurpose or maxIO)"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "EFS throughput mode (bursting or provisioned)"
  type        = string
  default     = "bursting"
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets (default: auto-created subnets)"
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of security group IDs for EFS mount targets (default: auto-created security group)"
  type        = list(string)
  default     = null
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Supporting network infrastructure
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "efs-vpc"
  }
}

resource "aws_subnet" "default" {
  count  = length(data.aws_availability_zones.available.names)
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "efs-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "default" {
  name        = "efs-mount-targets"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id
}

# ---------------------------------------------------------------------------
# KMS key for EFS encryption (with key rotation enabled)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS file system encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------------------------------------------------------------------
# EFS file system (encrypted, with lifecycle policy)
# ---------------------------------------------------------------------------

resource "aws_efs_file_system" "shared" {
  creation_token   = var.creation_token
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# EFS mount targets (one per subnet, attached to security groups)
# ---------------------------------------------------------------------------

locals {
  efs_subnet_ids = var.subnet_ids != null ? var.subnet_ids : aws_subnet.default[*].id
  efs_sg_ids     = var.security_group_ids != null ? var.security_group_ids : [aws_security_group.default.id]
}

resource "aws_efs_mount_target" "this" {
  count           = length(local.efs_subnet_ids)
  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = local.efs_subnet_ids[count.index]
  security_groups = local.efs_sg_ids
}

variable "user_name" {
  description = "Name of the IAM user for cert-manager"
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID for DNS record management scope"
  type        = string
  default     = "*"
}

resource "aws_iam_user" "cert_manager" {
  name = var.user_name
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

resource "aws_ssm_parameter" "access_key" {
  name  = "/cert-manager/access-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.id
}

resource "aws_ssm_parameter" "secret_key" {
  name  = "/cert-manager/secret-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.secret
}

resource "aws_iam_policy" "cert_manager_dns" {
  name        = "cert-manager-dns"
  description = "Policy for cert-manager to manage Route 53 DNS records for TLS certificate validation"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "route53:GetChange"
        Resource = "arn:aws:route53:::change/*"
      },
      {
        Effect = "Allow"
        Action = [
          "route53:ChangeResourceRecordSets",
          "route53:ListResourceRecordSets"
        ]
        Resource = "arn:aws:route53:::hostedzone/${var.hosted_zone_id}"
      },
      {
        Effect   = "Allow"
        Action   = "route53:ListHostedZonesByName"
        Resource = "*"
      }
    ]
  })
}

# ============================================================
# GuardDuty Threat Detection & Findings Export Infrastructure
# ============================================================

# ------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------

variable "enable_detector" {
  description = "Enable or disable the primary GuardDuty detector"
  type        = bool
  default     = true
}

variable "datasources" {
  description = "Configuration for GuardDuty data sources"
  type = object({
    s3_logs_enabled      = optional(bool, false)
    kubernetes_enabled   = optional(bool, false)
    malware_scan_enabled = optional(bool, false)
  })
  default = {
    s3_logs_enabled      = false
    kubernetes_enabled   = false
    malware_scan_enabled = false
  }
}

variable "finding_publish_frequency" {
  description = "Frequency for publishing GuardDuty findings"
  type        = string
  default     = "FIFTEEN_MINUTES"
  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publish_frequency)
    error_message = "Valid values: FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS"
  }
}

variable "snapshot_retention_enabled" {
  description = "Toggle EBS snapshot retention policy (RETENTION_WITH_FINDING or NO_RETENTION)"
  type        = bool
  default     = false
}

variable "finding_filters" {
  description = "Custom GuardDuty finding filters"
  type = list(object({
    name             = string
    action           = string
    rank             = number
    finding_criteria = list(object({
      field  = string
      equals = list(string)
    }))
  }))
  default = []
}

variable "ip_sets" {
  description = "GuardDuty IP sets (allow/block lists)"
  type = list(object({
    name     = string
    format   = string
    location = string
  }))
  default = []
}

variable "threat_intel_sets" {
  description = "GuardDuty threat intelligence sets"
  type = list(object({
    name     = string
    format   = string
    location = string
  }))
  default = []
}

variable "publishing_destinations" {
  description = "GuardDuty finding publishing destinations"
  type = list(object({
    destination_type = string
    destination_arn  = string
    kms_key_arn      = string
  }))
  default = []
}

variable "replica_region" {
  description = "AWS region for the replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

# ------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ------------------------------------------------------------------

data "aws_availability_zones" "available" {}

data "aws_region" "current" {}

data "aws_caller_identity" "self" {}

# ------------------------------------------------------------------
# PROVIDER ALIAS FOR REPLICA REGION
# ------------------------------------------------------------------

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ------------------------------------------------------------------
# LOCAL VALUES
# ------------------------------------------------------------------

locals {
  enable_advanced_features = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 || length(var.publishing_destinations) > 0
  snapshot_retention_value = var.snapshot_retention_enabled ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
}

# ====================================================================
# 1. GUARDDUTY DETECTOR
# ====================================================================

resource "aws_guardduty_detector" "main" {
  enable                       = var.enable_detector
  finding_publishing_frequency = var.finding_publish_frequency

  datasources {
    s3_logs {
      enable = var.datasources.s3_logs_enabled
    }
    kubernetes {
      audit_logs {
        enable = var.datasources.kubernetes_enabled
      }
    }
  }
}

# ====================================================================
# 2. GUARDDUTY FINDING FILTERS
# ====================================================================

resource "aws_guardduty_filter" "finding_filters" {
  count       = length(var.finding_filters)
  detector_id = aws_guardduty_detector.main.id
  name        = var.finding_filters[count.index].name
  action      = var.finding_filters[count.index].action
  rank        = var.finding_filters[count.index].rank

  finding_criteria {
    dynamic "criterion" {
      for_each = var.finding_filters[count.index].finding_criteria
      content {
        field  = criterion.value.field
        equals = criterion.value.equals
      }
    }
  }
}

# ====================================================================
# 3. GUARDDUTY IP SETS
# ====================================================================

resource "aws_guardduty_ipset" "ip_sets" {
  count       = length(var.ip_sets)
  activate    = true
  detector_id = aws_guardduty_detector.main.id
  name        = var.ip_sets[count.index].name
  format      = var.ip_sets[count.index].format
  location    = var.ip_sets[count.index].location
}

# ====================================================================
# 4. GUARDDUTY THREAT INTELLIGENCE SETS
# ====================================================================

resource "aws_guardduty_threatintelset" "threat_intel_sets" {
  count       = length(var.threat_intel_sets)
  activate    = true
  detector_id = aws_guardduty_detector.main.id
  name        = var.threat_intel_sets[count.index].name
  format      = var.threat_intel_sets[count.index].format
  location    = var.threat_intel_sets[count.index].location
}

# ====================================================================
# 5. GUARDDUTY PUBLISHING DESTINATIONS
# ====================================================================

resource "aws_guardduty_publishing_destination" "publishing_destinations" {
  count            = length(var.publishing_destinations)
  detector_id      = aws_guardduty_detector.main.id
  destination_type = var.publishing_destinations[count.index].destination_type
  destination_arn  = var.publishing_destinations[count.index].destination_arn
  kms_key_arn      = var.publishing_destinations[count.index].kms_key_arn
}

# ====================================================================
# 6. LOCAL-EXEC PROVISIONER FOR EBS SNAPSHOT PRESERVATION
# ====================================================================

resource "null_resource" "snapshot_preservation" {
  provisioner "local-exec" {
    command = "echo 'Setting EBS snapshot preservation to ${local.snapshot_retention_value}'"
  }
}

# ====================================================================
# 7. CONDITIONAL ADVANCED INFRASTRUCTURE
#    (provisioned when IP sets, threat intel sets, or S3 publishing
#     destinations are configured)
# ====================================================================

# ------------------------------------------------------------------
# 7a. KMS KEY – PRIMARY REGION
# ------------------------------------------------------------------

resource "aws_kms_key" "primary" {
  count                   = local.enable_advanced_features ? 1 : 0
  description             = "GuardDuty findings encryption key (Primary)"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  is_enabled              = true
}

# ------------------------------------------------------------------
# 7b. KMS KEY – REPLICA REGION
# ------------------------------------------------------------------

resource "aws_kms_key" "replica" {
  count                   = local.enable_advanced_features ? 1 : 0
  provider                = aws.replica
  description             = "GuardDuty findings encryption key (Replica – ${var.replica_region})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  is_enabled              = true
}

# ------------------------------------------------------------------
# 7c. PRIMARY S3 BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  count         = local.enable_advanced_features ? 1 : 0
  bucket        = "guardduty-findings-primary-${data.aws_region.current.region}"
  force_destroy = false

  logging {
    target_bucket = aws_s3_bucket.logging[0].id
    target_prefix = "access-logs/"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# 7d. VERSIONING – PRIMARY BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "primary" {
  count  = local.enable_advanced_features ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------
# 7e. SERVER-SIDE ENCRYPTION – PRIMARY BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count  = local.enable_advanced_features ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary[0].key_id
    }
  }
}

# ------------------------------------------------------------------
# 7f. PUBLIC ACCESS BLOCK – PRIMARY BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "primary" {
  count                   = local.enable_advanced_features ? 1 : 0
  bucket                  = aws_s3_bucket.primary[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------
# 7g. DEDICATED S3 LOGGING BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket" "logging" {
  count         = local.enable_advanced_features ? 1 : 0
  bucket        = "guardduty-findings-logs-${data.aws_region.current.region}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# 7h. PUBLIC ACCESS BLOCK – LOGGING BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = local.enable_advanced_features ? 1 : 0
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------
# 7i. IAM REPLICATION ROLE
# ------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count              = local.enable_advanced_features ? 1 : 0
  name               = "guardduty-replication-role-${data.aws_region.current.region}"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# 7j. IAM REPLICATION POLICY
# ------------------------------------------------------------------

resource "aws_iam_role_policy" "replication" {
  count = local.enable_advanced_features ? 1 : 0
  name  = "guardduty-replication-policy-${data.aws_region.current.region}"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ReplicateObject",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.primary[0].arn,
          "${aws_s3_bucket.primary[0].arn}/*"
        ]
      },
      {
        Effect   = "Allow"
        Action   = [
          "s3:PutObject",
          "s3:ReplicateObject",
          "s3:ReplicateTags"
        ]
        Resource = [
          "arn:aws:s3:::guardduty-findings-replica-${var.replica_region}",
          "arn:aws:s3:::guardduty-findings-replica-${var.replica_region}/*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------
# 7k. REPLICA S3 BUCKET (in replica region)
# ------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count         = local.enable_advanced_features ? 1 : 0
  provider      = aws.replica
  bucket        = "guardduty-findings-replica-${var.replica_region}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# 7l. VERSIONING – REPLICA BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.enable_advanced_features ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------
# 7m. PUBLIC ACCESS BLOCK – REPLICA BUCKET
# ------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "replica" {
  count                   = local.enable_advanced_features ? 1 : 0
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

variable "name_prefix" {
  description = "Name prefix for all IAM roles and profiles"
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

locals {
  prefix = var.name_prefix
}

# ---------------------------------------------------------------------------
# 1. EMR Service Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "emr_service" {
  name        = "${local.prefix}-emr-service-role"
  description = "IAM role for the EMR service to manage cluster resources"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "emr_service" {
  name = "${local.prefix}-emr-service-policy"
  role = aws_iam_role.emr_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:TerminateInstances",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:RebootInstances",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeTags",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeImages"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole",
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetBucketPolicy"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "elasticmapreduce:*"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ],
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 2. EC2 Instance Profile Role (with attached CloudWatch and SSM policies)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2_instance_profile" {
  name        = "${local.prefix}-ec2-instance-profile-role"
  description = "IAM role attached to EC2 instances within the EMR cluster"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

# CloudWatch policy attached to the EC2 instance profile role
resource "aws_iam_role_policy" "ec2_cloudwatch" {
  name = "${local.prefix}-ec2-cloudwatch-policy"
  role = aws_iam_role.ec2_instance_profile.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ],
        Resource = "*"
      }
    ]
  })
}

# SSM policy attached to the EC2 instance profile role
resource "aws_iam_role_policy" "ec2_ssm" {
  name = "${local.prefix}-ec2-ssm-policy"
  role = aws_iam_role.ec2_instance_profile.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:DescribeParameters",
          "ssm:GetParameters",
          "ssm:GetParameter",
          "ssm:StartSession",
          "ssm:ResumeSession",
          "ssm:TerminateSession",
          "ssm:DescribeSessions"
        ],
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. EMR Autoscaling Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "emr_autoscaling" {
  name        = "${local.prefix}-emr-autoscaling-role"
  description = "IAM role for EMR autoscaling operations"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy" "emr_autoscaling" {
  name = "${local.prefix}-emr-autoscaling-policy"
  role = aws_iam_role.emr_autoscaling.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticmapreduce:CreateScheduledAction",
          "elasticmapreduce:UpdateScheduledAction",
          "elasticmapreduce:DeleteScheduledAction",
          "elasticmapreduce:DescribeScheduledActions",
          "elasticmapreduce:CreateTimedAction",
          "elasticmapreduce:UpdateTimedAction",
          "elasticmapreduce:DeleteTimedAction",
          "elasticmapreduce:DescribeTimedActions",
          "elasticmapreduce:ModifyInstanceGroups",
          "elasticmapreduce:DescribeInstanceGroups",
          "elasticmapreduce:ListClusters",
          "elasticmapreduce:DescribeCluster"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeTags"
        ],
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 4. EC2 Instance Profile
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "${local.prefix}-ec2-instance-profile"
  role = aws_iam_role.ec2_instance_profile.name
  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "emr_service_role_arn" {
  description = "ARN of the EMR service role"
  value       = aws_iam_role.emr_service.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role"
  value       = aws_iam_role.emr_service.name
}

output "emr_service_role_id" {
  description = "Unique ID of the EMR service role"
  value       = aws_iam_role.emr_service.id
}

output "ec2_instance_profile_role_arn" {
  description = "ARN of the EC2 instance profile role"
  value       = aws_iam_role.ec2_instance_profile.arn
}

output "ec2_instance_profile_role_name" {
  description = "Name of the EC2 instance profile role"
  value       = aws_iam_role.ec2_instance_profile.name
}

output "ec2_instance_profile_role_id" {
  description = "Unique ID of the EC2 instance profile role"
  value       = aws_iam_role.ec2_instance_profile.id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.name
}

output "emr_autoscaling_role_id" {
  description = "Unique ID of the EMR autoscaling role"
  value       = aws_iam_role.emr_autoscaling.id
}

output "ec2_instance_profile_id" {
  description = "ID of the EC2 instance profile"
  value       = aws_iam_instance_profile.ec2_profile.id
}

output "ec2_instance_profile_arn" {
  description = "ARN of the EC2 instance profile"
  value       = aws_iam_instance_profile.ec2_profile.arn
}

output "ec2_instance_profile_name" {
  description = "Name of the EC2 instance profile"
  value       = aws_iam_instance_profile.ec2_profile.name
}

variable "cognito_user_pool_arn" {
  type        = string
  default     = ""
  description = "Optional Cognito user pool ARN for granting cognito-idp:AdminInitiateAuth permission"
}

resource "aws_iam_user" "postman_user" {
  name = "postman-user"
  path = "/"
}

resource "aws_iam_access_key" "postman_user_key" {
  user = aws_iam_user.postman_user.name
}

resource "aws_iam_user_policy" "api_gateway_readonly" {
  name   = "api-gateway-readonly"
  user   = aws_iam_user.postman_user.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "apigateway:GET",
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "cloudwatch_metrics_readonly" {
  name   = "cloudwatch-metrics-readonly"
  user   = aws_iam_user.postman_user.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "cognito_admin_initiate_auth" {
  count = length(var.cognito_user_pool_arn) > 0 ? 1 : 0
  name   = "cognito-admin-initiate-auth"
  user   = aws_iam_user.postman_user.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:AdminInitiateAuth",
        ]
        Effect   = "Allow"
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

variable "cluster_name" {
  type        = string
  default     = "legion"
  description = "Name of the EKS cluster, used as a suffix when naming IAM roles and policies"
}

locals {
  master_role_name        = "tf-${var.cluster_name}"
  worker_role_name        = "tf-${var.cluster_name}-node"
  profile_name            = "tf-${var.cluster_name}-node"
  autoscaling_policy_name = "eks-worker-autoscaling-${var.cluster_name}"
}

# ── Master IAM Role (EKS Control Plane) ──────────────────────────────────────

resource "aws_iam_role" "master" {
  name = local.master_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action   = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "master_eks_cluster" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_eks_service" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

# ── Worker IAM Role (EKS Node) ───────────────────────────────────────────────

resource "aws_iam_role" "worker" {
  name = local.worker_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action   = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker_eks_node" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_eks_cni" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "worker_ec2_registry" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ── Custom Auto‑Scaling Policy ──────────────────────────────────────────────

resource "aws_iam_policy" "worker_autoscaling" {
  name = local.autoscaling_policy_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeTags",
          "autoscaling:DescribeLaunchTemplateVersions"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}" = "owned"
            "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"        = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker_autoscaling_attach" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

# ── EC2 Instance Profile (mapped to the worker role) ─────────────────────────

resource "aws_iam_instance_profile" "worker" {
  name = local.profile_name
  role = aws_iam_role.worker.name
}

locals {
  vpc_cidr     = "172.69.0.0/16"
  public_cidr  = "172.69.1.0/24"
  private_cidr = "172.69.2.0/24"
  vpc_tag      = "vpc_name"
  public_tag   = "public_subnet"
  private_tag  = "private_subnet"
  igw_tag      = "igw_tag"
  rtb_tag      = "rtb_tag"
  web_sg_tag   = "web-server_security_group"
}

resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr

  tags = {
    Name = local.vpc_tag
  }
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = local.public_cidr

  tags = {
    Name = local.public_tag
  }
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = local.private_cidr

  tags = {
    Name = local.private_tag
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.igw_tag
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = local.rtb_tag
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Web server security group for VPC ${aws_vpc.main.id}"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = local.web_sg_tag
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Database security group for VPC ${aws_vpc.main.id}"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "database-security_group"
  }
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# ── IAM Policies ────────────────────────────────────────────────

resource "aws_iam_policy" "aws_ccm_k8s_controlplane" {
  name        = "aws_ccm_k8s_controlplane"
  description = "IAM policy for AWS CCM Kubernetes control plane nodes"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:AttachNetworkInterface",
          "ec2:DetachNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:DescribeVpcs",
          "ec2:CreateVpc",
          "ec2:DeleteVpc",
          "ec2:DescribeSubnets",
          "ec2:CreateSubnet",
          "ec2:DeleteSubnet",
          "ec2:DescribeSecurityGroups",
          "ec2:CreateSecurityGroup",
          "ec2:DeleteSecurityGroup",
          "ec2:DescribeRouteTables",
          "ec2:CreateRouteTable",
          "ec2:DeleteRouteTable",
          "ec2:DescribeInternetGateways",
          "ec2:CreateInternetGateway",
          "ec2:AttachInternetGateway",
          "ec2:DetachInternetGateway",
          "ec2:DeleteInternetGateway",
          "ec2:DescribeNatGateways",
          "ec2:CreateNatGateway",
          "ec2:DeleteNatGateway",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeRegions"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeAutoScalingNotificationConfigurations",
          "autoscaling:DescribeAutoScalingPolicies",
          "autoscaling:DescribeScalingProcessActivities",
          "autoscaling:DescribeTags"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:ModifyLoadBalancerAttributes",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:SetSubnets",
          "elasticloadbalancing:SetSecurityGroups",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:RemoveTags"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:DescribeKey",
          "kms:ListKeys",
          "kms:ListAliases"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "aws_ccm_k8s_worker" {
  name        = "aws_ccm_k8s_worker"
  description = "IAM policy for AWS CCM Kubernetes worker nodes"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeRegions",
          "ec2:DescribeAvailabilityZones"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:ListImages"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ── IAM Roles ───────────────────────────────────────────────────

resource "aws_iam_role" "aws_ccm_k8s_controlplane" {
  name        = "aws_ccm_k8s_controlplane"
  description = "IAM role for AWS CCM Kubernetes control plane nodes"
  assume_role_policy = jsonencode({
