  }
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "awscademo-"
}

locals {
  default_tags = {
    Contact          = "awscademo"
    DeploymentMethod = "terraform"
    DeploymentDate   = "20261006"
    TTL              = "infinite"
  }
  role_name = substr("${var.name_prefix}admin-role", 0, 31)
}

data "aws_caller_identity" "current" {}

# Custom self-management policy for demo users
resource "aws_iam_policy" "self_management" {
  name        = "${var.name_prefix}self-management"
  description = "Policy allowing users to manage their own credentials and MFA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:CreateVirtualMFADevice",
          "iam:ResyncMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Effect = "Allow"
        Action = "iam:DeactivateMFADevice"
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
  tags = local.default_tags
}

# Demo users group
resource "aws_iam_group" "demo_users" {
  name = "${var.name_prefix}demo-users"
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Read-only users group
resource "aws_iam_group" "read_only_users" {
  name = "${var.name_prefix}readonly-users"
}

resource "aws_iam_group_policy_attachment" "read_only_users_readonly" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

# Admin role policy - full admin permissions conditioned on MFA
resource "aws_iam_policy" "admin_role_policy" {
  name        = "${var.name_prefix}admin-full-access"
  description = "Full administrator access conditioned on MFA presence"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
  tags = local.default_tags
}

# Admin role with root assume-role access
resource "aws_iam_role" "admin" {
  name                 = local.role_name
  description          = "Administrative role requiring MFA for assume-role access"
  max_session_duration = 43200
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
  tags = local.default_tags
}

resource "aws_iam_role_policy_attachment" "admin_role_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_role_policy.arn
}

# MFA superadmin group
resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name_prefix}mfa-superadmin"
}

# Policy for MFA superadmin group to assume the admin role with MFA
resource "aws_iam_policy" "mfa_superadmin_assume_role" {
  name        = "${var.name_prefix}assume-admin-role"
  description = "Allows MFA superadmin group members to assume the admin role when MFA is present"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
  tags = local.default_tags
}

resource "aws_iam_group_policy_attachment" "mfa_superadmin_assume_role" {
  group      = aws_iam_group.mfa_superadmin.name
  policy_arn = aws_iam_policy.mfa_superadmin_assume_role.arn
}

# Variables
variable "namespace" {
  description = "Namespace for CloudPosse label module"
  type        = string
  default     = "iac"
}

variable "environment" {
  description = "Environment for CloudPosse label module"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Base name for CloudPosse label module"
  type        = string
  default     = "access"
}

variable "tags" {
  description = "Tags map for CloudPosse label module"
  type        = map(string)
  default     = {}
}

variable "attributes" {
  description = "Additional attributes for CloudPosse label module"
  type        = list(string)
  default     = []
}

variable "admin_users" {
  description = "List of admin user names"
  type        = list(string)
  default     = []
}

variable "non_admin_users" {
  description = "List of non-admin user names"
  type        = list(string)
  default     = []
}

# Data Sources
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# CloudPosse Label Modules
module "admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = "${var.name}-admin"
  tags        = var.tags
  attributes  = var.attributes
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = "${var.name}-non-admin"
  tags        = var.tags
  attributes  = var.attributes
}

# IAM Users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)
  name     = each.key
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)
  name     = each.key
}

# IAM Groups
resource "aws_iam_group" "admin" {
  name = module.admin_label.id
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
}

# Policy Documents using the data source
data "aws_iam_policy_document" "self_management" {
  statement {
    sid     = "SelfManagePasswordsAndKeys"
    effect  = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:CreateVirtualMFADevice",
      "iam:DeleteAccessKey",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccessKeys",
      "iam:ListVirtualMFADevices",
      "iam:UpdateAccessKey",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
    ]
  }
  statement {
    sid     = "DeactivateMFADeviceWithMFA"
    effect  = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid     = "AssumeAdminRoleWithMFA"
    effect  = "Allow"
    actions = [
      "sts:AssumeRole",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/${module.admin_label.id}-admin-role",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "AllowAccountRootToAssumeWithMFA"
    effect  = "Allow"
    actions = [
      "sts:AssumeRole",
    ]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# IAM Group Policies
resource "aws_iam_group_policy" "self_management_admin" {
  name   = "${module.admin_label.id}-self-management"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy" "self_management_non_admin" {
  name   = "${module.non_admin_label.id}-self-management"
  group  = aws_iam_group.non_admin.name
  policy = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy" "assume_admin_role" {
  name   = "${module.admin_label.id}-assume-admin-role"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.assume_admin_role.json
}

# IAM Role (using manually constructed trust policy because of Principal requirement)
locals {
  admin_role_trust_json = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAccountRootToAssumeWithMFA"
        Effect   = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
    ]
  })
}

resource "aws_iam_role" "admin" {
  name               = "${module.admin_label.id}-admin-role"
  assume_role_policy = local.admin_role_trust_json
}

# IAM Role Policy Attachment (AdministratorAccess)
resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

# IAM Group Memberships (conditional)
resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0
  name  = "${module.admin_label.id}-membership"
  group = aws_iam_group.admin.name
  users = var.admin_users

  depends_on = [aws_iam_user.admin]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0
  name  = "${module.non_admin_label.id}-membership"
  group = aws_iam_group.non_admin.name
  users = var.non_admin_users

  depends_on = [aws_iam_user.non_admin]
}

locals {
  vpc_cidr      = "10.0.0.0/16"
  public_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_cidrs = ["10.0.10.0/24", "10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr

  tags = {
    Name = "dev-test-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dev-test-igw"
  }
}

# ---------------------------------------------------------------------------
# Public subnets (2 AZs, 1 per AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-az${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Private subnets (2 per AZ = 4 total)
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 4

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index % 2]

  tags = {
    Name = "private-${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Public route table & associations
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Private route table & associations (no explicit routes)
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "private"
  }
}

resource "aws_route_table_association" "private" {
  count = 4

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Public security group
# ---------------------------------------------------------------------------
resource "aws_security_group" "public" {
  name        = "public-sg"
  description = "Public security group: inbound VPC-wide, SSH from VPC, HTTP from anywhere; outbound to VPC only"
  vpc_id      = aws_vpc.main.id
}

resource "aws_vpc_security_group_ingress_rule" "public_all_from_vpc" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = -1
  to_port           = -1
  ip_protocol       = "-1"
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh_from_vpc" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_http_from_anywhere" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_outbound_to_vpc" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = -1
  to_port           = -1
  ip_protocol       = "-1"
}

# ---------------------------------------------------------------------------
# Private security group
# ---------------------------------------------------------------------------
resource "aws_security_group" "private" {
  name        = "private-sg"
  description = "Private security group: inbound VPC-wide, outbound to VPC only"
  vpc_id      = aws_vpc.main.id
}

resource "aws_vpc_security_group_ingress_rule" "private_all_from_vpc" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = -1
  to_port           = -1
  ip_protocol       = "-1"
}

resource "aws_vpc_security_group_egress_rule" "private_outbound_to_vpc" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = -1
  to_port           = -1
  ip_protocol       = "-1"
}

variable "name_suffix" {
  description = "Suffix appended to all resource names"
  type        = string
  default     = ""
}

locals {
  role_name   = "prod-ci-${var.name_suffix}"
  policy_name = "prod-ci-${var.name_suffix}"
  group_name  = "prod-ci-${var.name_suffix}"
  user_name   = "prod-ci-${var.name_suffix}"
}

resource "aws_iam_role" "ci_cd" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "ci_cd_assume" {
  name   = local.policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.ci_cd.arn
      }
    ]
  })
}

resource "aws_iam_group" "ci_cd" {
  name = local.group_name
}

resource "aws_iam_group_policy_attachment" "ci_cd" {
  group      = aws_iam_group.ci_cd.name
  policy_arn = aws_iam_policy.ci_cd_assume.arn
}

resource "aws_iam_user" "ci_cd" {
  name = local.user_name
}

resource "aws_iam_group_membership" "ci_cd" {
  name  = local.group_name
  group = aws_iam_group.ci_cd.name
  users = [aws_iam_user.ci_cd.name]
}

# AWS Config Aggregator - collects configuration and compliance data
# across all AWS regions for the current AWS account

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  # Aggregate data from the current account across all regions
  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = {
    ManagedBy = "Terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  default     = "benchmark-vpc"
}

variable "additional_tags" {
  description = "Additional tags to apply to the VPC"
  default     = {}
  type        = map(string)
}

variable "ssh_inbound" {
  description = "CIDR blocks allowed for SSH inbound traffic"
  default     = ["10.0.0.0/16"]
  type        = list(string)
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  all_azs     = data.aws_availability_zones.available.names
  az_count    = length(local.all_azs)
  subnet_bits = ceil(log(local.az_count * 2, 2))
  vpc_tags    = merge({ Name = var.vpc_name }, var.additional_tags)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags                 = local.vpc_tags
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_bits, count.index)
  availability_zone       = local.all_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${local.all_azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_bits, local.az_count + count.index)
  availability_zone       = local.all_azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${local.all_azs[count.index]}"
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count = 1

  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-main"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public"
  }
}

resource "aws_route" "main_default" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name} Default"
  }
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = {
    Name = "${var.vpc_name} Default"
  }
}

resource "aws_security_group" "public" {
  name_prefix = "${var.vpc_name}-public-"
  description = "Security group for the public tier of ${var.vpc_name}"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public"
    Tier = "public"
  }
}

resource "aws_security_group_rule" "public_inbound_http" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_inbound_https" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_inbound_ssh" {
  count = length(var.ssh_inbound)

  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.ssh_inbound[count.index]]
}

resource "aws_security_group_rule" "public_outbound_http" {
  security_group_id = aws_security_group.public.id
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
}

resource "aws_security_group_rule" "public_outbound_https" {
  security_group_id = aws_security_group.public.id
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
}

resource "aws_security_group" "private" {
  name_prefix = "${var.vpc_name}-private-"
  description = "Security group for the private tier of ${var.vpc_name}"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private"
    Tier = "private"
  }
}

resource "aws_security_group_rule" "private_inbound_http" {
  security_group_id = aws_security_group.private.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public[*].cidr_block
}

resource "aws_security_group_rule" "private_inbound_https" {
  security_group_id = aws_security_group.private.id
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = aws_subnet.public[*].cidr_block
}

resource "aws_security_group_rule" "private_outbound_https" {
  security_group_id = aws_security_group.private.id
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
}

resource "aws_network_acl" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public"
    Tier = "public"
  }
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 10
  egress         = false
  rule_action    = "allow"
  from_port      = 80
  to_port        = 80
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 20
  egress         = false
  rule_action    = "allow"
  from_port      = 443
  to_port        = 443
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 30
  egress         = false
  rule_action    = "allow"
  from_port      = 1024
  to_port        = 65535
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count = length(var.ssh_inbound)

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  rule_action    = "allow"
  from_port      = 22
  to_port        = 22
  protocol       = "tcp"
  cidr_block     = var.ssh_inbound[count.index]
}

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 10
  egress         = true
  rule_action    = "allow"
  from_port      = 80
  to_port        = 80
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 20
  egress         = true
  rule_action    = "allow"
  from_port      = 443
  to_port        = 443
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 30
  egress         = true
  rule_action    = "allow"
  from_port      = 1024
  to_port        = 65535
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private"
    Tier = "private"
  }
}

resource "aws_network_acl_rule" "private_ingress_http" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 10 + count.index
  egress         = false
  rule_action    = "allow"
  from_port      = 80
  to_port        = 80
  protocol       = "tcp"
  cidr_block     = aws_subnet.public[count.index].cidr_block
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 20 + count.index
  egress         = false
  rule_action    = "allow"
  from_port      = 443
  to_port        = 443
  protocol       = "tcp"
  cidr_block     = aws_subnet.public[count.index].cidr_block
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 30
  egress         = false
  rule_action    = "allow"
  from_port      = 1024
  to_port        = 65535
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 10
  egress         = true
  rule_action    = "allow"
  from_port      = 443
  to_port        = 443
  protocol       = "tcp"
  cidr_block     = "0.0.0.0/0"
}

resource "aws_network_acl_rule" "private_egress_ephemeral_private" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 20 + count.index
  egress         = true
  rule_action    = "allow"
  from_port      = 1024
  to_port        = 65535
  protocol       = "tcp"
  cidr_block     = aws_subnet.private[count.index].cidr_block
}

resource "aws_network_acl_rule" "private_egress_ephemeral_public" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 30 + count.index
  egress         = true
  rule_action    = "allow"
  from_port      = 1024
  to_port        = 65535
  protocol       = "tcp"
  cidr_block     = aws_subnet.public[count.index].cidr_block
}

resource "aws_network_acl_association" "public" {
  count = local.az_count

  network_acl_id = aws_network_acl.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl_association" "private" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

locals {
  role_name    = "imagebuilder_role"
  profile_name = "imagebuilder_instance_profile"
}

data "aws_partition" "current" {}

resource "aws_iam_role" "imagebuilder" {
  name = local.role_name
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSImageBuilderFullAccess"
}

resource "aws_iam_instance_profile" "imagebuilder" {
  name = local.profile_name
  path = "/"
  role = aws_iam_role.imagebuilder.name

  lifecycle {
    prevent_destroy = true
  }
}

variable "role_name" {
  description = "Name of the IAM role for Tamr EC2 instances"
  type        = string
  default     = "tamr-instance-role"
}

variable "profile_name" {
  description = "Name of the IAM instance profile for Tamr EC2 instances"
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of an IAM permissions boundary policy to attach to the role"
  type        = string
  default     = null
}

variable "tags" {
  description = "A customizable map of resource tags to apply to all created resources"
  type        = map(string)
  default     = {}
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance" {
  name                 = var.role_name
  assume_role_policy   = data.aws_iam_policy_document.assume_role.json
  permissions_boundary = var.permissions_boundary_arn
  tags                 = var.tags
}

resource "aws_iam_instance_profile" "tamr_instance" {
  name = var.profile_name
  role = aws_iam_role.tamr_instance.name
  tags = var.tags
}

resource "aws_iam_role" "custom_sql_server_role" {
  name = "AWSRDSCustomSQLServerInstanceRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "custom_sql_server_policy_attach" {
  role       = aws_iam_role.custom_sql_server_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSCustomInstanceProfileRolePolicy"
}

resource "aws_iam_instance_profile" "custom_sql_server_instance_profile" {
  name = "AWSRDSCustomSQLServerInstanceProfile"
  role = aws_iam_role.custom_sql_server_role.name
}

variable "environment" {
  description = "Environment-specific name prefix (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "target_account_id" {
  description = "AWS account ID of the target account that hosts the S3 software installation files"
  type        = string
  default     = "123456789012"
}

variable "target_role_name" {
  description = "Name of the IAM role in the target account to assume for reading S3 software installation files"
  type        = string
  default     = "s3-software-install-reader"
}

locals {
  name_prefix = "packer-builder-${var.environment}"
}

resource "aws_iam_role" "packer_builder" {
  name = local.name_prefix

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "assume_target_role" {
  name = "${local.name_prefix}-assume-target-role"
  role = aws_iam_role.packer_builder.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = [
          "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
        ]
      }
    ]
  })
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "three-tier-vpc"
}

variable "region_name" {
  description = "Region for deployment"
  type        = string
  default     = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.16.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "presentation" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "presentation-subnet"
  }
}

resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "application-subnet"
  }
}

resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "data-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "three-tier-igw"
  }
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "presentation-route-table"
  }
}

resource "aws_route" "default_gateway" {
  route_table_id         = aws_route_table.presentation.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id     = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ── IAM Role: service-catalog-assumable with launch-constraint policy ────

resource "aws_iam_role" "test_role" {
  name        = "test_role"
  description = "Service Catalog assumable role with scoped launch-constraint policy"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "servicecatalog.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "launch_constraint" {
  name = "launch-constraint-policy"
  role = aws_iam_role.test_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "servicecatalog:LaunchProduct"
        Resource = "*"
        Condition = {
          StringEquals = {
            "servicecatalog:productType" = "terraform-approved-product"
          }
        }
      }
    ]
  })
}

# ── IAM Group ─────────────────────────────────────────────────────────────

resource "aws_iam_group" "test_group" {
  name = "test_group"

  lifecycle {
    prevent_destroy = true
  }
}

# ── IAM User (console-enabled) ────────────────────────────────────────────

resource "aws_iam_user" "test_user" {
  name = "test_user"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user_login_profile" "test_user" {
  user = aws_iam_user.test_user.name

  password_reset_required = true
}

# ── Group membership (user → group) ──────────────────────────────────────

resource "aws_iam_group_membership" "test_user" {
  name  = "test-user-membership"
  group = aws_iam_group.test_group.name
  users = [aws_iam_user.test_user.name]
}

# ── Group policy: allow members to assume the service-catalog role ───────

resource "aws_iam_group_policy" "test_group" {
  name  = "assume-service-catalog-role"
  group = aws_iam_group.test_group.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = aws_iam_role.test_role.arn
      }
    ]
  })
}

locals {
  vpc_cidr = "10.0.0.0/16"
  name     = "DatatogAgentlessScanner"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs  = [for i, az in local.azs : cidrsubnet(local.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i, az in local.azs : cidrsubnet(local.vpc_cidr, 8, i + 10)]

  default_tags = {
    Datadog                  = "true"
    DatadogAgentlessScanner  = "true"
  }

  enable_ssm_endpoints = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.default_tags, {
    Name = local.name
  })
}

# ---------------------------------------------------------------------------
# Public subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "${local.name}-public-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Private subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.default_tags, {
    Name = "${local.name}-private-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.default_tags, {
    Name = "${local.name}-igw"
  })
}

# ---------------------------------------------------------------------------
# Public route table
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.default_tags, {
    Name = "${local.name}-public"
  })
}

resource "aws_route_table_association" "public" {
  count = length(local.azs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic IP and NAT Gateway (first public subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.default_tags, {
    Name = "${local.name}-nat"
  })
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.default_tags, {
    Name = "${local.name}-nat"
  })

  depends_on = [aws_internet_gateway.this]
}

# ---------------------------------------------------------------------------
# Private route table
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(local.default_tags, {
    Name = "${local.name}-private"
  })
}

resource "aws_route_table_association" "private" {
  count = length(local.azs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# S3 Gateway VPC Endpoint
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.this.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = [
    aws_route_table.public.id,
    aws_route_table.private.id,
  ]

  tags = merge(local.default_tags, {
    Name = "${local.name}-s3-endpoint"
  })
}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Interface VPC Endpoint Security Group
# ---------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name}-vpc-endpoints"
  description = "Allow HTTPS from VPC CIDR to interface VPC endpoints"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow HTTPS outbound to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.default_tags, {
    Name = "${local.name}-vpc-endpoints"
  })
}

# ---------------------------------------------------------------------------
# Lambda Interface VPC Endpoint
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.lambda"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids = aws_subnet.private[*].id

  security_group_ids = [
    aws_security_group.vpc_endpoints.id,
  ]

  tags = merge(local.default_tags, {
    Name = "${local.name}-lambda-endpoint"
  })
}

# ---------------------------------------------------------------------------
# EBS Interface VPC Endpoint
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.this.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ebs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids = aws_subnet.private[*].id

  security_group_ids = [
    aws_security_group.vpc_endpoints.id,
  ]

  tags = merge(local.default_tags, {
    Name = "${local.name}-ebs-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Optional SSM Interface VPC Endpoints
# ---------------------------------------------------------------------------
locals {
  ssm_service_names = compact([
    "com.amazonaws.${data.aws_region.current.name}.ssm",
    "com.amazonaws.${data.aws_region.current.name}.ssmmessages",
    "com.amazonaws.${data.aws_region.current.name}.ec2messages",
  ])

  ssm_endpoint_names = [
    "ssm",
    "ssmmessages",
    "ec2messages",
  ]
}

resource "aws_vpc_endpoint" "ssm" {
  count = local.enable_ssm_endpoints ? length(local.ssm_service_names) : 0

  vpc_id              = aws_vpc.this.id
  service_name        = local.ssm_service_names[count.index]
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids = aws_subnet.private[*].id

  security_group_ids = [
    aws_security_group.vpc_endpoints.id,
  ]

  tags = merge(local.default_tags, {
    Name = "${local.name}-${local.ssm_endpoint_names[count.index]}-endpoint"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

################################################################################
# Module toggle / mode selection
################################################################################

variable "enabled" {
  description = "Main toggle that controls whether this module creates any resources."
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "When true a new security group is created. When false the supplied security_group_id is managed instead."
  type        = bool
  default     = true
}

variable "security_group_id" {
  description = "Existing security group ID that rules are attached to when create_security_group is false."
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID that hosts the new security group. When null a fallback VPC is created."
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the fallback VPC that is created when no vpc_id is supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "security_group_description" {
  description = "Description applied to the newly created security group."
  type        = string
  default     = "Managed by Terraform"
}

################################################################################
# Label module inputs (git based naming / tagging)
################################################################################

variable "name" {
  description = "Base name passed to the label module. Suffixes such as -sg and -prefix-list are appended to it."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment passed to the label module (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "delimiter" {
  description = "Delimiter used by the label module when assembling names."
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes passed to the label module."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags passed to the label module."
  type        = map(string)
  default     = {}
}

################################################################################
# Managed prefix list
################################################################################

variable "create_prefix_list" {
  description = "Whether to create a managed prefix list. Ignored when pre-existing prefix_list_ids are supplied."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Pre-existing managed prefix list IDs. When non-empty no new prefix list is created."
  type        = list(string)
  default     = []
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list. A maximum of 5 entries is supported."
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the managed prefix list."
  type        = number
  default     = 5
}

################################################################################
# Ingress rule inputs (categorised by source type)
################################################################################

variable "ingress_cidr_blocks" {
  description = "Ingress rules sourced from IPv4/IPv6 CIDR blocks."
  type = list(object({
    description      = optional(string, "")
    from_port        = number
    to_port          = number
    protocol         = optional(string, "tcp")
    cidr_blocks      = list(string)
    ipv6_cidr_blocks = optional(list(string), [])
  }))
  default = []
}

variable "ingress_self" {
  description = "Ingress rules that allow the security group to reference itself."
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = optional(string, "tcp")
  }))
  default = []
}

variable "ingress_source_security_group_ids" {
  description = "Ingress rules sourced from other security group IDs."
  type = list(object({
    description              = optional(string, "")
    from_port                = number
    to_port                  = number
    protocol                 = optional(string, "tcp")
    source_security_group_id = string
  }))
  default = []
}

variable "ingress_prefix_list_ids" {
  description = "Ingress rules sourced from managed prefix lists. When prefix_list_ids is omitted the created prefix list is used."
  type = list(object({
    description     = optional(string, "")
    from_port       = number
    to_port         = number
    protocol        = optional(string, "tcp")
    prefix_list_ids = optional(list(string), [])
  }))
  default = []
}

################################################################################
# Egress rule inputs (categorised by source type)
################################################################################

variable "egress_cidr_blocks" {
  description = "Egress rules sourced from IPv4/IPv6 CIDR blocks."
  type = list(object({
    description      = optional(string, "")
    from_port        = number
    to_port          = number
    protocol         = optional(string, "tcp")
    cidr_blocks      = list(string)
    ipv6_cidr_blocks = optional(list(string), [])
  }))
  default = []
}

variable "egress_self" {
  description = "Egress rules that allow the security group to reference itself."
  type = list(object({
    description = optional(string, "")
    from_port   = number
    to_port     = number
    protocol    = optional(string, "tcp")
  }))
  default = []
}

variable "egress_source_security_group_ids" {
  description = "Egress rules sourced from other security group IDs."
  type = list(object({
    description              = optional(string, "")
    from_port                = number
    to_port                  = number
    protocol                 = optional(string, "tcp")
    source_security_group_id = string
  }))
  default = []
}

variable "egress_prefix_list_ids" {
  description = "Egress rules sourced from managed prefix lists. When prefix_list_ids is omitted the created prefix list is used."
  type = list(object({
    description     = optional(string, "")
    from_port       = number
    to_port         = number
    protocol        = optional(string, "tcp")
    prefix_list_ids = optional(list(string), [])
  }))
  default = []
}

################################################################################
# Naming and tagging through the shared label module
################################################################################

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  delimiter   = var.delimiter
  attributes  = var.attributes
  enabled     = var.enabled
}

locals {
  enabled               = var.enabled
  create_security_group = local.enabled && var.create_security_group
  use_existing_sg       = local.enabled && !var.create_security_group
  create_vpc            = local.create_security_group && var.vpc_id == null

  base_name        = module.labels.id
  sg_name          = "${local.base_name}-sg"
  prefix_list_name = "${local.base_name}-prefix-list"
  vpc_name         = "${local.base_name}-vpc"

  tags = merge(module.labels.tags, var.tags)
}

################################################################################
# Fallback VPC (only when a new security group is requested without a vpc_id)
################################################################################

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = local.vpc_name })
}

################################################################################
# Optional managed prefix list
################################################################################

locals {
  create_prefix_list = local.enabled && var.create_prefix_list && length(var.prefix_list_ids) == 0

  # Prefix list IDs used when a rule does not specify its own list.
  default_prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : aws_ec2_managed_prefix_list.this[*].id

  resolved_vpc_id = try(coalesce(one(aws_vpc.this[*].id), var.vpc_id), null)

  resolved_security_group_id = try(coalesce(one(aws_security_group.this[*].id), var.security_group_id), null)
}

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(local.tags, { Name = local.prefix_list_name })
}

################################################################################
# Normalised ingress / egress rules
################################################################################

locals {
  ingress_rules = concat(
    [for r in var.ingress_cidr_blocks : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = coalesce(r.cidr_blocks, [])
      ipv6_cidr_blocks         = coalesce(r.ipv6_cidr_blocks, [])
      prefix_list_ids          = []
      self                     = false
      source_security_group_id = null
    }],
    [for r in var.ingress_self : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = []
      self                     = true
      source_security_group_id = null
    }],
    [for r in var.ingress_source_security_group_ids : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = []
      self                     = false
      source_security_group_id = r.source_security_group_id
    }],
    [for r in var.ingress_prefix_list_ids : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = length(coalesce(r.prefix_list_ids, [])) > 0 ? r.prefix_list_ids : local.default_prefix_list_ids
      self                     = false
      source_security_group_id = null
    }],
  )

  egress_rules = concat(
    [for r in var.egress_cidr_blocks : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = coalesce(r.cidr_blocks, [])
      ipv6_cidr_blocks         = coalesce(r.ipv6_cidr_blocks, [])
      prefix_list_ids          = []
      self                     = false
      source_security_group_id = null
    }],
    [for r in var.egress_self : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = []
      self                     = true
      source_security_group_id = null
    }],
    [for r in var.egress_source_security_group_ids : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = []
      self                     = false
      source_security_group_id = r.source_security_group_id
    }],
    [for r in var.egress_prefix_list_ids : {
      description              = coalesce(r.description, "")
      from_port                = r.from_port
      to_port                  = r.to_port
      protocol                 = coalesce(r.protocol, "tcp")
      cidr_blocks              = []
      ipv6_cidr_blocks         = []
      prefix_list_ids          = length(coalesce(r.prefix_list_ids, [])) > 0 ? r.prefix_list_ids : local.default_prefix_list_ids
      self                     = false
      source_security_group_id = null
    }],
  )

  # Drop rules that resolve to no valid source (e.g. prefix list rules when no
  # prefix list exists and none was supplied).
  ingress_rules_valid = [
    for r in local.ingress_rules : r
    if r.self || r.source_security_group_id != null || length(r.prefix_list_ids) > 0 || length(r.cidr_blocks) > 0 || length(r.ipv6_cidr_blocks) > 0
  ]

  egress_rules_valid = [
    for r in local.egress_rules : r
    if r.self || r.source_security_group_id != null || length(r.prefix_list_ids) > 0 || length(r.cidr_blocks) > 0 || length(r.ipv6_cidr_blocks) > 0
  ]
}

################################################################################
# New security group (with inline categorised rules)
################################################################################

resource "aws_security_group" "this" {
  count = local.create_security_group ? 1 : 0

  name        = local.sg_name
  description = var.security_group_description
  vpc_id      = local.resolved_vpc_id

  tags = merge(local.tags, { Name = local.sg_name })

  dynamic "ingress" {
    for_each = local.ingress_rules_valid
    content {
      description      = ingress.value.description
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      protocol         = ingress.value.protocol
      cidr_blocks      = length(ingress.value.cidr_blocks) > 0 ? ingress.value.cidr_blocks : null
      ipv6_cidr_blocks = length(ingress.value.ipv6_cidr_blocks) > 0 ? ingress.value.ipv6_cidr_blocks : null
      prefix_list_ids  = length(ingress.value.prefix_list_ids) > 0 ? ingress.value.prefix_list_ids : null
      security_groups  = ingress.value.source_security_group_id != null ? [ingress.value.source_security_group_id] : null
      self             = ingress.value.self
    }
  }

  dynamic "egress" {
    for_each = local.egress_rules_valid
    content {
      description      = egress.value.description
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      protocol         = egress.value.protocol
      cidr_blocks      = length(egress.value.cidr_blocks) > 0 ? egress.value.cidr_blocks : null
      ipv6_cidr_blocks = length(egress.value.ipv6_cidr_blocks) > 0 ? egress.value.ipv6_cidr_blocks : null
      prefix_list_ids  = length(egress.value.prefix_list_ids) > 0 ? egress.value.prefix_list_ids : null
      security_groups  = egress.value.source_security_group_id != null ? [egress.value.source_security_group_id] : null
      self             = egress.value.self
    }
  }
}

################################################################################
# Rules attached to a pre-existing security group
################################################################################

resource "aws_security_group_rule" "ingress" {
  for_each = local.use_existing_sg ? { for idx, r in local.ingress_rules_valid : "ingress-${idx}" => r } : {}

  security_group_id        = var.security_group_id
  type                     = "ingress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description != "" ? each.value.description : null
  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  prefix_list_ids          = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : null
  self                     = each.value.self
  source_security_group_id = each.value.source_security_group_id
}

resource "aws_security_group_rule" "egress" {
  for_each = local.use_existing_sg ? { for idx, r in local.egress_rules_valid : "egress-${idx}" => r } : {}

  security_group_id        = var.security_group_id
  type                     = "egress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = each.value.description != "" ? each.value.description : null
  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  prefix_list_ids          = length(each.value.prefix_list_ids) > 0 ? each.value.prefix_list_ids : null
  self                     = each.value.self
  source_security_group_id = each.value.source_security_group_id
}

################################################################################
# Outputs
################################################################################

output "security_group_id" {
  description = "ID of the newly created or pre-existing managed security group."
  value       = local.resolved_security_group_id
}

output "security_group_name" {
  description = "Name of the newly created security group."
  value       = try(one(aws_security_group.this[*].name), null)
}

output "vpc_id" {
  description = "VPC ID hosting the security group (created fallback VPC or supplied VPC)."
  value       = local.resolved_vpc_id
}

output "fallback_vpc_id" {
  description = "ID of the fallback VPC created when no vpc_id was supplied."
  value       = try(one(aws_vpc.this[*].id), null)
}

output "prefix_list_id" {
  description = "ID of the created managed prefix list (if any)."
  value       = try(one(aws_ec2_managed_prefix_list.this[*].id), null)
}

output "prefix_list_ids" {
  description = "Managed prefix list IDs available to rules."
  value       = local.default_prefix_list_ids
}

output "tags" {
  description = "Tags applied to all resources, generated by the label module."
  value       = local.tags
}

variable "role_name" {
  description = "Name of the IAM role for CloudForecast"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID for cross-account STS assume-role condition"
  type        = string
  default     = "benchmark-external-id"
}

resource "aws_iam_role" "cloudforecast" {
  name        = var.role_name
  description = "IAM role for CloudForecast read-only cost optimization and waste-monitoring analysis"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::656227328603:root"
        }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })
}

# --- Policy  1: CloudWatch GetMetricStatistics ---
resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name   = "cloudwatch-get-metric-statistics"
  role   = aws_iam_role.cloudforecast.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cloudwatch:GetMetricStatistics"
        Resource = "*"
      }
    ]
  })
}

# --- Policy  2: Tag GetResources ---
resource "aws_iam_role_policy" "tag_resources" {
