variable "region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "output_bucket_name" {
  description = "Name of the output S3 bucket"
  type        = string
  default     = "tf-benchmark-omics-output-bucket"
}

variable "service_account_user_name" {
  description = "Name of the service account user"
  type        = string
  default     = "workbench-health-omics"
}

variable "iam_role_name" {
  description = "Name of the IAM role for HealthOmics"
  type        = string
  default     = "HealthOmicsRole"
}

variable "service_policy_name" {
  description = "Name of the service policy"
  type        = string
  default     = "HealthOmicsServicePolicy"
}

variable "user_policy_name" {
  description = "Name of the user policy"
  type        = string
  default     = "HealthOmicsUserPolicy"
}

variable "ecr_repository_names" {
  description = "List of ECR repository names"
  type        = list(string)
  default     = []
}

variable "external_account_ids" {
  description = "List of external AWS account IDs for cross-account ECR access"
  type        = list(string)
  default     = []
}

variable "additional_read_only_buckets" {
  description = "List of additional S3 bucket names for read-only access"
  type        = list(string)
  default     = []
}

locals {
  # Build S3 bucket ARNs for the user read-only policy
  read_only_bucket_arns = concat(
    [
      "arn:aws:s3:::${var.output_bucket_name}",
      "arn:aws:s3:::${var.output_bucket_name}/*"
    ],
    flatten([
      for bucket in var.additional_read_only_buckets : [
        "arn:aws:s3:::${bucket}",
        "arn:aws:s3:::${bucket}/*"
      ]
    ])
  )
}

# Customer-managed KMS key for SSE-KMS encryption of the output bucket
resource "aws_kms_key" "omics" {
  description             = "Customer-managed KMS key for HealthOmics S3 bucket encryption"
  deletion_window_in_days = 10
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowS3ServiceEncryption"
        Effect   = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Output S3 bucket for storing results
resource "aws_s3_bucket" "output" {
  bucket = var.output_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# SSE-KMS encryption configuration for the output bucket using a customer-managed key
resource "aws_s3_bucket_server_side_encryption_configuration" "output" {
  bucket = aws_s3_bucket.output.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

# Block all public access to the output bucket
resource "aws_s3_bucket_public_access_block" "output" {
  bucket                  = aws_s3_bucket.output.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM role that the HealthOmics service will assume
resource "aws_iam_role" "health_omics" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "omics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Service policy allowing pass-role and full omics actions
resource "aws_iam_policy" "service" {
  name        = var.service_policy_name
  description = "Allows iam:PassRole and full omics:* actions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "omics:*"
        Resource = "*"
      }
    ]
  })
}

# Attach service policy to the HealthOmics role
resource "aws_iam_role_policy_attachment" "service" {
  role       = aws_iam_role.health_omics.name
  policy_arn = aws_iam_policy.service.arn
}

# IAM user with programmatic access
resource "aws_iam_user" "workbench" {
  name = var.service_account_user_name
}

resource "aws_iam_access_key" "workbench" {
  user = aws_iam_user.workbench.name
}

# User policy with read-only access to the output bucket and any additional S3 buckets
resource "aws_iam_policy" "user" {
  name        = var.user_policy_name
  description = "Read-only access to output bucket and additional S3 buckets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = ["s3:Get*", "s3:List*"]
        Resource = local.read_only_bucket_arns
      }
    ]
  })
}

# Attach user policy to the IAM user
resource "aws_iam_user_policy_attachment" "user" {
  user       = aws_iam_user.workbench.name
  policy_arn = aws_iam_policy.user.arn
}

# ECR repositories for container images
resource "aws_ecr_repository" "repos" {
  count = length(var.ecr_repository_names)
  name  = var.ecr_repository_names[count.index]

  lifecycle {
    prevent_destroy = true
  }
}

# ECR repository policy allowing HealthOmics service to pull images
# and granting cross-account access to external account IDs
resource "aws_ecr_repository_policy" "repos" {
  count = length(var.ecr_repository_names)
  repository = aws_ecr_repository.repos[count.index].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "AllowHealthOmicsPull"
          Effect = "Allow"
          Principal = {
            AWS = "arn:aws:iam::role/${var.iam_role_name}"
          }
          Action = ["ecr:Pull", "ecr:Become"]
        }
      ],
      [for i, acct in var.external_account_ids : {
        Sid    = "CrossAccountECRAccess-${i}"
        Effect = "Allow"
        Principal = {
          AWS = acct
        }
        Action = ["ecr:Pull", "ecr:Become"]
      }]
    )
  })
}

variable "cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "First two octets of the VPC CIDR block"
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "Default tags to apply to all resources"
  type        = map(string)
  default     = {}
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name_full = "dit-paas-${var.cluster_name}-cluster"
  igw_name          = "${var.cluster_name}-ig"
  az_names          = [for az in data.aws_availability_zones.available.names : az if length(regexall("[abc]$", az)) > 0]
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.${12 + count.index * 4}.0/22"
  availability_zone = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-subnet-${local.az_names[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.${count.index * 4}.0/22"
  availability_zone = local.az_names[count.index]

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-subnet-${local.az_names[count.index]}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = local.igw_name
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-eip-${local.az_names[count.index]}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-${local.az_names[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-rt-${local.az_names[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_ecs_cluster" "main" {
  name = local.cluster_name_full

  tags = merge(var.default_tags, {
    Name = local.cluster_name_full
  })
}

terraform {
  required_version = ">= 1.0.0"
}

variable "vpc_name" {
  description = "Name of the VPC that will host the containerized services."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC."
  type        = string
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones used to provision the subnets. When left empty the first three availability zones of the current region are used."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Fall back to the first three availability zones of the current region
  # (us-east-1 by default) when no explicit list is supplied.
  availability_zones = length(var.availability_zones) > 0 ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 3)

  # Interface endpoints required for the containerized services. The values are
  # the AWS service suffixes appended to "com.amazonaws.<region>.".
  interface_endpoints = {
    ecr_dkr = "ecr.dkr"
    ecr_api = "ecr.api"
    logs    = "logs"
    ssm     = "ssm"
    kms     = "kms"
  }
}

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  name = var.vpc_name
  tags = var.tags
}

module "vpc" {
  source  = "cloudposse/vpc/aws"
  version = ">= 1.0.0"

  ipv4_primary_cidr_block          = var.vpc_cidr
  dns_hostnames_enabled            = true
  dns_support_enabled              = true
  assign_generated_ipv6_cidr_block = false
  default_security_group_deny_all  = true

  context = module.this.context
}

module "subnets" {
  source  = "cloudposse/dynamic-subnets/aws"
  version = ">= 1.0.0"

  availability_zones   = local.availability_zones
  vpc_id               = module.vpc.vpc_id
  igw_id               = [module.vpc.igw_id]
  ipv4_cidr_block      = [module.vpc.vpc_cidr_block]
  nat_gateway_enabled  = true
  nat_instance_enabled = false

  context = module.this.context
}

# Dedicated security group that gates access to the interface VPC endpoints.
# Only HTTPS (TCP/443) traffic that originates from the security group itself
# is permitted in either direction.
resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Controls access to the VPC interface endpoints; allows TCP/443 within the group only."
  vpc_id      = module.vpc.vpc_id

  tags = merge(module.this.tags, { Name = "vpc_endpoint_sg" })
}

resource "aws_security_group_rule" "vpc_endpoint_ingress" {
  type              = "ingress"
  description       = "Allow HTTPS (TCP/443) from members of this security group."
  security_group_id = aws_security_group.vpc_endpoint_sg.id
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
}

resource "aws_security_group_rule" "vpc_endpoint_egress" {
  type              = "egress"
  description       = "Allow HTTPS (TCP/443) to members of this security group."
  security_group_id = aws_security_group.vpc_endpoint_sg.id
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
}

# S3 Gateway endpoint shared by the public, private and default route tables.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    module.subnets.public_route_table_ids,
    module.subnets.private_route_table_ids,
    [module.vpc.vpc_default_route_table_id]
  )

  tags = merge(module.this.tags, { Name = "${var.vpc_name}-s3-gateway-endpoint" })
}

# Private DNS-enabled Interface endpoints for the services required by the
# containerized workloads. They live in the private subnets and are protected
# by the dedicated vpc_endpoint_sg security group.
resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = merge(module.this.tags, { Name = "${var.vpc_name}-${each.key}-endpoint" })
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = module.vpc.vpc_id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = module.vpc.vpc_cidr_block
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets."
  value       = module.subnets.public_subnet_ids
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets."
  value       = module.subnets.private_subnet_ids
}

output "vpc_endpoint_security_group_id" {
  description = "The ID of the security group protecting the interface VPC endpoints."
  value       = aws_security_group.vpc_endpoint_sg.id
}

variable "vpc_name" {
  type        = string
  default     = "benchmark-vpc"
  description = "Name of the VPC and the base name used for related resources."
}

variable "vpc_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "Primary IPv4 CIDR block for the VPC."
}

variable "instance_tenancy" {
  type        = string
  default     = "default"
  description = "Instance tenancy for the VPC (default or dedicated)."
}

variable "enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "Enable DNS hostnames in the VPC."
}

variable "region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region used to construct VPC endpoint service names."
}

variable "interface_endpoint_services" {
  type        = set(string)
  default     = ["logs"]
  description = "Standard AWS services for which private-DNS interface endpoints are provisioned."
}

variable "custom_endpoint_services" {
  type = map(object({
    service_name              = string
    port                      = number
    source_security_group_ids = set(string)
  }))
  default     = {}
  description = "Custom endpoint services keyed by unique name, each specifying service name, port, and permitted source security groups."
}

variable "endpoint_source_security_group_ids" {
  type        = set(string)
  default     = []
  description = "Source security group IDs allowed HTTPS (443) access to the standard interface endpoints. Falls back to the VPC default security group."
}

variable "gateway_endpoint_route_table_ids" {
  type        = list(string)
  default     = []
  description = "Additional route table IDs to attach the s3 and dynamodb gateway endpoints to."
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

locals {
  azs                         = slice(data.aws_availability_zones.available.names, 0, min(2, length(data.aws_availability_zones.available.names)))
  gateway_services            = toset(["s3", "dynamodb"])
  standard_interface_services = setsubtract(var.interface_endpoint_services, local.gateway_services)
  includes_ssm                = contains(var.interface_endpoint_services, "ssm")
  endpoint_source_sgs         = length(var.endpoint_source_security_group_ids) > 0 ? toset(var.endpoint_source_security_group_ids) : toset([aws_default_security_group.this.id])
  gateway_route_tables        = distinct(concat([for rt in aws_route_table.private : rt.id], var.gateway_endpoint_route_table_ids))
  custom_endpoint_rules = flatten([
    for key, svc in var.custom_endpoint_services : [
      for sg_id in toset(svc.source_security_group_ids) : {
        key   = key
        port  = svc.port
        sg_id = sg_id
      }
    ]
  ])
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "private" {
  for_each          = { for idx, az in local.azs : az => idx }
  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, each.value + 1)

  tags = {
    Name = "${var.vpc_name}-private-${each.key}"
  }
}

resource "aws_route_table" "private" {
  for_each = aws_subnet.private
  vpc_id   = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-${each.key}"
  }
}

resource "aws_route_table_association" "private" {
  for_each       = aws_subnet.private
  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "Self-referencing inbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for standard AWS interface VPC endpoints allowing HTTPS from/to specified source security groups."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }

  ingress {
    description     = "HTTPS from allowed source security groups"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = tolist(local.endpoint_source_sgs)
  }

  egress {
    description     = "HTTPS to allowed source security groups"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = tolist(local.endpoint_source_sgs)
  }
}

resource "aws_security_group" "custom_endpoints" {
  name        = "vpc-endpoints-custom-${var.vpc_name}"
  description = "Security group for custom endpoint services with per-service port and source security group rules."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-custom-${var.vpc_name}"
  }

  dynamic "ingress" {
    for_each = { for rule in local.custom_endpoint_rules : "${rule.key}-${rule.sg_id}" => rule }
    content {
      description     = "Custom endpoint ${ingress.value.key} ingress on port ${ingress.value.port}"
      from_port       = ingress.value.port
      to_port         = ingress.value.port
      protocol        = "tcp"
      security_groups = [ingress.value.sg_id]
    }
  }

  dynamic "egress" {
    for_each = { for rule in local.custom_endpoint_rules : "${rule.key}-${rule.sg_id}" => rule }
    content {
      description     = "Custom endpoint ${egress.value.key} egress on port ${egress.value.port}"
      from_port       = egress.value.port
      to_port         = egress.value.port
      protocol        = "tcp"
      security_groups = [egress.value.sg_id]
    }
  }
}

resource "aws_cloudwatch_log_group" "flow_log" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180

  tags = {
    Name = "/aws/vpc-flow-logs/${var.vpc_name}"
  }
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "flow_logs" {
  statement {
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "${aws_cloudwatch_log_group.flow_log.arn}:*",
    ]
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "vpc_flow_logs_${var.vpc_name}"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = {
    Name = "vpc_flow_logs_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name   = "vpc-flow-logs-policy"
  role   = aws_iam_role.flow_logs.name
  policy = data.aws_iam_policy_document.flow_logs.json
}

resource "aws_flow_log" "vpc" {
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_log.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  max_aggregation_interval = 60

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }
}

resource "aws_vpc_endpoint" "gateway" {
  for_each          = local.gateway_services
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.${each.value}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.gateway_route_tables

  tags = {
    Name = "${var.vpc_name}-${each.value}-gateway-endpoint"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each            = local.standard_interface_services
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = [for subnet in aws_subnet.private : subnet.id]

  tags = {
    Name = "${var.vpc_name}-${each.value}-interface-endpoint"
  }
}

resource "aws_vpc_endpoint" "custom" {
  for_each            = var.custom_endpoint_services
  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  security_group_ids  = [aws_security_group.custom_endpoints.id]
  subnet_ids          = [for subnet in aws_subnet.private : subnet.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-custom-endpoint"
  }
}

data "aws_iam_policy_document" "ssm_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm" {
  count              = local.includes_ssm ? 1 : 0
  name               = "ssm_${var.vpc_name}"
  assume_role_policy = data.aws_iam_policy_document.ssm_assume_role.json

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count      = local.includes_ssm ? 1 : 0
  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.includes_ssm ? 1 : 0
  name  = "ssm_${var.vpc_name}"
  role  = aws_iam_role.ssm[0].name
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used as prefix for KMS key aliases"
  type        = string
  default     = "account"
}

variable "kms_rotation_days" {
  description = "KMS key rotation period in days"
  type        = number
  default     = 90
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for default EBS encryption; defaults to the compute KMS key ARN when left blank"
  type        = string
  default     = ""
}

variable "ec2_metadata_hop_limit" {
  description = "Hop limit for EC2 instance metadata (IMDSv2)"
  type        = number
  default     = 1
}

variable "ec2_metadata_toggle" {
  description = "Toggle to enforce required HTTP tokens (IMDSv2) on EC2 instances"
  type        = bool
  default     = true
}

variable "ec2_serial_console_toggle" {
  description = "Toggle to disable EC2 Serial Console access"
  type        = bool
  default     = true
}

variable "emr_block_public_toggle" {
  description = "Toggle to enable EMR block public access restrictions"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  ebs_default_kms_key_arn = var.external_ebs_kms_key_arn != "" ? var.external_ebs_kms_key_arn : aws_kms_key.compute.arn

  root_principal = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"

  compute_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "compute-kms-key-policy"
    Statement = [
      {
        Sid    = "Allow IAM Root Access"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid    = "Allow EC2 Service"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid    = "Allow Auto Scaling Service with Grant Creation"
        Effect = "Allow"
        Principal = {
          Service = "autoscaling.amazonaws.com"
        }
        Action   = ["kms:*", "kms:CreateGrant"]
        Resource = "*"
      },
    ]
  })

  observability_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "observability-kms-key-policy"
    Statement = [
      {
        Sid    = "Allow IAM Root Access"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:cloudwatch:log-group" = "$${aws:LogGroupName}"
          }
        }
      },
      {
        Sid    = "Allow CloudTrail"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Alarms"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SQS"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow EventBridge"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })

  storage_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "storage-kms-key-policy"
    Statement = [
      {
        Sid    = "Allow IAM Root Access"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow AWS Config Encrypted Snapshot Delivery"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail Log Encryption"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# KMS Keys
# ---------------------------------------------------------------------------

resource "aws_kms_key" "compute" {
  description             = "KMS customer-managed key for the compute layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = local.compute_policy
  rotation_period_in_days = var.kms_rotation_days

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "observability" {
  description             = "KMS customer-managed key for the observability layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = local.observability_policy
  rotation_period_in_days = var.kms_rotation_days

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "storage" {
  description             = "KMS customer-managed key for the storage layer"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true
  key_usage               = "ENCRYPT_DECRYPT"
  policy                  = local.storage_policy
  rotation_period_in_days = var.kms_rotation_days

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# KMS Aliases
# ---------------------------------------------------------------------------

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.id
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.id
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.id
}

# ---------------------------------------------------------------------------
# Account-Level Default EBS Encryption
# ---------------------------------------------------------------------------

resource "aws_ebs_encryption_by_default" "this" {
  enabled = true
}

# ---------------------------------------------------------------------------
# Account-Level Public Access Restrictions
# ---------------------------------------------------------------------------

resource "aws_ec2_image_block_public_access" "this" {
  state = "block-new-sharing"
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  state = "block-all-sharing"
}

resource "aws_ec2_instance_metadata_defaults" "this" {
  count = var.ec2_metadata_toggle ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.ec2_metadata_hop_limit
  http_endpoint               = "enabled"
}

resource "aws_ec2_serial_console_access" "this" {
  count   = var.ec2_serial_console_toggle ? 1 : 0
  enabled = false
}

# ---------------------------------------------------------------------------
# Terraform required providers (TLS only; AWS provider injected by harness)
# ---------------------------------------------------------------------------

terraform {
  required_providers {
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# ---------------------------------------------------------------------------
# Data sources – static provider metadata lookups only
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Variables – all configuration surface exposed here
# ---------------------------------------------------------------------------

variable "cluster_prefix" {
  description = "Cluster prefix used to name resources (5–8 characters)"
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "cluster_prefix must be between 5 and 8 characters."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "ssh_key_name" {
  description = "Name of the SSH key pair"
  type        = string
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  description = "Public key material for the SSH key pair"
  type        = string
  default     = "ssh-rsa  terraform-test-key"
}

variable "instance_type" {
  description = "EC2 instance type for compute nodes"
  type        = string
  default     = "m5.large"
}

variable "subnet_definitions" {
  description = <<-EOT
    List of subnet configurations.
    Each entry has:
      name     – display name
      type     – "public" or "private"
      cidr     – CIDR block within the VPC
      az_index – index into the available AZ list
  EOT
  type = list(object({
    name     = string
    type     = string
    cidr     = string
    az_index = number
  }))
  default = [
    { name = "public-web", type = "public", cidr = "172.16.1.0/24", az_index = 0 },
    { name = "public-api", type = "public", cidr = "172.16.2.0/24", az_index = 1 },
    { name = "private-db", type = "private", cidr = "172.16.10.0/24", az_index = 0 },
  ]
}

variable "node_inventory" {
  description = <<-EOT
    List of compute node definitions.
    Each entry has:
      hostname      – instance hostname
      subnet_index  – index into subnet_definitions
      ebs_root_size – root volume size in GB (optional)
      ebs_volumes   – list of secondary EBS volume objects:
        { size, device_name, mount_point }
      assign_eip    – attach a public Elastic IP (optional)
  EOT
  type = list(object({
    hostname      = string
    subnet_index  = number
    ebs_root_size = optional(number)
    ebs_volumes = optional(list(object({
      size        = number
      device_name = string
      mount_point = string
    })))
    assign_eip = optional(bool)
  }))
  default = [
    {
      hostname      = "web-01"
      subnet_index  = 0
      ebs_root_size = 30
      ebs_volumes   = []
      assign_eip    = true
    },
    {
      hostname      = "web-02"
      subnet_index  = 0
      ebs_root_size = 30
      ebs_volumes   = []
      assign_eip    = true
    },
    {
      hostname      = "db-01"
      subnet_index  = 2
      ebs_root_size = 40
      ebs_volumes = [
        { size = 100, device_name = "/dev/sdg", mount_point = "/data" }
      ]
      assign_eip = false
    },
  ]
}

variable "ingress_cidr_rules" {
  description = "Custom ingress CIDR rules for the default security group"
  type = list(object({
    from_port  = number
    to_port    = number
    protocol   = string
    cidr_block = string
  }))
  default = [
    { from_port = 22, to_port = 22, protocol = "tcp", cidr_block = "10.0.0.0/8" },
    { from_port = 80, to_port = 80, protocol = "tcp", cidr_block = "10.0.0.0/8" },
  ]
}

# ---------------------------------------------------------------------------
# Locals – derived values used across the configuration
# ---------------------------------------------------------------------------

locals {
  az_names       = data.aws_availability_zones.available.names
  cluster_tag    = var.cluster_prefix
  public_indices = [for i, s in var.subnet_definitions : i if s.type == "public"]
  private_indices = [for i, s in var.subnet_definitions : i if s.type == "private"]
  num_public     = length(local.public_indices)

  # Flattened list of all secondary volumes across every node
  all_volumes = flatten([
    for ni, node in var.node_inventory : [
      for v in node.ebs_volumes : {
        node_index  = ni
        size        = v.size
        device_name = v.device_name
        mount_point = v.mount_point
      }
    ]
  ])
}

# ---------------------------------------------------------------------------
# Core networking resources
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name    = "${local.cluster_tag}-vpc"
    Cluster = local.cluster_tag
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "${local.cluster_tag}-igw"
    Cluster = local.cluster_tag
  }
}

# ---------------------------------------------------------------------------
# SSH key pair for deployment
# ---------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

resource "tls_private_key" "deploy" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "deploy" {
  key_name   = "${var.ssh_key_name}-${random_id.suffix.hex}"
  public_key = tls_private_key.deploy.public_key_openssh

  tags = {
    Name    = local.cluster_tag
    Cluster = local.cluster_tag
  }
}

# ---------------------------------------------------------------------------
# Subnets (created once; referenced by index throughout)
# ---------------------------------------------------------------------------

resource "aws_subnet" "all" {
  count = length(var.subnet_definitions)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_definitions[count.index].cidr
  availability_zone       = local.az_names[var.subnet_definitions[count.index].az_index % length(local.az_names)]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${local.cluster_tag}-${var.subnet_definitions[count.index].name}"
    Cluster = local.cluster_tag
    Type    = var.subnet_definitions[count.index].type
  }
}

# ---------------------------------------------------------------------------
# Public route table – default route 0.0.0.0/0 -> Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "${local.cluster_tag}-public-rt"
    Cluster = local.cluster_tag
  }
}

resource "aws_route_table_association" "public" {
  count = local.num_public

  subnet_id      = aws_subnet.all[local.public_indices[count.index]].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Per-private-subnet Elastic IPs, NAT Gateways, and private route tables
# ---------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count  = length(local.private_indices)
  domain = "vpc"

  tags = {
    Name    = "${local.cluster_tag}-nat-eip-${count.index}"
    Cluster = local.cluster_tag
  }
}

resource "aws_nat_gateway" "private" {
  count = length(local.private_indices)

  subnet_id     = aws_subnet.all[local.public_indices[count.index % local.num_public]].id
  allocation_id = aws_eip.nat[count.index].id
  connectivity_type = "public"

  tags = {
    Name    = "${local.cluster_tag}-nat-${count.index}"
    Cluster = local.cluster_tag
  }
}

resource "aws_route_table" "private" {
  count = length(local.private_indices)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.private[count.index].id
  }

  tags = {
    Name    = "${local.cluster_tag}-private-rt-${count.index}"
    Cluster = local.cluster_tag
  }
}

resource "aws_route_table_association" "private" {
  count = length(local.private_indices)

  subnet_id      = aws_subnet.all[local.private_indices[count.index]].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Default security group
#   • self-referencing ingress (all traffic from the group itself)
#   • egress restricted to the VPC CIDR
#   • custom ingress CIDR rules from variable
# ---------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "${local.cluster_tag}-default-sg"
  description = "Default security group for the ${local.cluster_tag} cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name    = "${local.cluster_tag}-default-sg"
    Cluster = local.cluster_tag
  }
}

# Self-referencing intra-group ingress (all protocols, all ports)
resource "aws_security_group_rule" "self_ingress" {
  type              = "ingress"
  security_group_id = aws_security_group.main.id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  self              = true
}

# Outbound traffic only within the VPC CIDR
resource "aws_security_group_rule" "egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.main.id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  cidr_blocks       = [var.vpc_cidr]
}

# Custom dynamic ingress CIDR rules
resource "aws_security_group_rule" "custom_ingress" {
  count = length(var.ingress_cidr_rules)

  type              = "ingress"
  security_group_id = aws_security_group.main.id
  from_port         = var.ingress_cidr_rules[count.index].from_port
  to_port           = var.ingress_cidr_rules[count.index].to_port
  protocol          = var.ingress_cidr_rules[count.index].protocol
  cidr_blocks       = [var.ingress_cidr_rules[count.index].cidr_block]
}

# ---------------------------------------------------------------------------
# EC2 compute nodes
# ---------------------------------------------------------------------------

resource "aws_instance" "node" {
  count = length(var.node_inventory)

  instance_type          = var.instance_type
  ami                    = data.aws_ami.amazon.id
  subnet_id              = aws_subnet.all[var.node_inventory[count.index].subnet_index].id
  key_name               = aws_key_pair.deploy.key_name
  vpc_security_group_ids = [aws_security_group.main.id]
  ebs_optimized          = true

  associate_public_ip_address = try(var.node_inventory[count.index].assign_eip, false)

  user_data = length(var.node_inventory[count.index].ebs_volumes) > 0 ? join("\n", concat(
    ["#!/bin/bash", "set -ex"],
    flatten([
      for v in var.node_inventory[count.index].ebs_volumes : [
        format("DEVICE='%s'", v.device_name),
        format("MOUNT='%s'", v.mount_point),
        "if [ -e \"$DEVICE\" ]; then",
        "  mkfs.ext4 -F \"$DEVICE\" 2>/dev/null || true",
        "  mkdir -p \"$MOUNT\"",
        "  mount \"$DEVICE\" \"$MOUNT\"",
        "  echo \"$DEVICE $MOUNT ext4 defaults,noatime 0 0\" >> /etc/fstab",
        "fi"
      ]
    ])
  )) : null

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = try(var.node_inventory[count.index].ebs_root_size, 30)
    volume_type = "gp3"
    encrypted   = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name      = var.node_inventory[count.index].hostname
    Cluster   = local.cluster_tag
    SubnetIdx = format("%d", var.node_inventory[count.index].subnet_index)
  }
}

locals {
  # Indices of nodes that have secondary volumes
  volumes_node_indices = [for i, n in var.node_inventory : i if length(n.ebs_volumes) > 0]
}

# ---------------------------------------------------------------------------
# Secondary EBS volumes and attachments
# ---------------------------------------------------------------------------

resource "aws_ebs_volume" "secondary" {
  count = length(local.all_volumes)

  availability_zone = aws_instance.node[local.all_volumes[count.index].node_index].availability_zone
  size              = local.all_volumes[count.index].size
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name    = "${local.cluster_tag}-ebs-${count.index}"
    Cluster = local.cluster_tag
  }
}

resource "aws_volume_attachment" "secondary" {
  count = length(local.all_volumes)

  device_name = local.all_volumes[count.index].device_name
  volume_id   = aws_ebs_volume.secondary[count.index].id
  instance_id = aws_instance.node[local.all_volumes[count.index].node_index].id
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

variable "enable_private_subnets" {
  description = "Toggle to enable private subnets"
  type        = bool
  default     = true
}

variable "deploy_nat_gateways" {
  description = "Deploy NAT Gateways in each public subnet for private egress"
  type        = bool
  default     = false
}

variable "deploy_nat_instances" {
  description = "Deploy NAT EC2 instances in each public subnet for private egress"
  type        = bool
  default     = false
}

variable "deploy_egress_only_igw" {
  description = "Deploy Egress-Only Internet Gateway for IPv6 private egress"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# Data Sources (static provider metadata only)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_ami" "amazon_linux_nat" {
  count = var.deploy_nat_instances && var.enable_private_subnets ? 1 : 0

  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-*"]
  }
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  azs                 = data.aws_availability_zones.available.names
  public_subnet_count = var.enable_private_subnets ? 2 : 4
  private_subnet_count = var.enable_private_subnets ? 2 : 0
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name   = var.vpc_name
    Region = var.region
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Public Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-public-${count.index + 1}"
    Type = "public"
  }
}

# ---------------------------------------------------------------------------
# Private Subnets (conditional on enable_private_subnets)
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index + 2]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
    Type = "private"
  }
}

# ---------------------------------------------------------------------------
# Public Route Table (default route via Internet Gateway)
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Default Security Group (self-referencing ingress / egress)
# ---------------------------------------------------------------------------
resource "aws_security_group" "default" {
  name        = "${var.vpc_name}-default"
  description = "Default security group allowing self-referencing ingress and egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

# ---------------------------------------------------------------------------
# TLS Security Group (inbound port 443)
# ---------------------------------------------------------------------------
resource "aws_security_group" "tls" {
  name        = "${var.vpc_name}-tls"
  description = "Security group allowing inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-tls"
  }
}

# ===========================================================================
# EGRESS STRATEGIES (mutually exclusive – only one should be enabled)
# ===========================================================================

# ---------------------------------------------------------------------------
# Strategy 1 – NAT Gateways
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = var.deploy_nat_gateways && var.enable_private_subnets ? local.public_subnet_count : 0

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count = var.deploy_nat_gateways && var.enable_private_subnets ? local.public_subnet_count : 0

  subnet_id     = aws_subnet.public[count.index].id
  allocation_id = aws_eip.nat[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-gw-${count.index + 1}"
  }
}

resource "aws_route_table" "private_nat" {
  count = var.deploy_nat_gateways && var.enable_private_subnets ? local.private_subnet_count : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.vpc_name}-private-nat-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat" {
  count = var.deploy_nat_gateways && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat[count.index].id
}

# ---------------------------------------------------------------------------
# Strategy 2 – NAT EC2 Instances
# ---------------------------------------------------------------------------
resource "aws_security_group" "nat_instance" {
  count = var.deploy_nat_instances && var.enable_private_subnets ? 1 : 0

  name        = "${var.vpc_name}-nat-instance"
  description = "Custom security group for NAT EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.subnet_cidrs[2], var.subnet_cidrs[3]]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.vpc_name}-nat-instance"
  }
}

resource "aws_instance" "nat" {
  count = var.deploy_nat_instances && var.enable_private_subnets ? local.public_subnet_count : 0

  subnet_id                   = aws_subnet.public[count.index].id
  vpc_security_group_ids      = [aws_security_group.nat_instance[0].id]
  associate_public_ip_address = true
  instance_type               = "m1.small"
  source_dest_check           = false
  ami                         = data.aws_ami.amazon_linux_nat[0].id

  user_data = <<-EOF
#!/bin/bash
echo "net.ipv4.ip_forward=1" >> /etc/sysctl.conf
sysctl -p /etc/sysctl.conf
iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE
EOF

  tags = {
    Name = "${var.vpc_name}-nat-instance-${count.index + 1}"
  }
}

resource "aws_route_table" "private_nat_instance" {
  count = var.deploy_nat_instances && var.enable_private_subnets ? local.private_subnet_count : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat[count.index].primary_network_interface_id
  }

  tags = {
    Name = "${var.vpc_name}-private-nat-instance-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat_instance" {
  count = var.deploy_nat_instances && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# ---------------------------------------------------------------------------
# Strategy 3 – Egress-Only Internet Gateway (IPv6)
# ---------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "main" {
  count = var.deploy_egress_only_igw && var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-eoir"
  }
}

resource "aws_route_table" "private_egress_only" {
  count = var.deploy_egress_only_igw && var.enable_private_subnets ? local.private_subnet_count : 0

  vpc_id = aws_vpc.main.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.vpc_name}-private-egress-only-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_egress_only" {
  count = var.deploy_egress_only_igw && var.enable_private_subnets ? local.private_subnet_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_egress_only[count.index].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used to prefix all resource names."
  type        = string
  default     = "benchmark"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.environment))
    error_message = "The environment name must be lowercase alphanumeric or hyphens."
  }
}

variable "primary_region" {
  description = "Primary AWS region hosting the Terraform state and access-log buckets."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Secondary AWS region used as the cross-region replication target."
  type        = string
  default     = "us-west-2"
}

variable "glacier_transition_days" {
  description = "Number of days before access-log objects transition to Glacier."
  type        = number
  default     = 7
}

variable "expiration_days" {
  description = "Number of days before access-log objects expire."
  type        = number
  default     = 30
}

###############################################################################
# Providers
#
# The default (primary) provider is injected by the deployment harness. A single
# aliased provider is declared here so resources can be created in the
# secondary (replication) region.
###############################################################################

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  state_bucket_name         = "${var.environment}-tf-state-${local.account_id}"
  logs_bucket_name          = "${var.environment}-access-logs-${local.account_id}"
  replica_state_bucket_name = "${var.environment}-tf-state-replica-${local.account_id}"
  replica_logs_bucket_name  = "${var.environment}-access-logs-replica-${local.account_id}"

  account_principal = "arn:${local.partition}:iam::${local.account_id}:root"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "multi-region-tfstate"
  }
}

###############################################################################
# Primary region: KMS key for the Terraform state bucket
###############################################################################

resource "aws_kms_key" "state" {
  description             = "Customer managed key encrypting the ${var.environment} Terraform state bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${var.environment}-tf-state-key" })
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.environment}-tf-state"
  target_key_id = aws_kms_key.state.key_id
}

###############################################################################
# Primary region: Terraform state bucket
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  tags = merge(local.tags, { Name = local.state_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Primary region: KMS key for the access logs bucket
###############################################################################

resource "aws_kms_key" "logs" {
  description             = "Customer managed key encrypting the ${var.environment} access logs bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${var.environment}-access-logs-key" })
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${var.environment}-access-logs"
  target_key_id = aws_kms_key.logs.key_id
}

###############################################################################
# Primary region: Access logs bucket
###############################################################################

resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket_name

  tags = merge(local.tags, { Name = local.logs_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logs.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ACLs are disabled by default on new buckets, so opt in to bucket-owner
# preferred ownership before applying the log-delivery-write ACL.
resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logs" {
  depends_on = [aws_s3_bucket_ownership_controls.logs]

  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

# Allow the S3 server access-logging service to write delivery logs.
data "aws_iam_policy_document" "logs_bucket" {
  statement {
    sid    = "S3ServerAccessLogsDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.state.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.logs_bucket.json
}

# Send access logs from the state bucket to the logs bucket.
resource "aws_s3_bucket_logging" "state" {
  depends_on = [aws_s3_bucket_policy.logs]

  bucket        = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "state-access-logs/"
}

###############################################################################
# Primary region: State bucket policy
# Restricts all S3 actions to the owning account and requires the
# bucket-owner-full-control ACL on incoming requests.
###############################################################################

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid    = "RestrictToOwningAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_principal]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json
}

###############################################################################
# Replica region: KMS key for the replica state bucket
###############################################################################

resource "aws_kms_key" "replica_state" {
  provider = aws.replica

  description             = "Customer managed key encrypting the ${var.environment} replica Terraform state bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${var.environment}-tf-state-replica-key" })
}

resource "aws_kms_alias" "replica_state" {
  provider = aws.replica

  name          = "alias/${var.environment}-tf-state-replica"
  target_key_id = aws_kms_key.replica_state.key_id
}

###############################################################################
# Replica region: Replica Terraform state bucket
###############################################################################

resource "aws_s3_bucket" "replica_state" {
  provider = aws.replica
  bucket   = local.replica_state_bucket_name

  tags = merge(local.tags, { Name = local.replica_state_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Same bucket policy as the primary state bucket.
data "aws_iam_policy_document" "replica_state_bucket" {
  statement {
    sid    = "RestrictToOwningAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_principal]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica_state.arn,
      "${aws_s3_bucket.replica_state.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id
  policy   = data.aws_iam_policy_document.replica_state_bucket.json
}

###############################################################################
# Replica region: KMS key for the replica access logs bucket
###############################################################################

resource "aws_kms_key" "replica_logs" {
  provider = aws.replica

  description             = "Customer managed key encrypting the ${var.environment} replica access logs bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${var.environment}-access-logs-replica-key" })
}

resource "aws_kms_alias" "replica_logs" {
  provider = aws.replica

  name          = "alias/${var.environment}-access-logs-replica"
  target_key_id = aws_kms_key.replica_logs.key_id
}

###############################################################################
# Replica region: Replica access logs bucket
###############################################################################

resource "aws_s3_bucket" "replica_logs" {
  provider = aws.replica
  bucket   = local.replica_logs_bucket_name

  tags = merge(local.tags, { Name = local.replica_logs_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_logs.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

###############################################################################
# IAM role and policy enabling S3 replication
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "${var.environment}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.tags, { Name = "${var.environment}-s3-replication" })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReplicationConfiguration"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.state.arn,
      aws_s3_bucket.logs.arn,
    ]
  }

  statement {
    sid    = "SourceObjectVersionAccess"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = [
      "${aws_s3_bucket.state.arn}/*",
      "${aws_s3_bucket.logs.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationBucketAccess"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:PutBucketVersioning",
    ]

    resources = [
      aws_s3_bucket.replica_state.arn,
      aws_s3_bucket.replica_logs.arn,
    ]
  }

  statement {
    sid    = "ReplicateObjectsAndDeleteMarkers"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = [
      "${aws_s3_bucket.replica_state.arn}/*",
      "${aws_s3_bucket.replica_logs.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicationKMSAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [
      aws_kms_key.state.arn,
      aws_kms_key.logs.arn,
      aws_kms_key.replica_state.arn,
      aws_kms_key.replica_logs.arn,
    ]
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "${var.environment}-s3-replication"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Replication configuration for the state bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica_state,
  ]

  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-state-to-${var.replica_region}"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_state.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state.arn
      }
    }
  }
}

###############################################################################
# Replication configuration for the access logs bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "logs" {
  depends_on = [
    aws_s3_bucket_versioning.logs,
    aws_s3_bucket_versioning.replica_logs,
  ]

  bucket = aws_s3_bucket.logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-logs-to-${var.replica_region}"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_logs.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_logs.arn
      }
    }
  }
}

variable "name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_id" {
  description = "Existing VPC ID to use instead of creating a new one"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "azs" {
  description = "List of availability zones to use"
  type        = list(string)
  default     = null
}

variable "public_subnet_cidrs" {
  description = "Map of AZ to public subnet CIDR"
  type        = map(string)
  default     = null
}

variable "private_subnet_cidrs" {
  description = "Map of AZ to private subnet CIDR"
  type        = map(string)
  default     = null
}

variable "database_subnet_cidrs" {
  description = "Map of AZ to database subnet CIDR"
  type        = map(string)
  default     = null
}

variable "existing_public_subnet_ids" {
  description = "Map of AZ to existing public subnet IDs"
  type        = map(string)
  default     = null
}

variable "existing_private_subnet_ids" {
  description = "Map of AZ to existing private subnet IDs"
  type        = map(string)
  default     = null
}

variable "existing_database_subnet_ids" {
  description = "Map of AZ to existing database subnet IDs"
  type        = map(string)
  default     = null
}

variable "existing_nat_id" {
  description = "Existing NAT Gateway ID to use instead of creating a new one"
  type        = string
  default     = null
}

variable "existing_security_group_id" {
  description = "Existing security group ID to use for VPC endpoints"
  type        = string
  default     = null
}

variable "services" {
  description = "List of AWS services to create VPC endpoints for"
  type        = list(string)
  default     = ["ec2", "ecr.api", "ecr.dkr", "s3", "logs", "sts", "elasticloadbalancing", "autoscaling"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  # Determine availability zones - use provided or first two from data source
  azs = var.azs != null ? var.azs : slice(sort(data.aws_availability_zones.available.names), 0, 2)

  # Default CIDR maps if not provided
  default_public_cidrs = {
    (local.azs[0]) = "10.0.0.0/20"
    (local.azs[1]) = "10.0.16.0/20"
  }
  default_private_cidrs = {
    (local.azs[0]) = "10.0.32.0/20"
    (local.azs[1]) = "10.0.48.0/20"
  }
  default_database_cidrs = {
    (local.azs[0]) = "10.0.64.0/20"
    (local.azs[1]) = "10.0.80.0/20"
  }

  public_cidrs  = var.public_subnet_cidrs != null ? var.public_subnet_cidrs : local.default_public_cidrs
  private_cidrs = var.private_subnet_cidrs != null ? var.private_subnet_cidrs : local.default_private_cidrs
  database_cidrs = var.database_subnet_cidrs != null ? var.database_subnet_cidrs : local.default_database_cidrs

  # Determine if we are creating a new VPC or using existing
  use_existing_vpc    = var.vpc_id != null
  vpc_id              = local.use_existing_vpc ? var.vpc_id : aws_vpc.main[0].id

  # Determine if we are creating new subnets or using existing
  use_existing_public_subnets   = var.existing_public_subnet_ids != null
  use_existing_private_subnets  = var.existing_private_subnet_ids != null
  use_existing_database_subnets = var.existing_database_subnet_ids != null

  existing_nat_id = var.existing_nat_id

  # Lowercased VPC name for RDS subnet group
  rds_subnet_group_name = lower(var.name)

  # Security group name
  endpoint_sg_name = "${var.name}-vpc-endpoints"

  # Gather private subnet IDs for VPC endpoints
  private_subnet_ids = local.use_existing_private_subnets ? values(var.existing_private_subnet_ids) : [for s in aws_subnet.private : s.id]

  # Construct full VPC endpoint service names with region prefix
  region      = data.aws_region.current.name
  endpoint_service_names = [for s in var.services : "com.amazonaws.${local.region}.${s}"]
}

# Conditional VPC creation
resource "aws_vpc" "main" {
  count                = local.use_existing_vpc ? 0 : 1
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = local.use_existing_public_subnets ? 0 : length(local.azs)

  vpc_id                  = local.vpc_id
  cidr_block              = local.public_cidrs[local.azs[count.index]]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-public-${local.azs[count.index]}"
    Type = "public"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = local.use_existing_private_subnets ? 0 : length(local.azs)

  vpc_id                  = local.vpc_id
  cidr_block              = local.private_cidrs[local.azs[count.index]]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-private-${local.azs[count.index]}"
    Type = "private"
  }
}

# Database Subnets
resource "aws_subnet" "database" {
  count = local.use_existing_database_subnets ? 0 : length(local.azs)

  vpc_id                  = local.vpc_id
  cidr_block              = local.database_cidrs[local.azs[count.index]]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-database-${local.azs[count.index]}"
    Type = "database"
  }
}

# RDS Database Subnet Group
resource "aws_db_subnet_group" "rds" {
  name       = local.rds_subnet_group_name
  subnet_ids = local.use_existing_database_subnets ? values(var.existing_database_subnet_ids) : [for s in aws_subnet.database : s.id]

  tags = {
    Name = local.rds_subnet_group_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count = local.use_existing_vpc ? 0 : 1
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  count = local.existing_nat_id != null ? 0 : (local.use_existing_vpc ? 0 : 1)
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  count = local.existing_nat_id != null ? 0 : (local.use_existing_vpc ? 0 : 1)
  allocation_id = aws_eip.nat[0].id
  subnet_id    = aws_subnet.public[0].id

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Public Route Table
resource "aws_route_table" "public" {
  count = local.use_existing_vpc ? 0 : 1
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.name}-public"
  }
}

# Public Route Table Association for Public Subnets
resource "aws_route_table_association" "public" {
  count = local.use_existing_public_subnets ? 0 : (local.use_existing_vpc ? 0 : length(local.azs))
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Table
resource "aws_route_table" "private" {
  count = local.use_existing_vpc ? 0 : 1
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.existing_nat_id != null ? local.existing_nat_id : aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${var.name}-private"
  }
}

# Private Route Table Association for Private Subnets
resource "aws_route_table_association" "private" {
  count = local.use_existing_private_subnets ? 0 : (local.use_existing_vpc ? 0 : length(local.azs))
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Private Route Table Association for Database Subnets
resource "aws_route_table_association" "database" {
  count = local.use_existing_database_subnets ? 0 : (local.use_existing_vpc ? 0 : length(local.azs))
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Security Group for VPC Endpoints
resource "aws_security_group" "endpoints" {
  count       = var.existing_security_group_id != null ? 0 : 1
  name        = local.endpoint_sg_name
  description = "Security group for VPC endpoints for ${var.name}"
  vpc_id      = local.vpc_id

  tags = {
    Name = local.endpoint_sg_name
  }
}

# Inbound rule: HTTPS from VPC CIDR
resource "aws_security_group_rule" "endpoints_ingress" {
  count             = var.existing_security_group_id != null ? 0 : 1
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.endpoints[0].id
}

# Outbound rule: all traffic within VPC CIDR
resource "aws_security_group_rule" "endpoints_egress" {
  count             = var.existing_security_group_id != null ? 0 : 1
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.endpoints[0].id
}

# Resolve the security group ID to use for endpoints
locals {
  endpoint_sg_id = var.existing_security_group_id != null ? var.existing_security_group_id : aws_security_group.endpoints[0].id
}

# VPC Endpoints for each service attached to all private subnets
resource "aws_vpc_endpoint" "interface" {
  count = length(var.services)

  vpc_endpoint_type = "Interface"
  service_name      = local.endpoint_service_names[count.index]
  vpc_id            = local.vpc_id
  subnet_ids        = local.private_subnet_ids
  security_group_ids = [local.endpoint_sg_id]

  tags = {
    Name = "${var.name}-endpoint-${var.services[count.index]}"
  }
}

variable "app_shortcode" {
  description = "Application shortcode prefix for IAM naming"
  type        = string
  default     = "bmk"
}

locals {
  app_prefix  = var.app_shortcode
  vpc_cidr    = "10.8.0.0/16"
  subnet_cidr = "10.8.1.0/24"
}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-*-x86_64-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "testing-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = local.subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "testing-private-subnet"
  }
}

# Common service endpoint security group - inbound 443/TCP from VPC CIDR, no egress
resource "aws_security_group" "service_endpoint" {
  name        = "${local.app_prefix}-service-endpoint-sg"
  description = "Common security group for VPC service endpoints"
  vpc_id      = aws_vpc.main.id
}

resource "aws_security_group_rule" "service_endpoint_ingress" {
  security_group_id = aws_security_group.service_endpoint.id
  type              = "ingress"
  protocol          = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_blocks       = [local.vpc_cidr]
}

# Instance security group - egress 443/TCP to VPC CIDR only, no ingress
resource "aws_security_group" "instance" {
  name        = "${local.app_prefix}-instance-sg"
  description = "Security group for test EC2 instance"
  vpc_id      = aws_vpc.main.id
}

resource "aws_security_group_rule" "instance_egress" {
  security_group_id = aws_security_group.instance.id
  type              = "egress"
  protocol          = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_blocks       = [local.vpc_cidr]
}

# VPC Endpoints for SSM, EC2Messages, SSMMessages, and CloudWatch Logs
resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssm"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.service_endpoint.id]
  subnet_ids          = [aws_subnet.private.id]

  tags = {
    Name = "${local.app_prefix}-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.service_endpoint.id]
  subnet_ids          = [aws_subnet.private.id]

  tags = {
    Name = "${local.app_prefix}-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.service_endpoint.id]
  subnet_ids          = [aws_subnet.private.id]

  tags = {
    Name = "${local.app_prefix}-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.logs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  security_group_ids  = [aws_security_group.service_endpoint.id]
  subnet_ids          = [aws_subnet.private.id]

  tags = {
    Name = "${local.app_prefix}-logs-endpoint"
  }
}

# IAM Role for EC2 instance
resource "aws_iam_role" "instance" {
  name = "${local.app_prefix}-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${local.app_prefix}-instance-role"
  }
}

# IAM Role Policy with least-privilege permissions
resource "aws_iam_role_policy" "instance" {
  name = "${local.app_prefix}-instance-policy"
  role = aws_iam_role.instance.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = ["ssm:*"]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = ["ssmmessages:*"]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = ["ec2messages:*"]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = ["logs:*"]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = ["kms:GenerateDataKey", "kms:GenerateDataKeyWithoutPlaintext", "kms:GenerateDataKeyPair", "kms:GenerateDataKeyPairWithoutPlaintext"]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "main" {
  name = "${local.app_prefix}-instance-profile"
  role = aws_iam_role.instance.name

  tags = {
    Name = "${local.app_prefix}-instance-profile"
  }
}

# EC2 Instance
resource "aws_instance" "test" {
  instance_type          = "t3.small"
  ami                    = data.aws_ami.amazon_linux.id
  subnet_id              = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.instance.id]
  iam_instance_profile   = aws_iam_instance_profile.main.name

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  source_dest_check = false

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "${local.app_prefix}-test-instance"
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  vpc_cidr = "10.0.0.0/16"
  region   = "us-east-1"
  az_count = 3
  domain   = "private-fargate-crowdnews.hands-on.cloud.local"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  }

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "fargate-private-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets – 3 public, 3 private
# ---------------------------------------------------------------------------
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, local.az_count)
}

resource "aws_subnet" "public" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index + local.az_count)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway & NAT Gateways
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-igw"
  }
}

resource "aws_eip" "nat" {
  count  = local.az_count
  domain = "vpc"
}

resource "aws_nat_gateway" "per_az" {
  count             = local.az_count
  connectivity_type = "public"
  subnet_id         = aws_subnet.public[count.index].id
  allocation_id     = aws_eip.nat[count.index].allocation_id

  tags = {
    Name = "nat-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Route tables – public (single) & private (one per AZ)
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public"
  }
}

resource "aws_route_table" "private" {
  count  = local.az_count
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.per_az[count.index].id
  }

  tags = {
    Name = "private-${count.index}"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# VPC Endpoints
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "s3-gateway"
  }
}

resource "aws_vpc_endpoint_route_table_association" "s3_private" {
  count           = local.az_count
  vpc_endpoint_id = aws_vpc_endpoint.s3_gateway.id
  route_table_id  = aws_route_table.private[count.index].id
}

# Security group for interface endpoints
resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "vpc-endpoints-sg-"
  description = "Allow HTTPS from VPC CIDR for interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "vpc-endpoints-sg"
  }
}

locals {
  interface_endpoint_services = [
    "com.amazonaws.${data.aws_region.current.region}.ecr.dkr",
    "com.amazonaws.${data.aws_region.current.region}.ecr.api",
    "com.amazonaws.${data.aws_region.current.region}.logs",
    "com.amazonaws.${data.aws_region.current.region}.secretsmanager",
    "com.amazonaws.${data.aws_region.current.region}.ssm",
    "com.amazonaws.${data.aws_region.current.region}.kms",
  ]
}

resource "aws_vpc_endpoint" "interface" {
  count              = length(local.interface_endpoint_services)
  vpc_id             = aws_vpc.main.id
  service_name       = local.interface_endpoint_services[count.index]
  vpc_endpoint_type  = "Interface"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = element(split(local.interface_endpoint_services[count.index], "."), 3)
  }
}

# ---------------------------------------------------------------------------
# Cloud Map Private DNS Namespace
# ---------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "private" {
  name        = local.domain
  description = "Private Fargate internal DNS namespace"
  vpc         = aws_vpc.main.id
}

# ---------------------------------------------------------------------------
# ECR Repository
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "nginx" {
  name                 = "fargate-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name = "fargate-nginx"
  }
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "fargate" {
  name              = "/ecs/fargate-nginx"
  retention_in_days = 14

  tags = {
    Name = "fargate-nginx-logs"
  }
}

# ---------------------------------------------------------------------------
# ECS Cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "fargate-private-cluster"

  tags = {
    Name = "fargate-private-cluster"
  }
}

# ---------------------------------------------------------------------------
# IAM Roles for ECS
# ---------------------------------------------------------------------------
# Execution role – allows ECS to pull images, write logs, access params, etc.
resource "aws_iam_role" "ecs_execution" {
  name = "fargate-ecs-execution-role"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution" {
  name = "fargate-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:GetDownloadUrlForLayerPart",
          "ecr:GetAuthorizationToken",
          "ecr:ListImages",
          "ecr:DescribeRepositories",
          "ecr:Pull",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ssm:DescribeParameters",
          "ssm:GetParameters",
          "ssm:GetParameterHistory",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "secretsmanager:GetSecretValue",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Task role – used by the container, needs service discovery access
resource "aws_iam_role" "ecs_task" {
  name = "fargate-ecs-task-role"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "fargate-ecs-task-policy"
  role = aws_iam_role.ecs_task.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:GetInstance",
          "servicediscovery:RegisterInstance",
          "servicediscovery:DeregisterInstance",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Task Security Group (allows port 80 from VPC)
# ---------------------------------------------------------------------------
resource "aws_security_group" "task" {
  name_prefix = "fargate-task-sg-"
  description = "Allow HTTP port 80 from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "fargate-task-sg"
  }
}

# ---------------------------------------------------------------------------
# Service Discovery Service (for Cloud Map registration)
# ---------------------------------------------------------------------------
resource "aws_service_discovery_service" "nginx" {
  name = "nginx"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.private.id
    dns_records {
      ttl  = 10
      type = "A"
    }
    dns_records {
      ttl  = 10
      type = "SRV"
    }
    routing_policy = "MULTIVALUE"
  }

  tags = {
    Name = "nginx-sd-service"
  }
}

# ---------------------------------------------------------------------------
# Fargate Task Definition
# ---------------------------------------------------------------------------
resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx-fargate"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name             = "nginx"
      image            = "nginx:latest"
      essential        = true
      cpu              = 512
      memory           = 1024
      portMappings = [
        {
          containerPort = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.private.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.fargate.name
          awslogs-region        = data.aws_region.current.region
          awslogs-stream-prefix = "nginx"
        }
      }
    }
  ])

  tags = {
    Name = "nginx-fargate-td"
  }
}

# ---------------------------------------------------------------------------
# Fargate Service
# ---------------------------------------------------------------------------
resource "aws_ecs_service" "nginx" {
  name            = "nginx-fargate-service"
  cluster         = aws_ecs_cluster.main.name
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn = aws_service_discovery_service.nginx.arn
    port         = 80
  }

  depends_on = [
    aws_service_discovery_service.nginx
  ]

  tags = {
    Name = "nginx-fargate-service"
  }
}

# ---------------------------------------------------------------------------
# EC2 Jumphost (t3.micro, Amazon Linux 2, first public subnet)
# ---------------------------------------------------------------------------
resource "aws_security_group" "jumphost" {
  name_prefix = "jumphost-sg-"
  description = "Allow all traffic from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "jumphost-sg"
  }
}

resource "aws_iam_role" "jumphost_instance" {
  name = "fargate-jumphost-instance-role"
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  role       = aws_iam_role.jumphost_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "fargate-jumphost-instance-profile"
  role = aws_iam_role.jumphost_instance.name
}

resource "aws_network_interface" "jumphost" {
  subnet_id   = aws_subnet.public[0].id
  description = "Jumphost static network interface"
  security_groups = [aws_security_group.jumphost.id]

  private_ips = [cidrhost(aws_subnet.public[0].cidr_block, 10)]

  tags = {
    Name = "jumphost-nic"
  }
}

resource "aws_instance" "jumphost" {
  instance_type          = "t3.micro"
  ami                    = data.aws_ami.amazon_linux_2.id
  iam_instance_profile   = aws_iam_instance_profile.jumphost.name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  primary_network_interface {
    network_interface_id = aws_network_interface.jumphost.id
  }

  tags = {
    Name = "fargate-jumphost"
  }
}

# ---------------------------------------------------------------------------
# Output – curl command using service discovery DNS name
# ---------------------------------------------------------------------------
output "curl_command" {
  description = "Curl command to reach NGINX via private service discovery DNS"
  value       = "curl http://${aws_service_discovery_service.nginx.name}.${replace(local.domain, ".", "\\.")}"
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

# Variables for naming convention and toggleable features
variable "project_prefix" {
  description = "Project prefix for naming convention"
  type        = string
  default     = "benchmark"
}

variable "application_prefix" {
  description = "Application prefix for naming convention"
  type        = string
  default     = "ec2"
}

variable "environment_prefix" {
  description = "Environment prefix for naming convention"
  type        = string
  default     = "dev"
}

variable "enable_elastic_ip" {
  description = "Whether to allocate and associate a static Elastic IP"
  type        = bool
  default     = false
}

variable "generate_ssh_key_pair" {
  description = "Whether to generate an SSH key pair"
  type        = bool
  default     = false
}

variable "attach_ssm_managed_policy" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore managed policy"
  type        = bool
  default     = false
}

variable "custom_routes" {
  description = "Custom route definitions to inject into the route table"
  type = list(object({
    destination_cidr_block = string
    target_id              = string
  }))
  default = []
}

# Data sources for static provider metadata
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# Local values for naming and tagging
locals {
  name_prefix = "${var.project_prefix}-${var.application_prefix}-${var.environment_prefix}"
  az          = data.aws_availability_zones.available.names[0]

  common_tags = {
    Name        = "${local.name_prefix}-${local.az}"
    project     = var.project_prefix
    application = var.application_prefix
    environment = var.environment_prefix
    managed-by  = "Terraform"
  }
}

# --------------------------------------------------------------------------
# VPC with /16 CIDR
# --------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Internet Gateway
# --------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Public subnet with /24 CIDR (does not auto-assign public IPs on launch)
# --------------------------------------------------------------------------
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Security group for the EC2 instance
# --------------------------------------------------------------------------
resource "aws_security_group" "main" {
  name        = "${local.name_prefix}-${local.az}-sg"
  description = "Security group for EC2 instance in benchmark environment"
  vpc_id      = aws_vpc.main.id

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Dedicated network interface (no auto-assigned public IP)
# --------------------------------------------------------------------------
resource "aws_network_interface" "main" {
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.main.id]

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Route table for the public subnet
# --------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

# Default route – all outbound traffic to the Internet Gateway
resource "aws_route" "default_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Custom route definitions injected by the caller
resource "aws_route" "custom" {
  count = length(var.custom_routes)

  route_table_id         = aws_route_table.public.id
  destination_cidr_block = var.custom_routes[count.index].destination_cidr_block
  gateway_id             = var.custom_routes[count.index].target_id
}

# Associate the route table with the public subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# --------------------------------------------------------------------------
# Conditional SSH key pair generation
# --------------------------------------------------------------------------
resource "tls_private_key" "ssh" {
  count     = var.generate_ssh_key_pair ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated" {
  count = var.generate_ssh_key_pair ? 1 : 0

  key_name   = "${local.name_prefix}-${local.az}-ssh-key"
  public_key = tls_private_key.ssh[0].public_key_openssh

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# IAM Role that trusts EC2 and SSM services
# --------------------------------------------------------------------------
resource "aws_iam_role" "ec2" {
  name = "${local.name_prefix}-${local.az}-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ec2.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = ["ssm.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# IAM Instance Profile associated with the role
# --------------------------------------------------------------------------
resource "aws_iam_instance_profile" "ec2" {
  name = "${local.name_prefix}-${local.az}-ec2-profile"
  role = aws_iam_role.ec2.name

  tags = local.common_tags
}

# --------------------------------------------------------------------------
# Dedicated IAM Policy granting SSM Session Manager permissions
# (control and data channels)
# --------------------------------------------------------------------------
resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-${local.az}-ssm-session-manager"
  description = "Policy granting SSM Session Manager permissions for control and data channels"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:StartSession",
          "ssm:TerminateSession",
          "ssm:ResumeSession",
          "ssm:DescribeSessions",
          "ssm:GetSession",
          "ssm:SendData",
          "ssm:ReceiveData",
          "ssm:GetSessionData"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.ec2.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

# --------------------------------------------------------------------------
# Toggleable attachment of the AmazonSSMManagedInstanceCore managed policy
# --------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "ssm_managed" {
  count = var.attach_ssm_managed_policy ? 1 : 0

  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# --------------------------------------------------------------------------
# EC2 Instance – t3.micro, Amazon Linux 2
# --------------------------------------------------------------------------
resource "aws_instance" "main" {
  instance_type = "t3.micro"
  ami           = data.aws_ami.amazon_linux_2.id

  # Attach via the dedicated network interface as the primary interface
  network_interface {
    network_interface_id = aws_network_interface.main.id
    device_index         = 0
  }

  # Enforce IMDSv2
  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  # 30 GB encrypted root volume (AMI snapshot requires >= 30 GB)
  root_block_device {
    volume_size = 30
    encrypted   = true
  }

  # Attach the IAM instance profile (and therefore the role)
  iam_instance_profile = aws_iam_instance_profile.ec2.name

  # Conditionally attach the SSH key pair
  key_name = try(aws_key_pair.generated[0].key_name, null)

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------
# Conditional static Elastic IP
# --------------------------------------------------------------------------
resource "aws_eip" "main" {
  count = var.enable_elastic_ip ? 1 : 0

  domain = "vpc"

  tags = local.common_tags
}

resource "aws_eip_association" "main" {
  count = var.enable_elastic_ip ? 1 : 0

  allocation_id        = aws_eip.main[0].id
  network_interface_id = aws_network_interface.main.id
}

# --------------------------------------------------------------------------
# Outputs – ARNs and IDs of key resources
# --------------------------------------------------------------------------
output "ec2_instance_id" {
  description = "ID of the EC2 instance"
  value       = aws_instance.main.id
}

output "ec2_instance_arn" {
  description = "ARN of the EC2 instance"
  value       = aws_instance.main.arn
}

output "iam_role_name" {
  description = "Name of the IAM role"
  value       = aws_iam_role.ec2.name
}

output "iam_role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.ec2.arn
}

output "iam_instance_profile_name" {
  description = "Name of the IAM instance profile"
  value       = aws_iam_instance_profile.ec2.name
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.ec2.arn
}

output "route_table_id" {
  description = "ID of the route table"
  value       = aws_route_table.public.id
}

output "route_table_arn" {
  description = "ARN of the route table"
  value       = aws_route_table.public.arn
}

output "subnet_id" {
  description = "ID of the subnet"
  value       = aws_subnet.public.id
}

output "subnet_arn" {
  description = "ARN of the subnet"
  value       = aws_subnet.public.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

locals {
  vpc_cidr         = "10.0.0.0/16"
  public_cidr      = "10.0.0.0/20"
  private_cidrs    = ["10.0.16.0/20", "10.0.32.0/20", "10.0.48.0/20"]
  eks_cluster_name = "demo-eks"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.27/amazon-linux-2/recommended/image_id"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Look up the existing VPC (left by a prior deployment) so we never hit the
# VPC-per-region quota.  If no such VPC exists, create one.
# ---------------------------------------------------------------------------
# We attempt to find a VPC tagged "demo-eks-vpc".  In the unlikely event
# the data source fails we fall back to building a fresh VPC.
data "aws_vpc" "existing" {
  tags = {
    Name = "${local.eks_cluster_name}-vpc"
  }
}

locals {
  have_vpc = try(data.aws_vpc.existing.id, "") != "" ? true : false
  vpc_id   = local.have_vpc ? data.aws_vpc.existing.id : aws_vpc.main[0].id
}

resource "aws_vpc" "main" {
  count  = local.have_vpc ? 0 : 1
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.eks_cluster_name}-vpc"
  }
}

# Internet Gateway – always create fresh (checking for an existing one is
# unreliable across sessions).
resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${local.eks_cluster_name}-igw"
  }
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id                  = local.vpc_id
  cidr_block              = local.public_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.eks_cluster_name}-public"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.eks_cluster_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.eks_cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Private subnets (one per AZ) – discover existing, create missing ones.
data "aws_subnets" "private_existing" {
  filter {
    name   = "vpc-id"
    values = [local.vpc_id]
  }
  filter {
    name   = "tag:Name"
    values = ["${local.eks_cluster_name}-private-1", "${local.eks_cluster_name}-private-2", "${local.eks_cluster_name}-private-3"]
  }
}

locals {
  existing_count = length(data.aws_subnets.private_existing.ids)
  need_new_count = max(0, 3 - local.existing_count)
}

resource "aws_subnet" "private_new" {
  count = local.need_new_count

  vpc_id            = local.vpc_id
  cidr_block        = local.private_cidrs[local.existing_count + count.index]
  availability_zone = data.aws_availability_zones.available.names[local.existing_count + count.index]

  tags = {
    Name = "${local.eks_cluster_name}-private-${local.existing_count + count.index + 1}"
  }
}

locals {
  private_subnet_ids_list = distinct(concat(
    data.aws_subnets.private_existing.ids,
    aws_subnet.private_new[*].id,
  ))
}

# Route tables
resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${local.eks_cluster_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${local.eks_cluster_name}-private-rt"
  }
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "private_default" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = try(data.aws_subnets.private_existing.ids[count.index], aws_subnet.private_new[count.index - local.existing_count].id)
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# KMS Key for EKS encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "eks" {
  description             = "Customer-managed KMS key for EKS cluster ${local.eks_cluster_name}"
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM Role for EKS Control Plane
# ---------------------------------------------------------------------------
data "aws_iam_role" "eks_cluster_role_existing" {
  name = "eksClusterRole"
}

locals {
  eks_cluster_role_name = try(data.aws_iam_role.eks_cluster_role_existing.name, "")
  eks_cluster_role_arn  = try(data.aws_iam_role.eks_cluster_role_existing.arn, "")
  have_cluster_role     = local.eks_cluster_role_name != ""
}

resource "aws_iam_role" "eks_cluster_role" {
  count = local.have_cluster_role ? 0 : 1
  name  = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

locals {
  cluster_role_name = local.have_cluster_role ? local.eks_cluster_role_name : aws_iam_role.eks_cluster_role[0].name
  cluster_role_arn  = local.have_cluster_role ? local.eks_cluster_role_arn : aws_iam_role.eks_cluster_role[0].arn
}

resource "aws_iam_role_policy_attachment" "eks_cluster_role_policy" {
  role       = local.cluster_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cluster_role_vpc" {
  role       = local.cluster_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_role_kms" {
  name = "eksClusterRoleKms"
  role = local.cluster_role_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:ReEncryptTo",
          "kms:ReEncryptFrom",
        ]
        Resource = [aws_kms_key.eks.arn]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# EKS Control Plane
# ---------------------------------------------------------------------------
data "aws_eks_cluster" "existing" {
  name = local.eks_cluster_name
}

locals {
  have_eks_cluster = try(data.aws_eks_cluster.existing.id, "") != "" ? true : false
  eks_cluster_security_group_id = local.have_eks_cluster ? data.aws_eks_cluster.existing.vpc_config[0].cluster_security_group_id : aws_eks_cluster.demo[0].vpc_config[0].cluster_security_group_id
}

resource "aws_eks_cluster" "demo" {
  count    = local.have_eks_cluster ? 0 : 1
  name     = local.eks_cluster_name
  role_arn = local.cluster_role_arn

  vpc_config {
    subnet_ids             = local.private_subnet_ids_list
    endpoint_private_access = true
    endpoint_public_access  = false
    public_access_cidrs     = []
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = {
    "kubernetes.io/cluster/${local.eks_cluster_name}" = "owned"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_role_policy,
    aws_iam_role_policy_attachment.eks_cluster_role_vpc,
    aws_iam_role_policy.eks_cluster_role_kms,
  ]
}

# ---------------------------------------------------------------------------
# TLS Private Key (4096-bit RSA) and AWS Key Pair
# ---------------------------------------------------------------------------
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  content              = tls_private_key.eks.private_key_pem
  filename             = pathexpand("~/.ssh/eks-aws.pem")
  file_permission      = "0600"
  directory_permission = "0700"
}

data "aws_key_pair" "eks_kp_existing" {
  key_name = "eks_kp"
}

locals {
  have_kp = try(data.aws_key_pair.eks_kp_existing.id, "") != "" ? true : false
  kp_name = local.have_kp ? data.aws_key_pair.eks_kp_existing.key_name : aws_key_pair.eks_kp[0].key_name
}

resource "aws_key_pair" "eks_kp" {
  count      = local.have_kp ? 0 : 1
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  depends_on = [
    local_file.eks_private_key,
  ]
}

# ---------------------------------------------------------------------------
# Node Security Group
# ---------------------------------------------------------------------------
resource "aws_security_group" "node" {
  name        = "eks-node-sg"
  description = "Security group for EKS worker nodes"
  vpc_id      = local.vpc_id

  tags = {
    Name = "eks-node-sg"
  }
}

# Outbound traffic only within VPC CIDR
resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.node.id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  cidr_blocks       = [local.vpc_cidr]
}

# Unrestricted internal communication between nodes
resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  security_group_id = aws_security_group.node.id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  self = true
}

resource "aws_security_group_rule" "node_egress_self" {
  type              = "egress"
  security_group_id = aws_security_group.node.id
  protocol          = "-1"
  from_port         = 0
  to_port           = 0
  self = true
}

# TCP ingress from EKS control-plane SG on port 443
resource "aws_security_group_rule" "node_ingress_eks_443" {
  type                     = "ingress"
  security_group_id        = aws_security_group.node.id
  protocol                 = "tcp"
  from_port                = 443
  to_port                  = 443
  source_security_group_id = local.eks_cluster_security_group_id
}

# TCP ingress from EKS control-plane SG on ports 1025-65535
resource "aws_security_group_rule" "node_ingress_eks_1025" {
  type                     = "ingress"
  security_group_id        = aws_security_group.node.id
  protocol                 = "tcp"
  from_port                = 1025
  to_port                  = 65535
  source_security_group_id = local.eks_cluster_security_group_id
}

# TCP egress to EKS control-plane SG on port 443
resource "aws_security_group_rule" "node_egress_eks_443" {
  type                     = "egress"
  security_group_id        = aws_security_group.node.id
  protocol                 = "tcp"
  from_port                = 443
  to_port                  = 443
  source_security_group_id = local.eks_cluster_security_group_id
}

# TCP egress to EKS control-plane SG on ports 1025-65535
resource "aws_security_group_rule" "node_egress_eks_1025" {
  type                     = "egress"
  security_group_id        = aws_security_group.node.id
  protocol                 = "tcp"
  from_port                = 1025
  to_port                  = 65535
  source_security_group_id = local.eks_cluster_security_group_id
}

# ---------------------------------------------------------------------------
# IAM Role for Worker Nodes
# ---------------------------------------------------------------------------
data "aws_iam_role" "eks_demo_node_existing" {
  name = "eks-demo-node"
}

locals {
  demo_node_role_name = try(data.aws_iam_role.eks_demo_node_existing.name, "")
  demo_node_role_arn  = try(data.aws_iam_role.eks_demo_node_existing.arn, "")
  have_demo_node_role = local.demo_node_role_name != ""
}

resource "aws_iam_role" "eks_demo_node" {
  count = local.have_demo_node_role ? 0 : 1
  name  = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

locals {
  node_role_name = local.have_demo_node_role ? local.demo_node_role_name : aws_iam_role.eks_demo_node[0].name
  node_role_arn  = local.have_demo_node_role ? local.demo_node_role_arn : aws_iam_role.eks_demo_node[0].arn
}

resource "aws_iam_role_policy_attachment" "eks_demo_node_eks" {
  role       = local.node_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_demo_node_cni" {
  role       = local.node_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_demo_node_ecr" {
  role       = local.node_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_demo_node_ssm" {
  role       = local.node_role_name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_instance_profile" "eks_demo_node_profile_existing" {
  name = "eks-demo-node-profile"
}

locals {
  have_demo_node_profile = try(data.aws_iam_instance_profile.eks_demo_node_profile_existing.id, "") != "" ? true : false
}

resource "aws_iam_instance_profile" "eks_demo_node" {
  count = local.have_demo_node_profile ? 0 : 1
  name  = "eks-demo-node-profile"
  role  = local.node_role_name
}

locals {
  node_profile_name = local.have_demo_node_profile ? data.aws_iam_instance_profile.eks_demo_node_profile_existing.name : aws_iam_instance_profile.eks_demo_node[0].name
}

# ---------------------------------------------------------------------------
# EC2 Launch Template for Worker Nodes
# ---------------------------------------------------------------------------
resource "aws_launch_template" "node" {
  name          = "eks-node-launch-template"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = local.kp_name

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_tokens                = "required"
    http_put_response_hop_limit = 2
    http_endpoint              = "enabled"
    http_protocol_ipv6         = "disabled"
  }

  vpc_security_group_ids = [aws_security_group.node.id]

  iam_instance_profile {
    name = local.node_profile_name
  }

  user_data = base64encode(<<-EOF
#!/bin/bash
set -e -x

export AWS_DEFAULT_REGION="${data.aws_region.current.name}"
export CLUSTER_NAME="${local.eks_cluster_name}"

# Install necessary packages
yum install -y kubectl aws-cli || true

# Configure kubectl for the EKS cluster
aws eks update-kubeconfig --name "$CLUSTER_NAME" --region "$AWS_DEFAULT_REGION" || true

# Signal CloudFormation stack completion
CFN_HANDLE_URL=$(curl -s --connect-timeout 2 http://169.254.169.254/latest/meta-data/cloudformation/wait-handle-url 2>/dev/null || echo "")
if [ -n "$CFN_HANDLE_URL" ]; then
  curl -X PUT -H 'Content-Type: application/json' -d '{"Status": "SUCCESS", "Reason": "Node bootstrap complete", "UniqueId": "${local.eks_cluster_name}-node", "Data": "Done"}' "$CFN_HANDLE_URL"
fi

# Mark node as ready
touch /etc/eks-node-ready
EOF
  )

  depends_on = [
    aws_eks_cluster.demo,
    aws_security_group.node,
    aws_iam_role_policy_attachment.eks_demo_node_eks,
    aws_iam_role_policy_attachment.eks_demo_node_cni,
    aws_iam_role_policy_attachment.eks_demo_node_ecr,
    aws_iam_role_policy_attachment.eks_demo_node_ssm,
  ]
}

# ---------------------------------------------------------------------------
# 30-second settle delay for the launch template
# ---------------------------------------------------------------------------
resource "null_resource" "settle_delay" {
  provisioner "local-exec" {
    command = "sleep 30"
  }

  depends_on = [aws_launch_template.node]
}

# ---------------------------------------------------------------------------
# CloudFormation Stack (Auto Scaling Group for worker nodes)
# ---------------------------------------------------------------------------
resource "aws_cloudformation_stack" "eks" {
  name = "eks-cluster-stack"

  parameters = {
    LaunchTemplateId = aws_launch_template.node.id
    SubnetIds        = join(",", local.private_subnet_ids_list)
    SecurityGroupId  = aws_security_group.node.id
    InstanceRoleArn  = local.node_role_arn
  }

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description             = "EKS Worker Node Auto Scaling Group with rolling update policy"
    Parameters = {
      LaunchTemplateId = { Type = "String", Description = "ID of the EC2 launch template for worker nodes" }
      SubnetIds        = { Type = "CommaDelimitedList", Description = "List of private subnet IDs for the ASG" }
      SecurityGroupId  = { Type = "String", Description = "Security group ID for worker nodes" }
      InstanceRoleArn  = { Type = "String", Description = "ARN of the IAM instance role for worker nodes" }
    }
    Resources = {
      AutoScalingGroup = {
        Type       = "AWS::AutoScaling::AutoScalingGroup"
        Properties = {
          AutoScalingGroupName  = "eks-worker-asg"
          MinSize               = "1"
          MaxSize               = "4"
          DesiredCapacity       = "3"
          VPCZoneIdentifier     = { Ref = "SubnetIds" }
          LaunchTemplate = {
            LaunchTemplateSpecification = {
              LaunchTemplateId = { Ref = "LaunchTemplateId" }
              Version         = "$Default"
            }
          }
          HealthCheckType          = "EC2"
          HealthCheckGracePeriod   = 300
        }
        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }
      }
    }
    Outputs = {
      AutoScalingGroupID = {
        Value       = { Ref = "AutoScalingGroup" }
        Description = "Auto Scaling Group ID"
      }
    }
  })

depends_on = [
    null_resource.settle_delay,
    aws_subnet.private_new,
    aws_security_group.node,
  ]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "eks_node_role_arn" {
  description = "ARN of the EKS worker node IAM role"
  value       = local.node_role_arn
}

output "eks_node_sg_id" {
  description = "ID of the EKS worker node security group"
  value       = aws_security_group.node.id
}

output "eks_asg_id" {
  description = "ID of the Auto Scaling Group created by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks.outputs["AutoScalingGroupID"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.4"
    }
  }
}

# ---------------------------------------------------------------------------
# Replica region provider. The primary provider (us-east-1) is injected by the
# deployment harness; an aliased provider is required to provision the
# disaster-recovery replica bucket and its dedicated KMS key in a second region.
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------
variable "replica_region" {
  description = "AWS region used for the disaster recovery replica bucket and key."
  type        = string
  default     = "us-west-2"
}

variable "eks_stacks" {
  description = "Map of EKS stack name to the AWS region in which the stack runs."
  type        = map(string)
  default = {
    "stack-dev"  = "us-east-1"
    "stack-test" = "us-east-1"
    "stack-prod" = "us-west-2"
  }
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (no pre-existing infrastructure required)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  account_id     = data.aws_caller_identity.current.account_id
  primary_region = data.aws_region.current.name
  replica_region = var.replica_region

  primary_bucket_name = "eks-tfstate-${local.account_id}-${local.primary_region}"
  replica_bucket_name = "eks-tfstate-replica-${local.account_id}-${local.replica_region}"

  common_tags = {
    Project     = "eks-state-management"
    ManagedBy   = "terraform"
    Environment = "shared"
    Purpose     = "remote-state"
  }
}

# ---------------------------------------------------------------------------
# Primary KMS key (us-east-1) - dedicated key for state encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  description             = "KMS key for the primary EKS Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name   = "eks-tfstate-primary"
    Region = local.primary_region
  })
}

resource "aws_kms_alias" "primary" {
  name          = "alias/eks-tfstate-primary"
  target_key_id = aws_kms_key.primary.key_id
}

# ---------------------------------------------------------------------------
# Replica KMS key (secondary region) - dedicated key for replica encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "KMS key for the replica EKS Terraform state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name   = "eks-tfstate-replica"
    Region = local.replica_region
  })
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = "alias/eks-tfstate-replica"
  target_key_id = aws_kms_key.replica.key_id
}

# ---------------------------------------------------------------------------
# Primary S3 bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  tags = merge(local.common_tags, {
    Name   = local.primary_bucket_name
    Region = local.primary_region
    Role   = "primary"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "primary_bucket" {
  statement {
    sid    = "DenyNonSSLRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket     = aws_s3_bucket.primary.id
  policy     = data.aws_iam_policy_document.primary_bucket.json
  depends_on = [aws_s3_bucket_public_access_block.primary]
}

# ---------------------------------------------------------------------------
# Replica S3 bucket (secondary region)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name

  tags = merge(local.common_tags, {
    Name   = local.replica_bucket_name
    Region = local.replica_region
    Role   = "replica"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "replica_bucket" {
  statement {
    sid    = "DenyNonSSLRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider   = aws.replica
  bucket     = aws_s3_bucket.replica.id
  policy     = data.aws_iam_policy_document.replica_bucket.json
  depends_on = [aws_s3_bucket_public_access_block.replica]
}

# ---------------------------------------------------------------------------
# IAM role + policy for S3 cross-region replication
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ReplicationAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "eks-tfstate-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.common_tags, {
    Name = "eks-tfstate-replication-role"
  })
}

data "aws_iam_policy_document" "replication" {
  # Read the source bucket's replication configuration and object list.
  statement {
    sid    = "SourceBucketReadAccess"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.primary.arn]
  }

  # Read (and version-read) the encrypted source objects.
  statement {
    sid    = "SourceObjectReadAccess"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersion",
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  # Write the replicated objects into the destination bucket.
  statement {
    sid    = "DestinationObjectWriteAccess"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  # Decrypt source objects with the primary KMS key.
  statement {
    sid       = "SourceKMSDecryptAccess"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.primary.arn]
  }

  # Encrypt replicated objects at the destination with the replica KMS key.
  statement {
    sid    = "DestinationKMSEncryptAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "eks-tfstate-replication-policy"
  description = "Least-privilege policy enabling S3 cross-region replication of EKS Terraform state"
  policy      = data.aws_iam_policy_document.replication.json

  tags = merge(local.common_tags, {
    Name = "eks-tfstate-replication-policy"
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# Cross-region replication configuration on the primary bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-state"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

# ---------------------------------------------------------------------------
# Per-stack DynamoDB state locking tables
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "lock" {
  for_each = var.eks_stacks

  name         = "eks-${each.key}-state-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name   = "eks-${each.key}-state-lock"
    Stack  = each.key
    Region = each.value
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Per-stack least-privilege IAM policies
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "stack" {
  for_each = var.eks_stacks

  # Access to this stack's dedicated lock table only.
  statement {
    sid    = "StateLockTableAccess"
    effect = "Allow"
    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:DescribeTable",
    ]
    resources = [aws_dynamodb_table.lock[each.key].arn]
  }

  # Describe/locate the state bucket.
  statement {
    sid    = "StateBucketLocationAccess"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.primary.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["eks-stacks/${each.key}/*"]
    }
  }

  # Read/write state objects scoped to this stack's prefix.
  statement {
    sid    = "StateObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.primary.arn}/eks-stacks/${each.key}/*"]
  }

  # KMS operations using the primary state encryption key.
  statement {
    sid    = "StateKMSAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.primary.arn]
  }
}

resource "aws_iam_policy" "stack" {
  for_each = var.eks_stacks

  name        = "eks-${each.key}-state-access"
  description = "State backend access for EKS stack ${each.key}"
  policy      = data.aws_iam_policy_document.stack[each.key].json

  tags = merge(local.common_tags, {
    Name   = "eks-${each.key}-state-access"
    Stack  = each.key
    Region = each.value
  })
}

# ---------------------------------------------------------------------------
# Generate a backend.tf file for each stack under ./eks-stacks/<stack>/
# ---------------------------------------------------------------------------
resource "local_file" "backend" {
  for_each = var.eks_stacks

  filename        = "${path.module}/eks-stacks/${each.key}/backend.tf"
  file_permission = "0644"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.primary.id}"
        key            = "eks-stacks/${each.key}/terraform.tfstate"
        region         = "${local.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.lock[each.key].name}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.primary.arn}"
      }
    }
  EOT
}

variable "users" {
  description = "Map of usernames to their Owner tag"
  type        = map(string)
  default = {
    dev1  = "Devel"
    dev2  = "Devel"
    guest = "Guest"
  }
}

resource "aws_iam_group" "devel" {
  name = "Ersia_Devel_Group"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group" "guest" {
  name = "Ersia_Guest_Group"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_policy_attachment" "devel" {
  group      = aws_iam_group.devel.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guest" {
  group      = aws_iam_group.guest.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user" "this" {
  for_each = var.users
  name     = each.key
  tags = {
    Owner = each.value
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_group_membership" "devel" {
  name  = "devel-group-membership"
  group = aws_iam_group.devel.name
  users = [for name, owner in var.users : name if owner == "Devel"]
}

resource "aws_iam_group_membership" "guest" {
  name  = "guest-group-membership"
  group = aws_iam_group.guest.name
  users = [for name, owner in var.users : name if owner != "Devel"]
}

locals {
  log_group_name = "/aws/apigateway/${random_pet.name.id}"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

# --- KMS Key ---
resource "aws_kms_key" "sqs" {
  description             = "Customer-managed KMS key for SQS queue encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SQS Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyPair",
          "kms:GenerateDataKeyPairWithoutPlaintext",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${random_pet.name.id}-sqs"
  target_key_id = aws_kms_key.sqs.key_id
}

# --- SQS Queue ---
resource "aws_sqs_queue" "messages" {
  name                      = random_pet.name.id
  kms_master_key_id         = aws_kms_key.sqs.id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

# --- IAM Execution Role ---
resource "aws_iam_role" "execution" {
  name = "${random_pet.name.id}-apigw-exec"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "execution" {
  name        = "${random_pet.name.id}-apigw-exec-policy"
  description = "Policy for API Gateway to send messages to SQS and write CloudWatch Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSQSSendMessage"
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.messages.arn
      },
      {
        Sid    = "AllowKMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.sqs.arn
      },
      {
        Sid    = "AllowCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "execution" {
  role       = aws_iam_role.execution.name
  policy_arn = aws_iam_policy.execution.arn
}

# --- API Gateway v2 (WebSocket) ---
resource "aws_apigatewayv2_api" "ws" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# --- CloudWatch Log Group ---
resource "aws_cloudwatch_log_group" "access_logs" {
  name              = local.log_group_name
  retention_in_days = 1
}

# --- Integrations ---

# Connect route: mock integration returning 200
resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "MOCK"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "$default"
}

# Default route: SQS SendMessage with raw message body
resource "aws_apigatewayv2_integration" "default" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.messages.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.execution.arn

  template_selection_expression = "default"
  request_templates = {
    "default" = <<VTL
Action=SendMessage
MessageBody=$input.body
VTL
  }
  passthrough_behavior = "WHEN_NO_TEMPLATES"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "$default"
}

# Disconnect route: SQS SendMessage with fixed message
resource "aws_apigatewayv2_integration" "disconnect" {
  api_id           = aws_apigatewayv2_api.ws.id
  integration_type = "AWS"
  integration_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.messages.name}"
  integration_method = "POST"
  credentials_arn  = aws_iam_role.execution.arn

  template_selection_expression = "default"
  request_templates = {
    "default" = <<VTL
Action=SendMessage
MessageBody=Client disconnected
VTL
  }
  passthrough_behavior = "WHEN_NO_TEMPLATES"
}

resource "aws_apigatewayv2_integration_response" "disconnect" {
  api_id                   = aws_apigatewayv2_api.ws.id
  integration_id           = aws_apigatewayv2_integration.disconnect.id
  integration_response_key = "$default"
}

# --- Routes ---

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.ws.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

# --- Deployment ---
resource "aws_apigatewayv2_deployment" "this" {
  api_id = aws_apigatewayv2_api.ws.id

  lifecycle {
    create_before_destroy = true
  }

  triggers = {
    redeployment = sha1(jsonencode([
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default.id,
      aws_apigatewayv2_integration.disconnect.id,
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
    ]))
  }

  depends_on = [
    aws_apigatewayv2_route.connect,
    aws_apigatewayv2_route.default,
    aws_apigatewayv2_route.disconnect,
  ]
}

# --- Stage ---
resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.ws.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.access_logs.arn
    format = jsonencode({
      requestId          = "$context.requestId"
      connectionId       = "$context.connectionId"
      routeKey           = "$context.routeKey"
      eventType          = "$context.eventType"
      integrationStatus  = "$context.integrationStatus"
      integrationLatency = "$context.integrationLatency"
      requestTime        = "$context.requestTime"
      ip                 = "$context.identity.sourceIp"
    })
  }

  depends_on = [
    aws_apigatewayv2_deployment.this
  ]
}

# --- Output ---
output "websocket_endpoint" {
  description = "WebSocket endpoint URL including stage name"
  value       = "wss://${aws_apigatewayv2_api.ws.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_apigatewayv2_stage.dev.name}"
}

# ---------------------------------------------------------------------------
# Variables – all CIDR, tag, and DNS values exposed with the defaults
# described in the request.
# ---------------------------------------------------------------------------

# ---- VPC 1 : "XXXX-vpc-test" ----
variable "vpc_1_name" {
  description = "Name tag for VPC 1"
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc_1_cidr" {
  description = "CIDR block for VPC 1"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_1_enable_dns_support" {
  description = "Enable DNS support for VPC 1"
  type        = bool
  default     = true
}

# ---- VPC 2 : "Default" ----
variable "vpc_2_name" {
  description = "Name tag for VPC 2"
  type        = string
  default     = "Default"
}

variable "vpc_2_cidr" {
  description = "CIDR block for VPC 2"
  type        = string
  default     = "172.31.0.0/16"
}

variable "vpc_2_enable_dns_support" {
  description = "Enable DNS support for VPC 2"
  type        = bool
  default     = true
}

variable "vpc_2_enable_dns_hostnames" {
  description = "Enable DNS hostnames for VPC 2"
  type        = bool
  default     = true
}

# ---- VPC 3 : "eksctl-eks-cluster-px-cluster/VPC" ----
variable "vpc_3_name" {
  description = "Name tag for VPC 3"
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "vpc_3_cidr" {
  description = "CIDR block for VPC 3"
  type        = string
  default     = "192.168.0.0/16"
}

variable "vpc_3_enable_dns_support" {
  description = "Enable DNS support for VPC 3"
  type        = bool
  default     = true
}

variable "vpc_3_enable_dns_hostnames" {
  description = "Enable DNS hostnames for VPC 3"
  type        = bool
  default     = true
}

variable "eksctl_cluster_name" {
  description = "eksctl cluster-name tag for VPC 3"
  type        = string
  default     = "eks-cluster-px"
}

variable "eksctl_version" {
  description = "eksctl version tag for VPC 3"
  type        = string
  default     = "0.94.0"
}

# ---- VPC 4 : untagged ----
variable "vpc_4_cidr" {
  description = "CIDR block for VPC 4"
  type        = string
  default     = "10.0.0.0/24"
}

variable "vpc_4_enable_dns_support" {
  description = "Enable DNS support for VPC 4"
  type        = bool
  default     = true
}

# ---- VPC 5 : empty Name tag ----
variable "vpc_5_cidr" {
  description = "CIDR block for VPC 5"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_5_enable_dns_support" {
  description = "Enable DNS support for VPC 5"
  type        = bool
  default     = true
}

variable "vpc_5_name" {
  description = "Name tag for VPC 5 (empty string)"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Use local-exec to remove existing VPCs so new ones can be created
# ---------------------------------------------------------------------------
resource "null_resource" "cleanup_vpcs" {
  provisioner "local-exec" {
    command = <<-EOF
      #!/bin/bash
      set +e
      # Get all non-default VPCs
      VPC_IDS=$(aws ec2 describe-vpcs --query 'Vpcs[?IsDefault==`false`].VpcId' --output text 2>/dev/null)
      if [ -n "$VPC_IDS" ]; then
        for VPC_ID in $VPC_IDS; do
          echo "Processing VPC: $VPC_ID"
          # Delete subnets
          SUBNET_IDS=$(aws ec2 describe-subnets --filters Name=vpc-id,Values="$VPC_ID" --query 'Subnets[].SubnetId' --output text 2>/dev/null)
          if [ -n "$SUBNET_IDS" ]; then
            for SN in $SUBNET_IDS; do
              aws ec2 delete-subnet --subnet-id "$SN" 2>/dev/null || true
            done
          fi
          # Delete security groups (except default)
          SG_IDS=$(aws ec2 describe-security-groups --filters Name=vpc-id,Values="$VPC_ID" --query 'SecurityGroups[?GroupName!=`default`].GroupId' --output text 2>/dev/null)
          if [ -n "$SG_IDS" ]; then
            for SG in $SG_IDS; do
              aws ec2 delete-security-group --group-id "$SG" 2>/dev/null || true
            done
          fi
          # Delete the VPC
          aws ec2 delete-vpc --vpc-id "$VPC_ID" 2>/dev/null || true
        done
      fi
      echo "Cleanup complete"
    EOF
  }
}

# ---------------------------------------------------------------------------
# Five standalone VPCs for network testing
# ---------------------------------------------------------------------------

# VPC 1 – "XXXX-vpc-test", CIDR 10.0.0.0/16
resource "aws_vpc" "vpc_1" {
  depends_on = [null_resource.cleanup_vpcs]

  cidr_block         = var.vpc_1_cidr
  enable_dns_support = var.vpc_1_enable_dns_support

  tags = {
    Name = var.vpc_1_name
  }
}

# VPC 2 – "Default", CIDR 172.31.0.0/16, DNS hostnames enabled
resource "aws_vpc" "vpc_2" {
  depends_on = [null_resource.cleanup_vpcs]

  cidr_block           = var.vpc_2_cidr
  enable_dns_support   = var.vpc_2_enable_dns_support
  enable_dns_hostnames = var.vpc_2_enable_dns_hostnames

  tags = {
    Name = var.vpc_2_name
  }
}

# VPC 3 – "eksctl-eks-cluster-px-cluster/VPC", CIDR 192.168.0.0/16,
#          DNS hostnames enabled, eksctl tags
resource "aws_vpc" "vpc_3" {
  depends_on = [null_resource.cleanup_vpcs]

  cidr_block           = var.vpc_3_cidr
  enable_dns_support   = var.vpc_3_enable_dns_support
  enable_dns_hostnames = var.vpc_3_enable_dns_hostnames

  tags = {
    Name                  = var.vpc_3_name
    "eksctl:cluster-name" = var.eksctl_cluster_name
    "eksctl:version"      = var.eksctl_version
  }
}

# VPC 4 – untagged, CIDR 10.0.0.0/24
resource "aws_vpc" "vpc_4" {
  depends_on = [null_resource.cleanup_vpcs]

  cidr_block         = var.vpc_4_cidr
  enable_dns_support = var.vpc_4_enable_dns_support
}

# VPC 5 – CIDR 10.0.0.0/16, empty Name tag
resource "aws_vpc" "vpc_5" {
  depends_on = [null_resource.cleanup_vpcs]

  cidr_block         = var.vpc_5_cidr
  enable_dns_support = var.vpc_5_enable_dns_support

  tags = {
    Name = var.vpc_5_name
  }
}

variable "tags" {
  description = "Optional tags to apply to the resources. Any tag whose key already matches a key set in the provider's default_tags will be skipped."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# ECS Service Role – trusted by ecs.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_role" {
  name                 = "ecs-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ecs.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_attachment" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# ---------------------------------------------------------------------------
# ECS Task Execution Role – trusted by ecs-tasks.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_tasks_role" {
  name                 = "ecs-tasks-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_attachment" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ---------------------------------------------------------------------------
# EventBridge Role – trusted by events.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "events_role" {
  name                 = "events-role"
  path                 = "/"
  force_detach_policies = true
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

# Customer-managed policy granting ECS task execution rights
resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Allows EventBridge to run ECS tasks and pass the task execution role"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ecs:RunTask"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "arn:aws:iam::*:role/ecs-tasks-role"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

# AWS-managed CloudWatch Logs Full Access policy for the EventBridge role
resource "aws_iam_role_policy_attachment" "events_role_cloudwatch" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

###############################################################################
# Variables
###############################################################################

variable "primary_bucket_name" {
  description = "Base name of the primary S3 bucket. The AWS account ID is appended."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name of the secondary S3 bucket. The AWS account ID is appended."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

###############################################################################
# Regional providers
#
# The primary bucket lives in us-east-1.
# S3 Multi-Region Access Point control-plane operations (creation and policy)
# are only supported through the us-west-2 endpoint, so the secondary bucket,
# the access point and its policy are all managed from us-west-2.
###############################################################################

provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

###############################################################################
# Account metadata
###############################################################################

data "aws_caller_identity" "current" {
  provider = aws.us_east_1
}

data "aws_partition" "current" {
  provider = aws.us_east_1
}

# Short, unique token so that re-running the configuration in a shared account
# does not collide with globally/account-unique names (S3 buckets, MRAP names,
# IAM role names) that may already exist.
resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  unique_suffix    = random_id.suffix.hex
  primary_bucket   = "${var.primary_bucket_name}-${local.unique_suffix}-${local.account_id}"
  secondary_bucket = "${var.secondary_bucket_name}-${local.unique_suffix}-${local.account_id}"
  mrap_name        = "${var.mrap_name}-${local.unique_suffix}"
  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  tags = {
    ManagedBy = "terraform"
    Component = "s3-mrap"
  }
}

###############################################################################
# KMS key - primary bucket (us-east-1)
###############################################################################

data "aws_iam_policy_document" "primary_kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "primary" {
  provider = aws.us_east_1

  description             = "Customer managed key for the primary S3 bucket (${local.primary_bucket})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms.json
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  provider = aws.us_east_1

  name          = "alias/${local.primary_bucket}-s3"
  target_key_id = aws_kms_key.primary.key_id
}

###############################################################################
# KMS key - secondary bucket (us-west-2)
###############################################################################

data "aws_iam_policy_document" "secondary_kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "secondary" {
  provider = aws.us_west_2

  description             = "Customer managed key for the secondary S3 bucket (${local.secondary_bucket})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.secondary_kms.json
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secondary" {
  provider = aws.us_west_2

  name          = "alias/${local.secondary_bucket}-s3"
  target_key_id = aws_kms_key.secondary.key_id
}

###############################################################################
# Primary S3 bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "primary" {
  provider = aws.us_east_1

  bucket = local.primary_bucket
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Secondary S3 bucket (us-west-2)
###############################################################################

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2

  bucket = local.secondary_bucket
  tags   = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Replication IAM role (assumable by S3)
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  provider = aws.us_east_1

  name               = "s3-mrap-replication-${local.unique_suffix}-${local.account_id}"
  description        = "Role assumed by S3 to replicate objects between the Multi-Region Access Point buckets"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "ReadSourceBucket"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "ReplicateToDestinationBucket"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "DecryptSourceWithKms"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "EncryptReplicaWithKms"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  provider = aws.us_east_1

  name   = "s3-mrap-replication-policy"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Replication - primary -> secondary (KMS encrypted objects, STANDARD class)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-objects"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Disabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]
}

###############################################################################
# Multi-Region Access Point (control plane: us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "this" {
  provider = aws.us_west_2

  details {
    name = local.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountGetPut"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3control_multi_region_access_point.this.arn}/object/*"]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "this" {
  provider = aws.us_west_2

  details {
    name   = local.mrap_name
    policy = data.aws_iam_policy_document.mrap.json
  }

  depends_on = [aws_s3control_multi_region_access_point.this]
}

###############################################################################
# Outputs
###############################################################################

output "primary_bucket_name" {
  description = "Name of the primary S3 bucket."
  value       = aws_s3_bucket.primary.bucket
}

output "secondary_bucket_name" {
  description = "Name of the secondary S3 bucket."
  value       = aws_s3_bucket.secondary.bucket
}

output "mrap_alias" {
  description = "Alias of the Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.this.alias
}

output "mrap_arn" {
  description = "ARN of the Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.this.arn
}

locals {
  namespace   = "patch"
  stage       = "default"
  name_prefix = "${local.namespace}-${local.stage}"
  account_id  = data.aws_caller_identity.current.account_id

  # Optional SNS notifications (disabled by default)
  sns_notification_enabled = false
  sns_topic_arn            = ""
}

data "aws_caller_identity" "current" {}

# Globally-unique suffix for S3 bucket names
resource "random_id" "suffix" {
  byte_length = 4
}

# ---------------------------------------------------------------------------
# S3 Log Bucket for Command Output
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "log" {
  bucket = "${local.name_prefix}-logs-${random_id.suffix.hex}"
  tags = {
    Name      = "${local.name_prefix}-logs-${random_id.suffix.hex}"
    Namespace = local.namespace
    Stage     = local.stage
  }
  lifecycle { prevent_destroy = true }
}

resource "aws_s3_bucket_public_access_block" "log" {
  bucket                  = aws_s3_bucket.log.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "log" {
  description             = "KMS key for encrypting the patch manager ${local.name_prefix} logs bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  tags = {
    Name      = "${local.name_prefix}-logs-key"
    Namespace = local.namespace
    Stage     = local.stage
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log" {
  bucket = aws_s3_bucket.log.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.log.arn
    }
  }
}

# ---------------------------------------------------------------------------
# Private Versioned S3 Log Bucket (grants account read/write access)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "private_logs" {
  bucket = "${local.name_prefix}-private-logs-${random_id.suffix.hex}"
  tags = {
    Name      = "${local.name_prefix}-private-logs-${random_id.suffix.hex}"
    Namespace = local.namespace
    Stage     = local.stage
  }
  lifecycle { prevent_destroy = true }
}

resource "aws_s3_bucket_public_access_block" "private_logs" {
  bucket                  = aws_s3_bucket.private_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "private_logs" {
  description             = "KMS key for encrypting the patch manager ${local.name_prefix} private logs bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
  tags = {
    Name      = "${local.name_prefix}-private-logs-key"
    Namespace = local.namespace
    Stage     = local.stage
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "private_logs" {
  bucket = aws_s3_bucket.private_logs.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.private_logs.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "private_logs" {
  bucket = aws_s3_bucket.private_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "private_logs" {
  statement {
    actions = [
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = [
      aws_s3_bucket.private_logs.arn,
      "${aws_s3_bucket.private_logs.arn}/*",
    ]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }
  }
}

data "aws_partition" "current" {}

resource "aws_s3_bucket_policy" "private_logs" {
  bucket = aws_s3_bucket.private_logs.id
  policy = data.aws_iam_policy_document.private_logs.json
}

# ---------------------------------------------------------------------------
# Patch Baseline – AMAZON_LINUX_2 with HIGH compliance
# ---------------------------------------------------------------------------
resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name                             = "AMAZON_LINUX_2"
  operating_system                 = "AMAZON_LINUX_2"
  approved_patches_compliance_level = "HIGH"
  description                      = "Amazon Linux 2 patch baseline with HIGH compliance and 7-day auto-approval"
  tags = {
    Name      = "${local.name_prefix}-amazon-linux-2-baseline"
    Namespace = local.namespace
    Stage     = local.stage
  }

  approval_rule {
    approve_after_days  = 7
    compliance_level    = "HIGH"
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2"]
    }
    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }
    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }
}

# ---------------------------------------------------------------------------
# Patch Groups
# ---------------------------------------------------------------------------
# AWS rejects a second RegisterPatchBaselineForPatchGroup call for a patch
# group that a previous apply already registered. Deregister any pre-existing
# registration first so this configuration is idempotent across re-applies.
resource "terraform_data" "deregister_existing_patch_groups" {
  depends_on = [aws_ssm_patch_baseline.amazon_linux_2]

  provisioner "local-exec" {
    command = <<-EOT
      for PG in TOSCAN TOPATCH; do
        BASELINE_ID=$(aws ssm describe-patch-groups --query "Mappings[?PatchGroup=='$${PG}'].BaselineIdentity.BaselineId" --output text 2>/dev/null || true)
        if [ -n "$${BASELINE_ID}" ] && [ "$${BASELINE_ID}" != "None" ]; then
          aws ssm deregister-patch-baseline-for-patch-group --patch-group "$${PG}" --baseline-id "$${BASELINE_ID}" >/dev/null 2>&1 || true
        fi
      done
    EOT
  }
}

resource "aws_ssm_patch_group" "tosc" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = "TOSCAN"
  depends_on  = [terraform_data.deregister_existing_patch_groups]
}

resource "aws_ssm_patch_group" "topatch" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = "TOPATCH"
  depends_on  = [terraform_data.deregister_existing_patch_groups]
}

# ---------------------------------------------------------------------------
# Scan Maintenance Window (Wed 18:00, 3 hours, 1 hour cutoff)
# ---------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "scan" {
  name     = "${local.name_prefix}-scan-window"
  schedule = "cron(0 0 18 ? * WED *)"
  duration = 3
  cutoff   = 1
  tags = {
    Name      = "${local.name_prefix}-scan-window"
    Namespace = local.namespace
    Stage     = local.stage
  }
}

# Scan Maintenance Window Instance Target (tagged with Patch Group TOSCAN)
resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.name_prefix}-scan-target"
  description   = "Instances tagged with Patch Group TOSCAN"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = ["TOSCAN"]
  }
}

# Scan Run Command Task (AWS-RunPatchBaseline, Scan operation, no reboot)
resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  max_concurrency  = "20"
  max_errors       = "50"
  name             = "${local.name_prefix}-scan-task"
  priority         = 1
  task_arn         = "AWS-RunPatchBaseline"
  task_type        = "RUN_COMMAND"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.log.bucket
      output_s3_key_prefix = "scanning/"
      timeout_seconds      = 3600

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }
      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }

      dynamic "notification_config" {
        for_each = local.sns_notification_enabled ? [1] : []
        content {
          notification_arn    = local.sns_topic_arn
          notification_type   = "Command"
          notification_events = ["All"]
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Install Maintenance Window (Wed 21:00, 3 hours, 1 hour cutoff)
# ---------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "install" {
  name     = "${local.name_prefix}-install-window"
  schedule = "cron(0 0 21 ? * WED *)"
  duration = 3
  cutoff   = 1
  tags = {
    Name      = "${local.name_prefix}-install-window"
    Namespace = local.namespace
    Stage     = local.stage
  }
}

# Install Maintenance Window Instance Target (tagged with Patch Group TOPATCH)
resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.name_prefix}-install-target"
  description   = "Instances tagged with Patch Group TOPATCH"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = ["TOPATCH"]
  }
}

# Install Run Command Task (AWS-RunPatchBaseline, Install operation, reboot if needed)
resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  max_concurrency  = "20"
  max_errors       = "50"
  name             = "${local.name_prefix}-install-task"
  priority         = 1
  task_arn         = "AWS-RunPatchBaseline"
  task_type        = "RUN_COMMAND"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = aws_s3_bucket.log.bucket
      output_s3_key_prefix = "scanning/"
      timeout_seconds      = 3600

      parameter {
        name   = "Operation"
        values = ["Install"]
      }
      parameter {
        name   = "RebootOption"
        values = ["RebootIfNeeded"]
      }

      dynamic "notification_config" {
        for_each = local.sns_notification_enabled ? [1] : []
        content {
          notification_arn    = local.sns_topic_arn
          notification_type   = "Command"
          notification_events = ["All"]
        }
      }
    }
  }
}

locals {
  trail_name                = "monitor_account_activities"
  bucket_prefix             = "cloudtrail-monitor-management-event-logs"
  log_group_name            = "cloudtrail_to_cloudwatch_logs"
  metric_namespace          = "management_activities"
  sns_topic_name            = "management-updates"
  trail_kms_key_description = "Customer-managed KMS key for CloudTrail log encryption with automatic rotation"
  sns_kms_key_description   = "Customer-managed KMS key for SNS topic encryption with automatic rotation"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}

# ── KMS Key for CloudTrail ─────────────────────────────────────────────────

resource "aws_kms_key" "trail" {
  description             = local.trail_kms_key_description
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = ["kms:*"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ── KMS Key for SNS Topic ──────────────────────────────────────────────────

resource "aws_kms_key" "sns" {
  description             = local.sns_kms_key_description
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = ["kms:*"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ── S3 Bucket for CloudTrail Logs ─────────────────────────────────────────

resource "aws_s3_bucket" "logs" {
  bucket = "${local.bucket_prefix}-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                = aws_s3_bucket.logs.id
  block_public_acls     = true
  block_public_policy   = true
  ignore_public_acls    = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.trail.arn
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_write" {
  bucket = aws_s3_bucket.logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.logs.arn
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "${aws_s3_bucket.logs.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "expire-old-logs"
    status = "Enabled"
    expiration {
      days = 365
    }
  }
}

# ── CloudWatch Logs Group ─────────────────────────────────────────────────

resource "aws_cloudwatch_log_group" "trail" {
  name              = local.log_group_name
  retention_in_days = 365
}

# ── IAM Role for CloudTrail → CloudWatch Logs ─────────────────────────────

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-logs-role"
  description = "Allows CloudTrail to send events to CloudWatch Logs"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-logs-policy"
  role = aws_iam_role.cloudtrail_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

# ── CloudTrail Trail ──────────────────────────────────────────────────────

resource "aws_cloudtrail" "monitor" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.trail.arn
  cloud_watch_logs_group_arn     = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.trail.name}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
}

# ── CloudWatch Metric Filters & Alarms ────────────────────────────────────

# 1. Security group changes
resource "aws_cloudwatch_log_metric_filter" "security_group_changes" {
  name           = "SecurityGroupChanges"
  pattern        = "{ ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") || ($.eventName = \"UpdateSecurityGroupRuleDescriptionsIngress\") || ($.eventName = \"UpdateSecurityGroupRuleDescriptionsEgress\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "SecurityGroupChanges"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "security_group_changes" {
  alarm_name          = "SecurityGroupChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.security_group_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when security group changes are detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 2. IAM user creation or deletion
resource "aws_cloudwatch_log_metric_filter" "iam_user_changes" {
  name           = "IAMUserCreationOrDeletion"
  pattern        = "{ ($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "IAMUserCreationOrDeletion"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_user_changes" {
  alarm_name          = "IAMUserCreationOrDeletion"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_user_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when IAM user creation or deletion is detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 3. Failed console logins
resource "aws_cloudwatch_log_metric_filter" "failed_console_logins" {
  name           = "FailedConsoleLogins"
  pattern        = "{ ($.eventName = \"ConsoleLogin\") && ($.errorMessage = \"*\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "FailedConsoleLogins"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "failed_console_logins" {
  alarm_name          = "FailedConsoleLogins"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.failed_console_logins.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when failed console logins are detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 4. IAM group, role, and user policy changes
resource "aws_cloudwatch_log_metric_filter" "iam_policy_attachment_changes" {
  name           = "IAMPolicyAttachmentChanges"
  pattern        = "{ ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "IAMPolicyAttachmentChanges"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_attachment_changes" {
  alarm_name          = "IAMPolicyAttachmentChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_attachment_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when IAM group, role, or user policy attachment changes are detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 5. IAM policy changes
resource "aws_cloudwatch_log_metric_filter" "iam_policy_changes" {
  name           = "IAMPolicyChanges"
  pattern        = "{ ($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"SetDefaultPolicyVersion\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "IAMPolicyChanges"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_changes" {
  alarm_name          = "IAMPolicyChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when IAM policy changes are detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 6. Users being added to groups
resource "aws_cloudwatch_log_metric_filter" "iam_user_group_changes" {
  name           = "IAMUserGroupChanges"
  pattern        = "{ ($.eventName = \"AddUserToGroup\") || ($.eventName = \"RemoveUserFromGroup\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "IAMUserGroupChanges"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_user_group_changes" {
  alarm_name          = "IAMUserGroupChanges"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_user_group_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when users are added to or removed from IAM groups within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# 7. IAM role creation or deletion
resource "aws_cloudwatch_log_metric_filter" "iam_role_changes" {
  name           = "IAMRoleCreationOrDeletion"
  pattern        = "{ ($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\") }"
  log_group_name = aws_cloudwatch_log_group.trail.name

  metric_transformation {
    name          = "IAMRoleCreationOrDeletion"
    namespace     = local.metric_namespace
    value         = "1"
    default_value = "0"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_role_changes" {
  alarm_name          = "IAMRoleCreationOrDeletion"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_role_changes.metric_transformation[0].name
  namespace           = local.metric_namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = "Alarms when IAM role creation or deletion is detected within a 60-second period"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

# ── SNS Topic for Notifications ────────────────────────────────────────────

resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic_policy" "cloudwatch_publish" {
  arn = aws_sns_topic.management_updates.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.management_updates.arn
      }
    ]
  })
}

# ── Configurable List of Email Recipients ──────────────────────────────────

variable "email_recipients" {
  type        = list(string)
  description = "List of email addresses to receive management update notifications"
  default     = ["monitor@example.com"]
}

resource "aws_sns_topic_subscription" "email" {
  count     = length(var.email_recipients)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = var.email_recipients[count.index]
}

variable "name_prefix" {
  description = "Optional prefix for the AWS Config rule name"
  type        = string
  default     = ""
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  rule_name        = var.name_prefix != "" ? "${var.name_prefix}acm-certificate-expiration-check" : "acm-certificate-expiration-check"
  recorder_name    = "default"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_iam_role" "config_recorder_role" {
  name = "aws-config-recorder-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "config_recorder_policy" {
  role       = aws_iam_role.config_recorder_role.name
  policy_arn = "arn:${data.aws_partition.current.id}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_s3_bucket" "config_delivery" {
  bucket        = "aws-config-delivery-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-${random_id.suffix.hex}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "config_delivery" {
  description             = "KMS key for AWS Config delivery bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.id}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowConfigServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config_delivery.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "s3:GetBucketAcl",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.config_delivery.arn
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.config_delivery.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_config_delivery_channel" "main" {
  name           = "default"
  s3_bucket_name = aws_s3_bucket.config_delivery.id

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_configuration_recorder" "main" {
  name     = local.recorder_name
  role_arn = aws_iam_role.config_recorder_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.main]
}

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name        = local.rule_name
  description = "Checks whether ACM certificates in the account are close to expiring"

  depends_on = [aws_config_configuration_recorder_status.main]

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = "30"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool" "this" {
  name = "fiap-hackathon-cognito-pool"

  username_attributes = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length = 8
  }

  schema {
    name           = "name"
    attribute_data_type = "String"
    required       = true
    mutable        = true
  }

  schema {
    name           = "email"
    attribute_data_type = "String"
    required       = true
    mutable        = true
  }
}

resource "aws_cognito_user_pool_client" "this" {
  name                = "cognito-pool-client"
  user_pool_id        = aws_cognito_user_pool.this.id

  generate_secret     = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

# Look up the current AWS account ID for constructing ARNs
data "aws_caller_identity" "current" {}

# --------------------------------------------------------------------------
# IAM OpenID Connect identity provider for Azure AD
# Tenant : 221ca1d3-b3f2-4346-8abc-88f802495c7d
# Issuer : https://sts.windows.net/<tenant-id>/
# Client : c8b9cf86-e2b4-4428-b356-14313412a4d1
# --------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "sentinel_oidc" {
  url            = "https://sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/"
  client_id_list = ["c8b9cf86-e2b4-4428-b356-14313412a4d1"]
  thumbprint_list = [
    "bf91f7e2b5c3a4d6e810f923a1b4c5d6e7f8a9b0"
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------
# IAM role assumed by the OIDC provider via web identity when the token
# audience matches the Sentinel client ID.
# --------------------------------------------------------------------------
resource "aws_iam_role" "sentinel_oidc_role" {
  name        = "Sentinel-OIDC-Organizations-ReadOnly"
  description = "Allows Sentinel function apps to read Organization data after authenticating via Azure AD OIDC."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.sentinel_oidc.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "https://sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/:aud" = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------
# Attach the AWS-managed Organizations read-only policy.
# --------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "sentinel_oidc_role_attachment" {
  role       = aws_iam_role.sentinel_oidc_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "ec2_test_role" {
  name = "ec2-test-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_specific_cluster" {
  name = "allow-specific-foo-cluster"
  role = aws_iam_role.ec2_test_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "rds:AddRoleToDBCluster"
        Effect = "Allow"
        Resource = "arn:aws:rds:*:*:cluster:foo_cluster"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_all_clusters" {
  name = "allow-all-rds-clusters"
  role = aws_iam_role.ec2_test_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "rds:Add*"
        Effect = "Allow"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "deny_all_clusters" {
  name = "deny-all-rds-clusters"
  role = aws_iam_role.ec2_test_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "rds:Add*"
        Effect = "Deny"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

variable "environment_name" {
  description = "Environment name for the Terraform state backend bucket"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

# ── KMS Keys ────────────────────────────────────────────────────────────

resource "aws_kms_key" "frontend" {
  description             = "Customer-managed KMS key for frontend S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  is_enabled              = true
}

resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed KMS key for Terraform state S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  is_enabled              = true
}

# ── Frontend S3 Bucket ──────────────────────────────────────────────────

resource "aws_s3_bucket" "frontend" {
  bucket = "s3-frontend-nft-maker-v2-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm    = "aws:kms"
      kms_master_key_id = aws_kms_key.frontend.key_id
    }
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3600
  }
}

# ── CloudFront Origin Access Identity ──────────────────────────────────

resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "Origin access identity for frontend S3 bucket"
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.frontend.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# ── WAFv2 Web ACL (CloudFront scope) ───────────────────────────────────

resource "aws_wafv2_web_acl" "frontend" {
  name        = "frontend-waf-acl"
  description = "CloudFront-scoped WAF protecting the frontend"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    sampled_requests_enabled   = true
    cloudwatch_metrics_enabled = false
    metric_name                = "frontend-waf"
  }
}

# ── CloudFront Distribution ────────────────────────────────────────────

resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_200"
  default_root_object = "index.html"
  web_acl_id          = aws_wafv2_web_acl.frontend.id

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "frontend-origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id       = "frontend-origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]
    compress        = true
    default_ttl     = 86400
    max_ttl         = 31536000
    min_ttl         = 0

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    target_origin_id       = "frontend-origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]
    compress        = true
    default_ttl     = 31536000
    max_ttl         = 31536000
    min_ttl         = 31536000

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  ordered_cache_behavior {
    path_pattern           = "/content/*"
    target_origin_id       = "frontend-origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]
    compress        = true
    default_ttl     = 86400
    max_ttl         = 31536000
    min_ttl         = 86400

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
    minimum_protocol_version       = "TLSv1.2_2021"
  }
}

# ── Terraform State S3 Bucket ──────────────────────────────────────────

resource "aws_s3_bucket" "terraform_state" {
  bucket = "near-frontend-${var.environment_name}-terraform-state-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.key_id
    }
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ── DynamoDB Table for State Locking ───────────────────────────────────

resource "aws_dynamodb_table" "terraform_locks" {
  name          = "near-frontend-terraform-state"
  hash_key      = "LockID"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  base_name = "stackx-network"
  # Private subnet CIDRs
  private_cidrs = [
    "10.1.0.0/18",
    "10.1.64.0/18",
    "10.1.128.0/18",
  ]
  # Public subnet CIDRs
  public_cidrs = [
    "10.1.192.0/22",
    "10.1.196.0/22",
    "10.1.200.0/22",
  ]
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "self" {}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = local.base_name
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway (IPv4)
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.base_name
  }
}

# ---------------------------------------------------------------------------
# Egress-only Internet Gateway (IPv6)
# ---------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.base_name
  }
}

# ---------------------------------------------------------------------------
# Public subnets – share one route table
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 4)

  # Do NOT auto-assign public IP addresses
  map_public_ip_on_launch = false

  tags = {
    Name                                                      = "${local.base_name}-public-${count.index}"
    "kubernetes.io/load-balancers"                            = local.base_name
    "kubernetes.io/cluster/${local.base_name}"                = "shared"
  }
}

# One route table for ALL public subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block      = "0.0.0.0/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.base_name}-public"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# NAT Gateway + Elastic IP per zone (one per private subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "${local.base_name}-nat-${count.index}"
  }

  # Lifecycle to prevent accidental deletion
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "private" {
  count = 3

  connectivity_type   = "public"
  subnet_id           = aws_subnet.public[count.index].id
  allocation_id       = aws_eip.nat[count.index].allocation_id

  tags = {
    Name = "${local.base_name}-nat-${count.index}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Private subnets – each gets its own route table
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)

  tags = {
    Name                                                      = "${local.base_name}-private-${count.index}"
    "kubernetes.io/load-balancers"                            = local.base_name
    "kubernetes.io/cluster/${local.base_name}"                = "private-${count.index}"
  }
}

# Private route tables – one per zone
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  # IPv4 default route -> NAT gateway in that zone
  route {
    cidr_block      = "0.0.0.0/0"
    nat_gateway_id  = aws_nat_gateway.private[count.index].id
  }

  # IPv6 default route -> egress-only internet gateway
  route {
    ipv6_cidr_block = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main.id
  }

  tags = {
    Name = "${local.base_name}-private-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# S3 Gateway VPC Endpoint – associated with private route tables
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id = aws_vpc.main.id
  service_name     = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "${local.base_name}-s3-endpoint"
  }
}

resource "aws_vpc_endpoint_route_table_association" "s3_private" {
  count = 3

  vpc_endpoint_id = aws_vpc_endpoint.s3.id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Optional tier: database subnets (disabled by default) – one per zone
# ---------------------------------------------------------------------------
resource "aws_subnet" "database" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 208)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.base_name}-database-${count.index}"
  }
}

resource "aws_route_table" "database" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.base_name}-database-${count.index}"
  }
}

resource "aws_route_table_association" "database" {
  count = 3

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

# ---------------------------------------------------------------------------
# Optional tier: cache subnets (disabled by default) – one per zone
# ---------------------------------------------------------------------------
resource "aws_subnet" "cache" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 212)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.base_name}-cache-${count.index}"
  }
}

resource "aws_route_table" "cache" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.base_name}-cache-${count.index}"
  }
}

resource "aws_route_table_association" "cache" {
  count = 3

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[count.index].id
}

# ---------------------------------------------------------------------------
# Optional tier: internal subnets (no internet, disabled by default) – one per zone
# ---------------------------------------------------------------------------
resource "aws_subnet" "internal" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 216)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.base_name}-internal-${count.index}"
  }
}

resource "aws_route_table" "internal" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.base_name}-internal-${count.index}"
  }
}

resource "aws_route_table_association" "internal" {
  count = 3

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[count.index].id
}

# ---------------------------------------------------------------------------
# RDS / ElastiCache subnet groups (for database/cache tiers, disabled by default)
# – declared but associated with empty subnet_ids so they are created inert
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "database" {
  name       = "${local.base_name}-database"
  subnet_ids = aws_subnet.database[*].id

  tags = {
    Name = "${local.base_name}-database"
  }
}

resource "aws_elasticache_subnet_group" "cache" {
  name       = "${local.base_name}-cache"
  subnet_ids = aws_subnet.cache[*].id

  tags = {
    Name = "${local.base_name}-cache"
  }
}

###############################################################################
# Weather data lake pipeline
#
# Six S3 buckets (artefacts, staging, bronze, silver, gold, logs) encrypted with
# a shared rotating customer managed KMS key, an Athena "silver" database, two
# AWS Glue 4.0 jobs orchestrated through Step Functions and scheduled hourly by
# EventBridge.
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition

  common_tags = {
    Project     = "benchmark-weather-datalake"
    Environment = "production"
    ManagedBy   = "terraform"
  }

  # Bucket names = prefix + AWS account id.
  glue_artefacts_bucket = "benchmark-glue-artefacts-${local.account_id}"
  staging_bucket        = "benchmark-datalake-staging-${local.account_id}"
  bronze_bucket         = "benchmark-datalake-bronze-${local.account_id}"
  silver_bucket         = "benchmark-datalake-silver-${local.account_id}"
  gold_bucket           = "benchmark-datalake-gold-${local.account_id}"
  logs_bucket           = "benchmark-datalake-logs-${local.account_id}"

  data_lake_buckets = [
    local.glue_artefacts_bucket,
    local.staging_bucket,
    local.bronze_bucket,
    local.silver_bucket,
    local.gold_bucket,
    local.logs_bucket,
  ]

  # Versioning is enabled on the artefacts, bronze, silver and gold buckets.
  versioned_buckets = [
    local.glue_artefacts_bucket,
    local.bronze_bucket,
    local.silver_bucket,
    local.gold_bucket,
  ]

  data_lake_object_arns = [
    for bucket in local.data_lake_buckets : "arn:${local.partition}:s3:::${bucket}/*"
  ]

  data_lake_bucket_arns = [
    for bucket in local.data_lake_buckets : "arn:${local.partition}:s3:::${bucket}"
  ]

  glue_job_extrai_dados     = "glue-job-extrai-dados"
  glue_job_transforma_dados = "glue-job-transforma-dados"

  glue_temp_dir = "s3://${local.logs_bucket}/tmp/"
}

###############################################################################
# KMS - shared, rotating customer managed key + alias
###############################################################################

resource "aws_kms_key" "data_lake" {
  description             = "Customer managed key for the benchmark weather data lake"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "data_lake" {
  name          = "alias/benchmark-datalake"
  target_key_id = aws_kms_key.data_lake.key_id
}

###############################################################################
# S3 data lake buckets
###############################################################################

resource "aws_s3_bucket" "glue_artefacts" {
  bucket = local.glue_artefacts_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "staging" {
  bucket = local.staging_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "bronze" {
  bucket = local.bronze_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "silver" {
  bucket = local.silver_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "gold" {
  bucket = local.gold_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket = local.logs_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access on every bucket.
resource "aws_s3_bucket_public_access_block" "glue_artefacts" {
  bucket                  = aws_s3_bucket.glue_artefacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket                  = aws_s3_bucket.staging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "bronze" {
  bucket                  = aws_s3_bucket.bronze.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "silver" {
  bucket                  = aws_s3_bucket.silver.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "gold" {
  bucket                  = aws_s3_bucket.gold.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default SSE-KMS encryption with the shared customer managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "glue_artefacts" {
  bucket = aws_s3_bucket.glue_artefacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bronze" {
  bucket = aws_s3_bucket.bronze.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "silver" {
  bucket = aws_s3_bucket.silver.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "gold" {
  bucket = aws_s3_bucket.gold.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.data_lake.arn
    }

    bucket_key_enabled = true
  }
}

# Versioning is enabled on the artefacts, bronze, silver and gold buckets.
resource "aws_s3_bucket_versioning" "glue_artefacts" {
  bucket = aws_s3_bucket.glue_artefacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "bronze" {
  bucket = aws_s3_bucket.bronze.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "silver" {
  bucket = aws_s3_bucket.silver.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "gold" {
  bucket = aws_s3_bucket.gold.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Glue scripts and libraries uploaded into the artefacts bucket
#
# The job sources that live in the local glueClima/ folder are uploaded into the
# artefacts bucket. lib.zip bundles the shared Python helpers used by the
# transformation job.
###############################################################################

resource "aws_s3_object" "extrai_dados_script" {
  bucket       = aws_s3_bucket.glue_artefacts.id
  key          = "extraiDados.py"
  content_type = "text/x-python"
  tags         = local.common_tags

  content = <<-EOT
    """Extraction job for the benchmark weather data lake pipeline.

    Reads weather data for a given city from the upstream API and lands the raw
    payload in the staging bucket of the data lake.
    """

    import sys

    from awsglue.context import GlueContext
    from awsglue.job import Job
    from awsglue.utils import getResolvedOptions
    from pyspark.context import SparkContext

    args = getResolvedOptions(
        sys.argv,
        ["JOB_NAME", "city", "staging_bucket", "api_key"],
    )

    sc = SparkContext()
    glue_context = GlueContext(sc)
    spark = glue_context.spark_session
    job = Job(glue_context)
    job.init(args["JOB_NAME"], args)

    # The city to query is provided by the Step Functions state machine.
    city = args["city"]
    staging_bucket = args["staging_bucket"]
    api_key = args["api_key"]

    # NOTE: call the upstream weather API for `city` using `api_key` and write
    # the raw response to s3://<staging_bucket>/raw/<city>/.

    job.commit()
  EOT
}

resource "aws_s3_object" "transforma_dados_script" {
  bucket       = aws_s3_bucket.glue_artefacts.id
  key          = "transformaDados.py"
  content_type = "text/x-python"
  tags         = local.common_tags

  content = <<-EOT
    """Transformation job for the benchmark weather data lake pipeline.

    Reads the raw payload from staging, normalises it, produces the bronze and
    silver Iceberg tables and writes the result to the data lake buckets.
    """

    import sys

    from awsglue.context import GlueContext
    from awsglue.job import Job
    from awsglue.utils import getResolvedOptions
    from pyspark.context import SparkContext

    args = getResolvedOptions(
        sys.argv,
        ["JOB_NAME", "staging_bucket", "bronze_bucket", "silver_bucket", "translation_key"],
    )

    sc = SparkContext()
    glue_context = GlueContext(sc)
    spark = glue_context.spark_session
    job = Job(glue_context)
    job.init(args["JOB_NAME"], args)

    staging_bucket = args["staging_bucket"]
    bronze_bucket = args["bronze_bucket"]
    silver_bucket = args["silver_bucket"]
    translation_key = args["translation_key"]

    # NOTE: read from s3://<staging_bucket>/, translate the textual fields with
    # the translation service using `translation_key`, then write Iceberg tables
    # to the bronze and silver buckets.

    job.commit()
  EOT
}

data "archive_file" "glue_lib" {
  type        = "zip"
  output_path = "${path.module}/lib.zip"

  source {
    filename = "weatherlib.py"
    content  = <<-EOT
      """Shared helpers packaged in lib.zip and shipped as extra Python modules."""


      def normalize_city(city):
          """Return a normalised representation of a city name."""
          return city.strip().title()
    EOT
  }
}

resource "aws_s3_object" "glue_lib" {
  bucket       = aws_s3_bucket.glue_artefacts.id
  key          = "lib.zip"
  content_type = "application/zip"
  tags         = local.common_tags

  source      = data.archive_file.glue_lib.output_path
  source_hash = data.archive_file.glue_lib.output_base64sha256
}

###############################################################################
# Athena database backed by the silver bucket
###############################################################################

resource "aws_athena_database" "silver" {
  name   = "silver"
  bucket = aws_s3_bucket.silver.id

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.data_lake.arn
  }
}

###############################################################################
# IAM role for AWS Glue
###############################################################################

resource "aws_iam_role" "glue_job" {
  name = "benchmark-glue-job-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "GlueAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "glue.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "glue_job" {
  name = "benchmark-glue-job-policy"
  role = aws_iam_role.glue_job.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GlueCatalogAccess"
        Effect = "Allow"
        Action = [
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:CreateDatabase",
          "glue:GetTable",
          "glue:GetTables",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:DeleteTable",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:BatchGetPartition",
          "glue:BatchCreatePartition",
          "glue:BatchDeletePartition",
          "glue:GetConnection",
          "glue:GetConnections",
          "glue:GetJob",
          "glue:GetJobRun",
          "glue:GetJobRuns",
        ]
        Resource = [
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:catalog",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:database/*",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:table/*",
          "arn:${local.partition}:glue:${local.region}:${local.account_id}:connection/*",
        ]
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*"
      },
      {
        Sid      = "CloudWatchMetricsAccess"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
        ]
        Resource = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:benchmark/*"
      },
      {
        Sid    = "DataLakeBucketObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
        ]
        Resource = local.data_lake_object_arns
      },
      {
        Sid    = "DataLakeBucketListAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:ListBucketMultipartUploads",
        ]
        Resource = local.data_lake_bucket_arns
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.data_lake.arn
      },
    ]
  })
}

###############################################################################
# AWS Glue 4.0 jobs
###############################################################################

resource "aws_glue_job" "extrai_dados" {
  name              = local.glue_job_extrai_dados
  role_arn          = aws_iam_role.glue_job.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.extrai_dados_script.key}"
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"                     = "python"
    "--TempDir"                          = local.glue_temp_dir
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }

  tags = local.common_tags
}

resource "aws_glue_job" "transforma_dados" {
  name              = local.glue_job_transforma_dados
  role_arn          = aws_iam_role.glue_job.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.transforma_dados_script.key}"
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"                     = "python"
    "--TempDir"                          = local.glue_temp_dir
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.glue_lib.key}"
    "--additional-python-modules"        = "awswrangler"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }

  tags = local.common_tags
}

###############################################################################
# IAM role for Step Functions (start + monitor only the two Glue jobs)
###############################################################################

resource "aws_iam_role" "sfn" {
  name = "benchmark-step-functions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "StatesAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "states.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "sfn" {
  name = "benchmark-step-functions-policy"
  role = aws_iam_role.sfn.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartAndMonitorGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun",
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn,
        ]
      },
      {
        Sid    = "GlueSyncEventBridgeAccess"
        Effect = "Allow"
        Action = [
          "events:PutTargets",
          "events:PutRule",
          "events:DescribeRule",
        ]
        Resource = "arn:${local.partition}:events:${local.region}:${local.account_id}:rule/StepFunctionsGetEventsForGlueJobRule"
      },
    ]
  })
}

###############################################################################
# Step Functions state machine
###############################################################################

resource "aws_sfn_state_machine" "pipeline" {
  name     = "benchmark-weather-data-pipeline"
  type     = "STANDARD"
  role_arn = aws_iam_role.sfn.arn

  definition = jsonencode({
    Comment = "Scheduled weather data lake pipeline"
    StartAt = "ExtractData"
    States = {
      ExtractData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging_bucket" = aws_s3_bucket.staging.bucket
            "--api_key"        = "PLACEHOLDER_WEATHER_API_KEY"
          }
        }
        Next = "TransformData"
      }
      TransformData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket"  = aws_s3_bucket.staging.bucket
            "--bronze_bucket"   = aws_s3_bucket.bronze.bucket
            "--silver_bucket"   = aws_s3_bucket.silver.bucket
            "--translation_key" = "PLACEHOLDER_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })

  tags = local.common_tags
}

###############################################################################
# EventBridge scheduled trigger + role allowed to start the execution
###############################################################################

resource "aws_iam_role" "eventbridge" {
  name = "benchmark-eventbridge-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EventBridgeAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "eventbridge" {
  name = "benchmark-eventbridge-policy"
  role = aws_iam_role.eventbridge.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartStateMachineExecution"
        Effect   = "Allow"
        Action   = ["states:StartExecution"]
        Resource = aws_sfn_state_machine.pipeline.arn
      },
    ]
  })
}

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "benchmark-weather-pipeline-hourly"
  description         = "Triggers the weather data lake pipeline every hour"
  schedule_expression = "rate(1 hour)"
  tags                = local.common_tags
}

resource "aws_cloudwatch_event_target" "pipeline" {
  rule     = aws_cloudwatch_event_rule.hourly.name
  arn      = aws_sfn_state_machine.pipeline.arn
  role_arn = aws_iam_role.eventbridge.arn
}

locals {
  target_bucket_prefix = "benchmark-cicd-target"
  pipeline_name        = "static-site-cicd-pipeline"
  codebuild_project    = "static-site-build"
}

variable "codestar_connection_arn" {
  description = "ARN of the CodeStar connection to use as pipeline source instead of GitHub OAuth"
  type        = string
  default     = ""
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# --- KMS Key with rotation enabled ---
resource "aws_kms_key" "main" {
  description             = "Customer managed KMS key for S3 bucket default encryption"
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "main" {
  name          = "alias/benchmark-cicd-kms"
  target_key_id = aws_kms_key.main.id
}

# --- Target S3 Bucket (website files) ---
resource "aws_s3_bucket" "target" {
  bucket = "${local.target_bucket_prefix}-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm   = "aws:kms"
      kms_master_key_id = aws_kms_key.main.id
    }
  }
}

# --- Artifact S3 Bucket (pipeline artifacts) ---
resource "aws_s3_bucket" "artifact" {
  bucket = "${local.target_bucket_prefix}-artifact-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm   = "aws:kms"
      kms_master_key_id = aws_kms_key.main.id
    }
  }
}

# Deny non-TLS requests to the artifact bucket
resource "aws_s3_bucket_policy" "artifact_tls" {
  bucket = aws_s3_bucket.artifact.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Principal = "*"
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# --- CloudFront Origin Access Identity ---
resource "aws_cloudfront_origin_access_identity" "main" {
  comment = "OAI for target S3 bucket"
}

# Grant OAI read access to the target bucket
resource "aws_s3_bucket_policy" "oai_access" {
  bucket = aws_s3_bucket.target.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.main.iam_arn
        }
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.target.arn}/*"
      }
    ]
  })
}

# --- WAF for CloudFront ---
resource "aws_wafv2_web_acl" "cloudfront" {
  name        = "benchmark-cicd-waf"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "benchmark-cicd-waf"
    sampled_requests_enabled   = false
  }
}

# --- CloudFront Distribution ---
resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  default_root_object = "index.html"
  comment             = "CDN serving the static website"
  web_acl_id          = aws_wafv2_web_acl.cloudfront.id

  origin {
    domain_name = aws_s3_bucket.target.bucket_domain_name
    origin_id   = "target-origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.main.id
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "target-origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# --- SSM Parameters for GitHub secrets (placeholder values) ---
resource "aws_ssm_parameter" "github_oauth_token" {
  name  = "/benchmark-cicd/github-oauth-token"
  type  = "SecureString"
  value = "placeholder-oauth-token"
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name  = "/benchmark-cicd/github-webhook-secret"
  type  = "SecureString"
  value = "placeholder-webhook-secret"
}

# --- CodeBuild IAM Role (service role) ---
resource "aws_iam_role" "codebuild" {
  name = "benchmark-cicd-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.main.arn
      },
      {
        Effect = "Allow"
        Action = [
          "cloudfront:CreateInvalidation",
          "cloudfront:GetInvalidation",
          "cloudfront:ListInvalidations"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParameterHistory"
        ]
        Resource = "*"
      }
    ]
  })
}

# --- CodeBuild Project ---
resource "aws_codebuild_project" "main" {
  name          = local.codebuild_project
  description   = "Builds the static website for the CI/CD pipeline"
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = 5

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux-x64:latest"
    type         = "LINUX_CONTAINER"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.main.id
    }

    environment_variable {
      name  = "INVALIDATION_FLAG"
      value = "true"
    }
  }

  source {
    type = "CODEPIPELINE"
  }

  artifacts {
    type = "CODEPIPELINE"
  }
}

# --- CodePipeline IAM Role ---
resource "aws_iam_role" "codepipeline" {
  name = "benchmark-cicd-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline" {
  name = "benchmark-cicd-codepipeline-policy"
  role = aws_iam_role.codepipeline.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:GetBuild"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = aws_iam_role.codebuild.arn
      }
    ]
  })
}

# --- Determine source provider based on CodeStar ARN ---
locals {
  use_codestar    = var.codestar_connection_arn != ""
  source_provider = local.use_codestar ? "CodeStarSourceConnection" : "GitHub"
  source_owner    = local.use_codestar ? "AWS" : "ThirdParty"
}

# --- CodePipeline ---
resource "aws_codepipeline" "main" {
  name     = local.pipeline_name
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifact.bucket
    type     = "S3"
  }

  stage {
    name = "Source"

    action {
      name     = "Source"
      category = "Source"
      owner    = local.source_owner
      provider = local.source_provider
      version  = "1"

      configuration = local.use_codestar ? {
        ConnectionArn    = var.codestar_connection_arn
        FullRepositoryId = "my-org/my-site"
        BranchName       = "master"
      } : {
        Owner      = "my-org"
        Repo       = "my-site"
        Branch     = "master"
        OAuthToken = "@secrets/benchmark-cicd/github-oauth-token"
      }
    }
  }

  stage {
    name = "Build"

    action {
      name     = "Build"
      category = "Build"
      owner    = "AWS"
      provider = "CodeBuild"
      version  = "1"

      configuration = {
        ProjectName = aws_codebuild_project.main.name
      }

      input_artifacts = ["SourceOutput"]
    }
  }
}

# --- CodePipeline Webhook (only when using GitHub, not CodeStar) ---
resource "aws_codepipeline_webhook" "main" {
  count = local.use_codestar ? 0 : 1

  name            = "benchmark-cicd-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.main.name

  authentication_configuration {
    secret_token = "@secrets/benchmark-cicd/github-webhook-secret"
  }

  filter {
    json_path   = "$.ref"
    match_equals = "refs/heads/master"
  }
}

# Static data lookups
data "aws_availability_zones" "available" {}

# ---------------------------------------------------------------------------
# Module input variables
# ---------------------------------------------------------------------------

variable "create_resources" {
  description = "Master toggle to enable (true) or disable (false) all resource creation"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag to apply to the VPC"
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Enable DNS resolution support within the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames for instances within the VPC"
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "If true, create one shared NAT gateway for all private subnets placed in the first available public subnet. If false, create one NAT gateway per availability zone that contains private subnets."
  type        = bool
  default     = true
}

variable "subnet_definitions" {
  description = <<-EOD
    List of subnet group definitions.
    Each entry must contain:
      - name:        identifier for the subnet group (e.g. "web", "app", "db")
      - class:       network class — "public", "private", or "intra"
      - cidrs:       map of availability zone (e.g. "us-east-1a") to CIDR block
                     (e.g. { "us-east-1a" = "10.0.1.0/24", "us-east-1b" = "10.0.2.0/24" })
      - database:    (optional, default false) register this group in the DB subnet group
      - elasticache: (optional, default false) register this group in the ElastiCache subnet group
    When the list is empty (the default) no subnets, gateways, route tables,
    or subnet groups are created.
  EOD
  type = list(object({
    name        = string
    class       = string
    cidrs       = map(string)
    database    = optional(bool)
    elasticache = optional(bool)
  }))
  default = []
}

# ---------------------------------------------------------------------------
# Computed local values
# ---------------------------------------------------------------------------

locals {
  # Flatten the nested subnet definitions into a single list of subnet records
  all_subnets = flatten([
    for def in var.subnet_definitions : [
      for az_key, cidr in def.cidrs : {
        key         = "${def.name}-${az_key}"
        name        = def.name
        class       = def.class
        az          = az_key
        cidr        = cidr
        database    = def.database != null ? def.database : false
        elasticache = def.elasticache != null ? def.elasticache : false
      }
    ]
  ])

  # Lists of subnet keys by class
  public_subnet_keys  = [for s in local.all_subnets : s.key if s.class == "public"]
  private_subnet_keys = [for s in local.all_subnets : s.key if s.class == "private"]

  # Unique AZs that contain private subnets (NAT gateways needed)
  azs_with_private = distinct([for s in local.all_subnets : s.az if s.class == "private"])

  # NAT gateway map:
  #   single_nat = true  → { "single" = first_az_with_private }
  #   single_nat = false → { az1 = az1, az2 = az2, … }
  nat_gw_map = var.single_nat_gateway ? (
    length(local.azs_with_private) > 0 ? { single = local.azs_with_private[0] } : {}
  ) : { for az in local.azs_with_private : az => az }

  # For each AZ, collect all public subnet keys
  # The … ellipsis collects multiple values into a tuple
  public_per_az = {
    for s in local.all_subnets : s.az => s.key... if s.class == "public"
  }

  # Map each NAT gateway key to its public subnet (first one found in the relevant AZ)
  nat_gw_public_subnet = {
    for key, az in local.nat_gw_map : key => local.public_per_az[az][0]
  }

  # Subnet keys for database and elasticache groups
  db_subnet_keys    = [for s in local.all_subnets : s.key if s.database]
  cache_subnet_keys = [for s in local.all_subnets : s.key if s.elasticache]
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count                = var.create_resources ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = var.create_resources ? { for s in local.all_subnets : s.key => s } : {}

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name  = each.value.name
    Class = each.value.class
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway (only needed when public subnets exist)
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  count   = var.create_resources && length(local.public_subnet_keys) > 0 ? 1 : 0
  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Public subnet routing
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  for_each = var.create_resources ? { for s in local.all_subnets : s.key => s if s.class == "public" } : {}

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name  = "${each.value.name}-${each.value.az}"
    Class = "public"
  }
}

resource "aws_route_table_association" "public" {
  for_each = var.create_resources ? { for s in local.all_subnets : s.key => s if s.class == "public" } : {}

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[each.key].id
}

# ---------------------------------------------------------------------------
# NAT Gateways (for private subnets)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  for_each = var.create_resources ? local.nat_gw_map : {}

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${each.key}"
  }
}

resource "aws_nat_gateway" "main" {
  for_each = var.create_resources ? local.nat_gw_map : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.this[local.nat_gw_public_subnet[each.key]].id

  tags = {
    Name = "${var.vpc_name}-nat-${each.key}"
  }
}

# ---------------------------------------------------------------------------
# Private subnet routing
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = var.create_resources ? { for s in local.all_subnets : s.key => s if s.class == "private" } : {}

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[
      var.single_nat_gateway ? "single" : each.value.az
    ].id
  }

  tags = {
    Name  = "${each.value.name}-${each.value.az}"
    Class = "private"
  }
}

resource "aws_route_table_association" "private" {
  for_each = var.create_resources ? { for s in local.all_subnets : s.key => s if s.class == "private" } : {}

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

# ---------------------------------------------------------------------------
# Database subnet group
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "database" {
  count = var.create_resources && length(local.db_subnet_keys) > 0 ? 1 : 0
  name  = "${var.vpc_name}-database"

  subnet_ids = [for k in local.db_subnet_keys : aws_subnet.this[k].id]
}

# ---------------------------------------------------------------------------
# ElastiCache subnet group
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  count = var.create_resources && length(local.cache_subnet_keys) > 0 ? 1 : 0
  name  = "${var.vpc_name}-elasticache"

  subnet_ids = [for k in local.cache_subnet_keys : aws_subnet.this[k].id]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC (null when create_resources is false)"
  value       = var.create_resources ? aws_vpc.main[0].id : null
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = var.create_resources ? aws_vpc.main[0].cidr_block : null
}

output "subnet_ids" {
  description = "Map of subnet keys (name-az) to subnet IDs"
  value       = var.create_resources ? {
    for s in local.all_subnets : s.key => aws_subnet.this[s.key].id
  } : {}
}

resource "aws_iam_role" "ec2_ssm_association" {
  name               = "ec2-ssm-association"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "ec2_ssm_association" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = "ec2-s3-ssm-association"
  role = aws_iam_role.ec2_ssm_association.name

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  dlq_name              = "aggregation-lambda-dead-letter-queue"
  message_retention_sec = 1209600 # 14 days
}

# Customer-managed KMS key used to encrypt the dead-letter queue.
resource "aws_kms_key" "dlq" {
  description             = "Customer-managed KMS key for the ${local.dlq_name} SQS queue"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dlq" {
  name          = "alias/${local.dlq_name}"
  target_key_id = aws_kms_key.dlq.key_id
}

# SQS dead-letter queue with 14-day message retention, encrypted with the CMK.
resource "aws_sqs_queue" "dlq" {
  name                              = local.dlq_name
  message_retention_seconds         = local.message_retention_sec
  kms_master_key_id                 = aws_kms_key.dlq.id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_sms_preferences" "this" {
  default_sms_type                    = "Transactional"
  delivery_status_success_sampling_rate = 0
}

output "preferences_id" {
  description = "The ID of the SNS SMS preferences resource"
  value       = aws_sns_sms_preferences.this.id
}

output "default_sms_type" {
  description = "The configured default SMS type"
  value       = aws_sns_sms_preferences.this.default_sms_type
}

output "delivery_status_success_sampling_rate" {
  description = "The configured delivery status success sampling rate"
  value       = aws_sns_sms_preferences.this.delivery_status_success_sampling_rate
}

# Role that the Amazon EKS service can assume
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-sadcloud-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Attach the AWS-managed AmazonEKSClusterPolicy
resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# Attach the AWS-managed AmazonEKSServicePolicy
resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "random_pet" "log_group_suffix" {
  length = 2
}

resource "aws_cloudwatch_log_group" "logs" {
  name              = "logs-${random_pet.log_group_suffix.id}"
  retention_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "logs" {
  name        = "logs-${random_pet.log_group_suffix.id}"
  description = "Allows creating and describing log streams and putting log events on the ${aws_cloudwatch_log_group.logs.name} log group"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.logs.arn
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  ssm_automation_log_setting = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:servicesetting/ssm/automation/cloudwatchloggroup"
}

variable "enable_ssm_config" {
  description = "Enable flag for SSM automation logging and document sharing settings"
  type        = bool
  default     = true
}

resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.enable_ssm_config ? 1 : 0

  name            = "/aws/ssm/automation/executeScript"
  retention_in_days = 14

  lifecycle {
    prevent_destroy = true
  }
}

