  }
}

# Role assumable by Lambda for creating DynamoDB backups
resource "aws_iam_role" "create_ddb_backup_role" {
  name = "create_ddb_backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Role assumable by Lambda for listing and deleting DynamoDB backups
resource "aws_iam_role" "remove_ddb_backup_role" {
  name = "remove_ddb_backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Policy granting create DynamoDB backup permission
resource "aws_iam_policy" "create_ddb_backup_policy" {
  name = "create_ddb_backup_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policy granting list and delete DynamoDB backup permissions
resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name = "remove_ddb_backup_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups",
          "dynamodb:DeleteBackup"
        ]
        Resource = "*"
      }
    ]
  })
}

# Customer-managed policy granting CloudWatch Logs write permissions (shared by both roles)
resource "aws_iam_policy" "lambda_logging" {
  name = "lambda_logging"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach create_ddb_backup_policy to create_ddb_backup_role
resource "aws_iam_role_policy_attachment" "create_policy_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

# Attach remove_ddb_backup_policy to remove_ddb_backup_role
resource "aws_iam_role_policy_attachment" "remove_policy_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

# Attach lambda_logging policy to create_ddb_backup_role
resource "aws_iam_role_policy_attachment" "create_logging_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Attach lambda_logging policy to remove_ddb_backup_role
resource "aws_iam_role_policy_attachment" "remove_logging_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Output both role names and ARNs
output "create_ddb_backup_role_name" {
  description = "Name of the create DynamoDB backup IAM role"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the create DynamoDB backup IAM role"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the remove DynamoDB backup IAM role"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the remove DynamoDB backup IAM role"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

