terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "github_oidc_issuer_url" {
  description = "GitHub Actions OIDC issuer URL used as the identity provider URL."
  type        = string
  default     = "https://token.actions.githubusercontent.com"
}

variable "github_oidc_audience" {
  description = "Audience (client_id_list) required by the GitHub Actions OIDC provider."
  type        = string
  default     = "sts.amazonaws.com"
}

variable "github_oidc_published_thumbprints" {
  description = "GitHub's published OIDC TLS thumbprints, combined with the CA fingerprints fetched live from the issuer certificate."
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

variable "create_github_roles" {
  description = "Whether to create the GitHub-federated IAM roles. No roles are created by default."
  type        = bool
  default     = false
}

variable "github_roles" {
  description = "Map of GitHub-federated IAM roles to optionally create. Empty by default, so no roles are created unless explicitly supplied."
  type = map(object({
    name           = string
    description    = optional(string, "IAM role federated to GitHub Actions via OIDC")
    subject_claims = list(string)
    policy_arns    = optional(list(string), [])
  }))
  default = {}
}

variable "tags" {
  description = "A map of tags to apply to the created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

# Fetches the live TLS certificate chain for the GitHub Actions OIDC issuer so
# that the CA SHA-1 fingerprints can be included in the provider thumbprint list.
data "tls_certificate" "github_oidc" {
  url = var.github_oidc_issuer_url
}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Issuer host (without scheme) is used as the prefix for OIDC condition keys.
  oidc_host = replace(var.github_oidc_issuer_url, "https://", "")

  # CA fingerprints from the issuer's TLS certificate chain.
  issuer_ca_thumbprints = [
    for cert in data.tls_certificate.github_oidc.certificates : cert.sha1_fingerprint
  ]

  # Combine the fetched CA fingerprints with GitHub's two published thumbprints.
  oidc_thumbprints = distinct(concat(
    local.issuer_ca_thumbprints,
    var.github_oidc_published_thumbprints,
  ))

  # Roles are only materialised when the feature flag is enabled.
  effective_github_roles = var.create_github_roles ? var.github_roles : {}

  # Flatten role -> policy ARN attachments into a single map for for_each.
  github_role_policy_attachments = merge([
    for role_key, role in local.effective_github_roles : {
      for idx, arn in role.policy_arns : "${role_key}-${idx}" => {
        role_key   = role_key
        policy_arn = arn
      }
    }
  ]...)
}

###############################################################################
# GitHub Actions OIDC identity provider
###############################################################################

resource "aws_iam_openid_connect_provider" "github" {
  url             = var.github_oidc_issuer_url
  client_id_list  = [var.github_oidc_audience]
  thumbprint_list = local.oidc_thumbprints

  tags = var.tags
}

###############################################################################
# Optional GitHub-federated IAM roles (none created by default)
###############################################################################

data "aws_iam_policy_document" "github_assume_role" {
  for_each = local.effective_github_roles

  statement {
    sid     = "AllowGitHubActionsAssumeRoleWithWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:aud"
      values   = [var.github_oidc_audience]
    }

    condition {
      test     = "StringLike"
      variable = "${local.oidc_host}:sub"
      values   = each.value.subject_claims
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = local.effective_github_roles

  name                 = each.value.name
  description          = each.value.description
  assume_role_policy   = data.aws_iam_policy_document.github_assume_role[each.key].json
  max_session_duration = 3600

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = local.github_role_policy_attachments

  role       = aws_iam_role.github[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

###############################################################################
# Outputs
###############################################################################

output "github_oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "github_oidc_provider_thumbprints" {
  description = "The combined thumbprint list applied to the OIDC provider."
  value       = aws_iam_openid_connect_provider.github.thumbprint_list
}

output "github_role_arns" {
  description = "ARNs of the created GitHub-federated IAM roles (empty unless enabled)."
  value       = { for k, r in aws_iam_role.github : k => r.arn }
}

