variable "role_name" {
  description = "Name of the IAM role for GitHub Actions OIDC federation"
  type        = string
  default     = "github-actions-oidc-role"
}

variable "subject_patterns" {
  description = "List of GitHub repository patterns for the OIDC subject condition (e.g., repo:my-org/my-repo:*)"
  type        = list(string)
  default     = []
}

locals {
  oidc_provider_url = "https://token.actions.githubusercontent.com"
  oidc_audience     = "sts.amazonaws.com"
  # SHA1 thumbprint of the GitHub Actions OIDC provider certificate
  oidc_thumbprint   = "693637fd1d4c29a0a61e8f5b4b1b6f8d8c8d8e8f"

  # When subject_patterns is empty, use a sentinel that can never match a real subject
  subject_values = length(var.subject_patterns) > 0 ? var.subject_patterns : ["repo:no-such-org/no-such-repo:ref:refs/heads/never"]
}

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = local.oidc_provider_url
  client_id_list  = [local.oidc_audience]
  thumbprint_list = [local.oidc_thumbprint]
}

data "aws_iam_policy_document" "github_actions_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["token.actions.githubusercontent.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = [local.oidc_audience]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = local.subject_values
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = "IAM role for GitHub Actions OIDC federation"
  assume_role_policy    = data.aws_iam_policy_document.github_actions_trust.json
  force_detach_policies = true
}

output "role_arn" {
  description = "ARN of the GitHub Actions OIDC role"
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions OIDC role"
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions OIDC role"
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Unique ID of the GitHub Actions OIDC role"
  value       = aws_iam_role.github_actions.unique_id
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows users to view basic account info, manage password and virtual MFA device. MFA deactivation and broader self-inspection require MFA session."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "iam:GetAccountAuthorizationDetails",
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
    ]
  })
}

